window.HS_LOAD(6,{"intro":[[["نبی کریمؐ اور آپؐ کے صحابہ کرامؓ کس طرح جمعوں میں، جماعتوں میں، حج اور غزوات میں اور تمام حالات میں بیان کیا کرتے تھے اور لوگوں کو ",""],["ٱللَّٰه","a"],[" کا حکم ماننے کی ترغیب دیا کرتے تھے چاہے ",""],["ٱللَّٰه","a"],[" کے حکم مشاہدہ اور تجربہ کے خلاف کیوں نہ ہوں اور کس طرح لوگوں کے دلوں میں دنیا اور اس کی فانی لذتوں کی بے رغبتی اور آخرت اور اس کی ہمیشہ رہنے والی لذتوں کا شوق پیدا کیا کرتے تھے اور گویا کہ وہ پوری امت مسلمہ کو مالدار اور غریب کو خواص اور عوام کو اس بات پر کھڑا کرتے تھے کہ ",""],["ٱللَّٰه","a"],[" اور اس کے رسول کی طرف سے جو احکام ان کی طرف متوجہ ہیں وہ اپنی جان لگا کر اپنا مال خرچ کر کے ان احکام کو پورا کریں اور وہ امت مسلمہ کو فانی مال اور ختم ہو جانے والے سامان پر کھڑا نہیں کرتے تھے",""]]],"topics":{"155":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسلمہ بن عبدالرحمٰنؒ","b"],[" فرماتے ہیں حضورؐ نے مدینہ میں سب سے پہلا بیان فرمایا، اس کی صورت یہ ہوئی کہ آپؐ نے کھڑے ہو کر پہلے ",""],["ٱللَّٰه","a"],[" کی شان کے مطابق حمد و ثناء بیان کی پھر فرمایا اما بعد! اے لوگو! اپنے لیے (آخرت میں کام آنے کے لیے) نیک اعمال کا ذخیرہ آگے بھیجو۔ اچھی طرح جان لو تم میں سے ہر آدمی نے ضرور مرنا ہے اور اپنی بکریاں بغیر چرواہے کے چھوڑ کر چلے جانا ہے، پھر اس کے اور اس کے رب کے درمیان نہ کوئی ترجمان ہوگا اور نہ کوئی دربان۔ اور اس کا رب اس سے پوچھے گا کیا میرے رسول نے تیرے پاس آ کر میرا دین نہیں پہنچایا تھا؟ کیا میں نے تجھے مال نہیں دیا تھا؟ اور تجھ پر فضل و احسان نہیں کیا تھا؟ اب بتا تو نے اپنے لیے یہاں آگے کیا بھیجا ہے؟ چنانچہ وہ دائیں بائیں دیکھے گا تو اسے کوئی چیز نظر نہ آئے گی پھر وہ اپنے سامنے دیکھے گا تو اسے جہنم کے سوا اور کچھ نظر نہ آئے گا۔ لہٰذا تم میں سے جو اپنے آپ کو جہنم کی آگ سے کھجور کا ایک ٹکڑا دے کر ہی بچا سکتا ہے اسے چاہیے کہ وہ خود کو بچا لے اور جسے یہ بھی میسر نہ ہو تو وہ اچھی بات بول کر ہی خود کو بچا لے، کیونکہ نیکی کا بدلہ دس گنا سے لے کر سات سو گنا تک ملے گا۔ والسلام علی رسول ",""],["ٱللَّٰه","a"],[" ورحمۃ ",""],["ٱللَّٰه","a"],[" وبرکاتہ۔ حضورؐ نے ایک مرتبہ پھر بیان فرمایا اور ارشاد فرمایا بات یہ ہے کہ تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، میں اس کی تعریف کرتا ہوں اور اس سے مدد طلب کرتا ہوں، ہم اپنے نفس کے شر اور برے اعمال کے شرور سے ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتے ہیں۔ جسے ",""],["ٱللَّٰه","a"],[" ہدایت دے دے اسے کوئی گمراہ کرنے والا نہیں اور جسے گمراہ کرے اسے کوئی ہدایت دینے والا نہیں اور میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ سب سے اچھا کلام ",""],["ٱللَّٰه","a"],[" کی کتاب ہے، وہ آدمی کامیاب ہو گیا جس کے دل کو ",""],["ٱللَّٰه","a"],[" نے قرآن سے مزین کیا اور اسے کفر کے بعد اسلام میں داخل کیا اور اس آدمی نے باقی تمام لوگوں کے کلام کو چھوڑ کر ",""],["ٱللَّٰه","a"],[" کی کتاب کو اختیار کیا۔ یہ ",""],["ٱللَّٰه","a"],[" کی کتاب سب سے عمدہ اور سب سے زیادہ بلیغ کلام ہے، جو ",""],["ٱللَّٰه","a"],[" سے محبت کرے تم اس سے محبت کرو اور تم ",""],["ٱللَّٰه","a"],[" سے محبت اس طرح کرو کہ سارے دل میں رچ جائے اور ",""],["ٱللَّٰه","a"],[" کے کلام اور اس کے ذکر سے مت اکتاؤ اور قرآن سے اعراض نہ کرو ورنہ تمہارے دل سخت ہو جائیں گے، کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ (اعمال میں سے) جو کچھ پیدا کرتے ہیں اس میں سے بعض (اعمال) کو چن لیتے ہیں، پسند کر لیتے ہیں۔ چنانچہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنی کتاب کا نام پسندیدہ عمل، پسندیدہ عبادت، نیک کلام اور لوگوں کو حلال و حرام والا جو دین دیا گیا ہے اس میں سے نیک عمل رکھا ہے، لہٰذا تم ",""],["ٱللَّٰه","a"],[" کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ کرو اور اس سے ایسے ڈرو جیسے اس سے ڈرنے کا حق ہے اور تم لوگ اپنے منہ سے جو نیک اور بھلی باتیں بولتے ہو ان میں تم ",""],["ٱللَّٰه","a"],[" سے سچ کہو اور ",""],["ٱللَّٰه","a"],[" کی رحمت کی وجہ سے تم ایک دوسرے سے محبت کرو، اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اس بات سے ناراض ہوتے ہیں کہ ان سے جو عہد کیا جائے اسے توڑا جائے۔ والسلام علیکم و رحمۃ ",""],["ٱللَّٰه","a"],[" و برکاتہ۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi in this manner as a mursal narration, as quoted in Al Bidaayah wan Nihaayah (Vol.3 Pg.212). Ibn Asaakir has also reported from Anas that this was the first sermon delivered by Rasulullah ﷺ, with other words in abridged form as mentioned earlier."]]}]},"156":{"lead":[],"stories":[{"b":[["n",[["حضرت سعید بن عبدالرحمٰن جمحیؒ","b"],[" کہتے ہیں مجھے یہ خبر پہنچی ہے کہ حضورؐ نے مدینہ میں بنوسالم بن عوف کے محلہ میں جو سب سے پہلا جمعہ پڑھایا تھا اس میں یہ خطبہ دیا تھا تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، میں اس کی تعریف کرتا ہوں، اس سے مدد مانگتا ہوں، اس سے مغفرت چاہتا ہوں اور اس سے ہدایت طلب کرتا ہوں اور اس پر ایمان لاتا ہوں اور اس کا انکار نہیں کرتا بلکہ جو اس کا انکار کرتا ہے اس سے دشمنی رکھتا ہوں۔ میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں اور (حضرت) محمدؐ اس کے بندے اور رسول ہیں، انہیں ",""],["ٱللَّٰه","a"],[" نے ہدایت، نور اور نصیحت دے کر اس وقت بھیجا جبکہ رسولوں کی آمد کا سلسلہ رکا ہوا تھا اور علم بہت کم ہو گیا تھا اور لوگ گمراہ ہو چکے تھے اور زمانے میں خیر و برکت نہیں رہی تھی اور قیامت قریب آ چکی تھی اور اس کا مقررہ وقت پورا ہونے والا تھا۔ اب جو ",""],["ٱللَّٰه","a"],[" اور اس کے رسول کی اطاعت کرے گا وہ ہدایت والا ہوگا اور جو ان دونوں کی نافرمانی کرے گا وہ بھٹکا ہوا اور کوتاہی کا مرتکب ہوگا اور بڑی دور کی گمراہی میں جا پڑے گا۔ میں تمہیں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں۔ ایک مسلمان دوسرے مسلمانوں کو جن باتوں کی تاکید کرتا ہے ان میں سے سب سے بہتر بات یہ ہے کہ اسے آخرت کی ترغیب دے اور ",""],["ٱللَّٰه","a"],[" سے ڈرنے کا حکم دے۔ لہٰذا ان تمام کاموں سے بچو جن کے بارے میں تمہیں ",""],["ٱللَّٰه","a"],[" نے اپنی ذات سے ڈرایا ہے، اس سے بہتر کوئی نصیحت نہیں، اس سے بہتر کوئی یاد دہانی نہیں۔ اپنے رب سے ڈر کر تقویٰ پر عمل کرنا ان تمام چیزوں کے حاصل ہونے کے لیے سچا مددگار ہے جنہیں تم آخرت میں چاہتے ہو اور جو محض ",""],["ٱللَّٰه","a"],[" کی رضا کی نیت سے لوگوں کے سامنے بھی اور ان سے چھپ کر بھی اپنے اور اپنے رب کے درمیان کے معاملے کو ٹھیک کر لے گا تو یہ اس کے لیے دنیا میں ذکر خیر کا ذریعہ ہوگا اور موت کے بعد ذخیرہ آخرت ہوگا جب کہ آدمی کو آگے بھیجے ہوئے اپنے اعمال کی بہت زیادہ ضرورت ہوگی اور جو اپنے اور اپنے رب کے درمیان کے معاملے کو ٹھیک نہیں کرے گا وہ تمنا کرے گا کاش میرے اور میرے آگے بھیجے ہوئے برے اعمال میں بہت زیادہ مسافت ہوتی۔ اور ",""],["ٱللَّٰه","a"],[" تمہیں اپنی ذات (کے غصہ اور سزا) سے ڈراتا ہے اور ",""],["ٱللَّٰه","a"],[" بندوں پر بہت مہربان ہے۔ ",""],["ٱللَّٰه","a"],[" اپنی ہر بات کو سچ کر دکھاتے ہیں اور اپنے وعدوں کو پورا کرتے ہیں، ان کے وعدے کے خلاف نہیں ہو سکتا کیونکہ خود ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["مَا يُبَدَّلُ ٱلْقَوْلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّٰمٍ لِّلْعَبِيدِ","a"]]],["p",[["ترجمہ: \"میرے ہاں (وہ) بات (وعید مذکور کی) نہیں بدلی جاوے گی اور میں (اس تجویز میں) بندوں پر ظلم کرنے والا نہیں ہوں۔\" (سورت ق آیت ۲۹) لہٰذا دنیا و آخرت کے تمام معاملات میں خفیہ اور اعلانیہ طور سے ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ جو ",""],["ٱللَّٰه","a"],[" سے ڈرے گا ",""],["ٱللَّٰه","a"],[" اس کی تمام برائیوں کو مٹا دے گا اور اسے اجر عظیم عطا فرمائے گا اور جو ",""],["ٱللَّٰه","a"],[" سے ڈرے گا اسے بہت بڑی کامیابی ملے گی اور ",""],["ٱللَّٰه","a"],[" کا ڈر ہی اس کے غصے، اس کی سزا اور ناراضگی سے بچاتا ہے اور ",""],["ٱللَّٰه","a"],[" کے ڈر سے ہی چہرے (قیامت کے دن) سفید ہوں گے اور رب عظیم راضی ہوں گے اور درجے بلند ہوں گے۔ لہٰذا تم تقویٰ میں سے پورا حصہ لو اور ",""],["ٱللَّٰه","a"],[" کی جناب میں کوتاہی نہ کرو۔ ",""],["ٱللَّٰه","a"],[" نے تمہیں اپنی کتاب کا علم عطا فرمایا ہے اور اپنا راستہ تمہارے لیے واضح کیا تاکہ ",""],["ٱللَّٰه","a"],[" کو سچوں اور جھوٹوں کا پتہ چل جائے اور لوگوں کے ساتھ اچھا سلوک کرو جیسے اس نے تمہارے ساتھ کیا ہے اور اس کے دشمنوں سے دشمنی رکھو اور ",""],["ٱللَّٰه","a"],[" کے دین کے لیے خوب محنت کرو جیسے کہ محنت کرنے کا حق ہے۔ اسی نے تمہیں چنا ہے اور اسی نے تمہارا نام مسلمان رکھا ہے تاکہ جسے گمراہ ہو کر برباد ہونا ہے وہ دلیل اور نشانی دیکھ کر پھر برباد ہو اور جسے ہدایت پا کر حقیقی زندگی حاصل کرنی ہے وہ دلیل اور نشانی دیکھ کر حاصل کرے اور نیکیاں کرنے کی طاقت صرف ",""],["ٱللَّٰه","a"],[" سے ہی ملتی ہے۔ ",""],["ٱللَّٰه","a"],[" کا ذکر کثرت سے کرو اور آج کے بعد والی زندگی یعنی آخرت کے لیے عمل کرو، جو اپنے اور ",""],["ٱللَّٰه","a"],[" کے تعلق کو ٹھیک کر لے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے اور لوگوں کے درمیان کے معاملات کو خود ٹھیک کر دیں گے کیونکہ ",""],["ٱللَّٰه","a"],[" لوگوں پر فیصلہ کرتا ہے اور لوگوں کا فیصلہ ",""],["ٱللَّٰه","a"],[" پر نہیں چلتا۔ ",""],["ٱللَّٰه","a"],[" لوگوں کی ہر چیز کے مالک ہیں اور لوگ ",""],["ٱللَّٰه","a"],[" کے ہاں کچھ اختیار نہیں رکھتے۔ ",""],["ٱللَّٰه","a"],[" سب سے بڑے ہیں اور ",""],["ٱللَّٰه","a"],[" عظیم سے ہی نیکی کرنے کی طاقت ملتی ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer (Vol.2 Pg.115). Ibn Katheer in Al Bidaayah (Vol.3 Pg.213) has said that Ibn Jareer has reported it in the same way in a mursal chain. Qurtubi has also mentioned a similar lengthy narration without a chain in his Tafseer (Vol.18 Pg.98)."]]}]},"157":{"lead":[],"stories":[{"b":[["n",[["نبی کریمؐ کے صحابی ",""],["حضرت جدارؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے ساتھ ایک غزوے میں گئے۔ جب ہمارا دشمن سے سامنا ہوا تو آپؐ نے کھڑے ہو کر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! تم سبز، زرد اور سرخ رنگ کی مختلف نعمتوں والے ہو گئے ہو اور تمہارے گھروں اور قیام گاہوں میں بہت قسم کی نعمتیں ہیں۔ جب تم دشمن سے لڑو تو قدم قدم آگے بڑھو کیونکہ جب بھی کوئی آدمی ",""],["ٱللَّٰه","a"],[" کے راستے میں دشمن پر حملہ کرتا ہے تو وہ حوریں اس کی طرف جھپٹتی ہیں اور جب وہ شہید ہوتا ہے تو خون کے پہلے قطرے کے زمین پر گرتے ہی ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے ہر گناہ کو معاف کر دیتے ہیں اور یہ دونوں حوریں اس کے منہ سے غبار کو صاف کرتی ہیں اور کہتی ہیں تمہارا وقت آ گیا ہے، وہ ان سے کہتا ہے تم دونوں کا وقت بھی آ گیا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani and Bazzaar; Haythami (Vol.5 Pg.375) has said that in its chain is Abbaas bin Fadl Ansari who is weak."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ غزوہ تبوک کے سفر میں حجر مقام میں ٹھہرے، وہاں آپؐ نے کھڑے ہو کر لوگوں میں بیان فرمایا اور فرمایا اے لوگو! تم اپنے نبی سے معجزوں کا مطالبہ نہ کرو۔ حضرت صالح علیہ السلام کی قوم نے اپنے نبی سے مطالبہ کیا تھا کہ وہ ان کے لیے (معجزے کے طور پر) ایک اونٹنی بھیجیں۔ حضرت صالحؑ نے ان کا یہ مطالبہ پورا کر دیا، چنانچہ وہ اونٹنی اس وسیع اور کشادہ راستہ سے پانی پینے آتی تھی اور اپنی باری کے دن وہ ان کا سارا پانی پی جاتی تھی اور جتنا دودھ پانی کے ناغہ والے دن دیتی تھی اتنا ہی پانی کی باری والے دن بھی دیتی تھی، پھر اسی وسیع راستے سے واپس چلی جاتی تھی۔ پھر انہوں نے اس کی ٹانگیں کاٹ ڈالیں۔ ",""],["ٱللَّٰه","a"],[" نے انہیں تین دن کی مہلت دی اور ",""],["ٱللَّٰه","a"],[" کا وعدہ جھوٹا نہیں ہوتا۔ پھر ان پر (ایک فرشتے کی) چیخ آئی اور اس قوم کے جتنے آدمی آسمان اور زمین کے درمیان تھے ان سب کو ",""],["ٱللَّٰه","a"],[" نے اس چیخ سے ہلاک کر دیا، صرف ایک آدمی بچا جو اس وقت ",""],["ٱللَّٰه","a"],[" کے حرم میں تھا۔ وہ ",""],["ٱللَّٰه","a"],[" کے حرم کی وجہ سے ",""],["ٱللَّٰه","a"],[" کے عذاب سے بچ گیا۔ کسی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! وہ کون تھا؟ آپؐ نے فرمایا ابورغال۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani; Haythami (Vol.7 Pg.38) has said that Tabraani in his Awsat and Bazzaar have reported a similar narration, and Ahmad's narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت حسن بن علیؓ","b"],[" فرماتے ہیں حضورؐ غزوہ تبوک کے دن منبر پر تشریف فرما ہوئے اور ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! میں تمہیں اسی بات کا حکم دیتا ہوں جس کا ",""],["ٱللَّٰه","a"],[" تمہیں حکم دیتے ہیں اور اسی چیز سے تمہیں روکتا ہوں جس سے ",""],["ٱللَّٰه","a"],[" تمہیں روکتے ہیں، لہٰذا روزی کی تلاش میں درمیانہ راستہ اختیار کرو۔ اس ذات کی قسم جس کے قبضے میں ابوالقاسم کی جان ہے! تم میں سے ہر آدمی کو اس کی روزی ایسے ڈھونڈتی ہے جیسے اسے اس کی موت ڈھونڈتی ہے۔ اگر تمہیں روزی میں کچھ مشکل پیش آئے تو ",""],["ٱللَّٰه","a"],[" کی اطاعت والے اعمال (تلاوت، دعا، ذکر، توبہ، استغفار وغیرہ) کے ذریعہ آسانی طلب کرو۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Kabeer, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.192)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں جب حضورؐ نے مکہ فتح کر لیا تو آپؐ نے فرمایا اب تم ہر ایک سے اپنے ہتھیار روک لو اور کسی پر ہتھیار نہ چلاؤ، البتہ قبیلہ خزاعہ والے قبیلہ بنوبکر پر ہتھیار اٹھا سکتے ہیں۔ چنانچہ آپؐ نے بنو خزاعہ کو ہتھیار اٹھانے کی اجازت دے دی لیکن جب عصر کی نماز پڑھ لی تو قبیلہ خزاعہ سے فرمایا اب تم بھی ہتھیار روک لو۔ اگلے دن مزدلفہ میں خزاعہ کے ایک آدمی کو بنو بکر کا ایک آدمی ملا، اس نے بنو بکر کا وہ آدمی قتل کر دیا۔ حضورؐ کو جب خبر ملی تو آپؐ بیان کے لیے کھڑے ہوئے۔ راوی کہتے ہیں میں نے دیکھا کہ حضورؐ اپنی کمر سے بیت ",""],["ٱللَّٰه","a"],[" کے ساتھ سہارا لگائے کھڑے ہیں۔ آپؐ نے فرمایا لوگوں میں سے ",""],["ٱللَّٰه","a"],[" کا سب سے زیادہ دشمن وہ ہے جو حرم میں کسی کو قتل کرے یا اپنے قاتل کے علاوہ کسی اور کو قتل کرے یا زمانہ جاہلیت کے قتل کے بدلے میں قتل کرے۔ ایک آدمی نے کھڑے ہو کر کہا بیشک فلاں آدمی میرا بیٹا ہے۔ آپؐ نے فرمایا کسی کو اپنا بیٹا بنا لینا اسلام میں (جائز) نہیں ہے۔ جاہلیت کی تمام باتیں اب ختم ہو چکی ہیں۔ اولاد عورت کے خاوند کی ہوگی (اگر وہ عورت باندی ہے تو اس کی اولاد باندی کے آقا کی ہوگی) اور زنا کرنے والے مرد کے لیے اثلب ہے۔ صحابہؓ نے پوچھا اثلب کیا چیز ہے؟ آپؐ نے فرمایا پتھر (یعنی زنا کار کو پتھر مار مار کر مار دیا جائے گا)۔ اور فرمایا فجر کی نماز کے بعد سورج نکلنے تک کوئی نماز نہیں پڑھنی چاہیے اور ایسے ہی عصر کے بعد سورج ڈوبنے تک کوئی نماز نہیں پڑھنی چاہیے۔ کسی عورت کی خالہ یا پھوپھی نکاح میں ہو تو اب اس عورت سے نکاح کرنا جائز نہیں ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani; Haythami (Vol.6 Pg.178) has said that its narrators are reliable. In the authentic Ahaadeeth there is the prohibition of salaah after Subh."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضورؐ نے فتح مکہ کے دن بیت ",""],["ٱللَّٰه","a"],[" کی سیڑھیوں پر کھڑے ہو کر بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے اپنا وعدہ پورا کر دیا اور اپنے بندے کی مدد کی اور اکیلے ہی تمام لشکروں کو شکست دی۔ غور سے سنو! خطاء مقتول وہ ہوگا جو کوڑے یا لاٹھی سے قتل ہوا ہو، اس کا خون بہا سو اونٹ ہیں جن میں چالیس گابھن اونٹنیاں بھی ہوں۔ توجہ سے سنو! جاہلیت کی ہر فخر کی چیز اور جاہلیت کے زمانہ کا ہر خون میرے ان دو قدموں کے نیچے رکھا ہوا ہے، البتہ بیت ",""],["ٱللَّٰه","a"],[" کی خدمت اور حاجیوں کو پانی پلانے کا کام جاہلیت میں جن کے پاس تھا میں نے اب بھی انہیں کے پاس باقی رہنے دیا ہے۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Majah."],["(6)","Ibn Abi Haatim; Abd bin Humayd has also reported it likewise, as quoted in Tafseer Ibn Katheer (Vol.4 Pg.218)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضورؐ نے فتح مکہ کے دن اپنی قصواء اونٹنی پر بیت ",""],["ٱللَّٰه","a"],[" کا طواف کیا۔ آپؐ کے دست مبارک میں ایک چھڑی تھی جس کا سرا مڑا ہوا تھا۔ آپؐ اس سے بیت ",""],["ٱللَّٰه","a"],[" کے کونوں کا بوسہ لے رہے تھے۔ مسجد حرام میں اونٹنی کے بیٹھنے کے لیے آپؐ کو جگہ نہ ملی، اس لیے آپؐ اونٹنی سے اترے تو لوگوں نے آپؐ کو اپنے ہاتھوں میں لے لیا پھر آپؐ اونٹنی کو پانی بہنے کی جگہ کے درمیان لے گئے اور اسے وہاں بٹھایا پھر اپنی سواری پر سوار ہو کر لوگوں میں بیان فرمایا۔ پہلے ",""],["ٱللَّٰه","a"],[" کی شان کے مطابق حمد و ثناء بیان کی پھر فرمایا اے لوگو! جاہلیت کے زمانے میں لوگ کبر و نخوت میں مبتلا تھے اور اپنے آباء و اجداد کے کارناموں کی بنا پر خود کو بڑا سمجھتے تھے۔ اب ",""],["ٱللَّٰه","a"],[" نے یہ تمام باتیں ختم کر دی ہیں۔ لوگ دو طرح کے ہیں، ایک نیک متقی اور پرہیزگار جو کہ ",""],["ٱللَّٰه","a"],[" کے ہاں عزت و شرافت والے ہوتے ہیں، دوسرے بدکار بدبخت جن کی ",""],["ٱللَّٰه","a"],[" کے ہاں کوئی وقعت نہیں ہوتی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں",""]]],["q",[["يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ","a"]]],["p",[["ترجمہ: \"اے لوگو! ہم نے تم کو ایک مرد اور ایک عورت سے پیدا کیا ہے اور تم کو مختلف قوموں اور مختلف خاندان بنایا تاکہ ایک دوسرے کو شناخت کر سکو۔ ",""],["ٱللَّٰه","a"],[" کے نزدیک تم سب میں بڑا شریف وہی ہے جو سب سے زیادہ پرہیزگار ہو۔ ",""],["ٱللَّٰه","a"],[" خوب جاننے والا پورا خبردار ہے۔\" (سورت حجرات آیت ۱۳) اس کے بعد آپؐ نے فرمایا میں اپنی یہ بات کہتا ہوں اور میں اپنے لیے اور تمہارے لیے ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں۔",""]]]],"f":[]}]},"158":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمانؓ","b"],[" فرماتے ہیں حضورؐ نے شعبان کی آخری تاریخ میں ہم لوگوں میں بیان فرمایا کہ اے لوگو! تمہارے اوپر ایک مہینہ آ رہا ہے جو بہت بڑا اور مبارک مہینہ ہے۔ اس میں ایک رات (شب قدر) ہے جو ہزار مہینوں سے بڑھ کر ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس کے روزے کو فرض فرمایا اور اس کی رات کے قیام (یعنی تراویح) کو ثواب کی چیز بنایا ہے۔ جو شخص اس مہینہ میں کسی نیکی کے ساتھ ",""],["ٱللَّٰه","a"],[" کا قرب حاصل کرے وہ ایسا ہے جیسا کہ غیر رمضان میں فرض ادا کیا اور جو شخص اس مہینہ میں کسی فرض کو ادا کرے وہ ایسا ہے جیسا کہ غیر رمضان میں ستر فرض ادا کیے۔ یہ مہینہ صبر کا ہے اور صبر کا بدلہ جنت ہے اور یہ مہینہ لوگوں کے ساتھ غم خواری کرنے کا ہے۔ اس مہینہ میں مومن کا رزق بڑھا دیا جاتا ہے۔ جو شخص کسی روزہ دار کا روزہ افطار کرائے اس کے لیے گناہوں کے معاف ہونے اور آگ سے خلاصی کا سبب ہوگا اور روزہ دار کے ثواب کی مانند اس کو ثواب ہوگا مگر اس روزہ دار کے ثواب میں سے کچھ کم نہیں کیا جائے گا۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم میں سے ہر شخص تو اتنی وسعت نہیں رکھتا کہ روزہ دار کو افطار کرائے؟ تو آپؐ نے فرمایا (پیٹ بھر کھلانے پر موقوف نہیں) یہ ثواب تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ایک کھجور سے کوئی افطار کرا دے یا ایک گھونٹ پانی پلا دے یا ایک گھونٹ لسی پلا دے اس پر بھی مرحمت فرما دیتے ہیں۔ یہ ایسا مہینہ ہے کہ اس کا اول حصہ ",""],["ٱللَّٰه","a"],[" کی رحمت ہے اور درمیانی حصہ مغفرت ہے اور آخری حصہ آگ سے آزادی ہے۔ جو شخص اس مہینہ میں اپنے غلام (و خادم) کے بوجھ کو ہلکا کر دے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی مغفرت فرماتے ہیں اور آگ سے آزادی عطا فرماتے ہیں۔ اور اس میں چار چیزوں کی کثرت رکھا کرو جن میں سے دو چیزوں سے تم ",""],["ٱللَّٰه","a"],[" کو راضی کرو گے اور دو چیزیں ایسی ہیں کہ جن سے تمہیں چارہ کار نہیں۔ وہ دو چیزیں جن سے تم اپنے رب کو راضی کرو گے وہ کلمہ شہادت اور استغفار کی کثرت ہے اور دوسری دو چیزیں یہ ہیں کہ جنت کی طلب کرو اور آگ سے پناہ مانگو۔ جو شخص کسی روزہ دار کو پانی پلائے، ",""],["ٱللَّٰه","a"],[" تعالیٰ (قیامت کے دن) میرے حوض سے اس کو ایسا پانی پلائیں گے جس کے بعد جنت میں داخل ہونے تک اسے پیاس نہیں لگے گی۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Khuzaymah, as quoted by Mundhiri in Targheeb wat Tarheeb (Vol.2 Pg.218), who said that Ibn Khuzaymah has reported it in his Saheeh. Bayhaqi has reported it through another chain, and Abu Shaykh Ibn Hibbaan in Kitaabuth Thawaab in abridged form. Ibn Najjaar has also reported it in full, as quoted in Kanzul Ummaal (Vol.4 Pg.323)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں جب ماہ رمضان قریب آ گیا تو حضورؐ نے مغرب کے وقت مختصر بیان فرمایا جس میں ارشاد فرمایا رمضان تمہارے سامنے آ گیا ہے اور تم اس کا استقبال کرنے والے ہو۔ غور سے سنو! رمضان کی پہلی رات میں ہی اہل قبلہ (مسلمانوں) میں سے ہر ایک کی مغفرت کر دی جاتی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.4 Pg.325)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں جب رمضان المبارک کی پہلی رات ہوئی تو حضورؐ نے کھڑے ہو کر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہارے دشمن جنات (شیاطین) سے خود ہی نمٹ لیا ہے (کیونکہ انہیں قید کر دیا ہے) اور تم سے دعا قبول کرنے کا وعدہ کیا ہے اور فرمایا ہے",""]]],["q",[["ٱدْعُونِي أَسْتَجِبْ لَكُمْ","a"]]],["p",[["ترجمہ: \"مجھ کو پکارو میں تمہاری درخواست قبول کروں گا۔\" توجہ سے سنو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہر سرکش شیطان پر سات فرشتے مقرر فرما دیے ہیں اور وہ رمضان ختم ہونے تک چھوٹ نہیں سکتا۔ غور سے سنو! رمضان کی پہلی رات سے لے کر آخری رات تک آسمان کے تمام دروازے کھلے رہیں گے اور اس مہینہ میں ہر دعا قبول ہوتی ہے۔ جب آخری عشرہ کی پہلی رات ہوتی تو حضورؐ لنگی کس لیتے اور عورتوں کے بیچ میں سے نکل جاتے اور اعتکاف فرماتے اور رات بھر عبادت فرماتے۔ کسی نے پوچھا لنگی کسنے کا مطلب کیا ہے؟ حضرت علیؓ نے فرمایا ان دنوں میں عورتوں سے جدا رہتے۔",""],[" (3)","s"]]]],"f":[["(3)","Isfahaani, as quoted in Kanzul Ummaal (Vol.4 Pg.323)."]]}]},"159":{"lead":[],"stories":[{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے ہم میں بیان فرمایا اس میں ارشاد فرمایا اے لوگو! مرنے سے پہلے توبہ کر لو، مشغول ہونے سے پہلے اعمال صالحہ میں جلدی لگ جاؤ، تمہارا ",""],["ٱللَّٰه","a"],[" سے جو تعلق ہے اس کو ",""],["ٱللَّٰه","a"],[" کے زیادہ ذکر کرنے سے اور چھپ کر اور برملا خوب صدقہ دینے سے جوڑے رکھو، اس طرح تمہیں رزق دیا جائے گا اور تمہاری مدد کی جائے گی اور تمہاری تلافی کی جائے گی۔ میرے اس مہینہ کے اس دن میں اس سال سے قیامت تک جمعہ کی نماز تم پر فرض کر دی گئی ہے۔ لہٰذا جس کا کوئی عادل یا ظالم امام ہو اور وہ میری زندگی میں یا میرے بعد جمعہ کو ہلکا سمجھ کر یا اس کا انکار کر کے اسے چھوڑ دے، ",""],["ٱللَّٰه","a"],[" اس کے بکھرے ہوئے کاموں کو جمع نہ فرمائے اور اس کے حالات ٹھیک نہ کرے اور اس کے کسی کام میں برکت نہ کرے۔ اور غور سے سنو! اور جب تک وہ اپنے اس گناہ سے توبہ نہیں کرے گا اس کی نماز قبول نہ ہوگی، نہ حج، نہ زکوٰۃ، نہ روزہ اور نہ کوئی اور نیکی۔ جو توبہ کرے گا ",""],["ٱللَّٰه","a"],[" اس کی توبہ قبول کرے گا۔ توجہ سے سنو! کوئی عورت ہرگز کسی مرد کی امامت نہ کرے اور نہ کوئی بدوی کسی مہاجر کا امام بنے اور نہ کوئی فاجر بدکار کسی مومن کا امام بنے، ہاں اگر وہ فاجر طاقت سے اسے دبا کر مجبور کر دے اور اسے اس کی تلوار اور کوڑے کا ڈر ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Majah (Pg.172). Tabraani has reported a similar narration, as quoted in Targheeb wat Tarheeb."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں جمعہ کے دن حضورؐ نے کھڑے ہو کر بیان فرمایا اور ارشاد فرمایا جو آدمی مدینہ سے ایک میل دور رہتا ہے اور جمعہ کا دن آ جاتا ہے اور وہ جمعہ پڑھنے نہیں آتا ",""],["ٱللَّٰه","a"],[" اس کے دل پر مہر لگا دے گا۔ پھر دوسری مرتبہ میں ارشاد فرمایا جو آدمی مدینہ سے دو میل دور رہتا ہے اور جمعہ کا دن آ جاتا ہے اور وہ جمعہ پڑھنے نہیں آتا ",""],["ٱللَّٰه","a"],[" اس کے دل پر مہر لگا دے گا۔ پھر تیسری مرتبہ میں ارشاد فرمایا جو آدمی مدینہ سے تین میل دور رہتا ہے اور جمعہ کا دن آ جاتا ہے اور وہ جمعہ پڑھنے نہیں آتا ",""],["ٱللَّٰه","a"],[" اس کے دل پر مہر لگا دے گا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Ya'la, as quoted in Targheeb wat Tarheeb (Vol.2 Pg.31)."]]}]},"160":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے حجۃ الوداع میں لوگوں کو خطبہ دیا اور فرمایا شیطان اس بات سے تو ناامید ہو گیا ہے کہ تمہاری زمین میں اس کی عبادت کی جائے (یعنی بتوں کی پرستش ہونے لگے) لیکن وہ اس بات پر راضی ہے کہ کفر و شرک کے علاوہ دوسرے ایسے گناہوں میں اس کی مانی جائے جن کو تم لوگ چھوٹا سمجھتے ہو (چونکہ کافر تو کفر و شرک کے بڑے گناہ میں مبتلا ہیں اس لیے شیطان انہیں چھوٹے گناہوں میں لگانے پر زور نہیں لگاتا اور مسلمان چونکہ بڑے گناہ سے بچے ہوئے ہیں اس وجہ سے شیطان انہیں کفر و شرک سے کم درجہ کے گناہ قتل، جھوٹ، خیانت وغیرہ میں لگانے پر سارا زور لگاتا ہے)۔ لہٰذا چوکنے ہو جاؤ! اے لوگو! میں تمہارے پاس ایسی چیز چھوڑ کر جا رہا ہوں کہ اگر تم اسے مضبوطی سے پکڑے رہو گے تو کبھی گمراہ نہیں ہو گے، ",""],["ٱللَّٰه","a"],[" کی کتاب اور اس کے نبیؐ کی سنت۔ ہر مسلمان دوسرے مسلمان کا بھائی ہے اور سارے مسلمان آپس میں بھائی بھائی ہیں اور کسی آدمی کے لیے اپنے مسلمان بھائی کے مال کو اس کی رضامندی کے بغیر لینا حلال نہیں اور ظلم نہ کرنا اور میرے بعد کافر نہ بن جانا (یا ناشکرے نہ بن جانا) کہ تم ایک دوسرے کی گردن اڑانے لگ جاؤ۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.1 Pg.93), who remarked that Bukhaari and Muslim have both used narrators of this chain as proof and that this sermon of Rasulullah ﷺ is agreed upon in the Saheehayn; Dhahabi agreed."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے ہم لوگوں میں مسجد خیف میں (جو کہ منیٰ میں ہے) بیان فرمایا، ",""],["ٱللَّٰه","a"],[" کی شان کے مطابق حمد و ثناء بیان کی پھر فرمایا جو آخرت کی فکر کرتا ہے اور اسے اپنا مقصد بناتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے بکھرے ہوئے کاموں کو جمع کر دے گا اور غنا کو اس کی آنکھوں کے سامنے کر دے گا اور دنیا ذلیل ہو کر اس کے پاس آئے گی اور جو دنیا کو مقصد بنا کر اس کی فکر کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے جمع شدہ کاموں کو بکھیر دے گا اور محتاجی کو اس کی آنکھوں کے سامنے کر دے گا اور دنیا اسے اتنی ہی ملے گی جو مقدر میں ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani and Abu Bakr Khaffaaf in his Mu'jam and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.202)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضورؐ نے منیٰ کی مسجد خیف میں ہم لوگوں میں بیان فرمایا، ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس بندے کو تر و تازہ رکھے جس نے میری بات کو سنا اور کوشش کر کے وہ بات اپنے بھائی سے بیان کی۔ تین چیزیں ایسی ہیں جن میں کسی مسلمان کا دل کھوٹ اور خیانت نہیں کرے گا، ایک عمل کو خالص ",""],["ٱللَّٰه","a"],[" کے لیے کرنا اور دوسرے حاکم اور امراء کی خیر خواہی کرنا، تیسرے مسلمانوں کی جماعت کے ساتھ چمٹے رہنا کیونکہ مسلمانوں کی دعا ان کو ہر طرف سے گھیر لیتی ہے (اور شیطان کے مکر و فریب سے ان کی حفاظت کرتی ہے)۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.228)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" نے حضورؐ کے حج کے بارے میں ایک لمبی حدیث ذکر کی ہے جس میں یہ ہے کہ حضورؐ منیٰ سے چلے اور مزدلفہ سے گزرتے ہوئے عرفات پہنچ گئے، وہاں جا کر آپؐ نے دیکھا کہ آپؐ کا خیمہ وادی نمرہ میں لگا ہوا ہے۔ آپؐ اس میں ٹھہر گئے، جب زوال کا وقت ہو گیا تو آپؐ نے حکم فرمایا تو قصواء اونٹنی پر کجاوہ رکھا گیا پھر آپؐ وادی کے درمیانی حصہ میں تشریف لے گئے اور لوگوں میں مشہور خطبہ بیان فرمایا جس میں آپؐ نے فرمایا تمہارے خون اور تمہارے مال تم پر ایسے قابل احترام ہیں جیسے کہ یہ دن، تمہارا یہ مہینہ اور تمہارا یہ شہر قابل احترام ہے۔ غور سے سنو! جاہلیت کا ہر غلط کام اور طور طریقہ میرے ان دو قدموں کے نیچے رکھا ہوا ہے یعنی اسے ختم کر دیا گیا ہے۔ جاہلیت کے تمام خون بھی آج سے ختم ہیں اور میں اپنے خونوں میں سے سب سے پہلے ربیعہ بن حارث کے بیٹے کا خون ختم کراتا ہوں جو کہ بنو سعد کے ہاں دودھ پی رہا تھا اور قبیلہ ہذیل نے اسے قتل کر دیا تھا۔ جاہلیت کے سود بھی ختم کر دیے گئے ہیں اور میں اپنے سودوں میں سے سب سے پہلے حضرت عباسؓ بن عبدالمطلب کا سود معاف کراتا ہوں، اب یہ سارا معاف کر دیا گیا ہے۔ اور عورتوں کے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ تم نے ",""],["ٱللَّٰه","a"],[" کی امانت سے ان کو لیا ہے (تم ان کے مالک نہیں بلکہ امین ہو) اور ",""],["ٱللَّٰه","a"],[" کے مقرر کردہ طریقہ نکاح کے ذریعہ تمہارے لیے وہ عورتیں حلال ہوئیں اور تمہارا ان پر یہ حق ہے کہ جس کا آنا تمہیں پسند نہ ہو وہ تمہارے گھر میں نہ آنے دیں، اگر وہ ایسا کریں تو تم انہیں مارو لیکن یہ مار سخت نہ ہو اور ان کا تم پر یہ حق ہے کہ دستور کے مطابق انہیں کھانا اور کپڑا دو۔ اور میں تم میں ایسی چیز چھوڑ کر جا رہا ہوں کہ اگر تم اسے مضبوطی سے پکڑ لو گے تو کبھی گمراہ نہیں ہو گے اور وہ ہے ",""],["ٱللَّٰه","a"],[" کی کتاب۔ تم سے میرے بارے میں پوچھا جائے گا تو کیا کہو گے؟ صحابہؓ نے عرض کیا ہم گواہی دیتے ہیں کہ آپؐ نے (",""],["ٱللَّٰه","a"],[" کا دین سارا) پہنچا دیا اور امت کی خیر خواہی کی اور خدا کی امانت پہنچا دی۔ پھر آپؐ نے شہادت کی انگلی آسمان کی طرف اٹھائی اور پھر لوگوں کی طرف نیچے جھکائی اور فرمایا اے ",""],["ٱللَّٰه","a"],["! تو گواہ ہو جا۔ اے ",""],["ٱللَّٰه","a"],["! تو گواہ ہو جا اور تین دفعہ یہی فرمایا۔",""],[" (4)","s"]]]],"f":[["(4)","Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.148). Abu Dawood and Ibn Majah have also reported it, as quoted in Kanzul Ummaal (Vol.3 Pg.23)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں نحر کے دن یعنی دس ذی الحجہ کو حضورؐ نے لوگوں میں بیان فرمایا، ارشاد فرمایا اے لوگو! یہ کون سا دن ہے؟ لوگوں نے کہا یہ قابل احترام دن ہے۔ آپؐ نے پوچھا یہ کون سا شہر ہے؟ لوگوں نے کہا یہ قابل احترام شہر ہے۔ آپؐ نے پوچھا یہ کون سا مہینہ ہے؟ لوگوں نے کہا یہ قابل احترام مہینہ ہے۔ آپؐ نے فرمایا تمہارے خون، تمہارے مال اور تمہاری عزتیں ایسے ہی قابل احترام ہیں جیسے کہ تمہارا یہ دن، تمہارا یہ شہر اور تمہارا یہ مہینہ قابل احترام ہے۔ اور اس بات کو کئی مرتبہ فرمایا پھر سر اٹھا کر فرمایا اے ",""],["ٱللَّٰه","a"],["! میں نے پہنچا دیا ہے۔ اے ",""],["ٱللَّٰه","a"],["! میں نے پہنچا دیا ہے۔ حضرت ابن عباسؓ فرماتے ہیں اس ذات کی قسم جس کے قبضہ میں میری جان ہے اس کے بعد حضورؐ نے اپنی امت کو زبردست وصیت فرمائی کہ حاضرین (میرا سارا دین تمام) غائب انسانوں تک پہنچائیں۔ میرے بعد کافر نہ ہو جانا کہ ایک دوسرے کی گردن اڑانے لگو۔",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.194). Ahmad and Ibn Abi Shaybah have also reported it from him, Ibn Majah and Tabraani from Ibn Umar, and Ahmad and Baghawi from Abu Ghaadiyah, as quoted in Kanzul Ummaal (Vol.3 Pg.25)."]]},{"b":[["n",[["حضرت جریرؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا لوگوں کو چپ کراؤ پھر آپؐ نے فرمایا اب تو میں تمہارے حالات اچھے دیکھ رہا ہوں لیکن اس کے بعد میرے علم میں یہ بات نہ آئے کہ تم لوگ کافر بن کر ایک دوسرے کی گردن اڑانے لگے ہو۔ دوسری روایت میں ہے کہ حضورؐ نے حجۃ الوداع میں فرمایا اے جریر! لوگوں کو چپ کراؤ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.197)."]]},{"b":[["n",[["حضرت ام الحصینؓ","b"],[" فرماتی ہیں میں نے حضورؐ کے ہمراہ حجۃ الوداع کیا۔ میں نے دیکھا کہ حضرت اسامہؓ اور حضرت بلالؓ میں سے ایک نے حضورؐ کی اونٹنی کی نکیل پکڑ رکھی ہے اور دوسرا حضورؐ کو گرمی سے بچانے کے لیے آپؐ پر اپنے کپڑے سے سایہ کیے ہوئے ہے یہاں تک کہ حضورؐ نے جمرۃ العقبہ (بڑے شیطان) کو کنکریاں ماریں۔ پھر حضورؐ نے بہت سی باتیں ارشاد فرمائیں، پھر میں نے سنا کہ آپؐ فرما رہے ہیں کہ اگر تم پر ناک کان کٹا ہوا غلام امیر بنا دیا جائے جو کالا ہو لیکن وہ تمہیں ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق لے کر چلے تو تم اس کی ہر بات سنو اور مانو۔",""],[" (7)","s"]]]],"f":[["(7)","Muslim, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.196). Nasa'ee has reported a similar narration, as quoted in Kanzul Ummaal (Vol.3 Pg.62), and Ibn Sa'd (Vol.2 Pg.183) has also reported a similar narration."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں حجۃ الوداع کے سال میں نے حضورؐ کو خطبہ میں یہ فرماتے ہوئے سنا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہر حق والے کو اس کا حق خود دے دیا ہے لہٰذا اب وارث کے لیے وصیت نہیں ہو سکتی اور بچہ بستر کے مالک کا ہوگا اور زانی کو پتھر ملے گا اور سب کا حساب ",""],["ٱللَّٰه","a"],[" کے ہاں ہوگا۔ اور جس نے اپنے باپ کے علاوہ کسی اور کی طرف اپنے بیٹے ہونے کی نسبت کی یا جس غلام نے اپنے آقاؤں کے علاوہ کسی اور کی طرف اپنے غلام ہونے کی نسبت کی اس پر قیامت کے دن تک مسلسل ",""],["ٱللَّٰه","a"],[" کی لعنت ہوگی۔ کوئی عورت اپنے گھر سے خاوند کی اجازت کے بغیر خرچ نہ کرے۔ کسی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! کھانا بھی نہیں دے سکتی؟ آپؐ نے فرمایا کھانا تو ہمارے گھر کی چیزوں میں سب سے افضل چیز ہے۔ پھر آپؐ نے فرمایا عاریۃً مانگی ہوئی چیز واپس دینی ہوگی اور جو جانور دودھ پینے کے لیے کسی کو دیا تھا وہ واپس کرنا ہوگا، قرض ادا کرنا ہوگا اور کفیل تاوان کا ذمہ دار ہوگا۔ ابوداؤد کی روایت میں ہے کہ حضرت ابوامامہؓ نے فرمایا کہ میں نے منیٰ میں حضورؐ کا بیان سنا۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad and the compilers of the Sunan. Tirmidhi said that it is hasan."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں حضورؐ جدعاء نامی اونٹنی پر سوار تھے اور اس کی رکاب میں پاؤں رکھ کر آپؐ بلند ہو کر کھڑے تھے تاکہ لوگ آپؐ کی آواز سن لیں۔ میں نے سنا کہ آپؐ نے اونچی آواز میں فرمایا کیا تمہیں میری آواز سنائی نہیں دے رہی؟ تو مجمع میں سے ایک آدمی نے کہا آپؐ ہمیں کیا نصیحت فرمانا چاہتے ہیں؟ آپؐ نے فرمایا اپنے رب کی عبادت کرو اور پانچ نمازیں پڑھو اور ایک ماہ کے روزے رکھو اور اپنے امیر کی اطاعت کرو، اس طرح تم اپنے رب کی جنت میں داخل ہو جاؤ گے۔",""],[" (9)","s"]]]],"f":[["(9)","Ahmad also and Tirmidhi, who said that it is a hasan saheeh hadith, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.198)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن معاذ تیمیؒ","b"],[" فرماتے ہیں ہم لوگ منیٰ میں تھے، وہاں ہم میں حضورؐ نے بیان فرمایا، ",""],["ٱللَّٰه","a"],[" نے ہمارے سننے کی طاقت بہت بڑھا دی یہاں تک کہ ہم میں سے جو لوگ اپنی قیام گاہوں میں تھے وہ بھی حضورؐ کا بیان سن رہے تھے۔ چنانچہ حضورؐ انہیں حج کے احکام سکھانے لگے۔ جب آپؐ جمرے کے پاس پہنچے تو آپؐ نے دونوں کانوں میں شہادت کی انگلیاں ڈال کر اونچی آواز سے فرمایا چھوٹی چھوٹی کنکریاں مارو۔ پھر آپؐ نے حکم دیا تو مہاجرین مسجد (خیف) کے سامنے اور انصار مسجد کے پیچھے ٹھہرے۔ پھر باقی عام لوگ اپنی اپنی جگہوں میں ٹھہرے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Dawood (Vol.2 Pg.490). Ibn Sa'd (Vol.2 Pg.185), Ahmad and Nasa'ee have reported similar narrations."]]},{"b":[["n",[["حضرت رافع بن عمرو مزنیؓ","b"],[" فرماتے ہیں جب سورج بلند ہو گیا تو میں نے حضورؐ کو منیٰ میں خاکستری رنگ کے خچر پر لوگوں میں بیان کرتے ہوئے سنا اور حضرت علیؓ آپؐ کی بات لوگوں کو آگے پہنچا رہے تھے اور لوگ کچھ کھڑے تھے اور کچھ بیٹھے۔",""],[" (11)","s"]]]],"f":[["(11)","Abu Dawood, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.198)."]]},{"b":[["n",[["حضرت ابوحرہ رقاشیؒ","b"],[" اپنے چچاؓ سے نقل کرتے ہیں کہ میں ایام تشریق کے درمیانی دنوں میں حضورؐ کی اونٹنی کی نکیل پکڑے ہوئے تھا اور لوگوں کو آپؐ سے ہٹا رہا تھا تو آپؐ نے فرمایا اے لوگو! کیا تم جانتے ہو کہ یہ کون سا مہینہ ہے؟ اور کون سا دن ہے؟ اور کون سا شہر ہے؟ صحابہؓ نے عرض کیا دن بھی قابل احترام ہے اور مہینہ بھی قابل احترام ہے اور شہر بھی۔ آپؐ نے فرمایا بیشک تمہارے خون، تمہارے مال اور تمہاری عزتیں تمہارے لیے ایسے ہی قابل احترام ہیں جیسے یہ دن، یہ مہینہ اور یہ شہر قابل احترام ہے اور یہ حکم ",""],["ٱللَّٰه","a"],[" سے ملاقات تک کے لیے ہے یعنی زندگی بھر کے لیے ہے۔ پھر آپؐ نے فرمایا میری بات سنو تو زندہ رہو گے۔ خبردار ظلم نہ کرنا، خبردار ظلم نہ کرنا، خبردار ظلم نہ کرنا۔ کسی مسلمان کا مال اس کی رضامندی کے بغیر لینا جائز نہیں ہے۔ غور سے سنو! زمانہ جاہلیت کا ہر خون، ہر مال اور ہر قابل فخر کام میرے اس قدم کے نیچے قیامت تک کے لیے رکھا ہوا ہے یعنی ہمیشہ کے لیے ختم کر دیا گیا ہے اور سب سے پہلے ربیعہ بن حارث بن عبدالمطلب کا خون ختم کیا جاتا ہے جو بنو سعد میں دودھ پی رہا تھا اور قبیلہ ہذیل نے اسے قتل کر دیا تھا۔ غور سے سنو! زمانہ جاہلیت کا ہر سود ختم کیا جائے گا، تمہیں تمہارا اصل سرمایہ ملے گا۔ نہ تم کسی پر ظلم کرو گے اور نہ کوئی تم پر ظلم کرے گا۔ غور سے سنو! جس دن ",""],["ٱللَّٰه","a"],[" نے آسمانوں اور زمین کو پیدا فرمایا تھا اس دن والی حالت پر زمانہ گھوم کر پھر آ گیا ہے۔ پھر آپؐ نے یہ آیت پڑھی",""]]],["q",[["إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ شَهْرًا فِي كِتَٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ مِنْهَآ أَرْبَعَةٌ حُرُمٌ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ ۚ فَلَا تَظْلِمُوا۟ فِيهِنَّ أَنفُسَكُمْ","a"]]],["p",[["ترجمہ: \"یقیناً شمار مہینوں کا (جو کتاب الٰہی میں) ",""],["ٱللَّٰه","a"],[" کے نزدیک (معتبر ہیں) بارہ مہینے (قمری) ہیں جس روز ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آسمان اور زمین پیدا کیے تھے (اسی روز سے) ان میں چار خاص مہینے ادب کے ہیں، یہی (امر مذکور) دین مستقیم ہے، سو تم ان سب مہینوں کے بارے میں (دین کے خلاف کر کے) اپنا نقصان مت کرنا۔\" (سورت توبہ آیت ۳۶) توجہ سے سنو! میرے بعد تم کافر نہ ہو جانا کہ تم ایک دوسرے کی گردن اڑانے لگو۔ غور سے سنو! شیطان اس بات سے ناامید ہو گیا ہے کہ نمازی لوگ یعنی مسلمان اس کی عبادت کریں، البتہ وہ تمہیں آپس میں لڑانے کی کوشش میں لگا رہتا ہے۔ اور عورتوں کے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ وہ عورتیں تمہارے پاس قیدی ہیں کیونکہ انہیں اپنی ذات کے بارے میں کوئی اختیار نہیں ہے۔ ان کے بھی تمہارے اوپر حق ہیں اور تمہارے بھی ان کے اوپر حق ہیں، ان میں سے ایک حق یہ ہے کہ تمہارے علاوہ کسی کو تمہارا بستر نہ روندنے دیں اور جس کا آنا تمہیں برا لگے اسے گھر میں آنے کی اجازت نہ دیں۔ اگر تمہیں ان کی نافرمانی کا ڈر ہو تو انہیں سمجھاؤ، وعظ و نصیحت کرو اور بستروں پر انہیں تنہا چھوڑ دو اور انہیں اس طرح مارو کہ زیادہ تکلیف نہ ہو اور دستور کے مطابق کھانا کپڑا ان کا حق ہے۔ ",""],["ٱللَّٰه","a"],[" کی امانت سے تم نے انہیں لیا ہے یعنی تم ان کے امین ہو مالک نہیں اور ",""],["ٱللَّٰه","a"],[" کے مقرر کردہ طریقہ سے یعنی نکاح کے ایجاب و قبول سے وہ تمہارے لیے حلال ہوئی ہیں۔ غور سے سنو! جس کے پاس کوئی امانت ہے تو وہ اسے اس آدمی کو واپس کر دے جس نے اس کے پاس امانت رکھوائی تھی۔ پھر آپؐ نے ہاتھ پھیلا کر فرمایا غور سے سنو! میں نے (",""],["ٱللَّٰه","a"],[" کا سارا دین) پہنچا دیا ہے۔ غور سے سنو! میں نے پہنچا دیا ہے اور حاضرین اب غیر حاضر لوگوں تک پہنچائیں کیونکہ بعض دفعہ جسے بات پہنچائی جاتی ہے وہ براہ راست سننے والے سے زیادہ نیک بخت ہوتا ہے۔ حضرت حمیدؒ کہتے ہیں حضرت حسن بصریؒ جب حدیث کے اس مضمون پر پہنچتے تو فرماتے ",""],["ٱللَّٰه","a"],[" کی قسم! صحابہ کرامؓ نے دین ایسے لوگوں کو پہنچایا جو دین کی وجہ سے بہت زیادہ نیک بخت ہو گئے۔",""],[" (12)","s"]]]],"f":[["(12)","Ahmad."]]},{"b":[["n",[["بزار میں ",""],["حضرت ابن عمرؓ","b"],[" سے اسی کے ہم معنی حدیث منقول ہے۔ اس کے شروع میں یہ بھی ہے کہ حجۃ الوداع کے سفر میں ایام تشریق کے درمیانی دنوں میں منیٰ میں حضورؐ پر یہ سورت نازل ہوئی",""]]],["q",[["إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","a"]]],["p",[["ترجمہ: \"(اے محمدؐ!) جب خدا کی مدد اور (مکہ کی) فتح (مع اپنے آثار کے) آ پہنچے۔\" (سورت نصر) اس سورت سے آپؐ سمجھ گئے کہ اب آپؐ کے دنیا سے جانے کا وقت آ گیا ہے، اس لیے آپؐ کے فرمانے پر آپؐ کی قصواء اونٹنی پر کجاوہ رکھا گیا۔ آپؐ اس پر سوار ہو کر گھاٹی پر آ کر لوگوں کے لیے کھڑے ہوئے جس پر بے شمار مسلمان وہاں جمع ہو گئے۔ آپؐ نے حمد و ثناء کے بعد فرمایا اما بعد! اے لوگو! جاہلیت کا ہر خون ختم کر دیا ہے۔ اس حدیث میں آگے یہ بھی ہے اے لوگو! شیطان اس بات سے تو ناامید ہو گیا ہے کہ تمہارے علاقے میں آخری وقت تک اس کی عبادت کی جائے لیکن وہ تم سے اس بات پر راضی ہو جائے گا کہ تم چھوٹے موٹے گناہ کرو، اس لیے تم شیطان سے چوکنے ہو کر رہو، اپنے دین پر پکے رہو اور چھوٹے موٹے گناہ کر کے اسے خوش نہ کرو۔ اور اس روایت میں یہ بھی ہے کہ اے لوگو! میں تم میں ایسی چیز چھوڑ کر جا رہا ہوں کہ اگر تم اسے پکڑے رہو گے تو کبھی گمراہ نہیں ہو گے اور وہ ہے ",""],["ٱللَّٰه","a"],[" کی کتاب۔ لہٰذا تم اس پر عمل کرو۔ اور اس روایت کے آخر میں یہ ہے کہ توجہ سے سنو! تمہارے حاضرین غائبین تک پہنچائیں، میرے بعد کوئی نبی نہیں ہے اور تمہارے بعد کوئی امت نہیں ہے۔ پھر آپؐ نے ہاتھ اٹھا کر فرمایا اے ",""],["ٱللَّٰه","a"],["! گواہ ہو جا۔",""],[" (13)","s"]]]],"f":[["(13)","The narration of Ibn Umar has been mentioned in full in Al Bidaayah wan Nihaayah (Vol.5 Pg.202). Baghawi and Baawardi have reported the narration of Abu Harrah Raqaashi from his uncle, and Ibn Mardawayh has also reported it in full, as quoted in Kanzul Ummaal (Vol.3 Pg.26)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں ایام تشریق کے درمیانی دنوں میں حضورؐ نے ہم لوگوں میں حجۃ الوداع کا بیان فرمایا، ارشاد فرمایا اے لوگو! تمہارا رب ایک ہے اور تمہارا باپ بھی ایک ہے یعنی حضرت آدم علیہ السلام۔ غور سے سنو! کسی عربی کو عجمی پر اور کسی عجمی کو عرب پر کوئی فضیلت نہیں اور کسی سرخ انسان کو کالے پر اور کسی کالے کو سرخ پر کوئی فضیلت نہیں۔ ایک انسان کو دوسرے انسان پر صرف تقویٰ سے فضیلت ہو سکتی ہے۔ تم میں سے ",""],["ٱللَّٰه","a"],[" کے ہاں سب سے زیادہ شرافت والا وہ ہے جو سب سے زیادہ تقویٰ والا ہے۔ توجہ سے سنو! کیا میں نے (",""],["ٱللَّٰه","a"],[" کا دین سارا) پہنچا دیا ہے؟ صحابہؓ نے کہا بالکل یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے فرمایا اب حاضرین غائبین تک پہنچائیں۔",""],[" (14)","s"]]]],"f":[["(14)","Bayhaqi, who said that in its chain are some unknown narrators, as quoted in Targheeb wat Tarheeb (Vol.4 Pg.392)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں حضورؐ عرفات میں اپنی کان کٹی ہوئی اونٹنی پر کھڑے ہوئے اور فرمایا کیا تم لوگ جانتے ہو یہ کون سا دن ہے؟ یہ کون سا مہینہ ہے؟ یہ کون سا شہر ہے؟ صحابہؓ نے کہا یہ قابل احترام شہر اور قابل احترام مہینہ اور قابل احترام دن ہے۔ آپؐ نے فرمایا غور سے سنو! تمہارے مال اور تمہارے خون تمہارے لیے اسی طرح قابل احترام ہیں جیسے تمہارا یہ مہینہ، تمہارا یہ شہر اور تمہارا یہ دن قابل احترام ہے۔ میں تمہاری ضرورتوں کے لیے تم سے پہلے آگے جا رہا ہوں اور حوض (کوثر) پر تمہیں ملوں گا اور میں تمہاری تعداد کے زیادہ ہونے کی وجہ سے دوسری امتوں پر فخر کروں گا۔ لہٰذا (برے اعمال کر کے کل قیامت کے دن) میرا منہ کالا نہ کرنا۔ غور سے سنو! (کل قیامت کے دن) میں بہت سے لوگوں کو (شفاعت کر کے دوزخ سے) چھڑا لوں گا لیکن کچھ لوگوں کو مجھ سے چھڑا لیا جائے گا (فرشتے چھڑا کر دور لے جائیں گے)، میں کہوں گا اے میرے رب! یہ تو میرے ساتھی ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے تمہیں معلوم نہیں انہوں نے تمہارے بعد کیا کیا کرتوت کیے تھے (اس سے وہ لوگ مراد ہیں جو حضورؐ کے زمانہ میں مسلمان تھے لیکن حضورؐ کی وفات پر مرتد ہو گئے)۔",""],[" (15)","s"]]]],"f":[["(15)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.3 Pg.25)."]]}]},"161":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرؓ","b"],[" فرماتے ہیں ہم لوگ حجۃ الوداع کے بارے میں (حج سے پہلے) باتیں تو کرتے تھے (کہ ہم لوگ حضورؐ کے ساتھ حج کریں گے وغیرہ) لیکن ہمیں یہ خبر نہیں تھی کہ حضورؐ (اپنی امت کو) الوداع فرمانے کے لیے حج کر رہے ہیں۔ چنانچہ اسی سفر حجۃ الوداع میں حضورؐ نے ایک بیان میں مسیح دجال کا ذکر کیا اور بہت تفصیل سے اس کے بارے میں گفتگو فرمائی پھر فرمایا ",""],["ٱللَّٰه","a"],[" نے جس نبی کو بھیجا اس نے اپنی امت کو دجال سے ضرور ڈرایا۔ حضرت نوح علیہ السلام اور ان کے بعد کے سارے نبیوں نے اس سے ڈرایا ہے لیکن اس کی ایک بات ابھی تک بہت لوگوں سے مخفی ہے اور وہ تم لوگوں سے مخفی نہیں رہنی چاہیے (کہ وہ کانا ہوگا) اور تمہارا رب تبارک و تعالیٰ کانا نہیں ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad; Haythami (Vol.7 Pg.338) has said that its narrators are those of authentic Ahaadeeth, and some parts are in the Saheeh."]]},{"b":[["n",[["حضرت سفینہؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ہم میں بیان فرمایا اور ارشاد فرمایا مجھ سے پہلے ہر نبی نے اپنی امت کو دجال سے ڈرایا ہے۔ اس کی بائیں آنکھ کانی ہے اور اس کی دائیں آنکھ میں ناک کی طرف والے گوشہ میں گوشت کا ایک موٹا سا ٹکڑا ہوگا جو آنکھ کی سیاہی پر چڑھا ہوا ہوگا۔ اس کی دونوں آنکھوں کے درمیان کافر لکھا ہوا ہوگا۔ اس کے ساتھ دو وادیاں بھی ہوں گی۔ ایک جنت نظر آئے گی اور دوسری دوزخ لیکن اس کی جنت حقیقت میں دوزخ ہوگی اور اس کی دوزخ جنت ہوگی اور اس کے ساتھ دو فرشتے ہوں گے جو انبیاء علیہم السلام میں سے دو نبیوں کے مشابہ ہوں گے۔ ایک فرشتہ دجال کے دائیں طرف ہوگا اور دوسرا بائیں طرف اور اس میں لوگوں کی آزمائش ہوگی۔ دجال کہے گا کیا میں تمہارا رب نہیں ہوں؟ کیا میں مارتا ہوں اور زندہ کرتا ہوں؟ اس پر ایک فرشتہ کہے گا تو غلط کہتا ہے، اس جملہ کو اس کا ساتھی فرشتہ سن سکے گا اور کوئی نہیں سنے گا۔ دوسرا فرشتہ پہلے فرشتہ کو جواب میں کہے گا تم نے ٹھیک کہا، اس جملہ کو تمام لوگ سن لیں گے۔ اس سے لوگ یہ سمجھیں گے کہ یہ فرشتہ اس دجال کی تصدیق کر رہا ہے۔ یہ بھی آزمائش کی ایک صورت ہوگی۔ پھر وہ دجال چلے گا اور چلتے چلتے مدینہ پہنچ جائے گا لیکن اسے مدینہ کے اندر جانے کی اجازت نہیں ہوگی۔ پھر وہ کہے گا یہ تو اس عظیم ہستی (یعنی حضرت محمدؐ) کی بستی ہے۔ پھر وہ وہاں سے چل کر ملک شام پہنچے گا اور افیق مقام کی گھاٹی کے پاس ",""],["ٱللَّٰه","a"],[" اسے ہلاک کر دیں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad and Tabraani, the wording being Tabraani's; Haythami (Vol.7 Pg.340) has said that its narrators are reliable, and that in some of them there is a criticism that does no harm."]]},{"b":[["n",[["حضرت جنادہ بن ابی امیہ ازدیؒ","b"],[" کہتے ہیں میں اور ایک انصاری ہم دونوں نبی کریمؐ کے ایک صحابیؓ کی خدمت میں گئے اور ان سے عرض کیا ہمیں آپ کوئی ایسی حدیث بیان کریں جو آپ نے حضورؐ سے سنی ہو اور اس میں حضورؐ نے دجال کا ذکر کیا ہو۔ انہوں نے فرمایا ایک مرتبہ حضورؐ نے ہم لوگوں میں بیان فرمایا، اس میں ارشاد فرمایا میں تمہیں دجال سے ڈراتا ہوں۔ یہ جملہ تین دفعہ فرمایا پھر فرمایا کوئی نبی ایسا نہیں آیا جس نے دجال سے نہ ڈرایا ہو۔ اے امت والو! وہ تم میں ہوگا، وہ ٹھگنا، گھنگریالے بالوں والا اور گندمی رنگ والا ہوگا۔ اس کی بائیں آنکھ پر ہاتھ پھرا ہوا ہوگا اور وہ مٹی ہوئی ہوگی۔ اس کے ساتھ جنت اور دوزخ ہوگی اور اس کے ساتھ روٹی کے پہاڑ اور پانی کی نہر ہوگی۔ وہ بارش برسائے گا لیکن درخت نہیں اگا سکے گا اور وہ ایک آدمی پر غالب آ کر اسے قتل کر دے گا، اس کے علاوہ اور کسی کو قتل نہیں کر سکے گا۔ وہ زمین پر چالیس دن رہے گا اور پانی کے ہر گھاٹ پر پہنچے گا۔ چار مسجدوں کے قریب نہیں جا سکے گا: مسجد حرام، مسجد مدینہ، مسجد طور اور مسجد اقصیٰ۔ اور تم پر دجال مشتبہ نہیں ہونا چاہیے، وہ (کانا ہوگا) اور تمہارا رب کانا نہیں ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad; Haythami (Vol.7 Pg.343) has said that its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت ابوامامہ باہلیؓ","b"],[" فرماتے ہیں حضورؐ نے ایک دن ہم لوگوں میں بیان فرمایا۔ اس بیان میں آپؐ نے زیادہ تر دجال کے بارے میں گفتگو فرمائی اور جب دجال کا ذکر شروع کیا تو پھر آخر تک اسی کے بارے میں گفتگو فرماتے رہے۔ اس دن آپؐ نے جو کچھ ہم سے فرمایا اس میں یہ بھی تھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو بھی نبی بھیجا اس نے اپنی امت کو دجال سے ضرور ڈرایا اور میں آخری نبی ہوں اور تم آخری امت ہو اور وہ یقیناً تم میں ہی ظاہر ہوگا۔ اگر میں تم میں موجود ہوا اور وہ ظاہر ہوا تو میں ہر مسلمان کی طرف سے دلائل سے اس کا مقابلہ کر لوں گا اور اگر میرے بعد تم لوگوں میں ظاہر ہوا تو پھر ہر آدمی خود اپنی طرف سے اس کا مقابلہ کرے اور ",""],["ٱللَّٰه","a"],[" ہی ہر مسلمان کا میری طرف سے خلیفہ ہے۔ اور دجال عراق اور شام کے درمیان ایک راستہ میں ظاہر ہوگا اور دائیں بائیں لشکر بھیج کر فساد برپا کرے گا۔ اے ",""],["ٱللَّٰه","a"],[" کے بندو! جمے رہنا، کیونکہ پہلے وہ کہے گا میں نبی ہوں حالانکہ میرے بعد کوئی نبی نہیں آئے گا۔ پھر وہ کہے گا میں تمہارا رب ہوں حالانکہ تم میں سے کوئی بھی اپنے رب کو مرنے سے پہلے نہیں دیکھ سکتا۔ اور اس کی دونوں آنکھوں کے درمیان کافر لکھا ہوا ہوگا جسے ہر مومن پڑھ لے گا، لہٰذا تم میں سے جو اس سے ملے وہ اس کے چہرے پر تھوک دے اور سورت کہف کی شروع کی آیتیں پڑھے۔ وہ ایک آدمی پر غلبہ پا کر پہلے اسے قتل کرے گا پھر اسے زندہ کرے گا لیکن اس کے بعد کسی اور کے ساتھ ایسا نہیں کر سکے گا۔ اس کا ایک فتنہ یہ ہوگا کہ اس کے ساتھ جنت اور دوزخ ہوگی۔ اس کی دوزخ جنت ہوگی اور اس کی جنت دوزخ ہوگی، لہٰذا تم میں سے جو اس کی دوزخ میں ڈالے جانے کی آزمائش میں مبتلا ہو اسے چاہیے کہ وہ اپنی آنکھیں بند کر لے اور ",""],["ٱللَّٰه","a"],[" سے مدد مانگے تو دوزخ کی آگ اس کے لیے ایسے ٹھنڈی اور سلامتی والی ہو جائے گی جیسے حضرت ابراہیمؑ کے لیے ہو گئی تھی۔ اس کا ایک فتنہ یہ بھی ہوگا کہ وہ ایک قبیلے کے پاس سے گزرے گا، وہ سب اس پر ایمان لے آئیں گے اور اس کی تصدیق کریں گے تو وہ ان کے لیے دعا کرے گا تو اسی دن ان کے لیے آسمان سے بارش ہوگی اور اسی دن ان کی ساری زمین سرسبز و شاداب ہو جائے گی اور اس دن شام کو ان کے جانور چر کر واپس آئیں گے تو وہ بہت موٹے ہو چکے ہوں گے اور ان کے پیٹ خوب بھرے ہوئے ہوں گے اور ان کے تھنوں سے خوب دودھ بہہ رہا ہوگا۔ اور دوسرے قبیلہ کے پاس سے گزرے گا، وہ اس کا انکار کر دیں گے اور اسے جھٹلائیں گے تو وہ ان کے خلاف بددعا کرے گا جس سے ان کے سارے جانور مر جائیں گے اور ایک بھی جانور ان کے پاس نہیں رہے گا۔ اس دنیا میں وہ کل چالیس دن رہے گا جن میں سے ایک دن ایک سال کے برابر ہوگا اور ایک دن ایک مہینہ کے برابر ہوگا اور ایک دن ایک ہفتہ کے برابر ہوگا اور ایک دن عام دنوں جیسا ہوگا۔ اور اس کا آخری دن سراب کی طرح بہت مختصر ہوگا، اتنا مختصر کہ آدمی صبح مدینہ کے ایک دروازے پر ہوگا اور دوسرے دروازے تک پہنچنے سے پہلے ہی شام ہو جائے گی۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان چھوٹے دنوں میں ہم نمازیں کیسے پڑھیں گے؟ آپؐ نے فرمایا تم ان چھوٹے دنوں میں وقت کا اندازہ لگا کر ایسے ہی نمازیں پڑھ لینا جیسے لمبے دنوں میں اندازے سے پڑھو گے۔",""],[" (4)","s"]]]],"f":[["(4)","Haakim (Vol.4 Pg.536), who said that this hadith is authentic on the conditions of Muslim although they did not report it in this form, and Dhahabi agreed."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضورؐ نے ایک دن منبر پر کھڑے ہو کر فرمایا اے لوگو! میں نے تم لوگوں کو آسمان سے آنے والی (نئی) خبر کی وجہ سے جمع نہیں کیا۔ اس کے بعد آپؐ نے جساسہ کا ذکر کیا یعنی دجال کے لیے جاسوسی کرنے والی چیز کا اور اس حدیث میں یہ بھی ہے کہ وہ مسیح ہے۔ چالیس دن میں اس کے لیے ساری زمین لپیٹ دی جائے گی لیکن وہ طیبہ میں داخل نہیں ہو سکے گا۔ حضورؐ نے فرمایا طیبہ سے مراد مدینہ ہے۔ اس کے ہر دروازے پر تلوار سونتے ہوئے ایک فرشتہ ہوگا جو دجال کو اس میں جانے سے روکے گا اور مکہ میں بھی اسی طرح ہوگا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Ya'la; Haythami (Vol.7 Pg.346) has said that the narrators of both its chains are those of authentic Ahaadeeth."]]},{"b":[["n",[["بصرہ والوں میں سے ",""],["حضرت ثعلبہ بن عباد عبدیؒ","b"],[" کہتے ہیں میں ایک دن حضرت سمرہ بن جندبؓ کے بیان میں شریک ہوا، انہوں نے اپنے بیان میں حضورؐ کی طرف سے ایک حدیث بیان کی اور سورج گرہن والی حدیث بھی ذکر کی، اس میں یہ بھی فرمایا کہ جب حضورؐ دوسری رکعت میں بیٹھ گئے تو اس وقت سورج صاف ہوا اور اس کا گرہن ختم ہوا۔ سلام پھیرنے کے بعد آپؐ نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور اس بات کی گواہی دی کہ آپ ",""],["ٱللَّٰه","a"],[" کے بندے اور رسول ہیں پھر فرمایا اے لوگو! میں تمہیں ",""],["ٱللَّٰه","a"],[" کا واسطہ دے کر کہتا ہوں اگر تمہیں معلوم ہے کہ میں نے اپنے رب کے پیغامات پہنچانے میں کوئی کمی کی ہے تو مجھے ضرور بتاؤ۔ اس پر بہت سے آدمیوں نے کھڑے ہو کر کہا ہم اس بات کی گواہی دیتے ہیں کہ آپ نے اپنے رب کے تمام پیغام پہنچا دیے ہیں اور اپنی امت کی پوری خیر خواہی کی ہے اور جو کام ",""],["ٱللَّٰه","a"],[" آپ کے ذمہ تھا وہ پورا کر دیا ہے۔ پھر آپؐ نے فرمایا اما بعد! بہت سے لوگوں کا یہ خیال ہے کہ چاند سورج کا گرہن ہونا اور ستاروں کا اپنے نکلنے کی جگہ سے ہٹ جانا زمین کے کسی بڑے آدمی کے مرنے کی وجہ سے ہوتا ہے، یہ خیال بالکل غلط ہے۔ یہ گرہن تو ",""],["ٱللَّٰه","a"],[" کی قدرت کی نشانیوں میں سے ایک نشانی ہے جس کے ذریعہ ",""],["ٱللَّٰه","a"],[" اپنے بندوں کا امتحان لیتے ہیں اور دیکھتے ہیں کہ کون اس نشانی کو دیکھ کر کفر اور گناہوں سے توبہ کر لیتا ہے۔ اور میں نے جتنے وقت میں کھڑے ہو کر نماز اور گرہن کی نماز پڑھائی ہے اس میں میں نے دنیا اور آخرت میں تمہیں جو کچھ پیش آئے گا وہ سب دیکھ لیا ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! قیامت اس وقت تک قائم نہیں ہوگی جب تک تیس جھوٹے ظاہر نہ ہو جائیں گے جن میں آخری کانا دجال ہوگا۔ اس کی بائیں آنکھ مٹی ہوئی ہوگی، بالکل ایسی آنکھ جیسی ابویحییٰ کی آنکھ۔ حضرت ابویحییٰؓ انصار کے ایک بڑے میاں تھے جو اس وقت حضورؐ کے اور حضرت عائشہؓ کے حجرے کے درمیان بیٹھے ہوئے تھے۔ پھر حضورؐ نے فرمایا جب وہ ظاہر ہوگا تو دعویٰ کرے گا کہ وہ ",""],["ٱللَّٰه","a"],[" ہے، جو اس پر ایمان لائے گا، اس کی تصدیق کرے گا اور اس کا اتباع کرے گا اسے اس کا گزشتہ کوئی نیک عمل فائدہ نہیں دے گا اور جو اس کا انکار کرے گا اور اس کو جھٹلائے گا اس کو اس کے کسی عمل پر کوئی سزا نہیں دی جائے گی اور حرم اور بیت المقدس کے علاوہ باقی ساری زمین پر ہر جگہ جائے گا اور مسلمان بیت المقدس میں محصور ہو جائیں گے، پھر ان پر زبردست زلزلہ آئے گا پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ دجال کو ہلاک کریں گے یہاں تک کہ دیوار اور درخت کی جڑ آواز دے گی اے مومن! یہ یہودی ہے، یہ کافر ہے، آ اسے قتل کر۔ اور ایسا اس وقت تک نہیں ہوگا جب تک تم ایسی چیزیں نہ دیکھ لو جو تمہارے خیال میں بہت بڑی ہوں گی اور جن کے بارے میں تم ایک دوسرے سے پوچھو گے کہ کیا تمہارے نبی نے اس چیز کے بارے میں کچھ ذکر کیا ہے؟ اور (ایسا اس وقت تک نہیں ہوگا) جب تک کہ کچھ پہاڑ اپنی جگہ سے ہٹ نہ جائیں، پھر اس کے فوراً بعد عام موت ہوگی یعنی قیامت قائم ہوگی۔ حضرت ثعلبہؒ کہتے ہیں اس کے بعد میں نے حضرت سمرہؓ کا ایک اور بیان سنا، اس میں انہوں نے یہی حدیث ذکر کی اور ایک لفظ بھی آگے پیچھے نہیں کیا۔ احمد اور بزار کی روایت میں یہ بھی ہے کہ جو ",""],["ٱللَّٰه","a"],[" کو مضبوطی سے پکڑے گا اور کہے گا میرا رب ",""],["ٱللَّٰه","a"],[" ہے جو زندہ ہے اسے موت نہیں آ سکتی، اس پر (دجال کے) عذاب کا کوئی اثر نہیں ہوگا اور جو (دجال سے) کہے گا تو میرا رب ہے وہ فتنہ میں مبتلا ہو گیا۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Ahmad. Bazzaar has also reported it, as quoted by Haythami (Vol.7 Pg.341), who said that its narrators are those of authentic Ahaadeeth except Ibn Ubaadah whom Ibn Hibbaan has declared reliable."],["(7)","Ahmad and Tabraani; Haythami (Vol.7 Pg.332) has said that one chain of Ahmad and Tabraani has narrators who are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت ابوبکرہؓ","b"],[" فرماتے ہیں حضورؐ کے کچھ فرمانے سے پہلے ہی لوگوں نے مسیلمہ کے بارے میں بہت باتیں کیں، پھر حضورؐ بیان کے لیے کھڑے ہوئے اور فرمایا اما بعد! اس آدمی کے بارے میں تم لوگ بہت باتیں کر چکے ہو، یہ پکا جھوٹا ہے اور ان تیس جھوٹوں میں سے ہے جو قیامت سے پہلے ظاہر ہوں گے اور ہر شہر میں مسیح (دجال) کا رعب پہنچ جائے گا۔ ایک روایت میں اس کے بعد یہ ہے کہ لیکن مدینہ میں دجال مسیح کا رعب داخل نہیں ہو سکے گا کیونکہ اس کے ہر راستہ پر دو فرشتے ہوں گے جو دجال مسیح کے رعب کو مدینہ سے روکنے والے ہوں گے۔",""],[" (8)","s"]]]],"f":[["(8)","Haakim (Vol.4 Pg.541)."]]},{"b":[["n",[["حضرت خالد بن عبد","b"],["ٱللَّٰه","a"],[" بن حرملہؒ","b"],[" اپنی خالہ سے نقل کرتے ہیں، ان کی خالہ فرماتی ہیں حضورؐ نے بچھو کے ڈنک مارنے کی وجہ سے سر پر پٹی باندھ رکھی تھی، اسی حالت میں آپؐ نے بیان فرمایا اور ارشاد فرمایا تم لوگ کہتے ہو اب کوئی دشمن باقی نہیں رہا لیکن تم لوگ دشمنوں سے جنگ کرتے رہو گے یہاں تک کہ یاجوج ماجوج ظاہر ہوں گے جن کے چہرے چپٹے، آنکھیں چھوٹی، بال سفید مائل بسرخی ہوں گے۔ وہ ہر اونچی جگہ سے دوڑتے چلے آئیں گے۔ ان کے چہرے ایسے ہوں گے جیسے وہ ڈھال جس پر کھال چڑھائی گئی ہو۔",""],[" (9)","s"]]]],"f":[["(9)","Ahmad and Tabraani; Haythami (Vol.8 Pg.6) has said that the narrators of both are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت قعقاعؓ کی بیوی ",""],["حضرت بقیرہؓ","b"],[" فرماتی ہیں میں عورتوں کے صفہ (چبوترہ) میں بیٹھی ہوئی تھی، میں نے حضورؐ کو بیان فرماتے ہوئے سنا۔ آپؐ بائیں ہاتھ سے اشارہ کرتے ہوئے فرما رہے تھے اے لوگو! جب تم سنو کہ اس طرف یعنی مغرب کی طرف کچھ لوگ زمین میں دھنس گئے ہیں تو سمجھ لو کہ قیامت آ گئی ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Ahmad and Tabraani; Haythami (Vol.8 Pg.9) has said that in its chain is Ibn Is'haaq who is a mudallis, while the rest of the narrators of one of Ahmad's chains are those of authentic Ahaadeeth."]]}]},"162":{"lead":[],"stories":[{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ایسی اونچی آواز سے بیان فرمایا کہ گھروں میں پردے میں بیٹھی ہوئی جوان لڑکیوں نے بھی سن لیا۔ آپؐ نے فرمایا اے وہ لوگو! جو زبان سے ایمان لائے ہیں اور ابھی ایمان ان کے دل میں داخل نہیں ہوا، مسلمانوں کی غیبت نہ کیا کرو اور ان کے چھپے عیوب تلاش نہ کیا کرو کیونکہ جو اپنے بھائی کے پوشیدہ عیب تلاش کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے عیب تلاش کرے گا اور ",""],["ٱللَّٰه","a"],[" جس کے پوشیدہ عیب تلاش کرنے لگے گا اسے اس کے گھر کے بیچ میں بھی رسوا کر کے چھوڑے گا۔ طبرانی میں حضرت ابن عباسؓ سے اسی جیسی روایت منقول ہے لیکن اس کے الفاظ یہ ہیں کہ ایمان والوں کو تکلیف نہ پہنچاؤ اور ان کی چھپی ہوئی خرابیاں تلاش نہ کرو کیونکہ جو اپنے مسلمان بھائی کی چھپی ہوئی خرابی تلاش کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کا پردہ پھاڑ دیں گے اور اسے رسوا کر دیں گے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Abu Ya'la; Haythami (Vol.8 Pg.93) has said that its narrators are reliable."],["(2)","Haythami (Vol.8 Pg.94) has said that its narrators are reliable. Bayhaqi has reported a similar narration from Baraa, as quoted in Kanzul Ummaal (Vol.8 Pg.300)."]]}]},"163":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ نبی کریمؐ میرے پاس تشریف لائے تو میں نے چہرہ انور پر خاص اثر دیکھ کر محسوس کیا کہ کوئی اہم بات پیش آئی ہے۔ حضورؐ نے کسی سے کوئی بات نہ فرمائی بلکہ وضو فرما کر مسجد میں تشریف لے گئے اور میں حجرہ کی دیوار سے لگ کر سننے کھڑی ہو گئی کہ کیا ارشاد فرماتے ہیں۔ حضورؐ منبر پر بیٹھ گئے اور حمد و ثناء کے بعد فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں فرماتے ہیں امر بالمعروف اور نہی عن المنکر کرتے رہو، مبادا وہ وقت آ جائے کہ تم دعا کرو اور میں قبول نہ کروں اور تم سوال کرو اور میں اسے پورا نہ کروں، تم اپنے دشمنوں کے خلاف مدد چاہو اور میں تمہاری مدد نہ کروں۔ بس اتنا ہی بیان فرمایا اور منبر سے نیچے تشریف لے آئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Majah and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.4 Pg.121). Ahmad and Bazzaar have reported a similar narration, as quoted in Majma'uz Zawaa'id (Vol.7 Pg.266)."]]}]},"164":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ہم لوگوں میں بیان فرمایا، اس میں ارشاد فرمایا ظلم سے بچو کیونکہ قیامت کے دن یہ ظلم بہت سے اندھیرے ہوں گے اور بدکلامی اور تکلف سے بدکلامی کرنے سے بچو اور لالچ سے بچو کیونکہ تم سے پہلے لوگ لالچ میں آ کر بدکاری کے مرتکب ہوئے۔ پھر ایک آدمی نے کھڑے ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اسلام کا کون سا عمل سب سے افضل ہے؟ آپؐ نے فرمایا یہ کہ مسلمان تمہاری زبان اور ہاتھ سے محفوظ رہیں۔ اسی آدمی نے یا دوسرے نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ہجرت کی کون سی صورت سب سے افضل ہے؟ فرمایا یہ کہ تم ان کاموں کو چھوڑ دو جو تمہارے رب کو ناپسند ہیں۔ ہجرت دو طرح کی ہے، ایک شہر والوں کی ہجرت اور ایک دیہات والوں کی ہجرت۔ دیہات والوں کی ہجرت یہ ہے کہ (رہے تو اپنے دیہات میں لیکن) جب اسے (تقاضے کے لیے) بلایا جائے تو فوراً ہاں کہے اور جب اسے حکم دیا جائے تو اسے فوراً پورا کرے۔ شہر والوں کی ہجرت میں آزمائش بھی زیادہ ہے اور اجر بھی زیادہ (کیونکہ اپنا وطن ہمیشہ کے لیے چھوڑ کر مدینہ آ کر رہے گا اور دعوت کے تقاضوں میں ہر وقت چلے گا)۔ طبرانی میں حضرت ہرماس بن زیادؓ سے یہی حدیث مختصر طور سے منقول ہے لیکن اس کے شروع میں یہ ہے کہ خیانت سے بچو کیونکہ یہ بہت بری اندرونی صفت ہے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Haakim, who graded it authentic on the conditions of Muslim, the wording being his; Abu Dawood has reported it in abridged form, as quoted in Targheeb wat Tarheeb (Vol.4 Pg.158)."],["(2)","As quoted in Targheeb wat Tarheeb (Pg.267)."]]}]},"165":{"lead":[],"stories":[{"b":[["n",[["حضرت ایمن بن خریمؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے کھڑے ہو کر بیان فرمایا۔ آپؐ نے ارشاد فرمایا اے لوگو! جھوٹی گواہی ",""],["ٱللَّٰه","a"],[" کے ہاں شرک کے برابر شمار ہوتی ہے۔ یہ بات تین دفعہ ارشاد فرمائی پھر آپؐ نے یہ آیت تلاوت فرمائی",""]]],["q",[["فَٱجْتَنِبُوا۟ ٱلرِّجْسَ مِنَ ٱلْأَوْثَٰنِ وَٱجْتَنِبُوا۟ قَوْلَ ٱلزُّورِ","a"]]],["p",[["ترجمہ: \"تو تم لوگ گندگی سے یعنی بتوں سے (بالکل) کنارہ کش رہو اور جھوٹی بات سے کنارہ کش رہو۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Tirmidhi, Baghawi and Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.4 Pg.7)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ نے ہم میں بیان فرمایا اور سود کا ذکر فرمایا اور اسے بہت بڑا گناہ بتایا اور فرمایا آدمی سود میں جو ایک درہم لیتا ہے ",""],["ٱللَّٰه","a"],[" کے ہاں اس کا گناہ چھتیس مرتبہ زنا کرنے سے بھی زیادہ ہے اور سب سے بدترین سود مسلمان کی آبروریزی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Dunya, as quoted in Targheeb wat Tarheeb (Vol.4 Pg.282)."]]},{"b":[["n",[["حضرت ابوموسیٰ اشعریؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے ہم لوگوں میں بیان فرمایا، ارشاد فرمایا اے لوگو! شرک سے بچو کیونکہ شرک چیونٹی کی چال سے بھی زیادہ پوشیدہ ہے۔ اور ہو سکتا ہے کہ یہ بات سن کر کوئی یوں کہے یا رسول ",""],["ٱللَّٰه","a"],["! جب شرک چیونٹی کی چال سے بھی زیادہ پوشیدہ ہے تو ہم اس سے کیسے بچیں؟ فرمایا تم یہ دعا پڑھا کرو",""]]],["q",[["ٱللَّهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نُشْرِكَ بِكَ وَنَحْنُ نَعْلَمُهُ وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہم اس بات سے تیری پناہ چاہتے ہیں کہ ہمیں معلوم ہو کہ یہ شرک ہے اور ہم پھر تیرے ساتھ وہ شرک کریں اور جس شرک کا ہمیں پتہ ہی نہیں اس کی ہم معافی چاہتے ہیں۔\"",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.2 Pg.169)."]]}]},"166":{"lead":[],"stories":[{"b":[["n",[["حضرت نعمان بن بشیرؓ","b"],[" فرماتے ہیں حضورؐ نے اس منبر کی لکڑیوں پر ارشاد فرمایا جو تھوڑے پر شکر نہیں کرتا تو زیادہ پر بھی نہیں کر سکتا اور جو انسانوں کا شکر نہیں کرتا تو ",""],["ٱللَّٰه","a"],[" کا بھی شکر نہیں کر سکتا اور ",""],["ٱللَّٰه","a"],[" کی نعمتوں کو بیان کرنا بھی شکر ہے اور انہیں بیان نہ کرنا ناشکری ہے۔ آپس کا جوڑ سراسر رحمت سے اور آپس کا توڑ عذاب ہے۔ راوی کہتے ہیں حضرت ابوامامہ باہلیؓ نے کہا تم سواد اعظم سے چمٹے رہو یعنی علماء حق سے جڑے رہو۔ یہ آیت",""]]],["q",[["فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ","a"]]],["p",[["ترجمہ: \"پھر اگر تم لوگ (اطاعت سے) روگردانی کرو گے تو سمجھ رکھو کہ رسول کے ذمہ وہی (تبلیغ) ہے جس کا ان پر بار رکھا گیا ہے اور تمہارے ذمہ وہ ہے جس کا تم پر بار رکھا گیا ہے اور اگر تم نے ان کی اطاعت کر لی تو راہ پر جا لگو گے۔\" (سورت نور آیت ۵۴) یعنی ماننے سے منافقوں کا اپنا ہی نقصان ہوگا، رسول ",""],["ٱللَّٰه","a"],["ؐ کا نہیں ہوگا کیونکہ ہم نے ان کے ذمہ جو کام لگایا تھا انہوں نے پورا کر دیا، اس لیے یہ تو کامیاب ہیں، منافق مانیں یا نہ مانیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abdullah bin Ahmad, Bazzaar and Tabraani; Haythami (Vol.5 Pg.218) has said that their narrators are reliable."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو بیان فرماتے ہوئے سنا۔ بیان میں آپؐ نے یہ آیت پڑھی",""]]],["q",[["ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا ۚ وَقَلِيلٌ مِّنْ عِبَادِيَ ٱلشَّكُورُ","a"]]],["p",[["ترجمہ: \"اے داؤد کے خاندان والو! تم سب شکریہ میں نیک کام کیا کرو اور میرے بندوں میں شکر گزار کم ہی ہوتے ہیں۔\" (سورت سبا آیت ۱۳) پھر آپؐ نے فرمایا جسے تین خوبیاں مل گئیں اسے اتنا مل گیا جتنا داؤد علیہ السلام کو ملا تھا۔ لوگوں کے سامنے بھی اور چھپ کر بھی ہر حال میں ",""],["ٱللَّٰه","a"],[" سے ڈرنا، خوشی اور غصہ دونوں حالتوں میں انصاف سے کام لینا، فقر اور غنا دونوں حالتوں میں میانہ روی۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.226)."]]}]},"167":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ نے ایک مرتبہ بیان فرمایا، اس میں ارشاد فرمایا صرف دو آدمیوں کی زندگی بہترین ہے، ایک وہ جو سن کر محفوظ رکھے اور دوسرے وہ عالم جو حق بات کہنے والا ہو۔ اے لوگو! آج کل تم لوگ کفار سے صلح کے زمانے میں ہو اور بہت تیزی سے آگے کو جا رہے ہو اور تم نے دیکھ لیا کہ دن رات کے گزرنے سے ہر نئی چیز پرانی ہو رہی ہے اور ہر دور والی چیز نزدیک آ رہی ہے اور ہر چیز کے وعدہ کا وقت آ رہا ہے۔ چونکہ جنت کے مقابلہ میں ایک دوسرے سے آگے نکلنے کا میدان بہت لمبا چوڑا ہے اس لیے وہاں کی تیاری اچھی طرح کر لو۔ حضرت مقدادؓ نے عرض کیا یا نبی ",""],["ٱللَّٰه","a"],["! صلح سے کیا مراد ہے؟ آپؐ نے فرمایا (کفار سے صلح جس سے) آزمائش کا دور ختم ہو گیا اور جب اندھیری رات کے ٹکڑوں کی طرح تم پر بہت سے کام گڈمڈ ہو جائیں (اور پتہ نہ چلے کہ ٹھیک کونسا ہے اور غلط کونسا؟) تو تم قرآن کو لازم پکڑ لو (جسے قرآن ٹھیک کہے اسے تم اختیار کرو) کیونکہ قرآن ایسا سفارشی ہے جس کی سفارش قبول کی جاتی ہے اور (انسان کی طرف سے) ایسا جھگڑا کرنے والا ہے جس کی بات سچی مانی جاتی ہے۔ جو قرآن کو اپنے آگے رکھے گا (اور اس کے مطابق زندگی گزارے گا) قرآن اسے جنت کی طرف لے جائے گا اور جو اسے پس پشت ڈال دے گا اسے دوزخ کی طرف لے جائے گا۔ اور یہ سب سے بہتر راستہ دکھانے والا ہے۔ یہ دو ٹوک فیصلہ کرنے والا کلام ہے، لغو اور بیکار چیز نہیں ہے۔ اس کا ایک ظاہر ہے اور ایک باطن۔ ظاہر تو احکام شرعیہ ہیں اور باطن یقین ہے۔ اس کا سمندر بہت گہرا ہے، اس کے عجائب بے شمار ہیں۔ علماء اس کے علوم سے کبھی سیر نہیں ہو سکتے۔ یہ ",""],["ٱللَّٰه","a"],[" کی مضبوط رسی ہے۔ یہی سیدھا راستہ ہے۔ یہی حق بیان کرنے والا کلام ہے جسے سنتے ہی جنات ایک دم بول اٹھے",""]]],["q",[["إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى ٱلرُّشْدِ فَآمَنَّا بِهِ","a"]]],["p",[["ترجمہ: \"(پھر اپنی قوم میں واپس جا کر) انہوں نے کہا کہ ہم نے ایک عجیب قرآن سنا ہے جو راہ راست بتلاتا ہے سو ہم تو اس پر ایمان لے آئے۔\" (سورت جن آیت ۱-۲) جو قرآن کی بات کہتا ہے وہ سچ کہتا ہے، جو اس پر عمل کرتا ہے اسے اجر و ثواب ملتا ہے، جو اس کے مطابق فیصلہ کرتا ہے وہ عدل کرتا ہے اور جو اس پر عمل کرتا ہے اسے سیدھے راستے کی ہدایت ملتی ہے۔ اس میں ہدایت کے چراغ ہیں اور یہ حکمت کا مینار ہے اور سیدھے راستے کی رہنمائی کرتا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Askari, as quoted in Kanzul Ummaal (Vol.1 Pg.218)."]]}]},"168":{"lead":[],"stories":[{"b":[["n",[["حضرت حسین بن علیؓ","b"],[" فرماتے ہیں میں نے ایک مرتبہ دیکھا کہ حضورؐ اپنے صحابہؓ میں کھڑے ہو کر بیان فرما رہے ہیں۔ آپؐ نے ارشاد فرمایا ہمارے طرز عمل سے ایسا معلوم ہوتا ہے کہ جیسے موت ہمیں نہیں آئے گی بلکہ دوسروں کے مقدر میں موت لکھی ہوئی ہے اور حق کو قبول کر کے اس پر عمل کرنا ہمارے ذمہ نہیں ہے بلکہ دوسروں کے ذمہ ہے۔ اور ایسا معلوم ہوتا ہے کہ جن مردوں کو ہم رخصت کر رہے ہیں وہ چند دن کے لیے سفر میں گئے ہیں اور تھوڑے ہی دنوں میں ہمارے پاس واپس آ جائیں گے اور مرنے والوں کی میراث ہم اس طرح کھاتے ہیں کہ جیسے ان کے بعد ہم نے یہاں ہمیشہ رہنا ہے۔ ہم ہر نصیحت کو بھول گئے ہیں اور آنے والی مصیبتوں سے ہم اپنے آپ کو امن میں سمجھتے ہیں۔ خوشخبری ہو اس آدمی کے لیے جو اپنے عیبوں کو دیکھنے میں اس طرح سے لگ گیا کہ اسے دوسرے لوگوں کے عیب دیکھنے کی فرصت نہ ملے اور خوشخبری ہو اس آدمی کے لیے جس کی کمائی پاکیزہ ہو اور اس کی اندرونی حالت بھی ٹھیک ہو اور ظاہری اعمال بھی اچھے ہوں اور اس کا راستہ بھی سیدھا ہو۔ اور خوشخبری ہو اس آدمی کے لیے جس میں کوئی دینی اور اخلاقی کمی نہ ہو اور پھر وہ تواضع اختیار کرے اور اس مال میں سے خرچ کرے جو اس نے بغیر کسی گناہ کے حلال طریقہ سے جمع کیا ہے اور دین کی سمجھ رکھنے والوں اور حکمت و دانائی والوں سے میل جول رکھے اور کمزور اور مسکین لوگوں پر ترس کھائے۔ اور خوشخبری ہو اس آدمی کے لیے جو اپنا ضرورت سے زائد مال دوسروں پر خرچ کرے اور ضرورت سے زائد بات نہ کرے اور ہر حال میں سنت پر عمل کرے اور سنت چھوڑ کر کسی بدعت کو اختیار نہ کرے۔ پھر آپؐ منبر سے نیچے تشریف لے آئے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.3 Pg.202), who said that it is a ghareeb hadith. Ibn Asaakir has also reported it from Anas, as quoted in Kanzul Ummaal (Vol.8 Pg.204)."]]},{"b":[["n",[["ابن عساکر کی روایت کے شروع میں یہ ہے کہ آپؐ نے اپنی جدعاء نامی اونٹنی پر سوار ہو کر ہم میں بیان فرمایا اور ارشاد فرمایا اے لوگو! اور اس روایت کے آخر میں یہ ہے کہ ہم مردوں کو قبروں میں دفن کرتے ہیں اور پھر ان کی میراث کھاتے ہیں۔ ایک روایت میں یہ ہے کہ اس نے سنت کا اتباع کیا اور سنت کو چھوڑ کر بدعت کی طرف نہیں گیا اور بزار کی روایت میں یہ ہے کہ حضورؐ اپنی عضباء نامی اونٹنی پر تھے جو کہ جدعاء نہیں تھی اور اس روایت میں یہ بھی ہے کہ ان مردوں کے گھر ان کی قبریں ہیں اور اس روایت میں یہ بھی ہے کہ اس نے دین کی سمجھ رکھنے والوں سے میل جول رکھا اور شرک کرنے والوں اور بدعت اختیار کرنے والوں سے الگ رہا اور اس کے ظاہری اعمال ٹھیک ہوں اور لوگوں کو اپنے شر سے بچائے رکھے۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar; Haythami (Vol.10 Pg.229) has said that in its chain are Nadr Majrooz and others who are weak."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک مرتبہ حضورؐ منبر پر تشریف فرما تھے اور لوگ آپؐ کے ارد گرد بیٹھے ہوئے تھے۔ آپؐ نے فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ سے اس طرح حیا کرو جس طرح حیا کرنے کا حق ہے۔ ایک آدمی نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ہم ",""],["ٱللَّٰه","a"],[" تعالیٰ سے حیا کریں؟ آپؐ نے فرمایا تم میں سے جو آدمی حیا کرنے والا ہو اسے چاہیے کہ وہ رات اس طرح گزارے کہ اس کی موت اس کی آنکھوں کے سامنے ہو اور اپنے پیٹ کی اور پیٹ کے ساتھ جو اور اعضاء (دل، شرمگاہ وغیرہ) ہیں ان کی حفاظت کرے اور سر کی اور سر کے اندر جو اعضاء (کان، ناک، آنکھ اور منہ وغیرہ) ہیں ان کی حفاظت کرے۔ موت کو اور قبر میں جا کر بوسیدہ ہو جانے کو یاد رکھے اور دنیا کی زیب و زینت چھوڑ دے۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Awsat. Tirmidhi has reported a similar narration from Ibn Mas'ood, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.200)."]]}]},"169":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو منبر پر بیان فرماتے ہوئے سنا، آپؐ فرما رہے تھے تم لوگ ",""],["ٱللَّٰه","a"],[" کی بارگاہ میں ننگے پاؤں، ننگے بدن، بغیر ختنہ کے حاضر ہو گے۔ ایک روایت میں پیدل بھی ہے اور ایک روایت میں ہے کہ حضورؐ نے کھڑے ہو کر ہمیں نصیحت فرمائی، ارشاد فرمایا اے لوگو! تمہیں ",""],["ٱللَّٰه","a"],[" کی بارگاہ میں ننگے پاؤں اور ننگے بدن بغیر ختنہ جمع کیا جائے گا (",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے)",""]]],["q",[["كَمَا بَدَأْنَآ أَوَّلَ خَلْقٍ نُّعِيدُهُۥ ۚ وَعْدًا عَلَيْنَآ ۚ إِنَّا كُنَّا فَٰعِلِينَ","a"]]],["p",[["ترجمہ: \"(اور) ہم نے جس طرح اول بار پیدا کرنے کے وقت (ہر چیز کی) ابتداء کی تھی اسی طرح (آسانی سے) اس کو دوبارہ پیدا کر دیں گے۔ یہ ہمارے ذمہ وعدہ ہے اور ہم (ضرور اس کو پورا) کریں گے۔\" (سورت انبیاء آیت ۱۰۴) غور سے سنو! (تمام انسانوں میں) قیامت کے دن سب سے پہلے حضرت ابراہیمؑ کو کپڑے پہنائے جائیں گے۔ غور سے سنو! میری امت کے کچھ لوگوں کو لایا جائے گا پھر انہیں بائیں طرف لے جایا جائے گا تو میں کہوں گا اے میرے رب! یہ تو میرے ساتھی ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے آپ کو معلوم نہیں ہے کہ انہوں نے آپ کے بعد کیا کیا نئی باتیں نکالیں؟ اس وقت میں وہی بات کہوں گا جو ",""],["ٱللَّٰه","a"],[" کے نیک بندے (حضرت عیسیٰ علیہ السلام) کہیں گے",""]]],["q",[["وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ، إِن تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ ۖ وَإِن تَغْفِرْ لَهُمْ فَإِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ","a"]]],["p",[["ترجمہ: \"اور میں ان پر مطلع رہا جب تک ان میں رہا، پھر جب آپ نے مجھے اٹھا لیا تو آپ ہی ان پر مطلع رہے اور آپ ہر چیز کی پوری خبر رکھتے ہیں۔ اگر آپ ان کو سزا دیں تو یہ آپ کے بندے ہیں اور اگر آپ ان کو معاف فرما دیں تو آپ زبردست ہیں، حکمت والے ہیں۔\" (سورت مائدہ آیت ۱۱۷ تا ۱۱۸) پھر مجھے بتایا جائے گا کہ جب آپ ان سے جدا ہوئے تو انہوں نے ایڑیوں کے بل واپس لوٹنا شروع کر دیا تھا اور ہوتے ہوتے یہ مرتد ہو گئے تھے (چنانچہ حضورؐ کے انتقال کے بعد عرب کے کچھ لوگ مرتد ہو گئے تھے)۔ ایک روایت میں اس کے بعد یہ ہے کہ میں کہوں گا دور ہو جاؤ، دور ہو جاؤ۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim and others, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.345)."]]}]},"170":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں حضورؐ ایک مرتبہ منبر پر تشریف لے گئے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی۔ اس کے بعد فرمایا ایک رجسٹر ایسا ہے جس میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جنت والوں کے نام و نسب سب تفصیل سے لکھے ہوئے ہیں اور آخر میں ان سب کی مجموعی تعداد لکھی ہوئی ہے، اب قیامت تک ان میں کوئی کمی بیشی نہیں ہوگی۔ پھر فرمایا ایک رجسٹر اور ہے جس میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے دوزخ والوں کے نام و نسب سب تفصیل سے لکھے ہوئے ہیں اور آخر میں ان سب کی مجموعی تعداد لکھی ہوئی ہے۔ اب قیامت تک ان میں کوئی کمی بیشی نہیں ہوگی۔ جنت میں جانے والا زندگی بھر کیسے بھی عمل کرتا رہے لیکن اس کا خاتمہ جنت والوں کے عمل پر ہوگا اور دوزخ میں جانے والا زندگی بھر کیسے ہی عمل کرتا رہے لیکن اس کا خاتمہ دوزخ والوں کے عمل پر ہوگا۔ بعض دفعہ خوش قسمت لوگ یعنی جن کے مقدر میں جنت جانا لکھا ہوا ہے وہ بدقسمتی کے راستہ پر اس طرح چل رہے ہوتے ہیں کہ یوں کہا جاتا ہے کہ یہ تو بدقسمتوں جیسے ہیں بلکہ ان ہی میں سے ہیں لیکن پھر خوش قسمتی انہیں آ لیتی ہے اور انہیں (بدقسمتی کے راستہ سے) چھڑا لیتی ہے۔ اور کبھی بدقسمت لوگ یعنی جن کے مقدر میں دوزخ میں جانا لکھا ہوا ہے وہ خوش قسمتی کے راستہ پر اس طرح چل رہے ہوتے ہیں کہ یوں کہا جاتا ہے کہ یہ تو بالکل خوش قسمتوں جیسے ہیں بلکہ ان ہی میں سے ہیں لیکن پھر بدقسمتی انہیں پکڑ لیتی ہے اور (خوش قسمتی کے راستہ سے) انہیں نکال کر (بدقسمتی کے راستہ پر) لے جاتی ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جسے لوح محفوظ میں خوش قسمت (یعنی جنتی) لکھا ہوا ہے اسے اس وقت تک دنیا سے نہیں نکالتے جب تک اس کے مرنے سے پہلے خوش قسمتی والا عمل نہیں کرا لیتے، چاہے وہ عمل مرنے سے اتنی ہی دیر پہلے ہو جتنا کہ اونٹنی کے دودھ نکالنے کے درمیان وقفہ ہوتا ہے۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جسے لوح محفوظ میں بدقسمت (یعنی دوزخی) لکھا ہوا ہے اسے اس وقت تک دنیا سے نہیں نکالتے جب تک اس کے مرنے سے پہلے بدقسمتی والا عمل نہیں کرا لیتے، چاہے وہ عمل مرنے سے اتنی ہی دیر پہلے ہو جتنا کہ اونٹنی کے دودھ نکالنے کے درمیان وقفہ ہوتا ہے۔ عمل کا دار و مدار آخری وقت کے عمل پر ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Awsat and Abu Sahl Jandansi Boori, as quoted in Kanzul Ummaal (Vol.1 Pg.87). Haythami (Vol.7 Pg.213) has said that Tabraani has reported it in his Awsat and that in its chain is Hammaad bin Waafid Sagheer who is weak."]]}]},"171":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو منبر پر یہ فرماتے ہوئے سنا کہ لوگوں کو کیا ہو گیا کہ یوں کہتے ہیں کہ رسول ",""],["ٱللَّٰه","a"],["ؐ کی رشتہ داری قیامت کے دن فائدہ نہیں دے گی۔ ",""],["ٱللَّٰه","a"],[" کی قسم! میری رشتہ داری دنیا اور آخرت میں جڑی ہوئی ہے، دونوں جگہ فائدہ دے گی۔ اور اے لوگو! میں تم سے پہلے (تمہاری ضروریات کا خیال کرنے کے لیے) آگے جا رہا ہوں اور قیامت کے دن حوض (کوثر) پر ملوں گا۔ کچھ لوگ (وہاں) کہیں گے یا رسول ",""],["ٱللَّٰه","a"],["! میں فلاں بن فلاں یعنی آپ کا رشتہ دار ہوں۔ میں کہوں گا نسب کو تو میں نے پہچان لیا لیکن تم نے میرے بعد بہت سے نئے کام ایجاد کیے اور الٹے پاؤں کفر میں واپس چلے گئے (ایمان و عمل کے بغیر میری رشتہ داری کام نہیں دیتی اور ایمان و عمل کے ساتھ خوب کام دیتی ہے)۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.1 Pg.98). Ahmad has also reported a similar narration from Abu Sa'eed, as quoted in Tafseer Ibn Katheer (Vol.3 Pg.256)."]]}]},"172":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ہم لوگوں میں بیان فرمایا اور اس بیان میں یہ ارشاد فرمایا غور سے سنو! قریب ہے کہ مجھے (اس دنیا سے) بلا لیا جائے اور میں یہاں سے چلا جاؤں۔ میرے بعد ایسے لوگ تمہارے حاکم بنیں گے جو ایسے عمل کریں گے جنہیں تم جانتے پہچانتے ہو، ان کی اطاعت صحیح اور اصل اطاعت ہے۔ کچھ عرصہ ایسا ہی ہوگا لیکن اس کے بعد ایسے لوگ تمہارے حاکم بن جائیں گے جو ایسے عمل کریں گے جنہیں تم جانتے پہچانتے نہیں ہو۔ جو ان کی قیادت (غلط کاموں میں) کرے گا اور (دنیاوی کاموں میں) ان کا فائدہ چاہے گا وہ خود بھی برباد ہوگا اور دوسروں کو بھی برباد کرے گا۔ جسمانی طور پر تو تم ان سے ملے جلتے رہو لیکن غلط اعمال میں تم ان سے الگ رہو، البتہ ان میں سے جو اچھے عمل کرے تم اس کے اچھے عمل کرنے کی گواہی دو اور جو برے عمل کرے تم اس کے برے عمل کرنے کی گواہی دو۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.5 Pg.237) has said that Tabraani has reported it in his Awsat from his teacher Muhammad bin Ali Marwazi who is weak."]]},{"b":[["n",[["حضرت ابوحمید ساعدیؓ","b"],[" فرماتے ہیں حضورؐ نے ایک آدمی کو صدقات (عشر و زکوٰۃ) وصول کرنے کے لیے بھیجا، وہ اپنے کام سے فارغ ہو کر حضورؐ کی خدمت میں آیا اور کہنے لگا یا رسول ",""],["ٱللَّٰه","a"],["! یہ مال اور جانور تو آپ کے ہیں اور یہ مجھے ہدیہ میں ملا ہے۔ حضورؐ نے اس سے فرمایا تم اپنے ماں باپ کے گھر کیوں نہیں بیٹھ جاتے کہ دیکھتے کہ تمہیں ہدیے ملتے ہیں یا نہیں؟ پھر شام کو حضورؐ بیان کے لیے کھڑے ہوئے، پہلے کلمہ شہادت پڑھا پھر ",""],["ٱللَّٰه","a"],[" کے شایان شان تعریف کی پھر فرمایا اما بعد! صدقات کی وصولی کے لیے جانے والے کا کیا ہوا؟ ہم اسے صدقات وصول کرنے کے لیے بھیجتے ہیں، وہ واپس آ کر ہمیں کہتا ہے یہ تو آپ کا ہے اور یہ مجھے ہدیہ میں ملا ہے۔ وہ اپنے ماں باپ کے گھر میں بیٹھ کر کیوں نہیں دیکھ لیتا کہ اسے ہدیے ملتے ہیں یا نہیں؟ اس ذات کی قسم جس کے قبضہ میں محمدؐ کی جان ہے! تم میں سے جو آدمی بھی صدقات کے مال میں تھوڑی سی بھی خیانت کرے گا اور صدقات کے جانوروں میں سے کچھ بھی لے لے گا وہ اسے اپنی گردن پر اٹھائے ہوئے قیامت کے دن لائے گا۔ اونٹ، گائے اور بکری جو لیا ہوگا اسے گردن پر اٹھا کر لائے گا اور ہر جانور اپنی آواز نکال رہا ہوگا۔ میں نے (تمہیں ",""],["ٱللَّٰه","a"],[" کا پیغام) پہنچا دیا ہے۔ حضرت ابوحمیدؓ فرماتے ہیں پھر حضورؐ نے اپنا ہاتھ اتنا اٹھایا کہ ہمیں آپ کی بغلوں کی سفیدی نظر آنے لگی۔ یہ بیان میرے ساتھ حضرت زید بن ثابتؓ نے حضورؐ سے سنا ہے، اس لیے ان سے بھی پوچھ لو۔",""],[" (2)","s"]]]],"f":[["(2)","Bukhaari (Vol.2 Pg.982). Muslim, Abu Dawood and Ahmad have also reported it, as quoted in Jaami' Sagheer."]]}]},"173":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوقتادہؓ","b"],[" فرماتے ہیں انصار کے بارے میں میں نے حضورؐ کو منبر پر یہ فرماتے ہوئے سنا غور سے سنو! لوگ تو میرا اوپر کا کپڑا ہیں اور انصار میرے اندر کا کپڑا ہیں یعنی ان سے میرا خاص تعلق ہے۔ اور لوگ اگر ایک وادی میں چلیں اور انصار کسی اور گھاٹی میں چلیں تو میں انصار کی گھاٹی میں چلوں گا۔ اگر ہجرت کو فضیلت نہ ہوتی تو میں انصار میں سے ایک آدمی ہوتا۔ لہٰذا جو بھی انصار کا حاکم بنے اسے چاہیے کہ وہ ان کے اچھے کے ساتھ اچھا سلوک کرے اور ان کے برے سے درگزر کرے۔ جس نے انہیں ڈرایا اس نے اس چیز کو ڈرایا جو ان دو پہلوؤں کے درمیان ہے یعنی میرے دل کو۔ حضورؐ نے اپنے دل کی طرف اشارہ بھی فرمایا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad; Haythami (Vol.10 Pg.35) has said that its narrators are those of authentic Ahaadeeth except Yahya bin Nadr Ansari who is reliable."]]},{"b":[["n",[["حضرت کعب بن مالک انصاریؓ","b"],[" ان تین صحابہؓ میں سے ہیں جن کی توبہ قبول ہوئی تھی۔ ان کے صاحبزادے ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں نبی کریمؐ کے ایک صحابیؓ نے میرے والد محترم کو بتایا کہ ایک دن حضورؐ سر پر پٹی باندھے ہوئے باہر تشریف لائے اور بیان میں آپؐ نے یہ فرمایا اما بعد! اے جماعت مہاجرین! تمہاری تعداد میں اضافہ ہوتا رہے گا (اور لوگ ہجرت کر کے آتے رہیں گے) لیکن انصار جتنے آج ہیں اتنے ہی رہیں گے، ان کی تعداد میں اضافہ نہ ہوگا۔ انصار تو میرے ذاتی کپڑوں کا صندوق ہیں یعنی یہ میرے خاص لوگ ہیں جن کے پاس آ کر میں ٹھہرا ہوں، لہٰذا ان کے کریم آدمی کا اکرام کرو اور ان کے برے آدمی سے درگزر کرو۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad also; Haythami (Vol.10 Pg.26) has said that its narrators are those of authentic Ahaadeeth."]]}]},"174":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" فرماتے ہیں میں نے منبر کی لکڑیوں پر حضورؐ کو یہ فرماتے ہوئے سنا دوزخ کی آگ سے بچو چاہے کھجور کے ایک ٹکڑے کے صدقہ کے ذریعہ سے ہی بچو، کیونکہ یہ صدقہ ٹیڑھ پن کو سیدھا کر دیتا ہے اور بری موت سے بچاتا ہے اور جیسے پیٹ بھرے آدمی کو فائدہ دیتا ہے ایسے ہی بھوکے کو بھی فائدہ دیتا ہے یعنی جو بھی صدقہ دے گا اسے اجر و ثواب ملے گا چاہے بھوکا ہو یا پیٹ بھرا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la and Bazzaar, as quoted in Targheeb wat Tarheeb (Vol.2 Pg.134)."]]},{"b":[["n",[["حضرت عامر بن ربیعہؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو بیان فرماتے ہوئے سنا آپؐ فرما رہے تھے جو مجھ پر درود بھیجتا رہے گا فرشتے اس کے لیے دعائے رحمت کرتے رہیں گے، اب چاہے بندہ اپنے لیے (فرشتوں سے) تھوڑی دعا کروائے چاہے زیادہ۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, Ibn Abi Shaybah and Ibn Majah, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.160)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے ہم لوگوں میں کھڑے ہو کر بیان فرمایا۔ آپؐ نے ارشاد فرمایا جس آدمی کو اس بات سے خوشی ہو کہ اسے آگ سے دور کر دیا جائے اور جنت میں داخل کر دیا جائے اسے چاہیے کہ اسے اس حال میں موت آئے کہ اس کے دل میں ",""],["ٱللَّٰه","a"],[" پر اور آخرت کے دن پر ایمان موجود ہو اور لوگوں کے ساتھ وہ معاملہ کرے جو اپنے ساتھ چاہتا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.76)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ہم لوگوں میں ایسا زبردست بیان فرمایا کہ میں نے ویسا بیان کبھی نہیں سنا۔ پھر آپؐ نے فرمایا جو کچھ میں جانتا ہوں اگر تم بھی وہ جان لو تو تمہارا ہنسنا کم ہو جائے اور رونا زیادہ۔ اس پر تمام صحابہؓ نے اپنے چہروں پر کپڑے ڈال لیے اور رونے لگے۔ ایک روایت میں یہ ہے کہ ایک مرتبہ حضورؐ کو اپنے صحابہؓ کے بارے میں کوئی شکایت پہنچی تو آپؐ نے بیان فرمایا اور ارشاد فرمایا میرے سامنے جنت اور جہنم پیش کی گئی اور میں نے (جنت اور جہنم دیکھ کر) جتنا خیر اور شر دیکھا ہے اتنا خیر و شر کبھی نہیں دیکھا اور جو کچھ میں جانتا ہوں اگر تم بھی وہ جان لو تو تم ہنسو کم اور روؤ زیادہ۔ چنانچہ حضورؐ کے صحابہؓ پر اس سے زیادہ سخت دن کوئی نہیں آیا۔ تمام صحابہؓ سر ڈھانک کر رونے لگے۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari and Muslim, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.226)."]]},{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے بیان فرمایا اور بیان کرتے کرتے یہ آیت پڑھی",""]]],["q",[["إِنَّهُۥ مَن يَأْتِ رَبَّهُۥ مُجْرِمًا فَإِنَّ لَهُۥ جَهَنَّمَ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","a"]]],["p",[["ترجمہ: \"جو شخص (بغاوت کا) مجرم ہو کر اپنے رب کے پاس حاضر ہوگا سو اس کے لیے دوزخ (مقرر) ہے، اس میں نہ مرے ہی گا اور نہ جیے ہی گا\" (سورۂ طٰہٰ، آیت 74)۔ تو حضورؐ نے فرمایا جو اصل دوزخ والے ہیں وہ اس میں نہ مریں گے اور نہ ہی وہ زندوں میں شمار ہوں گے، لیکن وہ لوگ جو اصل دوزخ والے نہیں ہیں (بلکہ گناہوں کی وجہ سے کچھ دن کے لیے دوزخ میں گئے ہیں) آگ ان کو کچھ جلائے گی، پھر سفارش کرنے والے کھڑے ہوں گے اور ان دوزخیوں کی سفارش کریں گے، پھر ان کی جماعتیں بنا کر انہیں دوزخ سے نکال کر نہر حیات یا نہر حیوان پر لایا جائے گا، یہ لوگ اس نہر میں ایسے اگیں گے جیسے سیلاب کے لائے ہوئے کوڑے کرکٹ میں گھاس اگتی ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Haatim, as quoted in Tafseer Ibn Katheer (Vol.3 Pg.159)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے ایک مرتبہ کھڑے ہو کر بیان فرمایا اور ارشاد فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" رب العالمین کے ساتھ اچھا گمان رکھو۔ بندہ اپنے رب کے ساتھ جیسا گمان رکھے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے ساتھ ویسا ہی معاملہ کرے گا۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Dunya and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.2 Pg.143)."]]},{"b":[["n",[["حضرت ابوزہیر ثقفیؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو بیان میں یہ فرماتے ہوئے سنا اے لوگو! قریب ہے کہ تم جنت والوں اور دوزخ والوں کو پہچان لو گے یا فرمایا تم اپنے بھلوں اور بروں کو پہچان لو گے۔ ایک آدمی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! کیسے؟ آپؐ نے فرمایا پہچاننے کا طریقہ یہ ہے کہ تم لوگ جس کی تعریف کرو گے وہ جنتی اور بھلا ہے اور جس کو برا کہو گے وہ دوزخی اور برا ہے۔ تم لوگ آپس میں ایک دوسرے کے بارے میں گواہ رہو (صحابہ کرامؓ اور کامل ایمان والے جسے اچھا کہیں گے وہ یقیناً اچھا ہوگا اور جسے برا کہیں گے وہ یقیناً برا ہوگا)۔",""],[" (7)","s"]]]],"f":[["(7)","Haakim (Vol.4 Pg.436), who said that its chain is authentic although Bukhaari and Muslim did not report it, and Dhahabi agreed with him."]]},{"b":[["n",[["حضرت ثعلبہؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے کھڑے ہو کر بیان فرمایا اور صدقۂ فطر دینے کا حکم دیا اور فرمایا ہر آدمی کی طرف سے ایک صاع (ساڑھے تین سیر) کھجور یا ایک صاع جو صدقۂ فطر میں دیے جائیں، چاہے وہ آدمی چھوٹا ہو یا بڑا، آزاد ہو یا غلام۔",""],[" (8)","s"]]]],"f":[["(8)","Hasan bin Sufyaan and Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.4 Pg.338)."]]}]},"175":{"lead":[],"stories":[{"b":[["n",[["حضرت عقبہ بن عامر جہنیؓ","b"],[" فرماتے ہیں ہم لوگ غزوۂ تبوک میں جا رہے تھے، ابھی پہنچنے میں ایک رات کا سفر باقی تھا کہ رات حضورؐ سوتے رہ گئے اور فجر کی نماز کے لیے آنکھ نہ کھل سکی بلکہ سورج نکل آیا اور ایک نیزے کے برابر بلند ہو گیا۔ آپؐ نے فرمایا اے بلال! کیا میں نے تمہیں نہیں کہا تھا کہ (ہم تو سونے لگے ہیں) تم ہماری فکر کا خیال رکھنا؟ حضرت بلالؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! (آپ نے فرمایا تو تھا لیکن) مجھے بھی اسی ذات نے سلا دیا جس نے آپ کو سلائے رکھا۔ اس کے بعد حضورؐ وہاں سے تھوڑا سا آگے گئے، پھر فجر کی نماز قضا پڑھی، اس کے بعد ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر آپؐ نے ارشاد فرمایا اما بعد! سب سے سچی بات ",""],["ٱللَّٰه","a"],[" کی کتاب ہے اور سب سے مضبوط کڑا تقویٰ کا کلمہ یعنی کلمۂ شہادت ہے اور سب سے بہترین ملت حضرت ابراہیم علیہ السلام کی ملت ہے اور سب سے بہترین طریقہ حضرت محمدؐ کا طریقہ ہے اور سب سے اعلیٰ بات ",""],["ٱللَّٰه","a"],[" کا ذکر ہے اور سب سے اچھا بیان یہ قرآن ہے۔ سب سے بہترین کام وہ ہیں جو عزیمت اور پختگی والے ہوں جن کا کرنا ",""],["ٱللَّٰه","a"],[" نے ضروری قرار دیا ہے اور سب سے برے کام وہ ہیں جو نئے ایجاد کیے گئے ہوں اور سب سے اچھی سیرت انبیاء علیہم السلام کی سیرت ہے اور سب سے زیادہ عزت والی موت شہید کی ہے اور سب سے بدترین اندھا پن ہدایت کے بعد گمراہ ہونا ہے اور بہترین علم وہ ہے جو نفع دے اور بہترین سیرت وہ ہے جس پر چلا جائے اور سب سے برا اندھا پن دل کا اندھا پن ہے۔ اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے یعنی دینے والا لینے والے سے بہتر ہے اور جو مال کم ہو اور انسان کی ضروریات کے لیے کافی ہو وہ اس مال سے بہتر ہے جو زیادہ ہو اور انسان کو ",""],["ٱللَّٰه","a"],[" سے غافل کر دے اور ",""],["ٱللَّٰه","a"],[" سے معذرت چاہنے کا سب سے برا وقت موت کے آنے کا وقت ہے اور سب سے بری ندامت وہ ہے جو قیامت کے دن ہوگی اور کچھ لوگ ہر نماز قضا کر کے پڑھتے ہیں اور کچھ لوگ صرف زبان سے ذکر کرتے ہیں دل سے نہیں کرتے اور سب سے بڑا گناہ زبان کا جھوٹ بولنا ہے اور سب سے بہترین مال داری دل کا غنا ہے اور بہترین توشہ تقویٰ ہے۔ حکمت کی جڑ ",""],["ٱللَّٰه","a"],[" کا خوف ہے۔ جو باتیں دل میں جمتی ہیں ان میں سب سے بہترین یقین ہے۔ (اسلام میں) شک کرنا کفر ہے۔ مردہ پر واویلا کرنا جاہلیت کے کاموں میں سے ہے اور مال غنیمت میں خیانت کرنا جہنم کے ڈھیر میں سے ہے اور جس خزانے کی زکوٰۃ نہ دی جائے اس کی سزا یہ ہے کہ جہنم کی آگ سے داغ لگائے جائیں گے۔ شعر و شاعری ابلیس کی بانسری ہے۔ اکثر اشعار شیطانی کاموں کے لیے استعمال ہوتے ہیں۔ شراب تمام گناہوں کا مجموعہ ہے۔ عورتیں شیطان کا جال ہیں۔ عورتوں کو ذریعہ بنا کر شیطان بہت سے برے کام کرا لیتا ہے۔ جوانی دیوانگی کا ایک حصہ ہے۔ اور سب سے بری کمائی سود کی ہے اور سب سے بری کھانے کی چیز یتیم کا مال ہے اور خوش قسمت وہ ہے جو دوسروں سے نصیحت حاصل کرے اور بدبخت وہ ہے جو اپنی ماں کے پیٹ میں بدبخت ہوا ہے۔ آخر کار تم میں سے ہر آدمی چار ہاتھ جگہ یعنی قبر میں جائے گا اور اعمال کا دار و مدار آخری وقت کے عمل پر ہے۔ سب سے بری روایتیں وہ ہیں جو جھوٹی ہوں اور ہر آنے والی چیز قریب ہے۔ مومن کو برا بھلا کہنے سے آدمی فاسق ہو جاتا ہے اور مومن کو قتل کرنا کفر جیسا گناہ ہے اور مومن کی غیبت کرنا خدا کی نافرمانی ہے۔ اس کے مال کا احترام ایسے ہی ضروری ہے جیسے اس کے خون کا احترام ضروری ہے۔ جو ",""],["ٱللَّٰه","a"],[" پر قسم کھاتا ہے (مثلاً کہتا ہے ",""],["ٱللَّٰه","a"],[" کی قسم فلاں جہنم میں ضرور داخل ہوگا) ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کا جھوٹا ہونا ثابت کر دیں گے (اور جس غلط بات کے ہونے کی قسم کھائی تھی ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے خلاف کریں گے)۔ جو دوسروں سے درگزر کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے درگزر فرمائیں گے۔ جو اوروں کو معاف کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے معاف فرمائیں گے۔ جو اپنا غصہ دبائے گا ",""],["ٱللَّٰه","a"],[" اسے اجر دیں گے۔ جو مصیبت پر صبر کرے گا ",""],["ٱللَّٰه","a"],[" اسے بدلہ دیں گے۔ جو اپنے نیک اعمال سے دنیا میں شہرت چاہے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن تمام انسانوں کو سنائیں گے کہ یہ عمل اخلاص سے نہیں کرتا تھا بلکہ شہرت کے لیے کرتا تھا۔ جو صبر کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کا اجر بڑھائیں گے۔ جو ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے گا ",""],["ٱللَّٰه","a"],[" اسے عذاب دیں گے۔ اے ",""],["ٱللَّٰه","a"],["! میری اور میری امت کی مغفرت فرما۔ اے ",""],["ٱللَّٰه","a"],["! میری اور میری امت کی مغفرت فرما۔ اے ",""],["ٱللَّٰه","a"],["! میری اور میری امت کی مغفرت فرما۔ میں اپنے لیے اور تمہارے لیے ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi in his Dalaa'il and Ibn Asaakir in his Taareekh. Abu Nasr Sijzi has also reported it in his Ibaanah from Abu Darda as a marfoo' narration. Ibn Abi Shaybah, Abu Nu'aym in his Hilyah and Qudaa'i in his Shihaab have reported it from Ibn Mas'ood as a mawqoof narration. The commentators of the Shihaab have said that it is hasan ghareeb. Askari and Daylami have reported it from Uqbah, as quoted in Jaami' Sagheer of Suyooti and its commentary Fayd Al Qadeer of Munaawi (Vol.2 Pg.179). Haakim has also reported it from the narration of Uqbah, as quoted in Zaadul Ma'aad (Vol.3 Pg.7)."]]},{"b":[["n",[["حضرت عیاض بن حمار مجاشعیؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے بیان فرمایا اور بیان میں ارشاد فرمایا کہ آج میرے رب نے مجھے اس بات کا حکم دیا ہے کہ مجھے جو کچھ سکھایا ہے اور آپ لوگ اسے نہیں جانتے ہو اس میں سے میں آپ لوگوں کو بھی سکھاؤں گا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے میں نے جو مال اپنے بندوں کو دیا ہے وہ سارا ان کے لیے حلال ہے (لہٰذا کفار عرب نے سائبہ، وصیلہ، بحیرہ وغیرہ نام رکھ کر جو کچھ اپنے اوپر حرام کر لیا ہے وہ حرام نہیں ہوا بلکہ حلال ہے)۔ میں نے اپنے تمام بندوں کو کفر و شرک اور گناہوں سے پاک صاف دین اسلام پر پیدا کیا ہے، پھر شیطانوں نے آ کر انہیں دین اسلام سے گمراہ کر دیا اور جو میں نے ان کے لیے حلال کیا تھا وہ ان پر حرام کر دیا اور انہیں اس بات کا حکم دیا کہ وہ میرے ساتھ ایسی چیزوں کو شریک کریں جن کی میں نے کوئی دلیل نہیں اتاری۔ پھر (میری بعثت سے پہلے) ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمام زمین والوں پر نظر ڈالی تو تمام عرب و عجم کو دیکھ کر ",""],["ٱللَّٰه","a"],[" کو غصہ آیا (کیونکہ سب کفر و شرک میں مبتلا تھے) لیکن کچھ اہل کتاب ایسے تھے جو اپنے سچے دین پر قائم تھے اور اس میں انہوں نے کوئی تبدیلی نہیں کی تھی۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا (اے ہمارے نبی!) میں نے آپ کو اس لیے بھیجا ہے تاکہ میں آپ کا امتحان لوں (کہ آپ میری منشاء پر چلتے ہیں یا نہیں) اور آپ کے ذریعہ سے دوسروں کا امتحان لوں (کہ وہ آپ کی دعوت کو مانتے ہیں یا نہیں) اور میں نے آپ پر ایسی کتاب نازل کی ہے جسے پانی دھو نہیں سکتا (اس کی لکھائی مٹنے والی نہیں، یعنی آپ کے سینے میں محفوظ رہے گی، آپ اسے بھولیں گے نہیں) اور آپ اسے سوتے اور جاگتے میں پڑھا کریں گے یعنی دونوں حالتوں میں آپ کو پکا یاد رہے گی۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے اس بات کا حکم دیا کہ میں قریش کو جلا دوں (یعنی انہیں ",""],["ٱللَّٰه","a"],[" کی دعوت دوں، جو مانے گا وہ کامیاب ہوگا اور جو نہیں مانے گا وہ برباد ہوگا، دوزخ کی آگ میں جلے گا)۔ میں نے عرض کیا اے میرے رب! پھر تو وہ میرا سر کچل دیں گے اور روٹی کی طرح چپٹا کر کے چھوڑ دیں گے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا آپ انہیں (مکہ سے) ایسے نکالیں جیسے انہوں نے آپ کو نکالا ہے، آپ ان سے جنگ کریں ہم آپ کی مدد کریں گے، آپ ان پر خرچ کریں ہم آپ پر خرچ کریں گے، آپ ان کی طرف ایک لشکر بھیجیں ہم اس جیسے (فرشتوں کے) پانچ لشکر بھیجیں گے اور آپ اپنے فرمانبرداروں کو لے کر نافرمانوں سے جنگ کریں۔ اور جنتی لوگ تین قسم کے ہوتے ہیں: ایک عادل بادشاہ جسے ",""],["ٱللَّٰه","a"],[" کی طرف سے نیک اعمال کی خوب توفیق ملی ہو اور وہ خوب صدقہ کرنے والا ہو۔ دوسرے وہ آدمی جو رحم کرنے والا اور رشتہ داروں بلکہ ہر مسلمان کے بارے میں نرم دل ہو۔ تیسرے وہ آدمی جو پاک دامن، فقیر، عیال دار اور (فقیری کے باوجود دوسروں پر) صدقہ کرنے والا ہو۔ دوزخی لوگ پانچ قسم کے ہوتے ہیں: ایک وہ کمزور آدمی جس میں عقل بالکل نہ ہو، ہر ایک کے پیچھے لگ جاتا ہو۔ دوسرے وہ لوگ جو تم لوگوں میں دوسروں کے پیچھے چلنے والے اور ہاں میں ہاں ملانے والے ہیں اور (بدکاری میں مبتلا رہنے کی وجہ سے) ان میں نہ اہل و عیال کی طلب ہے اور نہ مال کی۔ تیسرے وہ خیانت کرنے والا جس میں لالچ اتنی زیادہ ہو کہ وہ چھپ نہ سکے اور چھوٹی چھوٹی چیزوں میں بھی خیانت کرے۔ چوتھے وہ آدمی جس کا صبح و شام ہر وقت یہی کام ہے کہ وہ تمہیں، تمہارے اہل و عیال اور مال و دولت کے بارے میں دھوکہ دیتا رہتا ہے۔ اور پانچویں آدمی کی خرابیوں میں آپؐ نے کنجوسی، جھوٹ، بد اخلاقی اور بدگوئی کا ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad. Muslim and Nasa'ee have also reported it, as quoted in Tafseer Ibn Katheer (Vol.2 Pg.35)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے عصر کی نماز پڑھائی اور قیامت قائم ہونے تک پیش آنے والی ہر اہم دینی چیز کو ہمارے سامنے ذکر کر دیا۔ جس نے ان تمام چیزوں کو یاد رکھنے کی کوشش کی اسے تو یاد رہیں اور جس نے انہیں بھلا دیا اسے بھول گئیں۔ اس بیان میں آپؐ نے یہ بھی ارشاد فرمایا اما بعد! دنیا سر سبز اور میٹھی ہے، بڑی مزیدار اور اچھی لگتی ہے، بہت خوشنما نظر آتی ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہیں اپنا خلیفہ بنا کر اور دنیا دے کر دیکھنا چاہتے ہیں کہ تم کیسے عمل کرتے ہو اچھے یا برے (یعنی دنیا کے اصل مالک تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ہیں اور تم لوگوں کو اپنا نمائندہ بنایا ہے)۔ اس لیے دنیا کے فتنے سے بچو (بقدر ضرورت حاصل کرو اور ضرورت سے زیادہ آ جائے تو اسے دوسروں پر خرچ کر دو) اور عورتوں کے فتنے سے بچو (ان کی باتوں میں آ کر ان کی محبت سے مغلوب ہو کر ",""],["ٱللَّٰه","a"],[" کے کسی حکم کی خلاف ورزی نہ کرو)۔ بنی اسرائیل میں سب سے پہلا فتنہ عورتوں کے ذریعے پیش آیا تھا۔ غور سے سنو! آدم کی اولاد کو مختلف قسم کا بنا کر پیدا کیا گیا ہے۔ کچھ تو ایسے ہیں جو مومن پیدا ہوتے ہیں، مومن بن کر ساری زندگی گزارتے ہیں اور مومن ہونے کی حالت میں مرتے ہیں؛ اور کچھ ایسے ہیں جو کافر پیدا ہوتے ہیں، کافر بن کر زندگی گزارتے ہیں اور کافر ہونے کی حالت میں مرتے ہیں؛ اور کچھ ایسے ہیں جو مومن پیدا ہوتے اور مومن بن کر زندگی گزارتے ہیں لیکن کافر بن کر مرتے ہیں؛ اور کچھ ایسے ہیں جو کافر پیدا ہوتے ہیں اور کافر بن کر زندگی گزارتے ہیں لیکن مومن بن کر مرتے ہیں۔ توجہ سے سنو! غصہ ایک انگارہ ہے جو ابن آدم کے پیٹ میں دہکتا رہتا ہے۔ کیا تم دیکھتے نہیں کہ غصہ میں انسان کی آنکھیں سرخ ہو جاتی ہیں اور اس کے گلے کی رگیں پھول جاتی ہیں؟ لہٰذا جب تم میں سے کسی کو غصہ آئے تو اسے زمین سے چمٹ جانا چاہیے (کھڑا ہو تو بیٹھ جائے، بیٹھا ہو تو لیٹ جائے) زمین کی طرح عاجز اور مسکین بن جائے۔ غور سے سنو! بہترین مرد وہ ہے جسے غصہ دیر سے آئے اور جلدی چلا جائے اور سب سے برا مرد وہ ہے جسے غصہ جلدی آئے اور دیر سے جائے؛ اور جسے غصہ دیر سے آئے اور دیر سے جائے اور جسے غصہ جلدی آئے اور جلدی جائے تو اس کا معاملہ برابر سرابر ہو گیا، اس میں ایک اچھی صفت ہے اور ایک بری۔ غور سے سنو! سب سے بہترین تاجر وہ ہے جو عمدہ طریقے سے دے اور عمدہ طریقے سے مطالبہ کرے اور سب سے برا تاجر وہ ہے جو ادا کرنے میں بھی برا ہو اور مطالبہ کرنے میں بھی برا ہو؛ اور جو ادا کرنے میں اچھا ہو لیکن مطالبہ کرنے میں برا ہو یا ادا کرنے میں برا ہو اور مطالبہ کرنے میں اچھا ہو تو اس کا معاملہ برابر سرابر ہو گیا، اس میں ایک صفت اچھی ہے اور ایک بری۔ غور سے سنو! ہر بدعہد کو اس کی بدعہدی کے مطابق قیامت کے دن جھنڈا ملے گا (جس سے اس کے اس برے کام کی لوگوں میں شہرت ہوگی)۔ غور سے سنو! سب سے بڑی بدعہدی عام مسلمانوں کے امیر کی بدعہدی ہے۔ غور سے سنو! جسے حق بات معلوم ہے اسے لوگوں کی ہیبت اس حق بات کے کہنے سے ہرگز نہ روکے۔ غور سے سنو! سب سے افضل جہاد ظالم بادشاہ کے سامنے حق بات کہنا ہے۔ غور سے سنو! دنیا کی اتنی عمر گزر گئی ہے جتنا آج کا دن گزر گیا ہے اور اتنی باقی ہے جتنا آج کا دن باقی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, Tirmidhi, Haakim and Bayhaqi, as quoted in Jaami' Sagheer and its commentary Fayd Al Qadeer of Munaawi (Vol.2 Pg.181). In its chain is Ali bin Zayd bin Jud'aan whom Dhahabi has listed among the weak narrators in his Du'afaa; Ahmad and Yahya said that he is of no consequence."]]},{"b":[["n",[["حضرت سائب بن مہجان رحمۃ ","b"],["ٱللَّٰه","a"],[" علیہ","b"],[" اہل شام میں سے ہیں اور انہوں نے صحابہ کرامؓ کا زمانہ بھی پایا ہے۔ وہ کہتے ہیں جب حضرت عمرؓ ملک شام تشریف لائے تو انہوں نے (کھڑے ہو کر بیان فرمایا اور پہلے) ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور خوب وعظ و نصیحت فرمائی اور امر بالمعروف و نہی عن المنکر فرمایا۔ پھر فرمایا حضورؐ نے ہم لوگوں میں کھڑے ہو کر بیان فرمایا جیسے میں آپ لوگوں میں کھڑے ہو کر بیان کر رہا ہوں۔ آپؐ نے ہمیں اس بیان میں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کا، صلہ رحمی کرنے کا اور آپس میں صلح صفائی سے رہنے کا حکم دیا اور فرمایا تم لوگ جماعت سے چمٹے رہو اور امیر کی سننے اور ماننے کو لازم پکڑے رکھو کیونکہ ",""],["ٱللَّٰه","a"],[" کا ہاتھ جماعت پر ہوتا ہے۔ اکیلے آدمی کے ساتھ شیطان ہوتا ہے اور دو آدمیوں سے شیطان بہت دور ہوتا ہے۔ کسی مرد کو کسی اجنبی عورت کے ساتھ تنہائی میں ہرگز نہیں ہونا چاہیے ورنہ ان کے ساتھ تیسرا شیطان ہوگا۔ جسے اپنی برائی سے رنج ہو اور نیکی سے خوشی ہو یہ اس کے مسلمان اور مومن ہونے کی نشانی ہے اور منافق کی نشانی یہ ہے کہ اسے اپنی برائی سے کوئی رنج نہیں ہوتا اور نیکی سے کوئی خوشی نہیں ہوتی۔ اگر وہ کوئی خیر کا عمل کر لے تو اسے اس عمل پر ",""],["ٱللَّٰه","a"],[" سے کسی ثواب کی امید نہیں ہوتی اور اگر وہ کوئی برا کام کر لے تو اسے اس عمل پر ",""],["ٱللَّٰه","a"],[" کی طرف سے کسی سزا کا ڈر نہیں ہوتا۔ لہٰذا دنیا کی تلاش میں میانہ روی اختیار کرو کیونکہ ",""],["ٱللَّٰه","a"],[" نے تم سب کی روزی کا ذمہ لے رکھا ہے اور ہر انسان نے جو عمل کرنا ہے اس کا وہ عمل ضرور پورا ہو کر رہے گا۔ اپنے نیک اعمال کے لیے ",""],["ٱللَّٰه","a"],[" سے مدد مانگا کرو کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ جس عمل کو چاہیں مٹا دیں اور جس عمل کو چاہیں باقی رکھیں اور اسی کے پاس لوح محفوظ ہے۔ (حضورؐ کا بیان ختم ہو گیا اور پھر حضرت عمرؓ نے بھی بیان ختم کر دیا اور یہ فرمایا)",""]]],["q",[["وَصَلَّى ٱللَّهُ عَلَىٰ نَبِيِّنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَعَلَيْهِ ٱلسَّلَامُ وَرَحْمَةُ ٱللَّهِ","a"]]],["p",[["ترجمہ: \"اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمارے نبی حضرت محمدؐ اور ان کی آل پر درود بھیجے اور ان پر سلام ہو اور ",""],["ٱللَّٰه","a"],[" کی رحمت۔\" السلام علیکم۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Mardawayh, Bayhaqi in Shu'abul Imaan and Ibn Asaakir. Bayhaqi and Ibn Asaakir state that this is the sermon of Umar bin Khattab to the people of Shaam in which he narrated from Rasulullah ﷺ, as quoted in Kanzul Ummaal (Vol.8 Pg.207)."]]}]},"176":{"lead":[],"stories":[{"b":[["n",[["حضرت معاویہ بن ابی سفیانؓ","b"],[" فرماتے ہیں حضورؐ نے ایک مرتبہ (مرض الوفات) میں فرمایا مختلف کنوؤں سے سات مشکوں میں (پانی بھر کر) میرے اوپر ڈالو تاکہ (مجھے کچھ افاقہ ہو جائے اور) میں لوگوں کے پاس باہر جا کر انہیں وصیت کروں۔ چنانچہ (پانی ڈالنے سے) حضورؐ کو کچھ افاقہ ہوا تو حضورؐ سر پر پٹی باندھے ہوئے باہر آئے اور منبر پر تشریف فرما ہوئے، پھر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر فرمایا ",""],["ٱللَّٰه","a"],[" کے بندوں میں سے ایک بندے کو یہ اختیار دیا گیا کہ یا تو وہ دنیا میں رہ لے یا ",""],["ٱللَّٰه","a"],[" کے ہاں اجر و ثواب ہے اسے لے لے۔ اس بندے نے ",""],["ٱللَّٰه","a"],[" کے ہاں کے اجر و ثواب کو اختیار کر لیا (یہاں اس بندے سے مراد خود حضورؐ ہیں اور مطلب یہ ہے کہ آپؐ اس دنیا سے جلد تشریف لے جانے والے ہیں)۔ حضورؐ کے اس فرمان کا مطلب حضرت ابوبکرؓ کے علاوہ اور کوئی نہ سمجھ سکا اور اس پر وہ رونے لگے اور عرض کیا ہم اپنے ماں باپ اور آل اولاد سب آپ پر قربان کرتے ہیں۔ حضورؐ نے فرمایا (اے ابوبکر!) ذرا آرام سے بیٹھے رہو (مت رو)۔ میرے نزدیک ساتھ رہنے اور مال خرچ کرنے کے اعتبار سے لوگوں میں سب سے افضل ابن ابی قحافہ یعنی (حضرت ابوبکرؓ) ہیں۔ مسجد میں جتنے دروازے کھلے ہوئے ہیں سب بند کر دو، صرف ابوبکرؓ کا دروازہ کھلا رہنے دو کیونکہ میں نے اس پر نور دیکھا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Awsat and Kabeer in abridged form, as confirmed by Haythami (Vol.9 Pg.32). The chain mentions in addition the martyrs of Uhud for whom Rasulullah ﷺ performed salaah and made abundant du'aa; Haythami has remarked that its chain is hasan."]]},{"b":[["n",[["حضرت ایوب بن بشیرؓ","b"],[" فرماتے ہیں حضورؐ نے اپنے مرض الوفات میں ارشاد فرمایا مجھ پر پانی ڈالو، پھر آگے پچھلی جیسی حدیث ذکر کی اور مزید یہ بھی ہے کہ حضورؐ نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء کے بعد سب سے پہلے شہداء احد کا ذکر فرمایا اور ان کے لیے استغفار کیا اور دعا کی، پھر فرمایا اے جماعت مہاجرین! تمہاری تعداد بڑھتی جا رہی ہے اور انصار اپنی اسی حالت پر ہیں، ان کی تعداد نہیں بڑھ رہی ہے اور یہ انصار تو میرے خاص تعلق والے ہیں جن کے پاس آ کر مجھے ٹھکانہ ملا ہے۔ لہٰذا تم ان کے کریم آدمی کا اکرام کرو اور ان کے برے سے درگزر کرو۔ پھر حضورؐ نے فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" کے بندوں میں سے ایک بندے کو اختیار دیا گیا، پھر پچھلی حدیث جیسا مضمون ذکر کیا اور اس روایت میں ہے کہ حضورؐ کے اس فرمان کا مطلب لوگوں میں سے صرف ابوبکرؓ ہی سمجھ سکے اور اسی وجہ سے وہ رونے لگے۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted by Ibn Katheer in Al Bidaayah wan Nihaayah (Vol.5 Pg.229), who said that this is a mursal narration which has many supporting narrations."]]},{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے لوگوں میں بیان فرمایا کہ آپؐ نے ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ایک بندے کو اختیار دیا کہ یا تو وہ دنیا میں رہ لے یا ",""],["ٱللَّٰه","a"],[" کے ہاں جو کچھ ہے اسے لے لے، چنانچہ اس بندے نے ",""],["ٱللَّٰه","a"],[" کے ہاں جو کچھ ہے اس کو اختیار کر لیا۔ اس پر حضرت ابوبکرؓ رو پڑے۔ ہم اس بات پر حیران ہوئے کہ حضورؐ نے تو کسی بندے کے بارے میں خبر دی ہے، اس پر یہ حضرت ابوبکرؓ کیوں رو رہے ہیں، اس میں تو رونے کی کوئی بات نہیں۔ لیکن ہمیں بعد میں پتہ چلا کہ جس بندے کو اختیار دیا گیا ہے اس سے مراد تو خود حضورؐ تھے (اور حضورؐ کے اس فرمان کا مطلب یہ تھا کہ حضورؐ یہ بتا رہے تھے کہ حضورؐ تقریباً اس دنیا سے تشریف لے جانے والے ہیں)۔ یہ بات حضرت ابوبکرؓ ہم میں سب سے زیادہ سمجھنے والے تھے۔ پھر حضورؐ نے فرمایا ابوبکر نے ساتھ رہ کر اور مال خرچ کر کے لوگوں میں سب سے زیادہ مجھ پر احسان کیا ہے۔ اگر میں اپنے رب کے علاوہ کسی کو خلیل یعنی خالص دوست بناتا تو ابوبکر کو بناتا، البتہ ان سے اسلامی دوستی و محبت ضرور ہے۔ مسجد میں کھلنے والا ہر دروازہ بند کر دیا جائے، صرف ابوبکرؓ کا دروازہ رہنے دیا جائے۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad. Bukhaari and Muslim have also reported it in this manner, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ مرض الوفات میں باہر تشریف لائے۔ آپؐ نے سر پر کالی پٹی باندھی ہوئی تھی اور کندھوں پر چادر اوڑھی ہوئی تھی، آپؐ آ کر منبر پر بیٹھ گئے۔ راوی نے آگے حضورؐ کا بیان اور انصار کے بارے میں حضورؐ کی وصیت کا ذکر کیا۔ راوی کہتے ہیں کہ یہ انتقال سے پہلے حضورؐ کی آخری مجلس اور آخری بیان تھا۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.230). Ibn Sa'd (Vol.2 Pg.251) has reported a similar narration from Abu Sa'eed."]]},{"b":[["n",[["حضرت کعب بن مالکؓ","b"],[" ان تین صحابہؓ میں سے ہیں جن کی توبہ قبول کی گئی۔ وہ فرماتے ہیں حضورؐ نے کھڑے ہو کر بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر جنگ احد کے دن شہید ہونے والے صحابہؓ کے لیے مغفرت کی دعا فرمائی، پھر فرمایا اے جماعت مہاجرین! پھر اس کے بعد انصار کے بارے میں حضورؐ کی وصیت کا ذکر کیا جیسے کہ بیہقی کی حضرت ایوبؓ والی حدیث میں گزر چکا ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani from Abdur Rahman bin Ka'b bin Malik from his father; its narrators are those of authentic Ahaadeeth as confirmed by Haythami (Vol.10 Pg.37). Tabraani has also reported a similar narration in brief from Abdullah bin Ka'b from his father, who said that this was the last sermon of Rasulullah ﷺ; its narrators are also authentic (Haythami Vol.10 Pg.27). Haakim (Vol.3 Pg.78) has also reported it from Abdullah bin Ka'b from his father and said that its chain is authentic although Bukhaari and Muslim did not report it, and Dhahabi agreed."]]},{"b":[["n",[["حضرت ابوسلمہ بن عبدالرحمنؒ","b"],[" کہتے ہیں میں نے حضرت ابوہریرہؓ اور حضرت ابن عباسؓ کو یہ فرماتے ہوئے سنا کہ ہم لوگوں نے حضورؐ کو آخری بیان میں یہ فرماتے ہوئے سنا کہ جو جوان پانچ فرض نمازوں کو جماعت کے ساتھ پابندی سے ادا کرے گا وہ کوندتی ہوئی بجلی کی طرح سب سے پہلے پل صراط کو پار کرے گا اور (نبی کا) اچھے طریقہ سے اتباع کرنے والوں کی پہلی جماعت میں ",""],["ٱللَّٰه","a"],[" اس کا حشر کرے گا اور جس دن اور رات میں وہ ان پانچ نمازوں کی پابندی کرے گا اس کے بدلے ",""],["ٱللَّٰه","a"],[" کے راستہ میں شہید ہونے والے ہزار شہیدوں جیسا اجر ملے گا۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Awsat. Haythami (Vol.2 Pg.39) has commented that in its chain is Baqiyyah bin Waleed who is a mudallis and has reported with the word 'an."]]}]},"177":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوزید انصاریؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے ہمیں صبح کی نماز پڑھائی۔ اس کے بعد آپؐ نے ہم میں ظہر تک مسلسل بیان فرمایا، پھر منبر سے نیچے اتر کر ظہر کی نماز پڑھائی، پھر عصر تک بیان فرمایا، پھر اتر کر عصر کی نماز پڑھائی، پھر مغرب تک بیان فرمایا اور جو کچھ ہونے والا ہے وہ سب ہم سے بیان فرما دیا۔ اب جسے حضورؐ کی بتائی ہوئی یہ باتیں جتنی زیادہ یاد رہ گئیں وہ ہم میں اتنا زیادہ جاننے والا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.4 Pg.487), who said that its chain is authentic although Bukhaari and Muslim did not report it, and Dhahabi agreed with him."]]}]},"178":{"lead":[],"stories":[{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں حضورؐ جب لوگوں میں بیان فرماتے تو آپؐ کی آنکھیں سرخ ہو جاتیں، آواز بلند ہو جاتی اور غصہ تیز ہو جاتا، جیسے کہ آپؐ لوگوں کو دشمن کے لشکر سے ڈرا رہے ہوں اور فرما رہے ہوں کہ دشمن کا لشکر تم پر صبح حملہ کرنے والا ہے، شام کو حملہ کرنے والا ہے۔ پھر شہادت کی انگلی اور درمیانی انگلی کو ملا کر ارشاد فرماتے مجھے اور قیامت کو اس طرح ملا کر بھیجا گیا ہے۔ پھر فرماتے سب سے بہترین سیرت محمدؐ کی سیرت ہے اور سب سے برے کام وہ ہیں جو نئے ایجاد کیے گئے ہوں اور ہر بدعت گمراہی ہے۔ اور جو مر جائے اور مال چھوڑ کر جائے تو وہ مال اس کے گھر والوں کا ہے اور جو قرضہ یا چھوٹے بچے چھوڑ کر جائے جنہیں سنبھالنے والا کوئی نہ ہو تو وہ میرے ذمہ ہیں، وہ قرضہ میں ادا کروں گا اور ان بچوں کو میں سنبھالوں گا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.1 Pg.376) and Bayhaqi in his Asmaa was Sifaat (Pg.144), from Jaabir."]]}]},"179":{"lead":[],"stories":[{"b":[["n",[["حضرت عروہؓ","b"],[" فرماتے ہیں جب حضرت ابوبکرؓ خلیفہ بنے تو انہوں نے لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! اے لوگو! مجھے آپ لوگوں کا ذمہ دار بنایا گیا ہے، حالانکہ میں آپ لوگوں سے بہتر نہیں ہوں اور اب قرآن نازل ہو چکا ہے اور حضورؐ سنتیں بیان فرما چکے ہیں اور آپؐ نے ہمیں یہ سکھایا ہے کہ سب سے بڑی عقلمندی تقویٰ ہے اور سب سے بڑی حماقت فسق و فجور ہے اور جو تم لوگوں میں سب سے زیادہ طاقتور ہے (اور وہ طاقت کے زور سے کمزوروں کے حق دبا لیتا ہے) وہ میرے نزدیک کمزور ہے، میں کمزور کو اس طاقتور سے اس کا حق دلوا کر رہوں گا۔ اور جو تم میں سب سے زیادہ کمزور ہے (جس کے حق طاقتوروں نے دبا رکھے ہیں) وہ میرے نزدیک طاقتور ہے، میں اس کے حق طاقتوروں سے ضرور لے کر دوں گا۔ اے لوگو! میں تو (حضورؐ کا) اتباع کرنے والا ہوں اور اپنی طرف سے گھڑ کر نئی باتیں لانے والا نہیں ہوں۔ اگر میں اچھے کام کروں تو آپ لوگ ان میں میری مدد کریں اور اگر میں ٹیڑھا چلوں تو مجھے سیدھا کر دیں۔ میں اپنی بات اسی پر ختم کرتا ہوں اور اپنے لیے اور آپ لوگوں کے لیے ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd and Muhaamili, as quoted in Kanzul Ummaal (Vol.3 Pg.130)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عکیمؒ","b"],[" کہتے ہیں جب حضرت ابوبکرؓ کی بیعت خلافت ہو گئی تو وہ منبر پر تشریف لے گئے اور منبر پر جہاں نبی کریمؐ بیٹھا کرتے تھے اس سے ایک سیڑھی نیچے بیٹھے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! اچھی طرح سمجھ لو کہ سب سے بڑی عقلمندی تقویٰ ہے۔ اس کے بعد پچھلی حدیث جیسا مضمون ذکر کیا اور آخر میں اس مضمون کا اضافہ کیا کہ اپنے نفس کا محاسبہ کرو اس سے پہلے کہ تمہارا محاسبہ (",""],["ٱللَّٰه","a"],[" کی طرف سے) کیا جائے، اور جو قوم جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" چھوڑ دے گی اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ فقر مسلط کر دیں گے اور جس قوم میں بے حیائی عام ہو جائے گی ",""],["ٱللَّٰه","a"],[" تعالیٰ ان سب پر مصیبت بھیجیں گے۔ لہٰذا جب تک میں ",""],["ٱللَّٰه","a"],[" کی اطاعت کروں تم لوگ میری اطاعت کرو اور جب میں ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی نافرمانی کروں تو پھر میری اطاعت تمہارے ذمہ نہیں ہے۔ میں اپنی بات اس پر ختم کرتا ہوں اور اپنے لیے اور آپ لوگوں کے لیے ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Dinawari, as quoted in Kanzul Ummaal (Vol.3 Pg.135)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" پچھلی حدیث کا کچھ مضمون ذکر کرتے ہیں اور یہ جو حضرت ابوبکرؓ کا ارشاد ہے کہ سب سے بڑی حماقت فسق و فجور ہے اس کے بعد یہ اضافہ کرتے ہیں کہ غور سے سنو! میرے نزدیک سچ بولنا امانت داری ہے اور جھوٹ بولنا خیانت ہے۔ اور اسی طرح حضرت حسنؒ نے حضرت ابوبکرؓ کے فرمان کہ میں آپ لوگوں سے بہتر نہیں ہوں کے بعد یہ کہا کہ ",""],["ٱللَّٰه","a"],[" کی قسم! حضرت ابوبکرؓ ان سب سے بہتر تھے اور اس بات میں کوئی ان سے مزاحمت کرنے والا نہیں تھا، لیکن مومن آدمی یوں ہی کسر نفسی کیا کرتا ہے۔ اس کے بعد حضرت حسنؒ نے یہ بھی نقل کیا کہ حضرت ابوبکرؓ نے فرمایا میری تو دلی تمنا ہے کہ آپ لوگوں میں سے کوئی آدمی اس خلافت کا بوجھ اٹھا لیتا اور میں اس ذمہ داری سے بچ جاتا۔ حضرت حسنؒ کہتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! حضرت ابوبکرؓ نے یہ تمنا والی بات سچے دل سے کہی تھی (وہ واقعی خلیفہ نہیں بننا چاہتے تھے)۔ پھر حضرت ابوبکرؓ نے فرمایا اگر تم لوگ یوں چاہو کہ جس طرح ",""],["ٱللَّٰه","a"],[" تعالیٰ وحی کے ذریعے سے اپنے نبیؐ کو سیدھے راستے پر لے آیا کرتے تھے اسی طرح مجھے بھی لے آیا کریں، یہ بات تو مجھے حاصل نہیں ہے۔ میں تو عام انسان ہی ہوں، اس لیے تم لوگ میری نگرانی رکھو۔",""],[" (3)","s"]]]],"f":[["(3)","Bayhaqi (Vol.6 Pg.353)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے ایک مرتبہ بیان فرمایا اور ارشاد فرمایا غور سے سنو! ",""],["ٱللَّٰه","a"],[" کی قسم! میں آپ لوگوں میں سب سے بہتر نہیں ہوں، اور میں اپنے لیے اس مقام خلافت کو پسند نہیں کرتا تھا، مجھے اس کی خواہش نہیں تھی بلکہ میری خواہش تھی کہ آپ لوگوں میں سے کوئی میرے بجائے خلیفہ بن جاتا۔ کیا آپ لوگوں کا خیال یہ ہے کہ میں آپ لوگوں میں بعینہٖ حضورؐ والے طریقہ پر عمل کروں گا؟ تو یہ خیال بالکل غلط ہے، میں ایسا نہیں کر سکوں گا کیونکہ حضورؐ کی تو وحی کے ذریعہ غلط بات سے حفاظت ہو جاتی تھی اور انہیں تو عصمت خداوندی حاصل تھی اور ان کے ساتھ خاص فرشتہ ہر وقت رہتا تھا۔ میرے ساتھ تو شیطان لگا ہوا ہے جو میرے پاس آتا رہتا ہے۔ جب مجھے غصہ آ جائے تو مجھ سے بچ کر رہنا، کہیں میں آپ لوگوں کی کھالوں اور بالوں پر اثر انداز نہ ہو جاؤں۔ غور سے سنو! آپ لوگ میری نگرانی رکھو، اگر میں سیدھا چلوں تو میری مدد کرنا اور اگر میں ٹیڑھا چلوں تو مجھے سیدھا کر دینا۔ حضرت حسنؒ کہتے ہیں کہ ایسا زبردست بیان کیا تھا کہ ",""],["ٱللَّٰه","a"],[" کی قسم! اس کے بعد ویسا بیان تو کبھی ہوا ہی نہیں۔ ایک روایت میں یہ ہے کہ میں تو ایک عام انسان ہوں، کام ٹھیک بھی کر لیتا ہوں اور غلط بھی ہو جاتے ہیں، جب میں ٹھیک کام کروں تو آپ لوگ ",""],["ٱللَّٰه","a"],[" کی تعریف کریں (کیونکہ اسی کے کرم سے کام ٹھیک ہوا) اور جب غلط ہو جائے تو مجھے سیدھا کر دینا۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Abu Dhar Harawi and Ibn Raahway, as quoted in Kanzul Ummaal (Vol.3 Pg.126)."],["(5)","Abu Dhar Harawi in his Jaami' from Qays bin Abi Haazim in abridged form, as quoted in Kanzul Ummaal (Vol.3 Pg.136)."]]},{"b":[["n",[["حضرت قیس بن ابی حازمؒ","b"],[" کہتے ہیں حضورؐ کی وفات کے ایک مہینہ بعد میں حضورؐ کے خلیفہ حضرت ابوبکر صدیقؓ کے پاس بیٹھا ہوا تھا۔ اس کے بعد حضرت قیسؒ نے حضرت ابوبکرؓ کی خلافت کا قصہ ذکر کیا، اس کے بعد کہتے ہیں تمام لوگوں کو مسجد نبوی میں جمع کرنے کے لیے یہ اعلان کیا گیا الصلوٰۃ جامعۃ یعنی سب لوگ نماز مسجد نبوی میں اکٹھے پڑھیں (مدینہ کی باقی نو مسجدوں میں نہ پڑھیں) اور پھر جب لوگ جمع ہو گئے تو حضرت ابوبکرؓ اس منبر پر تشریف فرما ہوئے جو ان کے بیان اور خطبے کے لیے بنایا گیا تھا۔ انہوں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور پھر فرمایا اے لوگو! میری آرزو تو یہ ہے کہ کوئی اور میری جگہ خلیفہ بن جائے۔ اگر تم لوگ مجھ سے یہ مطالبہ کرو کہ میں عین تمہارے نبیؐ کی سنت کے مطابق چلوں تو یہ میرے بس میں نہیں ہے کیونکہ حضورؐ تو معصوم تھے۔ ",""],["ٱللَّٰه","a"],[" نے ان کی شیطان سے مکمل حفاظت فرما رکھی تھی اور ان پر آسمان سے وحی اترتی تھی (اور یہ دونوں باتیں مجھے حاصل نہیں ہیں، اس لیے میں بالکل ان جیسا نہیں ہو سکتا)۔ اور جلد دوم میں طبرانی کی روایت عیسیٰ بن عطیہ کے حوالے سے گزر چکی ہے کہ حضرت ابوبکرؓ نے بیان میں فرمایا اے لوگو! لوگ اسلام میں خوشی اور ناخوشی دونوں طرح داخل ہوئے ہیں لیکن اب وہ سب ",""],["ٱللَّٰه","a"],[" کی پناہ اور اس کے پڑوس میں ہیں، اس لیے تم اس کی پوری کوشش کرو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تم سے اپنی ذمہ داری کا کچھ بھی مطالبہ نہ کرے (یعنی کسی مسلمان کو کسی طرح تکلیف نہ پہنچاؤ)۔ میرے ساتھ بھی ایک شیطان رہتا ہے، جب تم دیکھو کہ مجھے غصہ آ گیا ہے تو پھر تم مجھ سے الگ ہو جاؤ کہ کہیں میں تمہارے بالوں اور کھالوں کو تکلیف نہ پہنچا دوں۔ اے لوگو! اپنے غلاموں کی آمدنی کی تحقیق کر لیا کرو کہ حلال ہے یا حرام، اس لیے کہ جس گوشت کی پرورش حرام مال سے ہو وہ جنت میں داخل ہونے کے لائق نہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad has also reported it. Haythami (Vol.5 Pg.184) has commented that in its chain is Isa bin Musayyab Jabali who is weak."]]},{"b":[["n",[["حضرت عاصم بن عدیؒ","b"],[" کہتے ہیں حضورؐ کی وفات کے اگلے دن حضرت ابوبکرؓ کی طرف سے ایک آدمی نے اعلان کیا کہ حضرت اسامہؓ کے لشکر کی روانگی کا کام مکمل ہو جانا چاہیے۔ غور سے سنو! اب حضرت اسامہؓ کے لشکر کا کوئی آدمی مدینہ میں باقی نہیں رہنا چاہیے بلکہ جرف میں جہاں ان کے لشکر کا پڑاؤ ہے وہاں پہنچ جانا چاہیے۔ اس کے بعد حضرت ابوبکرؓ لوگوں میں بیان کے لیے کھڑے ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان فرمائی پھر فرمایا اے لوگو! میں تمہارے جیسا ہی ہوں، لیکن مجھے معلوم نہیں کہ کیا تم لوگ مجھ سے وہ کام چاہو گے جو صرف حضورؐ کے بس میں تھا (اور میرے بس میں نہیں)۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت محمدؐ کو تمام جہانوں پر فوقیت عطا فرمائی تھی اور انہیں چنا تھا اور انہیں تمام آفات سے حفاظت عطا فرمائی تھی اور میں (ان ہی کے) پیچھے چلنے والا ہوں، اپنی طرف سے نئی چیزیں گھڑنے والا نہیں ہوں۔ اگر میں سیدھا چلوں تو تم میرے پیچھے چلو اور اگر میں ٹیڑھا چلوں تو تم لوگ مجھے سیدھا کر دو۔ حضورؐ کی شان تو یہ تھی کہ جب آپؐ کا انتقال ہوا تو اس وقت امت میں ایک آدمی بھی ایسا نہیں تھا جو کوڑے کی مار یا اس سے کم کسی ظلم کا مطالبہ کر رہا ہو۔ غور سے سنو! میرے ساتھ بھی ایک شیطان لگا ہوا ہے جو میرے پاس آتا رہتا ہے، جب وہ میرے پاس آئے تو مجھ سے تم لوگ الگ ہو جاؤ کہیں میں تمہاری کھالوں اور بالوں کو تکلیف نہ پہنچا دوں۔ تم لوگ صبح اور شام اس موت کے منہ میں ہو جس کا تمہیں علم نہیں کہ کب آ جائے گی۔ تم اس کی پوری کوشش کرو کہ جب بھی تمہاری موت آئے تو تم اس وقت نیک عمل میں لگے ہوئے ہو اور تم ایسا صرف ",""],["ٱللَّٰه","a"],[" کی مدد سے ہی کر سکتے ہو، لہٰذا جب تک موت نے مہلت دے رکھی ہے اس وقت تک تم لوگ نیک اعمال میں ایک دوسرے سے آگے بڑھنے کی کوشش کرو اس سے پہلے کہ موت آ جائے اور عمل کرنے کا موقع نہ رہے، کیونکہ بہت سے لوگوں نے موت کو بھلا رکھا ہے اور اپنے اعمال دوسروں کے لیے کر دیے ہیں۔ لہٰذا تم ان جیسے نہ بنو، خوب کوشش کرو اور مسلسل کوشش کرو اور (سستی سے کام نہ لو بلکہ) جلدی کرو اور جلدی کرو کیونکہ موت تمہارے پیچھے لگی ہوئی ہے جو تمہیں تلاش کر رہی ہے اور اس کی رفتار بہت تیز ہے۔ لہٰذا موت سے چوکنے رہو اور آباؤ اجداد، بیٹوں اور بھائیوں (کی موت) سے عبرت حاصل کرو اور زندہ لوگوں کے ان نیک اعمال پر رشک کرو جن پر تم مردوں کے بارے میں رشک کرتے ہو، یعنی دنیاوی چیزوں میں زندہ لوگوں پر رشک نہ کرو۔",""],[" (7)","s"]]]],"f":[["(7)","Tabari in his Taareekh (Vol.2 Pg.460)."]]},{"b":[["n",[["حضرت سعید بن ابی مریمؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ جب حضرت ابوبکرؓ خلیفہ بنائے گئے تو آپ منبر پر تشریف فرما ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی۔ پھر فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! اگر ہمارے ہوتے ہوئے تمہارے اجتماعی کاموں کے خراب ہو جانے کا خطرہ نہ ہوتا تو (میں خود خلیفہ نہ بنتا بلکہ) میں یہ چاہتا کہ جو تم میں مجھے سب سے زیادہ مبغوض ہے اس کی گردن میں اس امر خلافت کی ذمہ داری ڈال دی جاتی، پھر اس میں مجھے کوئی خیر نہ ہوتی۔ غور سے سنو! دنیا اور آخرت میں سب سے زیادہ بدبخت لوگ بادشاہ ہیں۔ اس پر تمام لوگوں نے گردنیں بلند کیں اور سر اٹھا کر حضرت ابوبکرؓ کی طرف دیکھنے لگے۔ پھر حضرت ابوبکرؓ نے فرمایا تم لوگ اپنی جگہ آرام سے بیٹھے رہو، تم لوگ جلد باز ہو۔ جو بھی کسی ملک کا بادشاہ بنتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے بادشاہ بنانے سے پہلے اس کے ملک کو جانتے ہیں اور بادشاہ بن جانے پر اس کی آدھی عمر کم کر دیتے ہیں اور اس پر خوف اور غم مسلط کر دیتے ہیں اور جو کچھ خود اس کے اپنے پاس ہے اس سے اس کا دل ہٹا دیتے ہیں اور جو کچھ لوگوں کے پاس ہے اس کا لالچ اس میں پیدا کر دیتے ہیں، وہ جو چاہے کتنے اچھے کھانے کھائے اور عمدہ کپڑے پہنے لیکن اس کی زندگی تنگ ہوگی، سکھ چین اسے نصیب نہ ہوگا۔ پھر جب اس کا سایہ ختم ہو جاتا ہے اور اس کی جان نکل جاتی ہے اور اپنے رب کے پاس پہنچ جاتا ہے تو وہ اس سے سختی سے حساب لیتا ہے اور اس کی بخشش کا امکان بہت کم ہوتا ہے بلکہ اس کی بخشش ہی نہیں ہوتی۔ غور سے سنو! مسکین لوگوں کی ہی مغفرت ہوتی ہے۔ غور سے سنو! مسکین لوگوں کی ہی مغفرت ہوتی ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عکیمؒ","b"],[" کہتے ہیں حضرت ابوبکرؓ نے ہم لوگوں میں بیان فرمایا تو اس میں ارشاد فرمایا اما بعد! میں تمہیں اس بات کی وصیت کرتا ہوں کہ تم ",""],["ٱللَّٰه","a"],[" سے ڈرو اور ",""],["ٱللَّٰه","a"],[" کے شایان شان تعریف کرو اور ",""],["ٱللَّٰه","a"],[" کے عذاب کا خوف تو ہونا چاہیے لیکن ساتھ ساتھ اس کی رحمت کی امید بھی رکھو اور ",""],["ٱللَّٰه","a"],[" سے خوب گڑگڑا کر مانگو کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت زکریا علیہ السلام اور ان کے گھر والوں کی قرآن میں تعریف فرمائی ہے اور ارشاد فرمایا ہے",""]]],["q",[["إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًا وَرَهَبًا ۖ وَكَانُوا۟ لَنَا خَٰشِعِينَ ","a"]]],["p",[["ترجمہ: \"یہ سب نیک کاموں میں دوڑتے تھے اور امید و بیم کے ساتھ ہماری عبادت کیا کرتے تھے اور ہمارے سامنے دب کر رہتے تھے\" (سورۃ الانبیاء، آیت 90)۔ پھر اے ",""],["ٱللَّٰه","a"],[" کے بندو! تم یہ بھی جان لو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے حق کے بدلہ میں تمہاری جانوں کو گروی رکھا ہوا ہے اور اس پر ",""],["ٱللَّٰه","a"],[" نے تم سب سے پختہ عہد لیا ہوا ہے اور اس نے تم سے (دنیا کے) تھوڑے اور ختم ہو جانے والے مال و سامان کو (آخرت کے) زیادہ اور ہمیشہ رہنے والے اجر کے بدلے میں خرید لیا ہے۔ اور یہ تم میں ",""],["ٱللَّٰه","a"],[" کی کتاب ہے جس کے عجائب ختم نہیں ہو سکتے اور اس کا نور کبھی بجھ نہیں سکتا، لہٰذا اس کتاب کے ہر قول کی تصدیق کرو اور اس سے نصیحت حاصل کرو اور اندھیرے والے دن کے لیے اس میں سے روشنی حاصل کرو۔ ",""],["ٱللَّٰه","a"],[" نے تمہیں صرف عبادت کے لیے پیدا کیا ہے اور لکھنے والے کریم فرشتوں کو تم پر مقرر کیا ہے جو تمہارے ہر فعل کو جانتے ہیں۔ پھر اے ",""],["ٱللَّٰه","a"],[" کے بندو! یہ بھی جان لو کہ تم صبح اور شام اس موت کی طرف بڑھ رہے ہو جس کا وقت مقرر ہے لیکن تمہیں وہ بتایا نہیں گیا۔ تم اس کی پوری کوشش کرو کہ جب تمہاری عمر کا آخری وقت آئے تو تم اس وقت ",""],["ٱللَّٰه","a"],[" کے کسی عمل میں لگے ہوئے ہو اور ایسا تم صرف ",""],["ٱللَّٰه","a"],[" کی مدد سے ہی کر سکتے ہو۔ لہٰذا عمر کے پورے ہونے سے پہلے تمہیں جو مہلت ملی ہوئی ہے اس میں نیک اعمال میں ایک دوسرے سے آگے بڑھو ورنہ تمہیں اپنے برے اعمال کی طرف جانا پڑے گا، کیونکہ بہت سے لوگوں نے اپنے آپ کو بھلا رکھا ہے اور اپنی عمر دوسروں کو دے دی ہے یعنی اپنے ایمان و عمل کی انہیں کوئی فکر نہیں ہے۔ میں تمہیں ان جیسا بننے سے سختی سے روکتا ہوں، جلدی کرو جلدی کرو کیونکہ تمہارے پیچھے موت کا فرشتہ لگا ہوا ہے جو تمہیں تیزی سے تلاش کر رہا ہے، اس کی رفتار بہت تیز ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.35). Ibn Abi Shaybah, Haakim and Bayhaqi have reported a similar narration, and parts of it have been reported by Ibn Abi Dunya in his Qasrul Amal, as quoted in Kanzul Ummaal (Vol.8 Pg.206)."]]},{"b":[["n",[["حضرت عمرو بن دینارؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابوبکرؓ نے بیان فرمایا، اس میں ارشاد فرمایا تمہارے فقر و فاقہ کی وجہ سے میں تمہیں اس بات کی وصیت کرتا ہوں کہ تم ",""],["ٱللَّٰه","a"],[" سے ڈرو اور اس کی شان کے مطابق اس کی تعریف کرو اور اس سے مغفرت طلب کرو کیونکہ وہ بہت زیادہ مغفرت کرنے والا ہے۔ اس کے بعد حضرت عبد",""],["ٱللَّٰه","a"],[" بن عکیمؒ والی پچھلی حدیث جیسا مضمون ذکر کیا اور مزید یہ مضمون ذکر کیا کہ تم اس بات کو بھی جان لو کہ جو عمل تم خالص ",""],["ٱللَّٰه","a"],[" کے لیے کرو گے تو اس طرح تم اپنے رب کی اطاعت کرو گے اور اپنے حق کو محفوظ کر لو گے۔ لہٰذا تم اپنے قرض دینے کے زمانہ میں یعنی دنیاوی زندگی میں جو تم نے کمایا ہے وہ سب (",""],["ٱللَّٰه","a"],[" کو) دے دو اور اپنے سامنے ان کو بطور نوافل کے رکھو (یعنی جتنا مال خرچ کرنا فرض ہے وہ تو خرچ کرنا ہی ہے، مزید اور بھی خرچ کرو)۔ اس طرح تمہیں شدید ضرورت کے وقت اور عین محتاجی کے زمانے میں اپنی ان کمائیوں کا اور دیے ہوئے اپنے قرضوں کا پورا پورا بدلہ ملے گا۔ پھر اے ",""],["ٱللَّٰه","a"],[" کے بندو! لوگوں کے بارے میں سوچو جو تم سے پہلے دنیا میں تھے، وہ کل کہاں تھے اور آج کہاں ہیں؟ وہ بادشاہ کہاں ہیں جنہوں نے زمین کو خوب بویا اور جوتا تھا، خوب کھیتی باڑی کی تھی اور سامان تعمیرات سے زمین کو خوب آباد کیا تھا؟ آج سب لوگ انہیں بھول چکے ہیں اور ان کا تذکرہ تک بھلایا جا چکا ہے، لہٰذا آج وہ ایسے ہیں جیسے کہ وہ کچھ بھی نہ تھے اور ان کے کفر و ظلم کی وجہ سے ان کے گھر اور شہر ویران پڑے ہیں اور وہ بادشاہ خود اس وقت قبر کی تاریکیوں میں ہیں۔ کیا تم ان ہلاک ہونے والوں میں سے کسی کو دیکھتے ہو یا ان میں سے کسی کی ہلکی سی بھی آواز سنتے ہو؟ تمہارے وہ ساتھی اور بھائی آج کہاں ہیں جن کو تم پہچانتے تھے؟ وہ ان اعمال کے بدلے کی جگہ پر پہنچ گئے ہیں جو انہوں نے آگے بھیجے تھے اور بدبختی یا نیک بختی دونوں میں سے کسی ایک کی جگہ پر پہنچ گئے ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ اور اس کی کسی مخلوق کے درمیان کوئی ایسا نسب کا رشتہ نہیں ہے جس کی وجہ سے ",""],["ٱللَّٰه","a"],[" اسے خیر دے اور اس سے برائی کو دور کرے۔ ",""],["ٱللَّٰه","a"],[" سے یہ باتیں تو صرف اس کی اطاعت اور اس کے حکم کے پیچھے چلنے سے ہی حاصل ہو سکتی ہیں۔ وہ راحت، راحت نہیں ہے جس کے بعد جہنم ہو اور وہ تکلیف، تکلیف نہیں جس کے بعد جنت ہو۔ میں اسی بات پر اپنی بات ختم کرتا ہوں اور اپنے لیے اور تمہارے لیے ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilyah (Vol.1 Pg.35)."]]},{"b":[["n",[["حضرت نعیم بن نمحہؒ","b"],[" حضرت عبد",""],["ٱللَّٰه","a"],[" بن عکیمؒ جیسی حدیث میں حضرت ابوبکرؓ کا بیان نقل کرتے ہیں اور مزید یہ بھی روایت کرتے ہیں کہ حضرت ابوبکرؓ نے فرمایا اس قول میں کوئی خیر نہیں جس سے ",""],["ٱللَّٰه","a"],[" کی رضا مقصود نہ ہو اور اس مال میں کوئی خیر نہیں جسے ",""],["ٱللَّٰه","a"],[" کے راستہ میں خرچ نہ کیا جائے اور اس آدمی میں کوئی خیر نہیں جس کی نادانی اس کی بردباری پر غالب ہو اور اس آدمی میں کوئی خیر نہیں جو ",""],["ٱللَّٰه","a"],[" کے معاملے میں ملامت کرنے والوں کی ملامت سے ڈرے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilyah (Vol.1 Pg.36). Tabraani has also reported it in full from Nu'aym bin Namhah with the additional part that Abu Nu'aym mentioned, as quoted by Haafiz Ibn Katheer in his Tafseer (Vol.4 Pg.342), who said that this chain is jayyid and its narrators are reliable."]]},{"b":[["n",[["حضرت عاصم بن عدیؒ","b"],[" نے پہلے دوسرا بیان نقل کیا جیسے ہم نے ابھی ذکر کیا، پھر حضرت عاصمؒ کہتے ہیں کہ حضرت ابوبکرؓ بیان کے لیے کھڑے ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ صرف وہی عمل قبول کرتے ہیں جس سے مقصود صرف ان کی ذات عالی ہو، لہٰذا تم اپنے اعمال سے صرف اسی کی ذات کو مقصود بناؤ اور اس کا یقین رکھو کہ تم جو عمل خالص ",""],["ٱللَّٰه","a"],[" کے لیے کرو گے تو یہ ایک نیکی ہے جو تم نے کی ہے اور بڑا حصہ ہے جسے حاصل کرنے میں تم کامیاب ہو گئے ہو اور یہ تمہاری ایسی آمدنی ہے جو تم نے (",""],["ٱللَّٰه","a"],[" کو) دے دی ہے اور یہ قرض ہے جو تم نے فانی دنیا کے دنوں سے لے کر ہمیشہ باقی رہنے والی آخرت کے لیے آگے بھیج دیا ہے اور یہ قرض تمہیں اس وقت کام آئے گا جب تمہیں اس کی سخت ضرورت ہوگی۔ اے ",""],["ٱللَّٰه","a"],[" کے بندو! جو تم میں سے مر گئے ہیں ان سے عبرت حاصل کرو اور جو تم سے پہلے تھے ان کے بارے میں غور کرو کہ وہ کل کہاں تھے اور آج کہاں ہیں؟ ظالم اور جابر لوگ کہاں ہیں؟ اور وہ لوگ کہاں ہیں جن کے میدان جنگ میں لڑنے اور غلبہ پا لینے کے تذکرے ہوتے تھے؟ زمانے نے ان کو ذلیل کر دیا، آج ان کی ہڈیاں بوسیدہ ہو چکی ہیں اور اب تو ان کے تذکرے بھی ختم ہو گئے ہیں۔ خبیث عورتیں خبیث مردوں کے لیے ہیں اور خبیث مرد خبیث عورتوں کے لیے ہیں۔ اور وہ بادشاہ کہاں ہیں جنہوں نے زمین کو خوب بویا اور جوتا تھا اور اسے ہر طرح آباد کیا تھا؟ اب وہ ہلاک ہو چکے ہیں اور ان کا تذکرہ بھی لوگ بھول چکے ہیں اور ایسے ہو گئے ہیں جیسے کہ وہ کچھ نہیں تھے۔ غور سے سنو! ",""],["ٱللَّٰه","a"],[" نے ان کی خواہشات کا سلسلہ تو (موت کے ذریعہ سے) ختم کر دیا ہے لیکن گناہوں کی سزا کا سلسلہ باقی رکھا ہوا ہے۔ وہ دنیا سے جا چکے ہیں اور انہوں نے جو عمل کیے تھے وہ تو اب ان کے ہیں، لیکن جو دنیا ان کے پاس تھی اب وہ دوسروں کی ہو گئی ہے۔ اب ہم ان کے بعد آئے ہیں، اگر ہم ان سے عبرت حاصل کریں گے تو نجات پائیں گے اور اگر ہم دھوکے میں پڑے رہے تو ہم بھی ان جیسے ہو جائیں گے۔ کہاں ہیں وہ حسین و جمیل لوگ جن کے چہرے خوبصورت تھے اور وہ اپنی جوانی پر اکڑتے تھے؟ اب وہ مٹی کے ہو چکے ہیں اور جن اعمال کے بارے میں انہوں نے کمی بیشی کی تھی اب وہ اعمال ان کے لیے حسرت کا باعث بنے ہوئے ہیں۔ کہاں ہیں وہ لوگ جنہوں نے بہت سے شہر بنائے تھے اور شہروں کے ارد گرد بڑی مضبوط دیواریں بنائی تھیں اور ان میں عجیب و غریب چیزیں بنائی تھیں؟ اور بعد میں آنے والوں کے لیے وہ ان شہروں کو چھوڑ کر چلے گئے اور اب ان کے رہنے کی جگہیں ویران پڑی ہوئی ہیں اور وہ خود قبر کی اندھیریوں میں ہیں۔ کیا تم ان میں سے کسی کو دیکھتے ہو یا ان کی ہلکی سی بھی آواز سنتے ہو؟ تمہارے وہ بیٹے اور بھائی کہاں ہیں جنہیں تم پہچانتے تھے؟ ان کی عمریں ختم ہو گئیں اور جو اعمال انہوں نے آگے بھیجے تھے اب وہ ان اعمال کے پاس پہنچ گئے ہیں اور وہاں ٹھہر گئے ہیں اور موت کے بعد بدبختی یا نیک بختی والی جگہ انہیں مل گئی ہے۔ غور سے سنو! ",""],["ٱللَّٰه","a"],[" کا کوئی شریک نہیں۔ ",""],["ٱللَّٰه","a"],[" کے اور اس کی کسی مخلوق کے درمیان کوئی ایسا خاص تعلق نہیں ہے جس کی وجہ سے ",""],["ٱللَّٰه","a"],[" اسے خیر دے اور اس سے برائی کو ہٹا دے۔ ",""],["ٱللَّٰه","a"],[" سے تعلق تو صرف اطاعت سے اور اس کے حکم کے پیچھے چلنے سے بنتا ہے۔ اور اس بات کو جان لو کہ تم ایسے بندے ہو جنہیں ان کے اعمال کا بدلہ ضرور ملے گا اور جو کچھ ",""],["ٱللَّٰه","a"],[" کے پاس ہے وہ صرف اس کی اطاعت سے حاصل ہو سکتا ہے۔ غور سے سنو! وہ راحت، راحت نہیں جس کے بعد جہنم ہو اور وہ تکلیف، تکلیف نہیں جس کے بعد جنت ہو۔",""],[" (11)","s"]]]],"f":[["(11)","Tabari has reported this sermon in his Taareekh (Vol.2 Pg.460) with a chain containing Sayf."]]},{"b":[["n",[["حضرت موسیٰ بن عقبہؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ بیان میں اکثر یہ فرمایا کرتے تھے کہ تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا پالنے والا ہے۔ میں ",""],["ٱللَّٰه","a"],[" کی تعریف کرتا ہوں اور ہم اس سے مدد مانگتے ہیں اور موت کے بعد کے اکرام کا اس سے سوال کرتے ہیں، کیونکہ میری اور تمہاری موت کا وقت قریب آ گیا ہے۔ اور میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں اور حضرت محمدؐ اس کے بندے اور رسول ہیں جنہیں ",""],["ٱللَّٰه","a"],[" نے حق دے کر خوشخبری سنانے والا اور ڈرانے والا اور روشن چراغ بنا کر بھیجا تاکہ جو شخص زندہ ہے وہ اسے ڈرائیں اور کافروں پر (عذاب کی) حجت ثابت ہو جائے۔ جس نے ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی اطاعت کی وہ ہدایت یافتہ ہو گیا اور جس نے ان دونوں کی نافرمانی کی وہ کھلی گمراہی میں پڑ گیا۔ میں آپ لوگوں کو اس بات کی وصیت کرتا ہوں کہ ",""],["ٱللَّٰه","a"],[" سے ڈرو اور ",""],["ٱللَّٰه","a"],[" کے اس دین کو مضبوطی سے پکڑو جو اس نے تمہارے لیے شریعت بنایا اور جس کی اس نے تمہیں ہدایت دی اور کلمۂ اخلاص (",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" محمد رسول ",""],["ٱللَّٰه","a"],[") کے بعد ہدایت اسلام کی جامع بات یہ ہے کہ اس آدمی کی بات سنی اور مانی جائے جس کو ",""],["ٱللَّٰه","a"],[" نے تمہارے تمام کاموں کا والی اور ذمہ دار بنایا ہے۔ جس نے امر بالمعروف اور نہی عن المنکر کے والی اور ذمہ دار کی اطاعت کی وہ کامیاب ہو گیا، جو حق اس کے ذمہ تھا وہ اس نے ادا کر دیا۔ اور اپنی خواہش کے پیچھے چلنے سے بچو، اور جو آدمی خواہش کے پیچھے چلنے سے، لالچ میں پڑنے سے اور غصہ میں آنے سے محفوظ رہا وہ کامیاب ہو گیا۔ اور اترانے سے بچو، اور اس انسان کا اترانا کیا اترانا جو مٹی سے بنا ہے اور عنقریب مٹی میں چلا جائے گا پھر اسے کیڑے کھا جائیں گے۔ آج وہ زندہ ہے اور کل وہ مرا ہوا ہوگا۔ ہر روز اور ہر گھڑی عمل کرتے رہو اور مظلوم کی بد دعا سے بچو اور اپنے آپ کو مردوں میں شمار کرو اور صبر کرو کیونکہ ہر عمل صبر کے ذریعہ ہی ہوتا ہے اور چوکنے رہو کیونکہ چوکنا رہنے سے فائدہ ہوتا ہے اور عمل کرتے رہو کیونکہ عمل ہی قبول ہوتے ہیں۔ اور ",""],["ٱللَّٰه","a"],[" نے اپنے جس عذاب سے ڈرایا ہے اس سے ڈرتے رہو اور ",""],["ٱللَّٰه","a"],[" نے اپنی جس رحمت کا وعدہ کیا ہے اسے حاصل کرنے میں جلدی کرو، سمجھنے کی کوشش کرو ",""],["ٱللَّٰه","a"],[" تمہیں سمجھا دے گا اور بچنے کی کوشش کرو ",""],["ٱللَّٰه","a"],[" تمہیں بچا دے گا، کیونکہ ",""],["ٱللَّٰه","a"],[" نے وہ اعمال بھی تمہارے سامنے بیان کر دیے ہیں جن کی وجہ سے تم سے پہلے لوگوں کو ",""],["ٱللَّٰه","a"],[" نے ہلاک کیا ہے اور وہ اعمال بھی بیان کر دیے ہیں جن کی وجہ سے نجات پانے والوں کو نجات ملی۔ اور ",""],["ٱللَّٰه","a"],[" نے اپنی کتاب میں اپنا حلال اور حرام اور اپنے پسندیدہ اور ناپسندیدہ اعمال سب بیان کر دیے ہیں۔ اور میں تمہارے بارے میں اور اپنے بارے میں کوئی کوتاہی نہیں کروں گا اور ",""],["ٱللَّٰه","a"],[" ہی سے مدد مانگی جاتی ہے اور برائی سے بچنے اور نیکی کرنے کی اطاعت ",""],["ٱللَّٰه","a"],[" ہی سے ملتی ہے۔ اور تم اس بات کو جان لو کہ تم جو عمل خالص ",""],["ٱللَّٰه","a"],[" کے لیے کرو گے تو اس طرح تم اپنے رب کی اطاعت کرو گے اور (آخرت میں اجر و ثواب کے) اپنے بڑے حصے کو محفوظ کر لو گے اور قابل رشک بن جاؤ گے۔ اور جو اعمال تم نے فرائض کے علاوہ کیے ہیں انہیں اپنے آگے کے لیے نفل بنا لو، اس طرح تم جو ",""],["ٱللَّٰه","a"],[" کو اعمال کا قرضہ دو گے اس قرضہ کا تمہیں آخرت میں پورا پورا بدلہ ملے گا جبکہ تمہیں اس کی شدید ضرورت ہوگی۔ پھر اے ",""],["ٱللَّٰه","a"],[" کے بندو! اپنے ان بھائیوں اور ساتھیوں کے بارے میں سوچو جو دنیا سے جا چکے ہیں، جو اعمال انہوں نے آگے بھیجے تھے اب وہ ان اعمال کے پاس پہنچ گئے ہیں اور وہاں ٹھہر گئے ہیں اور موت کے بعد بدبختی یا خوش قسمتی کی جگہ میں پہنچ گئے ہیں۔ ",""],["ٱللَّٰه","a"],[" کا کوئی شریک نہیں، ",""],["ٱللَّٰه","a"],[" کے اور اس کی کسی مخلوق کے درمیان کوئی نسب کا رشتہ نہیں جس کی وجہ سے ",""],["ٱللَّٰه","a"],[" اسے کوئی خیر دے یا اس سے کوئی برائی ہٹا دے، بلکہ یہ باتیں تو صرف ",""],["ٱللَّٰه","a"],[" کی اطاعت سے اور اس کے حکم کے پیچھے چلنے سے ہی حاصل ہو سکتی ہیں۔ اور وہ راحت، راحت نہیں جس کے بعد جہنم کی آگ ہو اور وہ تکلیف، تکلیف نہیں جس کے بعد جنت ہو۔ میں اسی بات پر ختم کرتا ہوں اور میں تمہارے لیے اور اپنے لیے ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں اور اپنے نبی پر درود بھیجتا ہوں۔",""]]],["q",[["وَصَلَّى ٱللَّهُ عَلَيْهِ وَٱلسَّلَامُ عَلَيْهِ وَرَحْمَةُ ٱللَّهِ وَبَرَكَاتُهُ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ ان پر درود بھیجے اور ان پر سلام ہو اور ",""],["ٱللَّٰه","a"],[" کی رحمت اور اس کی برکتیں ہوں۔\"",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abi Dunya in Kitaabul Hadhr and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.206)."]]},{"b":[["n",[["حضرت یزید بن ہارونؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے ایک مرتبہ بیان فرمایا اور اس میں ارشاد فرمایا کہ ایک ایسے بندے کو قیامت کے دن لایا جائے گا جسے ",""],["ٱللَّٰه","a"],[" نے دنیا میں بہت نعمتیں دی تھیں اور اسے رزق میں خوب وسعت دی تھی اور اسے جسمانی صحت کی نعمت بھی دی تھی لیکن اس نے اپنے رب کی ناشکری کی تھی۔ اسے ",""],["ٱللَّٰه","a"],[" کے سامنے کھڑا کیا جائے گا اور کہا جائے گا تم نے آج کے دن کے لیے کیا کیا اور اپنے لیے کون سے عمل آگے بھیجے؟ وہ کوئی نیک عمل آگے بھیجا ہوا نہیں پائے گا، اس پر وہ رونے لگے گا اور اتنا روئے گا کہ آنسو ختم ہو جائیں گے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ کے احکام ضائع کرنے کی وجہ سے اسے شرم دلائی جائے گی اور رسوا کیا جائے گا، اس پر وہ خون کے آنسو رونے لگے گا۔ پھر اسے شرم دلائی جائے گی اور رسوا کیا جائے گا، جس پر وہ اپنے دونوں ہاتھوں کو کہنیوں سمیت کھائے گا۔ پھر ",""],["ٱللَّٰه","a"],[" کے احکام ضائع کرنے پر اسے شرم دلائی جائے گی اور رسوا کیا جائے گا، جس پر وہ اونچی آواز سے روئے گا اور اس کی آنکھیں نکل کر اس کے رخساروں پر آ گریں گی اور دونوں آنکھوں میں سے ہر آنکھ تین میل لمبی اور تین میل چوڑی ہوگی۔ پھر اسے شرم دلائی جائے گی اور رسوا کیا جائے گا یہاں تک کہ وہ پریشان ہو کر کہے گا اے میرے رب! مجھے دوزخ میں بھیج دے اور مجھ پر رحم فرما کر مجھے یہاں سے نکال دے۔ اور اسے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس آیت میں بیان کیا ہے",""]]],["q",[["أَنَّهُۥ مَن يُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَٰلِدًا فِيهَا ۚ ذَٰلِكَ ٱلْخِزْىُ ٱلْعَظِيمُ","a"]]],["p",[["ترجمہ: \"جو شخص ",""],["ٱللَّٰه","a"],[" کی اور اس کے رسولؐ کی مخالفت کرے گا (جیسا یہ لوگ کر رہے ہیں) تو یہ بات ٹھہر چکی ہے کہ ایسے شخص کو دوزخ کی آگ اس طور پر نصیب ہوگی کہ وہ اس میں ہمیشہ رہے گا، یہ بڑی رسوائی ہے\" (سورۂ توبہ، آیت 63)۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Shaykh, as quoted in Kanzul Ummaal (Vol.1 Pg.246)."]]},{"b":[["n",[["حضرت محمد بن ابراہیم بن حارثؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے لوگوں میں بیان فرمایا اور ارشاد فرمایا اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اگر تم تقویٰ اور پاکدامنی اختیار کرو تو تھوڑا عرصہ ہی گزرے گا کہ تمہیں پیٹ بھر کر روٹی اور گھی ملنے لگے گا۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Abi Dunya and Dinawari, as quoted in Kanzul Ummaal (Vol.8 Pg.206)."]]},{"b":[["n",[["حضرت عروہ بن زبیرؒ","b"],[" فرماتے ہیں حضرت ابوبکرؓ نے ایک مرتبہ لوگوں میں بیان فرمایا، اس میں ارشاد فرمایا اے مسلمانوں کی جماعت! ",""],["ٱللَّٰه","a"],[" عز و جل سے حیا کرو۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! جب میں قضائے حاجت کے لیے جنگل جاتا ہوں تو میں اپنے رب سے حیا کی وجہ سے اپنے اوپر کپڑا اوڑھے رہتا ہوں۔",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Hilyah (Vol.1 Pg.34) from Urwah bin Zubayr. Ibn Mubarak, Darsah, Ibn Abi Shaybah and Kharaa'iti in his Makaarimul Akhlaaq have reported a similar narration from Ibn Zubayr, as quoted in Kanzul Ummaal (Vol.8 Pg.206)."]]},{"b":[["n",[["حضرت ابن شہابؒ","b"],[" کہتے ہیں حضرت ابوبکرؓ نے ایک دن بیان کرتے ہوئے فرمایا ",""],["ٱللَّٰه","a"],[" سے حیا کرو کیونکہ ",""],["ٱللَّٰه","a"],[" کی قسم! جب سے میں حضورؐ سے بیعت ہوا ہوں اس وقت سے جب بھی قضائے حاجت کے لیے باہر جاتا ہوں تو اپنے رب سے حیا کی وجہ سے میں اپنا سر کپڑے سے ڈھانکے رکھتا ہوں۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Hibbaan in his Rawdatul Uqalaa, as quoted in Kanzul Ummaal (Vol.5 Pg.124). He remarked that it is munqati'."]]},{"b":[["n",[["حضرت ابوبکرؓ","b"],[" ایک دن منبر پر کھڑے ہوئے تو رونے لگے، پھر فرمایا پہلے سال حضورؐ ہم میں بیان کرنے کے لیے منبر پر کھڑے ہوئے تو رونے لگے اور ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" سے معافی بھی مانگو اور عافیت بھی، کیونکہ کسی آدمی کو ایمان و یقین کے بعد عافیت سے بہتر کوئی نعمت نہیں دی گئی یعنی سب سے بڑی نعمت تو ایمان و یقین ہے اور اس کے بعد عافیت ہے۔",""],[" (17)","s"]]]],"f":[["(17)","Tirmidhi, who graded it hasan, and Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.233)."]]},{"b":[["n",[["حضرت اوسؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے ایک دن ہم لوگوں میں بیان فرمایا اور ارشاد فرمایا پچھلے سال حضورؐ نے میری اسی جگہ کھڑے ہو کر بیان فرمایا تھا، اس میں ارشاد فرمایا تھا ",""],["ٱللَّٰه","a"],[" سے عافیت مانگو کیونکہ کسی کو یقین کے بعد عافیت سے افضل نعمت نہیں دی گئی، اور سچ کو لازم پکڑے رہو کیونکہ سچ بولنے سے آدمی نیک اعمال تک پہنچ جاتا ہے۔ سچ اور نیک اعمال جنت میں لے جاتے ہیں اور جھوٹ سے بچو کیونکہ جھوٹ بولنے سے آدمی فسق و فجور تک پہنچ جاتا ہے اور جھوٹ اور فسق و فجور دوزخ میں لے جاتے ہیں۔ آپس میں حسد نہ کرو اور ایک دوسرے سے بغض نہ رکھو، قطع تعلق نہ کرو۔ ایک دوسرے سے پیٹھ نہ پھیرو اور جیسے تمہیں ",""],["ٱللَّٰه","a"],[" نے حکم دیا ہے ",""],["ٱللَّٰه","a"],[" کے بندے اور بھائی بھائی بن کر رہو۔",""],[" (18)","s"]]]],"f":[["(18)","Ahmad, Nasa'ee, Ibn Hibbaan and Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.291)."]]},{"b":[["n",[["حضرت ابوبکر بن محمد بن عمرو بن حزمؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے ایک مرتبہ بیان فرمایا اور اس میں ارشاد فرمایا کہ حضورؐ نے فرمایا نفاق والے خشوع سے ",""],["ٱللَّٰه","a"],[" کی پناہ مانگو۔ صحابہؓ نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! نفاق والا خشوع کیا ہے؟ آپؐ نے فرمایا دل میں تو نفاق ہو لیکن ظاہر بدن میں خشوع ہو۔",""],[" (19)","s"]]]],"f":[["(19)","Haakim, Askari and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.229)."]]},{"b":[["n",[["حضرت ابوالعالیہؒ","b"],[" کہتے ہیں حضرت ابوبکر صدیقؓ نے ہم میں بیان فرمایا اور اس میں ارشاد فرمایا کہ حضورؐ نے فرمایا مسافر (چار رکعت والی نماز کی) دو رکعت پڑھے گا اور مقیم چار رکعت پڑھے گا۔ میری پیدائش کی جگہ مکہ ہے اور میری ہجرت کی جگہ مدینہ ہے اور جب میں ذوالحلیفہ سے مکہ کی طرف روانہ ہوتا ہوں تو دو رکعت نماز پڑھتا ہوں۔",""],[" (20)","s"]]]],"f":[["(20)","Abu Nu'aym in his Hilyah and Ibn Jareer, as quoted in Kanzul Ummaal (Vol.4 Pg.239)."]]},{"b":[["n",[["حضرت ضمرہؒ","b"],[" کہتے ہیں حضرت ابوبکرؓ نے لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا عنقریب تمہارے لیے ملک شام فتح کر دیا جائے گا، پھر تم وہاں نرم زمین میں جاؤ گے اور روٹی اور تیل سے اپنا پیٹ بھرو گے اور وہاں تمہارے لیے مسجدیں بنائی جائیں گی۔ اور اس بات سے بچنا کہ ",""],["ٱللَّٰه","a"],[" کے علم میں یہ بات آئے کہ تم لوگ کھیل کود کے لیے ان مسجدوں میں جاتے ہو کیونکہ مسجدیں تو صرف ذکر کے لیے بنائی گئی ہیں۔",""],[" (21)","s"]]]],"f":[["(21)","Ahmad in his Zuhd, as quoted in Kanzul Ummaal (Vol.4 Pg.259)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضرت ابوبکرؓ ہم میں بیان فرماتے تو انسان کی پیدائش کی ابتدا کا تذکرہ کرتے اور فرماتے انسان پیشاب کی نالی سے دو دفعہ گزر کر پیدا ہوا ہے اور اس طرح تذکرہ کرتے کہ ہم اپنے آپ کو ناپاک سمجھنے لگتے۔ جہاد کے باب میں مرتدین سے جنگ کی ترغیب کے بارے میں اور جہاد کی ترغیب کے بارے میں اور روم سے غزوہ کرنے کے لیے جانے کے بارے میں اور صحابہ کرامؓ کے ملک شام جانے کے وقت حضرت ابوبکرؓ کے بیانات گزر چکے ہیں اور صحابہ کرامؓ کے باہمی اتحاد اور اتفاق رائے کے اہتمام کے باب میں آپس کے انتشار سے ڈرانے اور حضورؐ کی وفات کے واقع ہو جانے اور حضورؐ کے دین کو مضبوطی سے پکڑنے اور خلافت میں قریش کو ترجیح دینے اور خلافت قبول کرنے سے عذر پیش کرنے اور بیعت مسلمانوں کو واپس کرنے اور خلیفہ کی صفات کے بارے میں حضرت ابوبکرؓ کے بیانات گزر چکے ہیں اور امر بالمعروف اور نہی عن المنکر کے باب میں آیت لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهْتَدَيْتُمْ کی تفسیر کے بارے میں حضرت ابوبکرؓ کا بیان گزر چکا ہے۔",""],[" (22)","s"]]]],"f":[["(22)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.8 Pg.205)."]]}]},"180":{"lead":[],"stories":[{"b":[["n",[["حضرت حمید بن ہلالؒ","b"],[" کہتے ہیں ایک صاحب حضرت ابوبکرؓ کی وفات کے موقع پر موجود تھے۔ انہوں نے ہمیں بتایا کہ حضرت عمرؓ نے حضرت ابوبکرؓ کے دفن سے فارغ ہو کر قبر کی مٹی ہاتھوں سے جھاڑی، پھر اسی جگہ کھڑے ہو کر بیان کیا اور اس میں فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہارے ذریعہ سے مجھے اور میرے ذریعہ سے تمہیں آزمائیں گے اور ",""],["ٱللَّٰه","a"],[" نے مجھے میرے دو حضرات (رسول پاکؐ اور حضرت ابوبکرؓ) کے بعد آپ لوگوں میں باقی رکھا ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! ایسا نہیں ہو سکے گا کہ میرے پاس تمہارا کوئی کام پیش ہو اور میرے علاوہ کوئی اور کام کرے اور نہ ہی ایسے ہو سکے گا کہ تمہارا کوئی کام میری غیر موجودگی سے تعلق رکھتا ہو اور میں اس کی کفایت کرنے اور اس کے بارے میں امانت داری اختیار کرنے میں کوتاہی کروں۔ اگر لوگ اچھے عمل کریں گے تو میں ان کے ساتھ اچھا سلوک کروں گا اور اگر برے عمل کریں گے تو میں انہیں عبرت ناک سزا دوں گا۔ وہ بتانے والے صاحب کہتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! حضرت عمرؓ نے دنیا سے جانے تک پہلے دن کے بیان کردہ اپنے اس اصول کے خلاف نہ کیا، ہمیشہ اسی پر قائم رہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.3 Pg.275)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں جب حضرت عمر بن خطابؓ خلیفہ بنے تو وہ منبر پر تشریف فرما ہوئے اور فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے ایسا نہیں دیکھنا چاہتے کہ میں اپنے آپ کو منبر کی اس جگہ بیٹھنے کا اہل سمجھوں جہاں ابوبکرؓ بیٹھا کرتے تھے۔ یہ کہہ کر حضرت عمرؓ ایک سیڑھی نیچے ہو گئے۔ پھر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر فرمایا قرآن پڑھو، اس کے ذریعے سے پہچانے جاؤ گے اور قرآن پر عمل کرو، اس سے تم قرآن والوں میں سے ہو جاؤ گے۔ اور اعمال نامے کے تولے جانے سے پہلے پہلے تم خود اپنا موازنہ کر لو اور اس دن کی بڑی پیشی کے لیے اپنے آپ کو (نیک اعمال سے) آراستہ کر لو جس دن تم ",""],["ٱللَّٰه","a"],[" کے سامنے پیش کیے جاؤ گے اور تمہاری کوئی پوشیدہ بات چھپی نہیں رہ سکے گی۔ اور کسی حق والے کا حق اتنا نہیں بنتا کہ اس کی بات مان کر ",""],["ٱللَّٰه","a"],[" کی نافرمانی کی جائے۔ غور سے سنو! میں ",""],["ٱللَّٰه","a"],[" کے مال یعنی بیت المال میں سے اتنا لوں گا جتنا یتیم کے والی کو یتیم کے مال میں سے ملتا ہے، اگر مجھے اس کی بھی ضرورت نہ ہوئی تو میں یہ بھی نہیں لوں گا اور اگر ضرورت ہوئی تو کام کرنے والے کو عام طور سے جتنا ملتا ہے اس کے مطابق لوں گا۔",""],[" (2)","s"]]]],"f":[["(2)","Dinawari, as quoted in Kanzul Ummaal (Vol.8 Pg.210). Fadaa'ili has reported a similar narration from Sha'bi, as quoted in Riyaadun Nadrah (Vol.2 Pg.89)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے ایک بیان میں فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ کے تم سے حساب لینے سے پہلے پہلے تم اپنا محاسبہ کر لو، اس سے ",""],["ٱللَّٰه","a"],[" کا حساب آسان ہو جائے گا اور اعمال نامے کے تولے جانے سے پہلے پہلے تم اپنا موازنہ کر لو اور اس دن کی بڑی پیشی کے لیے اپنے آپ کو (نیک اعمال سے) آراستہ کر لو جس دن تم ",""],["ٱللَّٰه","a"],[" کے سامنے پیش کیے جاؤ گے اور تمہاری کوئی پوشیدہ بات چھپی نہیں رہ سکے گی۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Mubarak, Sa'eed bin Mansoor, Ahmad in his Zuhd, Ibn Abi Shaybah and others, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]},{"b":[["n",[["حضرت ابوفراسؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمر بن خطابؓ نے بیان فرمایا اور ارشاد فرمایا اے لوگو! غور سے سنو! پہلے ہمیں آپ لوگوں کے اندرونی حالات اس طرح معلوم ہو جاتے تھے کہ نبی کریمؐ ہمارے درمیان تشریف فرما تھے اور وحی نازل ہوا کرتی تھی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیں آپ لوگوں کے حالات بتا دیا کرتے تھے (کہ کون مومن ہے اور کون منافق اور کس مومن کا درجہ بڑا ہے اور کس کا چھوٹا)۔ غور سے سنو! حضورؐ اب تشریف لے جا چکے ہیں اور وحی کا سلسلہ بھی بند ہو چکا، اس لیے اب ہمارے لیے آپ لوگوں کے حالات و درجات معلوم کرنے کا طریقہ وہ ہوگا جو اب ہم بتانے لگے ہیں: آپ میں سے جو خیر کو ظاہر کرے گا ہم اس کے بارے میں اچھا گمان رکھیں گے اور اسی وجہ سے اس سے محبت کریں گے اور جو ہمارے سامنے شر ظاہر کرے گا ہم اس کے بارے میں برا گمان رکھیں گے اور اسی وجہ سے اس سے بغض رکھیں گے۔ اور آپ لوگوں کے پوشیدہ اور اندرونی حالات آپ کے اور آپ کے رب کے درمیان ہوں گے، یعنی ہم تو ہر ایک کے ظاہر کے مطابق اس کے متعلق فیصلہ کریں گے۔ غور سے سنو! ایک وقت تو ایسا تھا کہ مجھے اس بات کا یقین تھا کہ ہر قرآن پڑھنے والا صرف ",""],["ٱللَّٰه","a"],[" کے لیے اور ",""],["ٱللَّٰه","a"],[" کے ہاں کی نعمتوں کے لینے کے ارادے سے پڑھ رہا ہے، لیکن اب آخر میں آ کر کچھ ایسا اندازہ ہو رہا ہے کہ کچھ لوگ جو کچھ انسانوں کے پاس ہے اسے لینے کے ارادے سے قرآن پڑھتے ہیں۔ تم قرآن کے پڑھنے سے اور اپنے اعمال سے ",""],["ٱللَّٰه","a"],[" کی رضامندی کا ہی ارادہ کرو۔ توجہ سے سنو! میں اپنے گورنر آپ لوگوں کے پاس اس لیے نہیں بھیجتا کہ وہ آپ لوگوں کی کھالوں کی پٹائی کریں یا آپ لوگوں کے مال لے لیں بلکہ اس لیے بھیجتا ہوں تاکہ وہ آپ لوگوں کو دین اور سنت سکھائیں۔ جو گورنر کسی کے ساتھ اس کے علاوہ کچھ اور کرے تو وہ اس گورنر کی بات میرے پاس لے کر آئے۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! میں اسے اس گورنر سے ضرور بدلہ لے کر دوں گا۔ غور سے سنو! مسلمانوں کی پٹائی نہ کرو ورنہ تم انہیں ذلیل کر دو گے اور اسلامی سرحد سے انہیں گھر واپس جانے سے نہ روکو ورنہ تم انہیں فتنہ میں ڈال دو گے اور ان کے حقوق ان سے نہ روکو (بلکہ ادا کرو) ورنہ تم انہیں ناشکری میں مبتلا کر دو گے اور گھنے درختوں والے جنگل میں انہیں لے کر مت پڑاؤ ڈالنا ورنہ (بکھر جانے کی وجہ سے دشمن کا داؤ چل جائے گا اور) وہ ضائع ہو جائیں گے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd, Mas'ood, Ibn Khuzaymah, Haakim, Bayhaqi and others, as quoted in Kanzul Ummaal (Vol.8 Pg.209). Haythami (Vol.5 Pg.211) has commented that Abu Firaas did not meet Umar but the other narrators are reliable. Haakim (Vol.4 Pg.439) said that it is authentic on the conditions of Muslim although they did not report it, and Dhahabi agreed."]]},{"b":[["n",[["حضرت ابوالعجفاءؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمرؓ نے بیان میں فرمایا غور سے سنو! عورتوں کے مہر بہت زیادہ مقرر نہ کرو کیونکہ اگر مہر کا زیادہ ہونا دنیا میں عزت کی چیز ہوتی یا ",""],["ٱللَّٰه","a"],[" کے ہاں تقویٰ والا کام شمار ہوتا تو نبی کریمؐ تم سے زیادہ اس کے حقدار ہوتے۔ حضورؐ نے اپنی کسی بیوی یا بیٹی کا مہر بارہ اوقیہ یعنی چار سو اسی درہم سے زیادہ مقرر نہیں فرمایا۔ تم لوگ مہر بہت زیادہ مقرر کر لیتے ہو، جب دینا پڑتا ہے تو پھر دل میں اس عورت کی دشمنی محسوس کرتے ہو، تم مہر دیتے بھی ہو لیکن اس عورت سے کہتے ہو کہ مجھے تیرے مہر کی وجہ سے مشک بھی اٹھانی پڑی اور بہت مشقت بھی۔ اور دوسری بات یہ ہے کہ تمہارے غزوات میں جو آدمی قتل ہو جاتا ہے تم اس کے بارے میں کہتے ہو فلاں شہید ہو کر قتل ہوا یا فلاں نے شہید ہو کر وفات پائی (بغیر تحقیق کے کسی کے شہید ہونے کا قطعی فیصلہ نہ کیا کرو) کیونکہ ہو سکتا ہے کہ وہ تجارت کے ارادے سے ساتھ آیا ہو اور اس نے اپنی سواری کے آخری حصے پر اور کجاوے کے ایک جانب سونا چاندی لاد رکھا ہو (یہ تجارت والا ",""],["ٱللَّٰه","a"],[" کے راستے میں نہیں ہے)۔ اس لیے یہ بات نہ کہا کرو بلکہ جیسے حضورؐ نے فرمایا ویسے کہا کرو کہ جو آدمی ",""],["ٱللَّٰه","a"],[" کے راستے میں قتل ہوا یا فوت ہوا وہ جنت میں جائے گا۔",""],[" (5)","s"]]]],"f":[["(5)","Abdur Razzaaq, Tayaalisi, Ahmad, Daarimi, Tirmidhi who graded it authentic, Abu Dawood, Nasa'ee, Ibn Majah and others, as quoted in Kanzul Ummaal."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں ایک دن حضرت عمر بن خطابؓ منبر پر تشریف فرما ہوئے اور فرمایا اے لوگو! عورتوں کے مہر کیوں زیادہ مقرر کرتے ہو؟ حضورؐ اور آپؐ کے صحابہؓ کے زمانے میں مہر چار سو درہم یا اس سے کم ہوا کرتا تھا۔ اگر مہر بہت زیادہ مقرر کرنا ",""],["ٱللَّٰه","a"],[" کے ہاں تقویٰ کا یا عزت کا کام ہوتا تو آپ لوگ اس میں حضورؐ اور صحابہؓ سے آگے نہ نکل سکتے۔ نکاح کے باب میں اس بیان کی چند روایات ہم ذکر کر چکے ہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Sa'eed bin Mansoor and Abu Ya'la, as quoted in Kanzul Ummaal (Vol.8 Pg.258)."]]},{"b":[["n",[["ایک مرتبہ حضرت عمرؓ نے جابیہ شہر میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا جسے ",""],["ٱللَّٰه","a"],[" ہدایت دے اسے کوئی گمراہ نہیں کر سکتا اور جسے گمراہ کر دے اسے کوئی ہدایت دینے والا نہیں۔ حضرت عمرؓ کے سامنے ایک پادری بیٹھا تھا، اس نے فارسی میں کچھ کہا۔ حضرت عمرؓ نے اپنے ترجمان سے پوچھا یہ کیا کہہ رہا ہے؟ ترجمان نے بتایا یہ کہہ رہا ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کسی کو گمراہ نہیں کرتے۔ حضرت عمرؓ نے فرمایا اے ",""],["ٱللَّٰه","a"],[" کے دشمن! تم غلط کہتے ہو، بلکہ ",""],["ٱللَّٰه","a"],[" نے تمہیں پیدا کیا اور اسی نے تمہیں گمراہ کیا اور ان شاء ",""],["ٱللَّٰه","a"],[" وہ تمہیں دوزخ کی آگ میں داخل کرے گا۔ اگر تمہارے (ذمی ہونے کے) عہد کا پاس نہ ہوتا تو میں تمہاری گردن اڑا دیتا۔ پھر فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جب حضرت آدم علیہ السلام کو پیدا فرمایا تو ان کی ساری اولاد ان کے سامنے بکھیر دی اور جنت والوں کے نام اور ان کے اعمال (لوح محفوظ میں) اسی وقت لکھ دیے اور اسی طرح دوزخ والوں کے نام اور ان کے اعمال بھی اسی وقت لکھ دیے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا یہ لوگ اس (جنت) کے لیے ہیں اور یہ لوگ اس (دوزخ) کے لیے ہیں۔ راوی کہتے ہیں پھر لوگ بکھر گئے اور تقدیر کے بارے میں اختلاف کرنے لگے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Dawood in Kitaabul Qadariyyah, Ibn Jareer, Ibn Abi Haatim and others."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن ابزیٰؒ","b"],[" کہتے ہیں کسی آدمی نے آ کر حضرت عمرؓ کو بتایا کہ کچھ لوگ تقدیر کے بارے میں غلط باتیں کرتے ہیں۔ اس پر حضرت عمرؓ نے کھڑے ہو کر بیان فرمایا، ارشاد فرمایا اے لوگو! تم سے پہلی امتیں تقدیر کے بارے میں غلط باتیں کر کے ہی ہلاک ہوئی ہیں۔ اس ذات کی قسم جس کے قبضہ میں عمر کی جان ہے! آئندہ جن دو آدمیوں کے بارے میں میں نے یہ سنا کہ تقدیر کے بارے میں (اپنی عقل سے) باتیں کر رہے ہیں تو میں دونوں کی گردن اڑا دوں گا۔ راوی کہتے ہیں حضرت عمرؓ کا یہ اعلان سن کر تمام لوگوں نے تقدیر کے بارے میں بات کرنی چھوڑ دی۔ پھر حجاج کے زمانے میں شام میں ایک جماعت ظاہر ہوئی جس نے سب سے پہلے تقدیر کے بارے میں بات کرنی شروع کی۔",""],[" (8)","s"]]]],"f":[["(8)","Abdullah Laalka'i, Ibn Asaakir and others, as quoted in Kanzul Ummaal (Vol.1 Pg.86)."]]},{"b":[["n",[["حضرت باہلیؒ","b"],[" کہتے ہیں جب حضرت عمرؓ ملک شام میں داخل ہوئے تو انہوں نے جابیہ شہر میں کھڑے ہو کر بیان فرمایا، ارشاد فرمایا قرآن سیکھو، اس سے تمہارا تعارف ہوگا اور قرآن پر عمل کرو، اس سے تم قرآن والوں میں سے ہو جاؤ گے۔ اور کسی حقدار کا درجہ اتنا بڑا نہیں ہو سکتا کہ اس کی بات مان کر ",""],["ٱللَّٰه","a"],[" کی نافرمانی کی جائے۔ اور اس بات کا یقین رکھو کہ حق بات کہنے سے اور کسی بڑے کو نصیحت کرنے سے نہ تو موت قریب آتی ہے اور نہ ",""],["ٱللَّٰه","a"],[" کا رزق دور ہوتا ہے۔ اور اس بات کو جان لو کہ بندے اور اس کی روزی کے درمیان ایک پردہ پڑا ہوا ہے۔ اگر بندہ صبر سے کام لیتا ہے تو اس کی روزی خود اس کے پاس آ جاتی ہے اور اگر بے سوچے سمجھے روزی کمانے میں گھس جاتا ہے (حلال و حرام کی تمیز نہیں کرتا) تو وہ اس پردے کو تو پھاڑ لیتا ہے لیکن اپنے مقدر کی روزی سے زیادہ نہیں پا سکتا۔ گھوڑوں کو سدھاؤ اور تیر چلانا سیکھو اور جوتی پہنا کرو اور مسواک کیا کرو۔ اور موٹا جھوٹا استعمال کرو اور عجمیوں کی عادتیں اختیار کرنے سے اور ظالم جابر لوگوں کے پڑوس سے بھی بچو اور اس سے بھی بچو کہ تمہارے درمیان صلیب بلند کی جائے یا تم اس دستر خوان پر بیٹھو جس پر شراب پی جائے اور بغیر لنگی کے حمام میں داخل ہونے سے بھی بچو اور اس سے بھی بچو کہ تم عورتوں کو ایسے ہی چھوڑ دو کہ وہ حمام میں داخل ہوں کیونکہ حمام میں داخل ہونا عورتوں کے لیے جائز نہیں۔ تم جب عجمیوں کے علاقہ میں پہنچ جاؤ اور ان سے معاہدہ کر لو تو پھر کمائی کے ایسے کام اختیار کرنے سے بچو جن کی وجہ سے تمہیں وہاں ہی رہنا پڑ جائے اور ملک عرب میں واپس نہ آ سکو، کیونکہ تمہیں اپنے علاقہ میں عنقریب واپس آنا ہے اور ذلت اور خواری کو اپنی گردن میں ڈالنے سے بچو۔ عرب کے مال مویشی کو لازم پکڑو اور جہاں بھی جاؤ انہیں ساتھ لے جاؤ۔ اور یہ بات جان لو کہ شراب تین چیزوں سے بنائی جاتی ہے: کشمش، شہد اور کھجور۔ جو اس میں سے پرانی ہو جائے (اور اس میں نشہ پیدا ہو جائے) تو وہ شراب ہے جو کہ حلال نہیں ہے۔ اور جان لو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن تین آدمیوں کو پاک نہیں کریں گے اور انہیں (رحمت کی نگاہ سے) نہیں دیکھیں گے اور انہیں اپنے قریب نہیں کریں گے اور انہیں دردناک عذاب ہوگا۔ ایک وہ آدمی جو دنیا لینے کے ارادے سے امام سے بیعت ہو، پھر اگر اسے دنیا ملے تو وہ اس بیعت کو پورا کرے ورنہ نہ کرے۔ دوسرا وہ آدمی جو عصر کے بعد (بیچنے کے لیے) سامان لے کر جائے اور ",""],["ٱللَّٰه","a"],[" کی جھوٹی قسم کھا کر کہے اس کی اتنی اور اتنی قیمت لگ چکی ہے اور اس کی اس جھوٹی قسم کی وجہ سے وہ سامان بک جائے۔ (تیسرا وہ آدمی جس کے پاس بنجر زمین میں پانی ہو اور وہ مسافروں کو پانی دینے سے انکار کرے۔) مومن کو گالی دینا فسق ہے اور اسے قتل کرنا کفر ہے اور تمہارے لیے یہ حلال نہیں کہ تم اپنے بھائی کو تین دن سے زیادہ چھوڑے رکھو۔ اور جو شخص کسی جادوگر، کاہن یا نجومی کے پاس جائے اور جو وہ کہے اسے سچا مانے تو اس نے محمدؐ پر نازل ہونے والے دین کا انکار کر دیا۔",""],[" (9)","s"],[" (10)","s"]]]],"f":[["(9)","Targheeb wat Tarheeb, narrated by Hadhrat Abu Hurayrah."],["(10)","Adani, as quoted in Kanzul Ummaal (Vol.8 Pg.207)."]]},{"b":[["n",[["حضرت موسیٰ بن عقبہؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے جابیہ میں یہ بیان فرمایا تھا اما بعد! میں تمہیں اس ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں جو ہمیشہ رہے گا اور اس کے علاوہ ہر ایک فنا ہو جائے گا، جو فرمانبرداری کی وجہ سے اپنے دوستوں کا اکرام کرتا ہے اور نافرمانی کی وجہ سے اپنے دشمنوں کو گمراہ کرتا ہے۔ اب جو کسی گمراہی والے کام کو ہدایت والا سمجھ کر کرتا ہے اور ہلاک ہو جاتا ہے یا کسی حق والے کام کو گمراہی والا سمجھ کر چھوڑ دیتا ہے اور ہلاک ہو جاتا ہے تو اس ہلاک ہونے میں اس کے پاس کوئی عذر نہیں ہے۔ اور بادشاہ کو اپنی رعایا کے بارے میں سب سے زیادہ نگرانی اور دیکھ بھال اس بات کی کرنی چاہیے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے جس دین کی ان کو ہدایت نصیب فرمائی ہے اس دین والے احکامات ان لوگوں پر لازم ہیں۔ یہ لوگ ان احکامات کو صحیح طرح سے ادا کریں اور ہم ذمہ داران خلافت کے ذمہ یہ بھی ہے کہ ہم آپ لوگوں کو ",""],["ٱللَّٰه","a"],[" کی اس اطاعت کا حکم دیں جس کا ",""],["ٱللَّٰه","a"],[" نے آپ لوگوں کو حکم دیا اور ",""],["ٱللَّٰه","a"],[" کی اس نافرمانی سے روکیں جس سے ",""],["ٱللَّٰه","a"],[" نے آپ لوگوں کو روکا اور قریب اور دور کے آپ تمام لوگوں میں ",""],["ٱللَّٰه","a"],[" کے احکام کو قائم کریں اور جو حق کو جھکانا چاہتا ہے ہمیں اس کی کوئی پرواہ نہیں۔ اور مجھے معلوم ہے کہ بہت سے لوگ اپنے دین کے بارے میں بہت سی تمنائیں کرتے ہیں، کہتے ہیں ہم نمازیوں کے ساتھ نماز پڑھیں گے اور مجاہدوں کے ساتھ مل کر جہاد کریں گے اور ہم ہجرت کی نسبت حاصل کریں گے، اور وہ ان کاموں کو کرتے تو ہیں لیکن ان کا حق ادا نہیں کرتے اور ایمان صرف صورت بنا لینے سے نہیں ملتا۔ اور ہر نماز کا ایک وقت ہے جو ",""],["ٱللَّٰه","a"],[" نے اس کے لیے مقرر فرمایا ہے، اس کے بغیر نماز ٹھیک نہیں ہو سکتی۔ فجر کا وقت شروع ہوتا ہے جب رات ختم ہو جاتی ہے اور روزے دار کے لیے کھانا پینا حرام ہو جاتا ہے۔ فجر میں خوب زیادہ قرآن پڑھا کرو۔ اور ظہر کا وقت سورج کے زوال سے شروع ہو جاتا ہے لیکن گرمیوں میں اس وقت پڑھو جب تمہارا سایہ تمہارے جتنا لمبا ہو جائے، اس وقت تک انسان کا دوپہر کا آرام پورا ہو جاتا ہے، اور سردیوں میں اس وقت پڑھو جب کہ سورج تمہارے دائیں ابرو پر آ جائے یعنی زوال کے تھوڑی دیر بعد پڑھ لو۔ اور وضو، رکوع اور سجدے میں ",""],["ٱللَّٰه","a"],[" نے جو پابندیاں لگا رکھی ہیں وہ سب پوری کرو اور یہ سب اس لیے ہے تاکہ سوتا نہ رہ جائے اور نماز قضا ہو جائے۔ اور عصر کا وقت یہ ہے کہ سورج زرد ہونے سے پہلے ایسے وقت میں پڑھی جائے کہ ابھی سورج سفید اور صاف ہو اور نماز کے بعد آدمی سست رفتار اونٹ پر چھ میل کا فاصلہ غروب سے پہلے طے کر سکے۔ اور مغرب کی نماز سورج ڈوبتے ہی، روزہ کھولنے کے وقت ہوتے ہی پڑھی جائے۔ اور عشاء کی نماز سرخی غائب ہو کر رات کا اندھیرا چھا جانے سے لے کر تہائی رات تک پڑھی جائے، جو اس سے پہلے سو جائے ",""],["ٱللَّٰه","a"],[" اسے آرام و سکون کی نیند نہ دے۔ یہ نمازوں کے اوقات ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا",""]]],["q",[["إِنَّ ٱلصَّلَوٰةَ كَانَتْ عَلَى ٱلْمُؤْمِنِينَ كِتَٰبًا مَّوْقُوتًا","a"]]],["p",[["ترجمہ: \"یقیناً نماز مسلمانوں پر فرض ہے اور وقت کے ساتھ محدود ہے\" (سورۂ نساء، آیت 103)۔ اور ایک آدمی کہتا ہے میں نے ہجرت کی ہے حالانکہ اس کی ہجرت کامل نہیں ہے۔ کامل ہجرت والے تو وہ لوگ ہیں جو تمام برائیاں چھوڑ دیں۔ اور بہت سے لوگ کہتے ہیں ہم جہاد کر رہے ہیں حالانکہ جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" یہ ہے کہ آدمی دشمن کا مقابلہ بھی کرے اور حرام سے بھی بچے۔ بہت سے لوگ اچھی طرح دشمن سے جنگ کرتے ہیں لیکن ان کا ارادہ اجر لینے کا ہوتا ہے اور نہ ",""],["ٱللَّٰه","a"],[" کو یاد کرنے کا۔ اور قتل ہو جانا بھی موت کی ایک صورت ہے، یعنی قتل ہونا شہادت اس وقت شمار ہوگا جب صرف ",""],["ٱللَّٰه","a"],[" کے کلمہ کو بلند کرنے کی نیت سے جنگ کر رہا ہو اور ہر آدمی اسی نیت پر شمار کیا جائے گا جس نیت سے اس نے جنگ کی ہے۔ ایک آدمی اس لیے جنگ کرتا ہے کہ اس کی طبیعت میں بہادری ہے اور جسے جانتا ہے اور جسے نہیں جانتا ہر ایک کو جنگ کر کے دشمن سے بچاتا ہے۔ ایک آدمی طبعاً بزدل ہوتا ہے، وہ تو اپنے ماں باپ کی مدد نہیں کر سکتا بلکہ انہیں دشمن کے حوالے کر دیتا ہے، حالانکہ کتا بھی اپنے گھر والوں کے پیچھے سے بھونکتا ہے، یعنی بزدل آدمی کتے سے بھی کیا گزرا ہوتا ہے۔ اور جان لو کہ روزہ قابل احترام عمل ہے۔ آدمی روزہ رکھ کر جیسے کھانے، پینے اور عورتوں کی لذت سے بچتا ہے ایسے ہی اگر مسلمانوں کو تکلیف دینے سے بھی بچے تو پھر اس کا روزہ کامل درجہ کا ہوگا۔ اور زکوٰۃ حضورؐ نے (",""],["ٱللَّٰه","a"],[" کے فرمانے سے) فرض کی ہے، اسے خوشی خوشی ادا کیا جائے اور زکوٰۃ لینے والے پر اپنا احسان نہ سمجھا جائے۔ تمہیں جو نصیحتیں کی جا رہی ہیں انہیں اچھی طرح سمجھ لو۔ جس کا دین لٹ گیا اس کا سب کچھ لٹ گیا۔ خوش قسمت وہ ہے جو دوسرے کے حالات سے عبرت اور نصیحت حاصل کر لے۔ بدبخت وہ ہے جو ماں کے پیٹ میں یعنی ازل سے بدبخت ہوا ہو۔ اور سب سے برے کام وہ ہیں جو نئے گھڑے جائیں اور سنت میں میانہ روی اختیار کرنا بدعت میں بہت زیادہ کوشش کرنے سے بہتر ہے۔ اور لوگوں کے دلوں میں اپنے بادشاہ سے نفرت ہوا کرتی ہے، میں اس بات سے ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتا ہوں کہ مجھ میں اور تم میں طبعی کینہ پیدا ہو جائے یا میں اور تم خواہشات کے پیچھے چلنے لگ جائیں یا دنیا کو آخرت پر ترجیح دینے لگ جائیں۔ اور مجھے اس بات کا ڈر ہے کہ تم لوگ کہیں ظالموں کی طرف مائل نہ ہو جاؤ اور مالداروں پر تمہیں مطمئن نہیں ہونا چاہیے۔ تم اس قرآن کو لازم پکڑو کیونکہ اس میں نور اور شفاء ہے، باقی سب کچھ تو بدبختی کا سامان ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے تمہارے جن کاموں کا والی بنایا ہے ان میں جو حق میرے ذمہ تھا وہ میں نے ادا کر دیا ہے اور تمہاری خیر خواہی کے جذبہ سے تمہیں وعظ و نصیحت بھی کر چکا ہوں۔ ہم نے اس بات کا حکم دیا ہے کہ تمہیں تمہارے حصے (بیت المال میں سے) دے دیے جائیں اور تمہارے لشکروں کو ہم جمع کر چکے ہیں اور جہاں جا کر تم نے غزوہ کرنا ہے وہ جگہیں ہم مقرر کر چکے ہیں اور تمہارے پڑاؤ کی جگہیں بھی مقرر کر دی ہیں اور تلواروں سے لڑ کر جو تم نے مال غنیمت حاصل کیا ہے اس میں ہم نے تمہارے لیے پوری طرح وسعت کی ہے۔ لہٰذا اب تمہارے پاس ",""],["ٱللَّٰه","a"],[" کے حکم کے مقابلہ میں کوئی عذر نہیں ہے بلکہ سارے وہ دلائل ہیں جن سے ",""],["ٱللَّٰه","a"],[" کا ہر حکم ماننا تم پر لازم آتا ہے۔ میں اسی بات پر ختم کرتا ہوں اور اپنے لیے اور سب کے لیے ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔ سیف راوی نے اسی روایت کے ضمن میں بیان کیا کہ حضرت عمرؓ نے حضرت علی بن ابی طالبؓ کو مدینہ میں اپنی جگہ خلیفہ بنایا، پھر گھوڑے پر سوار ہو کر چلے تاکہ سفر تیزی سے پورا ہو۔ چلتے چلتے جابیہ شہر پہنچ گئے۔ وہاں قیام فرمایا اور وہاں ایک زبردست مؤثر بیان فرمایا، اس میں فرمایا اے لوگو! اپنے باطن کی اصلاح کرو، تمہارا ظاہر خود بخود ٹھیک ہو جائے گا۔ تم اپنی آخرت کے لیے عمل کرو، تمہاری دنیا کے کام منجانب ",""],["ٱللَّٰه","a"],[" خود ہی ہو جائیں گے۔ اور کسی آدمی کے اور حضرت آدم علیہ السلام کے درمیان ایسا کوئی زندہ باپ نہیں ہے جو موت کے وقت اس کے کام آ سکے اور نہ کسی آدمی کے اور ",""],["ٱللَّٰه","a"],[" کے درمیان نرمی کا کوئی معاہدہ ہے۔ اور جو آدمی اپنے لیے جنت کا راستہ واضح کرنا چاہتا ہے اسے چاہیے کہ وہ جماعت کو لازم پکڑے رکھے کیونکہ شیطان اکیلے آدمی کے ساتھ ہوتا ہے اور دو آدمیوں سے بہت دور ہوتا ہے۔ اور کوئی آدمی ہرگز کسی اجنبی عورت کے ساتھ تنہائی اختیار نہ کرے ورنہ شیطان ان دو کے ساتھ تیسرا ہوگا۔ جسے اپنی نیکی سے خوشی ہو اور اپنی برائی سے رنج و صدمہ ہو وہ کامل ایمان والا ہے۔ راوی لکھتے ہیں یہ بیان بہت لمبا ہے جسے ہم نے اختصار سے ذکر کیا ہے۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Mentioned in Kanzul Ummaal (Vol.8 Pg.210)."],["(12)","Ibn Katheer in Al Bidaayah wan Nihaayah (Vol.7 Pg.56)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں حضرت عمرؓ نے جابیہ میں بیان فرمایا، اس میں ارشاد فرمایا جیسے میں تم میں کھڑے ہو کر بیان کر رہا ہوں ایسے ہی ایک مرتبہ حضورؐ نے ہم میں کھڑے ہو کر بیان فرمایا تھا جس میں آپؐ نے فرمایا تھا کہ تم لوگ میرے صحابہؓ کے بارے میں اچھا معاملہ کرنے کی وصیت قبول کرو اور ان کے بعد والے ہیں ان کے بارے میں یہی وصیت قبول کرو اور جو ان کے بعد والے ہیں ان کے بارے میں بھی یہی وصیت قبول کرو یعنی تابعین اور تبع تابعین کے بارے میں۔ ان تین طبقات کے بعد پھر جھوٹ پھیل جائے گا یہاں تک کہ آدمی سے گواہی دینے کا مطالبہ نہیں کیا جائے گا اور خود ہی (جھوٹی) گواہی دینی شروع کر دے گا۔ تم میں سے جو آدمی جنت کے عین بیچ میں جانا چاہتا ہے اسے چاہیے کہ وہ جماعت کو لازم پکڑے رکھے کیونکہ شیطان اکیلے کے ساتھ ہوتا ہے اور دو آدمیوں سے بہت دور ہوتا ہے، اور تم میں سے کوئی آدمی کسی اجنبی عورت کے ساتھ ہرگز تنہائی اختیار نہ کرے ورنہ شیطان ان دو کے ساتھ تیسرا ہوگا۔ جسے اپنی نیکی سے خوشی ہو اور اپنی برائی سے رنج و صدمہ ہو وہ ایمان والا ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Ahmad (Vol.1 Pg.18)."]]},{"b":[["n",[["حضرت سوید بن غفلہؒ","b"],[" کہتے ہیں حضرت عمرؓ نے جابیہ شہر میں لوگوں میں بیان فرمایا، ارشاد فرمایا حضورؐ نے (مردوں کو) ریشم پہننے سے منع فرمایا ہے، صرف دو، تین یا چار انگلی کے برابر ریشم پہننے کی اجازت دی ہے۔ اس موقع پر حضرت عمرؓ نے سمجھانے کے لیے ہاتھ سے اشارہ بھی فرمایا۔",""],[" (14)","s"]]]],"f":[["(14)","Ahmad also (Vol.1 Pg.51)."]]},{"b":[["n",[["سیف راوی","b"],[" نے بیان کیا کہ طاعون عمواس کے بعد ۱۷ھ کے آخر میں حضرت عمرؓ ملک شام آئے۔ جب ذی الحجہ میں وہاں سے مدینہ واپس جانے کا ارادہ فرمایا تو لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر فرمایا غور سے سنو! مجھے تمہارا امیر بنایا گیا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے تمہارا والی بنایا ہے، اس کی وجہ سے جو ذمہ داریاں آتی ہیں ان میں سے ما شاء ",""],["ٱللَّٰه","a"],[" وہ سب ادا کر دی ہیں اور تمہارے حصہ کا مال غنیمت تم میں پھیلا دیا ہے اور پڑاؤ ڈالنے کی جگہیں اور غزوہ کرنے کی جگہیں سب تفصیل سے تمہیں بتا دی ہیں، جو کچھ ہمارے پاس تھا وہ سب تمہیں پہنچا دیا ہے۔ تمہارے لشکر جمع کر دیے ہیں اور تمہارے لیے ترقی کی راہیں مہیا کر دی ہیں اور تمہیں ٹھکانے دے دیے ہیں اور ملک شام میں جنگ کر کے تم نے جو مال غنیمت حاصل کیا تھا وہ سب تم لوگوں میں وسعت سے تقسیم کر دیا ہے، تمہاری خوراک مقرر کر دی ہے اور تمہیں عطایا، روزینہ اور مال غنیمت دینے کا حکم دے دیا ہے۔ کوئی آدمی ایسی چیز جانتا ہو جس پر عمل کرنا مناسب ہو تو وہ ہمیں بتائے، ہم اس پر ان شاء ",""],["ٱللَّٰه","a"],[" ضرور عمل کریں گے اور نیکی کرنے کی طاقت صرف ",""],["ٱللَّٰه","a"],[" سے ہی ملتی ہے۔",""],[" (15)","s"]]]],"f":[["(15)","Mentioned in Al Bidaayah wan Nihaayah (Vol.7 Pg.79)."]]},{"b":[["n",[["حضرت عروہ بن زبیرؒ","b"],[" اور دوسرے حضرات فرماتے ہیں کہ حضرت عمرؓ نے ایک مرتبہ بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء اس کی شان کے مناسب بیان کی، پھر لوگوں کو ",""],["ٱللَّٰه","a"],[" تعالیٰ اور آخرت کے دن کے بارے میں یاد دہانی کرائی، پھر فرمایا اے لوگو! مجھے تمہارا والی اور امیر بنایا گیا ہے، اگر مجھے یہ امید نہ ہوتی کہ میں تم میں سے تمہارے لیے سب سے بہتر، سب سے زیادہ قوی اور پیش آنے والے اہم امور میں سب سے زیادہ مضبوط رہوں گا تو ہرگز میں آپ لوگوں کا امیر نہ بنتا۔ اور عمر کے فکر مند اور غمگین ہونے کے لیے یہ بات کافی ہے کہ اسے حساب کے ٹھیک نکلنے کا انتظار ہے اور حساب اس بات کا کہ تم لوگوں سے حقوق لے کر کہاں رکھوں اور تم لوگوں کے ساتھ کیسے چلوں۔ میں اپنے رب سے ہی مدد چاہتا ہوں۔ اگر ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنی رحمت، مدد اور تائید سے عمر کا تدارک نہ فرما دیں تو عمر کو کسی طاقت اور تدبیر پر کوئی اعتماد نہیں۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Jareer Tabari in his Taareekh (Vol.3 Pg.281)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے ایک مرتبہ بیان فرمایا، اس میں ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے تمہارا امیر بنایا ہے، جتنی چیزیں تمہارے سامنے ہیں ان میں سے جو چیز تمہیں سب سے زیادہ نفع دینے والی ہے میں اسے خوب اچھی طرح جانتا ہوں اور میں ",""],["ٱللَّٰه","a"],[" تعالیٰ سے سوال کرتا ہوں کہ وہ اس سب سے زیادہ نفع دینے والی چیز میں میری مدد کرے اور جیسے اور چیزوں میں میری حفاظت کر رہا ہے ایسے ہی اس میں میری حفاظت فرمائے اور جیسے کہ ",""],["ٱللَّٰه","a"],[" نے عدل کرنے کا حکم دیا ہے وہ مجھے تم لوگوں کی تقسیم میں عدل کرنے کی توفیق عطا فرمائے۔ میں ایک مسلمان آدمی اور کمزور بندہ ہوں لیکن اگر ",""],["ٱللَّٰه","a"],[" میری مدد فرمائے تو پھر کوئی کمزوری نہیں ہے۔ یہ امارت و خلافت جو مجھے دی گئی ہے یہ ان شاء ",""],["ٱللَّٰه","a"],[" میرے اچھے اخلاق کو نہیں بدل سکے گی اور عظمت اور بڑائی تو صرف ",""],["ٱللَّٰه","a"],[" تعالیٰ کے لیے ہے اور بندوں کے لیے اس میں سے کچھ بھی نہیں، لہٰذا تم میں سے کوئی آدمی ہرگز یہ نہ کہے کہ جب سے عمر امیر بنا ہے بدل گیا ہے۔ میں اپنے نفس کے حق کو خوب سمجھتا ہوں (یا میں اپنے بارے میں حق بات کو خوب سمجھتا ہوں) اور میں خود آگے بڑھ کر ایسی بات بیان کرتا ہوں، لہٰذا جس آدمی کو کوئی ضرورت ہے یا کسی نے اس پر ظلم کیا ہے یا ہماری بد خلقی کی وجہ سے اسے ہم پر غصہ آیا ہوا ہے تو وہ مجھے بتا دے کیونکہ میں بھی تم میں کا ایک آدمی ہوں۔ اور تم لوگ اپنے ظاہر اور باطن میں اور اپنی قابل احترام چیزوں اور آبرو میں ",""],["ٱللَّٰه","a"],[" سے ڈرتے رہو اور جو حقوق تمہارے اوپر ہیں تم انہیں ادا کرو اور تم ایک دوسرے کو اپنے مقدمات میرے پاس لے کر آنے پر آمادہ نہ کرو کیونکہ میرے اور لوگوں میں سے کسی کے درمیان نرمی یا طرفداری کا کوئی معاہدہ نہیں۔ تم لوگوں کی درشتگی مجھے محبوب ہے اور تمہاری ناراضگی مجھ پر بہت گراں ہے۔ تم میں سے اکثر لوگ شہروں میں مقیم ہیں اور تمہارے علاقے میں نہ کوئی خاص کھیتی باڑی ہے اور نہ دودھ والے جانور زیادہ ہیں، بس وہی غلے اور جانور یہاں ملتے ہیں جو ",""],["ٱللَّٰه","a"],[" تعالیٰ باہر سے لے آتے ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تم سے بہت زیادہ اکرام کا وعدہ کیا ہوا ہے۔ اور میں اپنی امانت کا ذمہ دار ہوں۔ امانت کے بارے میں مجھ سے پوچھا جائے گا لیکن امانت کا جو حصہ میرے سامنے ہے اس کی دیکھ بھال تو میں خود کروں گا، کسی کے سپرد نہیں کروں گا، لیکن امانت کا جو حصہ مجھ سے دور ہے میں اس کی دیکھ بھال خود نہیں کر سکتا، اسے سنبھالنے کے لیے میں تم میں سے ایسے لوگ استعمال کروں گا جو امانت دار ہیں اور عام لوگوں کے لیے خیر خواہی کا جذبہ رکھنے والے ہیں اور ان شاء ",""],["ٱللَّٰه","a"],[" اپنی امانت ایسے لوگوں کے علاوہ اور کسی کے سپرد نہیں کروں گا۔",""],[" (17)","s"]]]],"f":[["(17)","Ibn Jareer Tabari with this chain."]]},{"b":[["n",[["ایک مرتبہ حضرت عمرؓ نے بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، پھر نبی کریمؐ پر درود بھیجا، پھر فرمایا اے لوگو! لالچ کی بعض صورتیں ایسی ہیں جن سے انسان فقیر اور محتاج ہو جاتا ہے اور (لوگوں کے پاس جو کچھ ہے اس سے) نا امیدی کی بعض صورتیں ایسی ہیں جن سے انسان غنی اور بے نیاز ہو جاتا ہے۔ تم وہ چیزیں جمع کرتے ہو جنہیں کھا نہیں سکتے اور ان باتوں کی امید لگاتے ہو جنہیں پا نہیں سکتے۔ تم دھوکے والے گھر یعنی دنیا میں ہو اور تمہیں موت تک (کی) مہلت ملی ہوئی ہے۔ حضورؐ کے زمانے میں تو تم لوگ وحی کے ذریعہ سے پکڑے جاتے تھے، جو اپنے باطن میں کوئی چیز چھپایا ہوتا تھا اس کی اس چیز پر پکڑ ہو جاتی تھی (اس کے اندر کی اس چیز کا پتہ وحی سے چل جاتا تھا) اور جو کسی چیز کو ظاہر کرتا تھا اس کی اس چیز پر گرفت ہو جاتی تھی۔ لہٰذا اب تم لوگ ہمارے سامنے اپنے سب سے اچھے اخلاق ظاہر کرو، باقی رہے تمہارے اندرونی حالات اور باطن کی نیتیں تو انہیں ",""],["ٱللَّٰه","a"],[" خوب جانتا ہے۔ اب جو ہمارے سامنے کسی کی بری چیز کو ظاہر کرے گا اور یہ دعویٰ کرے گا کہ اس کی اندرونی حالت بہت اچھی ہے ہم اس کی تصدیق نہیں کریں گے اور جو ہمارے سامنے کسی اچھی چیز کو ظاہر کرے گا ہم اس کے بارے میں اچھا گمان رکھیں گے۔ اور یہ بات جان لو کہ کنجوسی کی بعض صورتیں نفاق کا شعبہ ہیں، لہٰذا تم خرچ کرو جیسے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں",""]]],["q",[["وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ","a"]]],["p",[["ترجمہ: \"اور (بالخصوص مواقع حکم میں) خرچ (بھی) کیا کرو، یہ تمہارے لیے بہتر ہوگا اور جو شخص نفسانی حرص سے محفوظ رکھا گیا ہے سو ایسے ہی لوگ (آخرت میں) فلاح پانے والے ہیں\" (سورۂ تغابن، آیت 16)۔ اے لوگو! اپنے ٹھکانے پاک صاف رکھو اور اپنے تمام امور کو درست رکھو اور ",""],["ٱللَّٰه","a"],[" سے ڈرو جو تمہارا رب ہے۔ اور اپنی عورتوں کو قبطی (مصری) کپڑے نہ پہناؤ کیونکہ ان سے اندر جسم تو نظر نہیں آتا لیکن اس کی نوعیت معلوم ہو جاتی ہے۔ اے لوگو! میری تمنا یہ ہے کہ میں برابر سرابر نجات پا جاؤں، نہ مجھے انعام ملے اور نہ مجھے سزا۔ اور مجھے اس بات کی امید ہے کہ آئندہ مجھے تھوڑی یا زیادہ جتنی عمر ملے گی میں اس میں ان شاء ",""],["ٱللَّٰه","a"],[" حق پر عمل کروں گا۔ اور ہر مسلمان کا ",""],["ٱللَّٰه","a"],[" کے مال میں جتنا حصہ ہے وہ حصہ خود اس کے پاس اس کے گھر پہنچ جائے گا اور اسے اس حصہ کے لینے کے لیے نہ کچھ کرنا پڑے گا اور نہ کبھی تھکنا پڑے گا۔ اور جو مال ",""],["ٱللَّٰه","a"],[" نے تمہیں دے رکھے ہیں انہیں درست کرتے رہو اور سہولت کی تھوڑی کمائی اس زیادہ کمائی سے بہتر ہے جس کے لیے بڑی مشقت اٹھانی پڑے۔ اور قتل ہو جانا مرنے کی ایک صورت ہے جو نیک اور بد ہر آدمی کو حاصل ہو جاتی ہے لیکن ہر قتل ہونے والا ",""],["ٱللَّٰه","a"],[" کے ہاں شہید نہیں ہوتا بلکہ شہید وہ ہے جس کی نیت اجر و ثواب لینے کی ہو۔ اور جب تم کوئی اونٹ خریدنا چاہو تو لمبا اور بڑا اونٹ دیکھو اور اسے اپنی لاٹھی مارو، اگر تم اسے چوکنے دل والا پاؤ تو اسے خرید لو۔",""],[" (18)","s"]]]],"f":[["(18)","Ibn Jareer has also mentioned it in his Taareekh (Vol.3 Pg.282)."]]},{"b":[["n",[["حضرت عروہ بن زبیرؒ","b"],[" اور دوسرے حضرات فرماتے ہیں ایک مرتبہ حضرت عمرؓ نے بیان فرمایا، اس میں ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" سبحانہ و تعالیٰ نے تم لوگوں پر شکر واجب کیا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بغیر مانگے اور بغیر طلب کے جو دنیا اور آخرت کی شرافت تمہیں عطا فرمائی ہے اس بارے میں تمہارے اوپر کئی دلیلیں بنا دی ہیں۔ تم لوگ کچھ نہیں تھے لیکن اس نے تمہیں پیدا کیا اور پیدا بھی اپنے لیے اور اپنی عبادت کے لیے کیا، حالانکہ وہ تمہیں (انسان نہ بناتا بلکہ) اپنی سب سے بے قیمت مخلوق بنا سکتا تھا اور اپنی ساری مخلوق تمہارے فائدہ اور خدمت کے لیے بنائی اور تمہیں اپنے علاوہ اور کسی مخلوق کے لیے نہیں بنایا، جیسے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["سَخَّرَ لَكُم مَّا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُۥ ظَٰهِرَةً وَبَاطِنَةً","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمام چیزوں کو تمہارے کام میں لگا رکھا ہے جو کچھ آسمانوں میں ہیں اور جو کچھ زمین میں ہیں اور اس نے تم پر اپنی نعمتیں ظاہری اور باطنی پوری کر رکھی ہیں\" (سورۂ لقمان، آیت 20)۔ اور اس نے تمہیں خشکی اور سمندر کی سواریاں دیں اور پاکیزہ نعمتیں عطا فرمائیں تاکہ تم شکر گزار بنو، پھر تمہارے کان اور آنکھیں بنائیں۔ پھر ",""],["ٱللَّٰه","a"],[" کی کچھ نعمتیں ایسی ہیں جو تمام بنی آدم کو ملی ہیں اور کچھ نعمتیں ایسی ہیں جو صرف تم دین اسلام والوں کو ملی ہیں، پھر یہ تمام خاص اور عام نعمتیں تمہاری حکومت میں، تمہارے زمانے میں، تمہارے طبقے میں خوب فراوانی سے ہیں۔ اور ان نعمتوں میں سے ہر نعمت تم میں سے ہر آدمی کو اتنی زیادہ مقدار میں ملی ہے کہ اگر وہ نعمت تمام لوگوں میں تقسیم کر دی جائے تو وہ اس کا شکر ادا کرتے کرتے تھک جائیں اور اس کا حق ادا کرنا ان پر بھاری ہو جائے۔ ہاں اگر وہ ",""],["ٱللَّٰه","a"],[" اور اس کے رسول پر ایمان لائیں اور ",""],["ٱللَّٰه","a"],[" ان کی مدد کرے تو پھر وہ اس نعمت کا شکر اور اس کا حق ادا کر سکتے ہیں۔ اور ",""],["ٱللَّٰه","a"],[" نے تمام روئے زمین پر تمہیں اپنا خلیفہ بنایا ہوا ہے اور زمین والوں پر تم غالب آئے ہوئے ہو اور ",""],["ٱللَّٰه","a"],[" نے تمہارے دین کی خوب مدد کی ہے اور جن لوگوں نے تمہارا دین اختیار نہیں کیا ان کے دو حصے ہو گئے ہیں۔ کچھ لوگ تو اسلام اور اسلام والوں کے غلام بن گئے ہیں (اس سے مراد ذمی لوگ ہیں) جو تمہیں جزیہ دیتے ہیں، خون پسینہ ایک کر کے کماتے ہیں اور طلب معاش میں ہر طرح کی مشقت اٹھاتے ہیں، مشقت ساری ان کے ذمہ ہے اور ان کی کمائی سے جزیہ کا فائدہ آپ لوگوں کو ملتا ہے۔ اور کچھ لوگ وہ ہیں جو دن رات ہر وقت ",""],["ٱللَّٰه","a"],[" کے لشکروں کے حملوں کے منتظر ہیں (اس سے مراد وہ کافر ہیں جن کے پاس صحابہ کرامؓ کے لشکر جانے والے تھے)۔ ",""],["ٱللَّٰه","a"],[" نے ان کے دلوں کو رعب سے بھر دیا ہے، اب ان کے پاس کوئی جگہ ایسی نہیں ہے جہاں انہیں پناہ مل جائے یا بھاگ کر وہاں چلے جائیں اور اسلامی لشکروں سے کسی طرح بچ جائیں۔ ",""],["ٱللَّٰه","a"],[" کے لشکر ان پر چھائے ہوئے ہیں اور ان کے علاقے میں داخل ہو گئے ہیں اور ",""],["ٱللَّٰه","a"],[" کے حکم سے ان لشکروں کو زندگی کی وسعت، مال کی بہتات، لشکروں کا تسلسل اور اسلامی سرحدوں کی حفاظت جیسی نعمتوں کے ساتھ عافیت، امن و امان جیسی بڑی نعمت بھی حاصل ہے۔ اور جب سے اسلام شروع ہوا ہے کبھی اس امت کے ظاہری حالات اس سے زیادہ اچھے نہیں رہے۔ اور ہر شہر میں مسلمانوں کو جو بڑی بڑی فتوحات ہو رہی ہیں ان پر ",""],["ٱللَّٰه","a"],[" ہی کی تعریف ہونی چاہیے اور یہ جو بے حساب نعمتیں حاصل ہیں جن کا اندازہ نہیں لگایا جا سکتا ان کے مقابلہ میں مسلمان کتنا ہی ",""],["ٱللَّٰه","a"],[" کا شکر اور ذکر کر لیں اور دین کے لیے کتنی ہی محنت کر لیں وہ ان نعمتوں کے شکر کا حق ادا نہیں کر سکتے، ہاں ",""],["ٱللَّٰه","a"],[" اگر ان کی مدد فرمائے اور ان کے ساتھ رحم اور مہربانی کا معاملہ فرمائے تو اور بات ہے۔ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں ہے اور اسی نے ہم پر یہ اتنے انعام و احسان فرمائے ہیں، ہم اس سے سوال کرتے ہیں کہ وہ ہمیں اپنی اطاعت والے عمل کرنے کی اور اپنی رضا کی طرف جلدی کرنے کی توفیق عطا فرمائے۔ اے ",""],["ٱللَّٰه","a"],[" کے بندو! ",""],["ٱللَّٰه","a"],[" کی جو نعمتیں تمہارے پاس ہیں انہیں اپنی مجلسوں میں دو دو اور ایک ایک ہو کر یاد کرو اور اپنے اوپر ",""],["ٱللَّٰه","a"],[" کی نعمت کو پورا کرو، کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت موسیٰ علیہ السلام کو فرمایا ہے",""]]],["q",[["أَخْرِجْ قَوْمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرْهُم بِأَيَّىٰمِ ٱللَّهِ","a"]]],["p",[["ترجمہ: \"اپنی قوم کو (کفر کی) تاریکیوں سے (ایمان کی) روشنی کی طرف لاؤ اور ان کو ",""],["ٱللَّٰه","a"],[" کے معاملات (نعمت اور نقمت کے) یاد دلاؤ\" (سورۂ ابراہیم، آیت 5)۔ اور حضرت محمدؐ کو فرمایا ہے",""]]],["q",[["وَٱذْكُرُوٓا۟ إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِى ٱلْأَرْضِ","a"]]],["p",[["ترجمہ: \"اور اس حالت کو یاد کرو جبکہ تم قلیل تھے، سر زمین میں کمزور شمار کیے جاتے تھے\" (سورۂ انفال، آیت 26)۔ جب تم لوگ اسلام سے پہلے کمزور شمار کیے جاتے تھے اور دنیا کی خیر سے محروم تھے، اگر اس وقت تم حق کے کسی شعبہ پر ہوتے، اس شعبہ پر ایمان لاتے اور اس سے آرام پاتے اور ",""],["ٱللَّٰه","a"],[" اور اس کے دین کی معرفت تمہیں حاصل ہوتی اور اس شعبہ سے مرنے کے بعد کی زندگی میں تم لوگ خیر کی امید رکھتے تو یہ تو کوئی بات ہوتی، لیکن تم تو زمانہ جاہلیت میں لوگوں میں سب سے زیادہ سخت زندگی والے اور ",""],["ٱللَّٰه","a"],[" کی ذات و صفات سے سب سے زیادہ جاہل تھے، پھر ",""],["ٱللَّٰه","a"],[" نے اسلام کے ذریعہ تمہیں ہلاکت سے بچایا۔ اب اچھا یہ تھا کہ صرف اسلام ہوتا، اس کے ساتھ تمہاری دنیا کا کوئی حصہ نہ ہوتا اور آخرت میں جہاں تم نے لوٹ کر جانا ہے وہاں یہ اسلام تمہارے لیے بھروسہ کی چیز ہوتی، اور تم جس مشقت والی زندگی پر تھے اس زندگی میں تم اس بات کے قابل تھے کہ اسلام میں سے اپنے حصہ پر کنجوسی کرو، اسی سے چمٹے رہو اور اسے دوسروں پر ظاہر کرو۔ لہٰذا تم میں سے جو آدمی یہ چاہتا ہے کہ اسے دنیا کی فضیلتیں اور آخرت کی شرافت دونوں باتیں حاصل ہو جائیں تو میں اسے اس ",""],["ٱللَّٰه","a"],[" کی یاد دہانی کراتا ہوں جو آدمی اور اس کے دل کے درمیان حائل ہو جاتا ہے، تم ",""],["ٱللَّٰه","a"],[" کا حق پہچانو اور اس حق والے عمل کرو اور اپنے نفسوں کو ",""],["ٱللَّٰه","a"],[" کی اطاعت پر مجبور کرو۔ تمہیں نعمتوں پر خوش بھی ہونا چاہیے لیکن یہ ڈر بھی ہونا چاہیے کہ نہ معلوم کب یہ نعمتیں تم سے چھن جائیں اور دوسروں کو مل جائیں، کیونکہ کوئی چیز ناشکری سے زیادہ نعمت کو محروم کرانے والی نہیں ہے اور شکر کرنے سے نعمت بدل جانے سے محفوظ ہو جاتی ہے اور اس سے نعمت میں اضافہ ہوتا ہے۔ اور یہ کام ",""],["ٱللَّٰه","a"],[" کی طرف سے میرے ذمہ واجب ہے کہ میں تمہیں مفید کاموں کا حکم دوں اور نقصان دہ کاموں سے روکوں۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Jareer has also mentioned it in his Taareekh (Vol.3 Pg.283)."]]},{"b":[["n",[["حضرت کلیبؒ","b"],[" کہتے ہیں ایک دفعہ حضرت عمرؓ نے جمعہ کے دن بیان کیا اور اس میں سورۂ آل عمران کی آیتیں پڑھیں، جب اس آیت پر پہنچے",""]]],["q",[["إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ","a"]]],["p",[["ترجمہ: \"یقیناً تم میں جن لوگوں نے پشت پھیر دی تھی جس روز کہ دونوں جماعتیں باہم متقابل ہوئیں\" (سورۂ آل عمران، آیت 155)۔ تو حضرت عمرؓ نے فرمایا جنگ احد میں ہمیں شکست ہوئی۔ میں بھاگ کر پہاڑ پر چڑھ گیا، میں پہاڑی بکرے کی طرح چھلانگیں لگا کر بھاگ رہا ہوں اور لوگ کہہ رہے تھے کہ حضرت محمدؐ قتل کر دیے گئے۔ میں نے کہا جو یہ کہے گا حضرت محمدؐ قتل کر دیے گئے ہیں میں اسے قتل کر دوں گا۔ پھر ہم سب پہاڑ پر جمع ہو گئے، اس پر یہ آیت",""]]],["q",[["إِنَّ ٱلَّذِينَ تَوَلَّوْا۟ مِنكُمْ يَوْمَ ٱلْتَقَى ٱلْجَمْعَانِ نازل ہوئی۔","a"],[" (20)","s"]]]],"f":[["(20)","Ibn Jareer."]]},{"b":[["n",[["حضرت کلیبؒ","b"],[" کہتے ہیں ایک دفعہ حضرت عمرؓ نے ہم لوگوں میں بیان فرمایا اور منبر پر سورۂ آل عمران پڑھی، پھر فرمایا اس سورت کا جنگ احد سے بہت تعلق ہے۔ ہم جنگ احد کے دوران حضورؐ کو چھوڑ کر ادھر ادھر بکھر گئے تھے، میں ایک پہاڑ پر چڑھ گیا۔ میں نے ایک یہودی کو سنا وہ کہہ رہا تھا حضرت محمدؐ قتل کر دیے گئے۔ میں نے کہا میں جسے بھی یہ کہتے ہوئے سنوں گا کہ حضرت محمدؐ قتل کر دیے گئے ہیں میں اس کی گردن اڑا دوں گا۔ پھر میں نے دیکھا تو مجھے ایک جگہ حضورؐ نظر آئے اور لوگ آپؐ کے پاس لوٹ کر آ رہے تھے، اس پر یہ آیت نازل ہوئی",""]]],["q",[["وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ ۚ أَفَإِي۟ن مَّاتَ أَوْ قُتِلَ ٱنقَلَبْتُمْ عَلَىٰٓ أَعْقَٰبِكُمْ","a"]]],["p",[["ترجمہ: \"اور محمدؐ تو رسول ہی ہیں۔ آپ سے پہلے اور بھی بہت سے رسول گزر چکے ہیں، سو اگر آپ کا انتقال ہو جائے یا آپ شہید ہی ہو جاویں تو کیا تم لوگ الٹے پھر جاؤ گے؟\" (سورۂ آل عمران، آیت 144)۔",""],[" (21)","s"]]]],"f":[["(21)","Ibn Mundhir, as quoted in Kanzul Ummaal (Vol.1 Pg.238)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عدی بن خیارؒ","b"],[" کہتے ہیں میں نے منبر پر حضرت عمر بن خطابؓ کو فرماتے ہوئے سنا جب بندہ ",""],["ٱللَّٰه","a"],[" کی وجہ سے تواضع اختیار کرتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی قدر و منزلت بڑھا دیتے ہیں اور فرماتے ہیں بلند ہو جا، ",""],["ٱللَّٰه","a"],[" تجھے بلند کرے۔ یہ اپنے آپ کو حقیر سمجھتا ہے لیکن لوگوں کی نگاہ میں بڑا ہوتا ہے۔ اور جب بندہ تکبر کرتا ہے اور اپنی حد سے آگے بڑھتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے توڑ کر نیچے زمین پر گرا دیتے ہیں اور فرماتے ہیں دور ہو جا، ",""],["ٱللَّٰه","a"],[" تجھے دور کرے۔ اور یہ اپنے آپ کو بڑا سمجھتا ہے لیکن لوگوں کی نگاہ میں حقیر ہوتا ہے یہاں تک کہ وہ ان کے نزدیک سور سے بھی زیادہ حقیر ہو جاتا ہے۔",""],[" (22)","s"]]]],"f":[["(22)","Abu Ubayd, Kharaa'iti, Saaboooni and Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.2 Pg.143)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ نے ہم میں بیان فرمایا جس میں ارشاد فرمایا ہو سکتا ہے کہ میں آپ لوگوں کو ایسی چیزوں سے روک دیتا ہوں جن میں آپ لوگوں کا فائدہ ہو اور ایسی چیزوں کا حکم دے دیتا ہوں جن میں آپ لوگوں کا فائدہ نہ ہو۔ اور قرآن میں سب سے آخر میں سود کے حرام ہونے کی آیت نازل ہوئی اور حضورؐ ہمارے لیے ابھی سود کی اس آیت کی (موٹی موٹی اور بنیادی باتیں تو بیان فرماتے تھے لیکن اس کی تفصیلی اور باریک باریک باتیں بیان نہ کر پائے تھے کہ آپؐ کی وفات ہو گئی (کیونکہ حضورؐ اس سے زیادہ اہم کاموں میں مشغول تھے)۔ اس لیے جس صورت میں تمہیں سود کا کچھ کھٹکا ہو اسے چھوڑ دیا کرو اور جس میں کوئی کھٹکا نہ ہو وہ اختیار کر لیا کرو۔",""],[" (23)","s"]]]],"f":[["(23)","Khateeb, as quoted in Kanzul Ummaal (Vol.2 Pg.232)."]]},{"b":[["n",[["حضرت اسود بن یزیدؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے لوگوں میں بیان فرمایا اور ارشاد فرمایا تم میں سے جو بھی حج کا ارادہ کرے وہ صرف میقات سے ہی احرام باندھے اور احرام باندھنے کے لیے حضورؐ نے جو میقات مقرر فرمائے ہیں وہ یہ ہیں: مدینہ والوں کے لیے اور دوسری جگہ کے رہنے والے مدینہ سے گزریں تو ان کے لیے ذوالحلیفہ میقات ہے اور شام والوں کے لیے اور دوسری جگہ کے رہنے والے شام سے گزریں تو ان کے لیے جحفہ میقات ہے اور نجد والوں کے لیے اور دوسری جگہ کے رہنے والے نجد سے گزریں تو ان کے لیے قرن میقات ہے اور یمن والوں کے لیے یلملم اور عراق والوں اور باقی تمام لوگوں کے لیے ذات عرق میقات ہے۔",""],[" (24)","s"]]]],"f":[["(24)","Ibn Dhiyaa, as quoted in Kanzul Ummaal (Vol.3 Pg.30)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں ایک مرتبہ حضرت عمرؓ نے بیان فرمایا اور اس میں رجم یعنی زنا کرنے والوں کو سنگسار کرنے کی سزا کا ذکر کیا اور فرمایا رجم کے بارے میں دھوکہ نہ کھا لینا کیونکہ (اگرچہ اس کا قرآن میں ذکر نہیں ہے لیکن) یہ بھی ",""],["ٱللَّٰه","a"],[" کی مقرر کردہ سزاؤں میں سے ایک سزا ہے۔ غور سے سنو! حضورؐ نے خود رجم کیا ہے اور آپؐ کے بعد ہم نے رجم کیا ہے۔ اگر مجھے اس بات کا ڈر نہ ہوتا کہ لوگ یوں کہیں گے کہ عمرؓ نے ",""],["ٱللَّٰه","a"],[" کی کتاب میں وہ چیز بڑھا دی جو اس میں نہیں تھی تو میں قرآن کے کنارے پر یہ لکھ دیتا کہ عمر بن خطاب، حضرت عبدالرحمٰن بن عوف، فلاں اور فلاں صحابی اس بات کے گواہ ہیں کہ حضورؐ نے رجم کیا ہے اور آپؐ کے بعد ہم نے رجم کیا ہے۔ غور سے سنو! تمہارے بعد عنقریب ایسے لوگ آئیں گے جو رجم کو، دجال کو، شفاعت کو، عذاب قبر کو اور ان لوگوں کو جو جل جانے کے بعد جہنم سے نکلیں گے، ان سب چیزوں کو جھٹلائیں گے۔",""],[" (25)","s"]]]],"f":[["(25)","Ahmad, Abu Ya'la and Abu Ubayd."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں حضرت عمرؓ جب منیٰ سے واپس ہوئے تو انہوں نے پتھریلے میدان میں اپنی سواری بٹھائی، پھر کنکریوں کی ایک ڈھیری بنا کر اپنے کپڑے کا کنارا اس ڈھیری پر ڈالا اور اس پر لیٹ گئے اور آسمان کی طرف دونوں ہاتھ اٹھا کر یہ دعا کی اے ",""],["ٱللَّٰه","a"],["! میری عمر زیادہ ہو گئی ہے اور میری قوت کمزور ہو گئی ہے اور میری رعایا بہت پھیل گئی ہے، اس لیے اب مجھے اپنی طرف اس طرح اٹھا لے کہ میں تیرے احکام کو ضائع کرنے والا نہ بنوں اور نہ ان میں کمی کرنے والا۔ پھر جب حضرت عمرؓ مدینہ پہنچے تو لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! کچھ اعمال تم پر فرض کیے گئے ہیں اور سنتیں تمہارے لیے صاف بیان کر دی گئی ہیں اور تمہیں ایک واضح اور صاف ملت پر چھوڑا گیا ہے۔ پھر دایاں ہاتھ بائیں ہاتھ پر مار کر فرمایا اس کے بعد بھی تم دائیں بائیں ہو کر لوگوں کو گمراہ کرتے پھرتے تو یہ الگ بات ہے۔ پھر تم اس بات سے بچو کہ رجم کی آیت کی وجہ سے ہلاک ہو جاؤ اور تم میں سے کوئی یوں کہے کہ ہمیں کتاب ",""],["ٱللَّٰه","a"],[" میں زنا کے بارے میں دو سزائیں نہیں ملتیں (ایک رجم کی اور دوسری کوڑے مارنے کی، بلکہ ہمیں تو صرف ایک سزا ملتی ہے یعنی کوڑے مارنے کی)۔ میں نے خود دیکھا کہ حضورؐ نے رجم کیا ہے اور آپؐ کے بعد ہم نے بھی رجم کیا ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اگر مجھے یہ ڈر نہ ہوتا کہ لوگ کہیں گے کہ عمرؓ نے ",""],["ٱللَّٰه","a"],[" کی کتاب میں نئی چیز بڑھا دی تو میں یہ عبارت قرآن میں لکھ دیتا",""]]],["q",[["ٱلشَّيْخُ وَٱلشَّيْخَةُ إِذَا زَنَيَا فَٱرْجُمُوهُمَا ٱلْبَتَّةَ","a"]]],["p",[["ترجمہ: \"شادی شدہ مرد اور عورت جب زنا کریں تو دونوں کو ضرور رجم کرو۔\" کیونکہ (پہلے یہ آیت قرآن میں نازل ہوئی تھی اور) ہم قرآن میں اس کی تلاوت کیا کرتے تھے (بعد میں یہ الفاظ منسوخ ہو گئے لیکن ان کا حکم اب بھی باقی ہے)۔ حضرت سعیدؒ کہتے ہیں ابھی ذوالحجہ کا مہینہ ختم نہیں ہوا تھا کہ حضرت عمرؓ کو نیزہ مار کر زخمی کر دیا گیا (اور اسی میں ان کا انتقال ہو گیا)۔",""],[" (26)","s"]]]],"f":[["(26)","Maalik, Ibn Sa'd, Mas'ood and Haakim, as quoted in Kanzul Ummaal (Vol.3 Pg.90)."]]},{"b":[["n",[["حضرت معدان بن ابی طلحہ یعمریؒ","b"],[" کہتے ہیں ایک دفعہ جمعہ کے دن حضرت عمر بن خطابؓ منبر پر کھڑے ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر حضورؐ اور حضرت ابوبکرؓ کا ذکر کیا، پھر فرمایا میں نے ایک خواب دیکھا جس سے میں یہی سمجھا ہوں کہ میرے دنیا سے جانے کا وقت قریب آ گیا ہے۔ میں نے خواب میں دیکھا کہ ایک سرخ مرغے نے مجھے دو دفعہ چونچ ماری ہے۔ میں نے اس خواب کا ذکر اسماء بنت عمیسؓ سے کیا تو اس نے کہا اس کی تعبیر یہ ہے کہ عجم کا ایک آدمی آپ کو قتل کرے گا۔ لوگ مجھے کہہ رہے ہیں کہ میں کسی کو اپنا خلیفہ مقرر کر دوں (خلیفہ مقرر کرنا ٹھیک تو ہے لیکن ضروری نہیں ہے)۔ مجھے یقین ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو اپنا دین اور خلافت دے کر اپنے نبی کریمؐ کو بھیجا ہے اسے ہرگز ضائع نہیں ہونے دیں گے۔ اگر (دنیا سے جانے کا) میرا معاملہ جلدی ہو گیا تو یہ چھ آدمی جن سے دنیا سے جاتے وقت حضورؐ راضی تھے آپس کے مشورے سے اپنے میں سے کسی ایک کو خلیفہ بنا لیں: حضرت عثمانؓ، حضرت علیؓ، حضرت زبیرؓ، حضرت طلحہؓ، حضرت عبدالرحمٰن بن عوفؓ اور حضرت سعد بن ابی وقاصؓ۔ تم ان میں سے جس سے بھی بیعت کرو اس کی بات سنو اور مانو۔ اور مجھے معلوم ہے کہ کچھ لوگ اس امر خلافت میں اعتراض کریں گے، حالانکہ یہ وہ لوگ ہیں جن سے میں نے اپنے اس ہاتھ سے اسلام کی خاطر جنگ کی ہے۔ اگر وہ لوگ ایسا کریں تو وہ ",""],["ٱللَّٰه","a"],[" کے دشمن، کافر اور گمراہ ہوں گے (اگر وہ اس اعتراض کو جائز سمجھتے ہیں تو پھر واقعی وہ کافر ہو جائیں گے ورنہ ان کا یہ عمل کافروں کے عمل کے مشابہ ہو جائے گا)۔ میں کوئی ایسی چیز چھوڑ کر نہیں جا رہا ہوں جو میرے نزدیک کلالہ کے معاملہ سے زیادہ اہم ہو (کلالہ وہ آدمی ہے جس کے نہ اولاد ہو اور نہ ماں باپ ہوں)۔ ",""],["ٱللَّٰه","a"],[" کی قسم! جب سے میں حضورؐ کے ساتھ رہا ہوں حضورؐ نے کسی بھی چیز کے بارے میں اتنی سختی نہیں کی جتنی سختی میرے ساتھ اس کلالہ کے بارے میں کی ہے، یہاں تک کہ آپؐ نے اپنی انگلی میرے سینہ پر مار کر فرمایا سورۂ نساء کے آخر میں گرمیوں میں جو آیت (يَسْتَفْتُونَكَ قُلِ ٱللَّهُ يُفْتِيكُمْ فِى ٱلْكَلَٰلَةِ) نازل ہوئی ہے وہ تمہارے لیے کافی ہے۔ اگر میں زندہ رہا تو کلالہ کے بارے میں ایسا فیصلہ کروں گا کہ ہر پڑھے لکھے اور ان پڑھ کو اس کے بارے میں سب کچھ معلوم ہو جائے گا۔ اور میں ",""],["ٱللَّٰه","a"],[" کو گواہ بنا کر کہتا ہوں کہ میں شہر کے گورنروں کو اس لیے بھیجتا ہوں تاکہ وہ لوگوں کو دین اور ان کے نبی کریمؐ کی سنت سکھائیں اور جو کوئی نیا یا پیچیدہ معاملہ ایسا پیش آ جائے جس کا انہیں حل سمجھ میں نہ آئے تو وہ اسے میرے پاس بھیج دیں۔ پھر اے لوگو! تم یہ دو سبزیاں کھاتے ہو، میں تو انہیں برا ہی سمجھتا ہوں، یعنی لہسن اور پیاز۔ ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے ",""],["ٱللَّٰه","a"],[" کے نبیؐ کو دیکھا ہے کہ انہیں (مسجد میں) جس آدمی سے لہسن یا پیاز کی بو آ جاتی تھی تو حضورؐ کے فرمانے پر ہاتھ سے پکڑ کر مسجد سے باہر نکال کر جنت البقیع پہنچا دیا جاتا تھا۔ لہٰذا جو شخص لہسن یا پیاز ضرور ہی کھانا چاہتا ہے وہ انہیں پکا کر (ان کی بو) مار دے۔ حضرت عمرؓ نے یہ بیان جمعہ کے دن فرمایا اور اس کے بعد بدھ کے دن انہیں حملہ کر کے زخمی کر دیا گیا، جبکہ ذی الحجہ کے ختم ہونے میں چار دن باقی تھے۔",""],[" (27)","s"]]]],"f":[["(27)","Tayaalisi, Ibn Sa'd, Ahmad, Ibn Abi Shaybah, Muslim, Nasa'ee, Ibn Hibbaan, Abu Awaanah, Abu Ya'la and others, as quoted in Kanzul Ummaal (Vol.3 Pg.153)."]]},{"b":[["n",[["حضرت یسار بن معرورؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمرؓ نے ہم لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! حضورؐ نے یہ مسجد بنائی اور مسجد بنانے میں ہم مہاجرین اور انصار بھی آپؐ کے ساتھ تھے۔ جب مسجد میں مجمع زیادہ ہو جائے تو تم میں سے ہر آدمی کو چاہیے کہ وہ اپنے آگے والے بھائی کی پشت پر سجدے کر لے۔ اور حضرت عمرؓ نے کچھ لوگوں کو راستہ میں نماز پڑھتے ہوئے دیکھا تو فرمایا مسجد میں نماز پڑھو۔",""],[" (28)","s"]]]],"f":[["(28)","Tabraani in his Awsat, Ahmad, Shaafi'ee, Bayhaqi and Sa'eed bin Mansoor, as quoted in Kanzul Ummaal (Vol.4 Pg.259)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں جب حضرت عمرؓ خلیفہ بنے تو انہوں نے لوگوں میں بیان فرمایا جس میں ارشاد فرمایا حضورؐ نے ہمیں متعہ کی تین دن کے لیے اجازت دی تھی، پھر اس کے بعد آپؐ نے ہمیشہ کے لیے متعہ کو حرام فرما دیا تھا (متعہ یہ ہے کہ آدمی ایک مقررہ وقت تک کے لیے شادی کرے۔ خیبر سے پہلے متعہ والا نکاح حلال تھا، خیبر کے بعد حضورؐ نے حرام قرار دے دیا تھا، پھر فتح مکہ کے موقع پر حضورؐ نے متعہ کی صحابہؓ کو اجازت دی تھی، پھر تین دن کے بعد سے ہمیشہ کے لیے حرام قرار دے دیا تھا)۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اب مجھے جس کے بارے میں پتہ چلا کہ وہ شادی شدہ ہے اور اس نے متعہ والا نکاح کیا ہے تو میں اسے سنگسار کر دوں گا، وہ میرے پاس ایسے چار گواہ لے کر آئے جو اس بات کی گواہی دیں کہ حضورؐ نے متعہ کو حرام کرنے کے بعد پھر حلال کر دیا تھا۔ اور جو غیر شادی شدہ آدمی مجھے ایسا ملا جو متعہ والا نکاح کرے تو میں اسے سو کوڑے ماروں گا، یا وہ میرے پاس ایسے چار گواہ لے کر آئے جو اس بات کی گواہی دیں کہ حضورؐ نے متعہ کو حرام کرنے کے بعد پھر حلال کر دیا تھا۔",""],[" (29)","s"]]]],"f":[["(29)","Ibn Asaakir, Sa'eed bin Mansoor and Tammaam, as quoted in Kanzul Ummaal (Vol.8 Pg.293)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سعیدؒ","b"],[" کے دادا کہتے ہیں میں نے حضرت عمر بن خطابؓ کو منبر پر فرماتے ہوئے سنا اے مسلمانوں کی جماعت! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپ لوگوں کو عجمی ملکوں میں سے ان کی عورتیں اور بچے مال غنیمت میں (باندی اور غلام بنا کر) اتنے دے دیے ہیں کہ نہ تو اتنے حضورؐ کو دیے تھے اور نہ حضرت ابوبکرؓ کو۔ اور مجھے پتہ چلا ہے کہ بہت سے مرد ان عورتوں سے صحبت کرتے ہیں (کیونکہ یہ باندیاں ہیں اور باندیوں سے صحبت کرنا مالک کے لیے جائز ہے)۔ اب جس عجمی باندی سے تمہارا بچہ پیدا ہو جائے تو تم اسے نہ بیچنا کیونکہ اگر تم ایسا کر دو گے تو ہو سکتا ہے کہ آدمی کو پتہ بھی نہ چلے اور وہ اپنی کسی محرم عورت سے صحبت کر لے (ہو سکتا ہے کہ آدمی باندی کو بیچ دے اور باندی سے جو لڑکا پیدا ہوا تھا وہ اسی آدمی کا بیٹا تھا، وہ اسی کے پاس رہ گیا، بعد میں اس لڑکے نے اسی باندی کو خرید لیا اور اسے پتہ نہیں ہے کہ یہ اس کی ماں ہے)۔",""],[" (30)","s"]]]],"f":[["(30)","Bayhaqi from Abdullah bin Sa'eed, as quoted in Kanzul Ummaal (Vol.8 Pg.292)."]]},{"b":[["n",[["حضرت معرور یا ابن معرور تمیمیؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ منبر پر چڑھے اور حضورؐ والی جگہ سے دو سیڑھی نیچے بیٹھ گئے، وہاں میں نے ان کو یہ فرماتے ہوئے سنا میں تمہیں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں اور جسے ",""],["ٱللَّٰه","a"],[" تعالیٰ آپ لوگوں کا والی و حاکم بنا دیں اس کی بات سنو اور مانو۔",""],[" (31)","s"]]]],"f":[["(31)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ اپنے بیان میں فرمایا کرتے تھے تم میں سے وہ آدمی کامیاب رہا جو خواہش پر چلنے سے، غصہ میں آنے اور لالچ میں پڑنے سے محفوظ رہا اور جسے گفتگو میں سچ بولنے کی توفیق دی گئی، کیونکہ سچ اسے خیر کی طرف لے جائے گا۔ اور جو شخص جھوٹ بولے گا وہ گناہ کرے گا اور جو گناہ کے کام کرے گا وہ ہلاک ہو جائے گا۔ اور گناہ کے کاموں سے بچو، اور اس شخص کا کیا گناہ کرنا جو مٹی سے پیدا ہوا اور مٹی کی طرف لوٹ جائے گا۔ آج وہ زندہ ہے کل مردہ ہوگا۔ روزانہ کا کام کرو اور مظلوم کی بد دعا سے بچو اور اپنے آپ کو مردوں میں شمار کرو۔",""],[" (32)","s"]]]],"f":[["(32)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]},{"b":[["n",[["حضرت قبیصہؒ","b"],[" کہتے ہیں میں نے حضرت عمرؓ کو منبر پر فرماتے ہوئے سنا جو رحم نہیں کرتا اس پر رحم نہیں کیا جاتا، جو معاف نہیں کرتا اسے معاف نہیں کیا جاتا، جو توبہ نہیں کرتا اس کی توبہ قبول نہیں کی جاتی، جو (برے کاموں سے) نہیں بچتا اسے (عذاب سے) نہیں بچایا جاتا۔",""],[" (33)","s"]]]],"f":[["(33)","Bukhaari in his Adab, Ibn Khuzaymah and Ja'far Firyaabi, as quoted in Kanzul Ummaal (Vol.8 Pg.207)."]]},{"b":[["n",[["حضرت عروہؒ","b"],[" فرماتے ہیں حضرت عمرؓ نے اپنے بیان میں فرمایا یہ بات اچھی طرح سمجھ لو کہ لالچ فقر کی نشانی ہے اور ناامیدی سے انسان غنی ہو جاتا ہے۔ آدمی جب کسی چیز سے ناامید ہو جاتا ہے تو آدمی کو اس کی ضرورت نہیں رہتی۔",""],[" (34)","s"]]]],"f":[["(34)","Abu Nu'aym in his Hilyah (Vol.1 Pg.50), as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن خراشؒ","b"],[" کے چچا کہتے ہیں میں نے حضرت عمر بن خطابؓ کو بیان میں یہ فرماتے ہوئے سنا اے ",""],["ٱللَّٰه","a"],["! اپنی امان کے ذریعہ ہماری حفاظت فرما اور ہمیں اپنے دین پر ثابت قدم رکھ۔ اپنے فضل سے ہمیں رزق عطا فرما۔",""],[" (35)","s"],[" (36)","s"]]]],"f":[["(35)","Abu Nu'aym in his Hilyah (Vol.1 Pg.54)."],["(36)","Ahmad in his Zuhd, Ruyaani, Laalka'i and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.303)."]]},{"b":[["n",[["حضرت ابوسعیدؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عمرؓ نے لوگوں میں بیان فرمایا جس میں ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبیؐ کو جس چیز کی چاہی اجازت دے دی (چنانچہ حضورؐ نے پہلے صرف حج کا احرام باندھا تھا، بعد میں ",""],["ٱللَّٰه","a"],[" تعالیٰ کی اجازت سے اسی احرام میں عمرہ کی نیت بھی کر لی، اب ایسا کرنے کی امت کو اجازت نہیں ہے) اور اب ",""],["ٱللَّٰه","a"],[" کے نبیؐ اپنے راستہ پر (دنیا سے) تشریف لے جا چکے ہیں، لہٰذا حج اور عمرہ کو ",""],["ٱللَّٰه","a"],[" کے لیے ایسے پورا کرو جیسے تمہیں ",""],["ٱللَّٰه","a"],[" نے حکم دیا ہے اور ان عورتوں کی شرمگاہوں کی حفاظت کرو۔",""],[" (37)","s"]]]],"f":[["(37)","Ahmad (Vol.1 Pg.17)."]]},{"b":[["n",[["حضرت ابن زبیرؓ","b"],[" فرماتے ہیں میں نے حضرت عمر بن خطابؓ کو بیان میں فرماتے ہوئے سنا کہ میں نے حضورؐ کو فرماتے ہوئے سنا کہ جو مرد دنیا میں ریشم پہنے گا اسے آخرت میں ریشم نہیں پہنایا جائے گا۔",""],[" (38)","s"]]]],"f":[["(38)","Ahmad (Vol.1 Pg.20)."]]},{"b":[["n",[["حضرت ابوعبیدؒ","b"],[" جو حضرت عبدالرحمٰن بن عوفؓ کے غلام ہیں کہتے ہیں میں نے ایک مرتبہ حضرت عمر بن خطابؓ کے ساتھ عید کی نماز پڑھی۔ انہوں نے اذان اور اقامت کے بغیر خطبہ سے پہلے نماز پڑھائی، پھر خطبہ دیا اور فرمایا اے لوگو! حضورؐ نے ان دو دنوں کے روزے سے منع فرمایا ہے۔ ایک تو عید الفطر کا دن جس دن تم رمضان کے روزوں سے افطار کرتے ہو اور عید مناتے ہو اور دوسرا وہ دن جس دن تم لوگ اپنی قربانی کا گوشت کھاتے ہو۔",""],[" (39)","s"]]]],"f":[["(39)","Ahmad (Vol.1 Pg.34)."]]},{"b":[["n",[["حضرت علقمہ بن وقاص لیثیؒ","b"],[" کہتے ہیں میں نے حضرت عمر بن خطابؓ کو لوگوں میں بیان کرتے ہوئے سنا، وہ فرما رہے تھے میں نے حضورؐ کو فرماتے سنا کہ عمل کا دار و مدار نیت پر ہے اور آدمی کو عمل پر وہی ملے گا جس کی وہ نیت کرے گا۔ لہٰذا جس کی ہجرت ",""],["ٱللَّٰه","a"],[" و رسولؐ کی طرف ہوگی تو اس کی ہجرت ",""],["ٱللَّٰه","a"],[" و رسولؐ کی طرف ہی شمار ہوگی اور جس کی ہجرت دنیا حاصل کرنے یا کسی عورت سے شادی کرنے کے لیے ہوگی تو اس کی ہجرت اسی چیز کے لیے شمار ہوگی جس کی نیت سے اس نے ہجرت کی ہوگی۔",""],[" (40)","s"]]]],"f":[["(40)","Ahmad (Vol.1 Pg.43)."]]},{"b":[["n",[["حضرت سلیمان بن یسارؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے رمادہ کی قحط سالی کے زمانے میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! اپنے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو اور تمہارے جو کام لوگوں سے چھپے ہوئے ہیں ان میں بھی ",""],["ٱللَّٰه","a"],[" سے ڈرو۔ مجھے تمہارے ذریعہ سے آزمایا جا رہا ہے اور تمہیں میرے ذریعہ سے۔ اب مجھے معلوم نہیں کہ ",""],["ٱللَّٰه","a"],[" نے ناراض ہو کر جو یہ قحط سالی بھیجی ہے وہ کس سے ناراض ہے؟ وہ مجھ سے ناراض ہے اور تم سے نہیں، یا تم سے ناراض ہے مجھ سے نہیں، یا مجھ سے بھی ناراض ہے اور تم سے بھی۔ آؤ ہم ",""],["ٱللَّٰه","a"],[" سے دعا کریں کہ وہ ہمارے دلوں کو ٹھیک کر دے اور ہم پر رحم فرمائے اور یہ قحط ہم سے دور کر دے۔ راوی کہتے ہیں اس دن دیکھا گیا کہ حضرت عمرؓ دونوں ہاتھ اٹھا کر ",""],["ٱللَّٰه","a"],[" سے دعا کر رہے ہیں اور لوگ بھی دعا کر رہے ہیں، پھر حضرت عمرؓ اور لوگ تھوڑی دیر روتے رہے، پھر حضرت عمرؓ منبر سے نیچے تشریف لے آئے۔",""],[" (41)","s"]]]],"f":[["(41)","Ibn Sa'd (Vol.3 Pg.322)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں حضرت عمرؓ لوگوں میں بیان کر رہے تھے، میں ان کے منبر کے نیچے بیٹھا ہوا تھا، آپؓ نے بیان فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا مجھے اس امت پر سب سے زیادہ ڈر اس منافق کا ہے جو زبان کا خوب جاننے والا ہو یعنی جسے باتیں بنانی خوب آتی ہوں۔ حضرت عمرؓ کے بیانات صحابہ کرامؓ کے باہمی اتحاد و اتفاق رائے کے باب میں گزر چکے ہیں۔",""],[" (42)","s"]]]],"f":[["(42)","Ahmad (Vol.1 Pg.44)."]]}]},"181":{"lead":[],"stories":[{"b":[["n",[["حضرت ابراہیم بن عبدالرحمٰن مخزومیؒ","b"],[" کہتے ہیں جب لوگ حضرت عثمانؓ سے بیعت کر چکے تو آپؓ نے آ کر لوگوں میں بیان فرمایا۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان فرمائی، پھر فرمایا اے لوگو! پہلی مرتبہ سوار ہونا مشکل ہوتا ہے۔ آج کے بعد اور بھی دن ہیں۔ اگر میں زندہ رہا تو تم ایسا بیان سنو گے جو صحیح ترتیب سے ہوگا۔ ہم تو بیان کرنے والے نہیں ہیں، ",""],["ٱللَّٰه","a"],[" ہمیں بیان کا صحیح طریقہ سکھا دیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.3 Pg.62)."]]},{"b":[["n",[["حضرت بدر بن عثمانؒ","b"],[" کے چچا بیان کرتے ہیں جب اہل شوریٰ حضرت عثمانؓ سے بیعت ہو گئے تو اس وقت وہ بہت غمگین تھے، ان کی طبیعت پر بڑا بوجھ تھا، اور وہ حضورؐ کے منبر پر تشریف لائے اور لوگوں میں بیان فرمایا۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر نبی کریمؐ پر درود بھیجا، اس کے بعد فرمایا تم ایسے گھر میں ہو جہاں سے تمہیں کوچ کر جانا ہے اور تمہاری عمر تھوڑی باقی رہ گئی ہے، لہٰذا تم جو خیر کے کام کر سکتے ہو موت سے پہلے کر لو، صبح اور شام موت تمہیں آنے ہی والی ہے۔ غور سے سنو! دنیا سراسر دھوکہ ہی دھوکہ ہے۔ (",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے)",""]]],["q",[["فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا ۖ وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ ","a"]]],["p",[["ترجمہ: \"سو تم کو دنیوی زندگانی دھوکہ میں نہ ڈالے اور نہ وہ دھوکہ باز (شیطان) تم کو ",""],["ٱللَّٰه","a"],[" سے دھوکہ میں ڈالے\" (سورۂ لقمان، آیت 33)۔ اور جو لوگ جا چکے ہیں ان سے عبرت حاصل کرو اور خوب محنت کرو اور غفلت سے کام نہ لو کیونکہ موت کا فرشتہ تم سے کبھی غافل نہیں ہوتا۔ کہاں ہیں دنیا کے وہ بھائی اور بیٹے جنہوں نے دنیا میں کھیتی باڑی کی اور اسے خوب آباد کیا اور لمبی مدت تک اس سے فائدہ اٹھایا؟ کیا دنیا نے انہیں پھینک نہیں دیا؟ چونکہ ",""],["ٱللَّٰه","a"],[" نے دنیا کو پھینکا ہوا ہے، اس لیے تم بھی اسے پھینک دو اور آخرت کو طلب کرو کیونکہ ",""],["ٱللَّٰه","a"],[" نے دنیا کی اور آخرت کی جو کہ دنیا سے بہتر ہے دونوں کی مثال اس آیت میں بیان کی ہے",""]]],["q",[["وَٱضْرِبْ لَهُم مَّثَلَ ٱلْحَيَوٰةِ ٱلدُّنْيَا كَمَآءٍ أَنزَلْنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخْتَلَطَ بِهِۦ نَبَاتُ ٱلْأَرْضِ فَأَصْبَحَ هَشِيمًا تَذْرُوهُ ٱلرِّيَٰحُ ۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ مُّقْتَدِرًا ۞ ٱلْمَالُ وَٱلْبَنُونَ زِينَةُ ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَٱلْبَٰقِيَٰتُ ٱلصَّٰلِحَٰتُ خَيْرٌ عِندَ رَبِّكَ ثَوَابًا وَخَيْرٌ أَمَلًا","a"]]],["p",[["ترجمہ: \"اور آپ ان لوگوں سے دنیاوی زندگی کی حالت بیان فرمائیے کہ وہ ایسی ہے جیسے آسمان سے ہم نے پانی برسایا ہو، پھر اس کے ذریعہ سے زمین کی نباتات خوب گنجان ہو گئی ہوں، پھر وہ ریزہ ریزہ ہو جاوے کہ اس کو ہوا اڑائے لیے پھرتی ہو، اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ہر چیز پر پوری قدرت رکھتے ہیں۔ مال اور اولاد حیات دنیا کی ایک رونق ہے اور جو اعمال صالحہ باقی رہنے والے ہیں وہ آپ کے رب کے نزدیک ثواب کے اعتبار سے بھی ہزار درجہ بہتر ہیں اور امید کے اعتبار سے بھی\" (سورۂ کہف، آیات 45–46)۔ اس بیان کے بعد لوگ حضرت عثمانؓ سے بیعت ہونے لگے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer in his Taareekh (Vol.3 Pg.305)."]]},{"b":[["n",[["حضرت عتبہؒ","b"],[" کہتے ہیں حضرت عثمانؓ نے بیعت کرنے کے بعد لوگوں میں بیان کیا جس میں ارشاد فرمایا اما بعد! مجھ پر خلافت کی ذمہ داری ڈالی گئی ہے جسے میں نے قبول کر لیا ہے۔ غور سے سنو! میں (حضورؐ اور حضرت ابوبکرؓ کے) پیچھے چلوں گا اور اپنے پاس سے گھڑ کر نئی باتیں نہیں لاؤں گا۔ توجہ سے سنو! ",""],["ٱللَّٰه","a"],[" کی کتاب اور اس کے نبیؐ کی سنت کے بعد میرے اوپر تمہارے تین حق ہیں۔ پہلا حق یہ ہے کہ جس چیز پر آپ لوگ متفق ہیں اور اس کا ایک راستہ مقرر کر لیا ہے اس میں میں اپنے سے پہلوں کے طریقہ پر چلوں، اور دوسرا حق یہ ہے کہ جس چیز میں آپ سب لوگوں نے مل کر کوئی راستہ مقرر نہیں کیا ہے اس میں میں خیر والوں کے راستے پر چلوں، اور تیسرا حق یہ ہے کہ میں آپ لوگوں سے اپنے ہاتھ روکے رکھوں، آپ لوگوں کو کسی قسم کی سزا نہ دوں۔ ہاں آپ لوگ ہی خود کوئی ایسا کام کر بیٹھیں جس پر سزا دینا میرے ذمہ واجب ہو تو یہ الگ بات ہے۔ غور سے سنو! دنیا سرسبز و شاداب ہے اور تمام لوگوں کے دلوں میں اس کی رغبت رکھی ہوئی ہے اور بہت لوگ اس کی طرف مائل ہو چکے ہیں، لہٰذا تم دنیا کی طرف مت جھکو اور اس پر بھروسہ نہ کرو، یہ بھروسہ کے قابل نہیں۔ اور یہ اچھی طرح سمجھ لو کہ یہ دنیا صرف اسے چھوڑتی ہے جو اسے چھوڑ دے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Jareer has also reported it in his Taareekh (Vol.3 Pg.446) with a chain containing Sayf."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عثمانؓ نے بیان فرمایا اور ارشاد فرمایا اے ابن آدم! یہ بات جان لو کہ موت کا فرشتہ تمہارے لیے مقرر کیا گیا ہے، جب سے تم دنیا میں آئے ہو وہ تمہیں چھوڑ کر دوسروں کے پاس جا رہا تھا لیکن اب اس نے دوسروں کو چھوڑ کر تمہارے پاس آنے کا ارادہ کر لیا ہے۔ اس لیے اپنے بچاؤ کا سامان لے لو اور موت کی تیاری کر لو اور غفلت سے کام نہ لو کیونکہ موت کا فرشتہ تم سے بالکل غافل نہیں ہے۔ اور اے ابن آدم! جان لو کہ اگر تم اپنے بارے میں غفلت میں پڑ گئے اور تم نے موت کی تیاری نہ کی تو تمہارے علاوہ کوئی اور یہ تیاری نہیں کرے گا اور ",""],["ٱللَّٰه","a"],[" سے ملاقات ضروری ہوئی ہے۔ اس لیے اپنے لیے نیک اعمال لے لو اور یہ کام دوسروں پر نہ چھوڑو۔ فقط والسلام۔",""],[" (4)","s"]]]],"f":[["(4)","Dinawari in Mujaalasah and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.109)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت عثمان بن عفانؓ نے لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا ",""],["ٱللَّٰه","a"],[" کا تقویٰ اختیار کرو کیونکہ ",""],["ٱللَّٰه","a"],[" کا تقویٰ غنیمت ہے۔ سب سے زیادہ عقلمند وہ ہے جو اپنے نفس پر قابو پا لے اور موت کے بعد والی زندگی کے لیے عمل کرے اور قبر کے اندھیرے کے لیے ",""],["ٱللَّٰه","a"],[" سے نور حاصل کرے۔ اور بندے کو اس بات سے ڈرنا چاہیے کہ کہیں ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے حشر کے دن اندھا بنا کر نہ اٹھائیں حالانکہ وہ دنیا میں آنکھوں والا تھا۔ اور سمجھدار آدمی کو تو چند جامع کلمات کافی ہو جاتے ہیں جن کے الفاظ کم اور معنی زیادہ ہوں اور بہرے آدمی کو تو دور سے پکارنا پڑتا ہے۔ اور یقین رکھو کہ جس کے ساتھ ",""],["ٱللَّٰه","a"],[" ہوگا وہ کس چیز سے نہیں ڈرے گا اور ",""],["ٱللَّٰه","a"],[" جس کے خلاف ہوگا وہ ",""],["ٱللَّٰه","a"],[" کے علاوہ اور کس سے مدد کی امید کر سکتا ہے؟",""],[" (5)","s"]]]],"f":[["(5)","Dinawari and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں میں نے حضرت عثمانؓ کو منبر پر دیکھا، وہ فرما رہے تھے اے لوگو! تم چھپ کر جو عمل کرتے ہو ان میں ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ میں نے حضورؐ کو فرماتے ہوئے سنا اس ذات کی قسم جس کے قبضہ میں محمدؐ کی جان ہے! جو بھی کوئی عمل چھپ کر کرتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے اس عمل کی چادر علی الاعلان ضرور پہنائیں گے۔ اگر خیر کا عمل کیا ہوگا تو اسے خیر کی چادر پہنائیں گے اور برا عمل کیا ہوگا تو اسے بری چادر پہنائیں گے۔ پھر حضرت عثمانؓ نے یہ آیت پڑھی",""]]],["q",[["وَرِيَاشًا ۖ وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ","a"]]],["p",[["ترجمہ: \"اور زینت (کا لباس) اور تقویٰ کا لباس، یہ اس سے بڑھ کر ہے\" (سورۂ اعراف، آیت 26)۔ اس میں حضرت عثمانؓ نے وَرِيَاشًا پڑھا اور وَرِيشًا نہ پڑھا (جو کہ مشہور قراءت ہے)۔ راوی کہتے ہیں زینت اور تقویٰ والے لباس سے مراد اچھی عادتیں ہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Jareer and Ibn Abi Haatim, as quoted in Kanzul Ummaal (Vol.2 Pg.137)."]]},{"b":[["n",[["حضرت عباد بن زاہرؒ","b"],[" کہتے ہیں میں نے حضرت عثمانؓ کو بیان کرتے ہوئے سنا، انہوں نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! ہم لوگ سفر و حضر میں حضورؐ کے ساتھ رہے، آپؐ ہمارے بیماروں کی عیادت فرماتے تھے اور ہمارے جنازوں کے ساتھ تشریف لے جاتے تھے اور ہمارے ساتھ غزوہ میں جاتے تھے اور آپؐ کے پاس کم یا زیادہ جتنا ہوتا اسی سے ہم سے ہمدردی و غمخواری فرماتے۔ اور اب کچھ لوگ مجھے حضورؐ کے بارے میں بتا رہے ہیں حالانکہ ان لوگوں نے تو شاید حضورؐ کو دیکھا بھی نہیں ہوگا۔ احمد اور ابویعلیٰ کی روایت میں اس کے بعد یہ ہے کہ اس پر اعین بن امراۃ الفرزدق نے حضرت عثمانؓ کو مخاطب کرتے ہوئے کہا اے نعثل! (مصر کے ایک آدمی کا نام نعثل تھا، اس کی داڑھی لمبی تھی، حضرت عثمانؓ کی داڑھی بھی لمبی تھی، معترضین کو حضرت عثمانؓ میں اس کے علاوہ اور کوئی کمی ملتی نہیں تھی، اس لیے اس سے تشبیہ دیتے ہوئے اس کے نام سے پکارا کرتے تھے) آپ نے تو سب کچھ بدل دیا ہے۔ حضرت عثمانؓ نے پوچھا یہ کون ہے؟ لوگوں نے بتایا یہ اعین ہے، تو فرمایا نہیں اے غلام! تو نے بدلا ہے۔ اس پر لوگ اعین پر جھپٹے۔ بنولیث کا ایک آدمی لوگوں کو اعین سے ہٹانے لگا اور وہاں سے بچا کر اعین کو اپنے گھر لے گیا۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Ahmad, Bazzaar, Marwazi, Shaafi'ee, Abu Ya'la and Sa'eed bin Mansoor, as quoted in Kanzul Ummaal (Vol.4 Pg.44)."],["(8)","Haythami (Vol.7 Pg.228) has commented that Ahmad and Abu Ya'la have reported it in his Kabeer and that their narrators are those of authentic Ahaadeeth except Abbaad bin Zaahir who is reliable."]]},{"b":[["n",[["حضرت مالکؒ","b"],[" کہتے ہیں میں نے حضرت عثمان بن عفانؓ کو بیان میں فرماتے ہوئے سنا کہ چھوٹی عمر کے غلام کو کما کر لانے کا مکلف نہ بناؤ کیونکہ اگر تم اسے کمانے کا مکلف بناؤ گے تو وہ چھوٹا ہونے کی وجہ سے کما نہیں سکے گا، اس لیے چوری شروع کر دے گا۔ ایسے ہی جو باندی کوئی کام یا ہنر نہ جانتی ہو اسے بھی کما کر لانے کا مکلف نہ بناؤ کیونکہ اگر تم اسے کما کر لانے کا مکلف بناؤ گے تو اسے کوئی کام اور ہنر تو آتا نہیں، اس لیے وہ اپنی شرم گاہ کے ذریعہ یعنی زنا کے ذریعہ کمانے لگ جائے گی۔ اور پاکدامنی اختیار کیے رہو کیونکہ ",""],["ٱللَّٰه","a"],[" نے تمہیں پاکدامنی عطا فرما رکھی ہے اور کھانے کی صرف وہ چیزیں استعمال کرو جو حلال اور پاکیزہ ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Shaafi'ee and Bayhaqi (Vol.8 Pg.9) from Maalik, as quoted in Kanzul Ummaal (Vol.5 Pg.47). Bayhaqi remarked that its raising back to Uthman is weak."]]},{"b":[["n",[["حضرت زبید بن صلتؒ","b"],[" کہتے ہیں میں نے حضرت عثمانؓ کو منبر پر فرماتے ہوئے سنا اے لوگو! جوا کھیلنے سے بچو یعنی نرد نہ کھیلا کرو، کیونکہ مجھے بتایا گیا ہے کہ تم میں سے کچھ لوگوں کے گھروں میں نرد کھیل کے آلات ہیں، اس لیے جس کے گھر میں یہ آلات موجود ہیں وہ یا تو انہیں جلا دے یا توڑ دے۔ اور دوسری مرتبہ حضرت عثمانؓ نے منبر پر فرمایا اے لوگو! میں نے اس نرد کھیل کے بارے میں بات کی تھی لیکن ایسا نظر آ رہا ہے کہ تم لوگوں نے اس کھیل کے آلات کو گھروں سے ابھی نہیں نکالا ہے، اس لیے میں نے ارادہ کر لیا ہے کہ حکم دے کر لکڑیوں کے گٹھے جمع کراؤں اور جن گھروں میں یہ آلات ہیں ان سب کو آگ لگا دوں۔",""],[" (10)","s"]]]],"f":[["(10)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.7 Pg.334)."]]},{"b":[["n",[["حضرت سالمؒ","b"],[" جو حضرت عبدالرحمٰن بن حمیدؒ کے آزاد کردہ غلام ہیں کہتے ہیں حضرت عثمانؓ نے منیٰ میں نماز پوری پڑھائی (حضورؐ اور حضرت ابوبکرؓ اور حضرت عمرؓ حج کے موقع پر منیٰ کے دنوں میں ظہر، عصر، عشاء تینوں نمازوں میں دو رکعت نماز پڑھاتے رہے۔ شروع میں حضرت عثمانؓ بھی دو رکعت پڑھاتے رہے لیکن پھر چار رکعت پڑھانے لگے تھے)، پھر لوگوں میں بیان کیا جس میں فرمایا اے لوگو! اصل سنت تو وہ ہے جو حضورؐ اور آپؐ کے ساتھیوں (حضرت ابوبکرؓ اور حضرت عمرؓ) نے کیا، لیکن اس سال لوگ حج پر بہت آئے ہیں، اس لیے مجھے ڈر ہوا کہ لوگ دو رکعت پڑھنے کو مستقل سنت نہ بنا لیں (اس لیے میں نے چار رکعت پڑھائیں)۔",""],[" (11)","s"]]]],"f":[["(11)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.4 Pg.239)."]]},{"b":[["n",[["حضرت قتیبہ بن مسلمؒ","b"],[" کہتے ہیں حجاج بن یوسف نے ہم میں بیان کیا اور اس نے قبر کا تذکرہ کیا اور مسلسل کہتا رہا کہ یہ قبر تنہائی کا گھر ہے اور اجنبیت اور بیگانگی کا گھر ہے، یہاں تک کہ خود بھی رونے لگا اور آس پاس والوں کو بھی رلا دیا۔ پھر کہا میں نے امیر المومنین عبدالملک بن مروان کو کہتے ہوئے سنا کہ ایک مرتبہ حضرت عثمان بن عفانؓ نے ہم میں بیان کیا جس میں فرمایا حضورؐ نے جب بھی کسی قبر کو دیکھا یا اس کا تذکرہ کیا تو آپؐ ضرور روئے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.109)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں میں نے حضرت عثمانؓ کو منبر پر بیان میں فرماتے ہوئے سنا کہ میں بنو قینقاع کے ایک یہودی خاندان سے کھجوریں خریدتا تھا اور آ کر نفع پر بیچتا تھا۔ حضورؐ کو یہ خبر پہنچی تو فرمایا اے عثمان! جب خریدا کرو تو پیمانہ سے ناپ لیا کرو اور جب بیچا کرو تو دوبارہ پھر پیمانہ سے ناپ کر دیا کرو۔",""],[" (13)","s"]]]],"f":[["(13)","Ahmad (Vol.1 Pg.62)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں میں ایک مرتبہ حضرت عثمانؓ کی خدمت میں حاضر تھا، آپؓ بیان میں تکلیف دہ کتوں کو مارنے کا اور کھیل کے طور پر اڑائے جانے والے کبوتروں کو ذبح کر دینے کا حکم دے رہے تھے (جو دوسرے کبوتروں کو لے آتے ہوں)۔",""],[" (14)","s"]]]],"f":[["(14)","Ahmad (Vol.1 Pg.72)."]]},{"b":[["n",[["حضرت بدر بن عثمانؒ","b"],[" کے چچا کہتے ہیں مجمع میں حضرت عثمانؓ نے آخری بیان میں یہ فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہیں دنیا اس لیے دی ہے تاکہ تم اس کے ذریعہ سے آخرت حاصل کرو اور اس لیے نہیں دی کہ تم اسی کے ہو جاؤ۔ دنیا فنا ہونے والی ہے اور آخرت ہمیشہ باقی رہنے والی ہے۔ نہ تو فانی دنیا سے اترانے لگو اور نہ اس کی وجہ سے آخرت سے غافل ہو جاؤ۔ فانی دنیا پر ہمیشہ باقی رہنے والی آخرت کو ترجیح دو کیونکہ دنیا ختم ہو جائے گی اور ہم سب نے لوٹ کر ",""],["ٱللَّٰه","a"],[" ہی کے پاس جانا ہے۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ سے ڈرو کیونکہ ",""],["ٱللَّٰه","a"],[" سے ڈرنا ہی اس کے عذاب سے ڈھال اور اس کی بارگاہ میں پہنچنے کا وسیلہ ہے۔ اور احتیاط سے چلو کہیں ",""],["ٱللَّٰه","a"],[" تمہارے حالات نہ بدل دے اور اپنی جماعت سے چمٹے رہو اور مختلف گروہ نہ بن جاؤ، اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی نعمت کو یاد کرو",""]]],["q",[["وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءً فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًا","a"]]],["p",[["ترجمہ: \"اور تم پر جو ",""],["ٱللَّٰه","a"],[" تعالیٰ کا انعام ہے اس کو یاد کرو جبکہ تم دشمن تھے، پس ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہارے قلوب میں الفت ڈال دی، سو تم خدا تعالیٰ کے انعام سے آپس میں بھائی بھائی ہو گئے\" (سورۂ آل عمران، آیت 103)۔ اور جہاد کے باب میں ",""],["ٱللَّٰه","a"],[" تعالیٰ کے راستہ میں پہرہ دینے کی فضیلت میں حضرت عثمانؓ کا بیان گزر چکا ہے۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Jareer in his Taareekh (Vol.3 Pg.446)."]]}]},"182":{"lead":[],"stories":[{"b":[["n",[["حضرت علی بن حسینؒ","b"],[" کہتے ہیں امیر المومنین بننے کے بعد حضرت علیؓ نے جو سب سے پہلا بیان فرمایا اس میں پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا ",""],["ٱللَّٰه","a"],[" نے ہدایت دینے والی کتاب نازل فرمائی اور اس میں خیر و شر سب بیان کر دیا، لہٰذا تم خیر کو لو اور شر کو چھوڑ دو اور تمام فرائض ادا کر کے ",""],["ٱللَّٰه","a"],[" کے ہاں بھیج دو، ",""],["ٱللَّٰه","a"],[" ان کے بدلے میں تمہیں جنت میں پہنچا دیں گے۔ ",""],["ٱللَّٰه","a"],[" نے بہت سی چیزوں کو قابل احترام بنایا ہے جو سب کو معلوم ہے، لیکن ان تمام چیزوں پر مسلمان کی حرمت کو فوقیت عطا فرمائی ہے اور ",""],["ٱللَّٰه","a"],[" نے اخلاص اور وحدانیت کے یقین کے ذریعہ مسلمانوں کو مضبوط کیا ہے۔ اور کامل مسلمان وہ ہے جس کی زبان اور ہاتھ کی ناحق تکلیف سے تمام لوگ محفوظ رہیں۔ کسی مسلمان کو ایذا پہنچانا حلال نہیں ہے، البتہ قصاص اور بدلے میں جو تکلیف دینا شرعاً واجب ہو جائے اس کی اور بات ہے۔ قیامت اور موت کے آنے سے پہلے پہلے اعمال صالحہ کر لو کیونکہ بہت سے لوگ تم سے آگے جا چکے ہیں اور تمہارے پیچھے قیامت آ رہی ہے جو تمہیں ہانک رہی ہے۔ ہلکے پھلکے رہو یعنی گناہ نہ کر کے ہلکے رہو تاکہ آگے والوں سے جا ملو کیونکہ اگلے لوگ پچھلوں کا انتظار کر رہے ہیں۔ ",""],["ٱللَّٰه","a"],[" کے بندو! ",""],["ٱللَّٰه","a"],[" کے بندوں اور شہروں کے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو، تم سے ہر چیز کے بارے میں پوچھا جائے گا حتیٰ کہ زمین کے ٹکڑوں اور جانوروں کے بارے میں بھی پوچھا جائے گا۔ ",""],["ٱللَّٰه","a"],[" کی اطاعت کرو اور اس کی نافرمانی نہ کرو۔ جب تمہیں خیر کی کوئی چیز نظر آئے تو اسے لے لو اور جب شر نظر آئے تو اسے چھوڑ دو اور اس وقت کو یاد کرو جب تم تھوڑے تھے اور سرزمین مکہ میں تم کمزور سمجھے جاتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer in his Taareekh (Vol.3 Pg.457)."]]},{"b":[["n",[["ایک مرتبہ حضرت علیؓ نے بیان فرمایا جس میں ارشاد فرمایا آدمی کو اس کے کنبہ کو اتنے فائدے حاصل نہیں ہوتے جتنے کنبہ سے آدمی کو حاصل ہوتے ہیں، کیونکہ اگر آدمی کنبہ کی مدد سے اپنا ہاتھ روکتا ہے تو صرف ایک ہاتھ روکتا ہے اور کنبہ والے اپنے ہاتھ روک لیں تو پھر کئی ہاتھ رک جاتے ہیں۔ اور کنبہ کی طرف سے آدمی کو محبت، حفاظت اور نصرت ملتی ہے۔ بعض دفعہ ایک آدمی دوسرے کی خاطر ناراض ہوتا ہے حالانکہ وہ اس دوسرے آدمی کو صرف اس کے خاندانی نسب کی وجہ سے ہی جانتا ہے۔ میں تمہیں اس بارے میں ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے بہت سی آیتیں پڑھ کر سناؤں گا، پھر حضرت علیؓ نے یہ آیت پڑھی",""]]],["q",[["لَوْ أَنَّ لِى بِكُمْ قُوَّةً أَوْ ءَاوِىٓ إِلَىٰ رُكْنٍ شَدِيدٍ","a"]]],["p",[["ترجمہ: \"کیا خوب ہوتا اگر میرا تم پر کچھ زور چلتا یا میں کسی مضبوط پایہ کی پناہ پکڑتا\" (سورۂ ہود، آیت 80)۔ اس کے بعد حضرت علیؓ نے فرمایا یہ جو حضرت لوط علیہ السلام نے رکن شدید یعنی مضبوط پایہ فرمایا ہے اس سے مراد کنبہ ہے، کیونکہ حضرت لوطؑ کے بعد ",""],["ٱللَّٰه","a"],[" نے جو نبی بھی بھیجا وہ اپنی قوم کے بڑے کنبہ میں بھیجا۔ پھر حضرت علیؓ نے حضرت شعیب علیہ السلام کے بارے میں یہ آیت پڑھی",""]]],["q",[["وَإِنَّا لَنَرَىٰكَ فِينَا ضَعِيفًا","a"]]],["p",[["ترجمہ: \"اور ہم تم کو اپنے میں کمزور دیکھ رہے ہیں\" (سورۂ ہود، آیت 91)۔ حضرت علیؓ نے فرمایا حضرت شعیبؑ چونکہ نابینا تھے اس لیے ان لوگوں نے آپ کو کمزوری کی طرف منسوب کیا اور کہا",""]]],["q",[["وَلَوْلَا رَهْطُكَ لَرَجَمْنَٰكَ","a"]]],["p",[["ترجمہ: \"اور اگر تمہارے خاندان کا پاس نہ ہوتا تو ہم تم کو سنگسار کر چکے ہوتے\" (سورۂ ہود، آیت 91)۔ حضرت علیؓ نے فرمایا اس ذات کی قسم جس کے سوا کوئی معبود نہیں! انہیں اپنے رب کے جلال کا ڈر تو تھا نہیں، البتہ حضرت شعیبؑ کے خاندان کا ڈر تھا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Shaykh, as quoted in Kanzul Ummaal (Vol.1 Pg.250)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں جب رمضان شریف آتا تو حضرت علیؓ بیان فرماتے اور اس میں یہ ارشاد فرماتے یہ وہ مبارک مہینہ ہے جس کے روزے کو ",""],["ٱللَّٰه","a"],[" نے فرض کیا اور اس کی تراویح کو (ثواب کی چیز بنایا لیکن) فرض نہیں کیا۔ اور آدمی کو یہ بات کہنے سے بچنا چاہیے کہ فلاں روزہ رکھے گا تو میں بھی رکھوں گا اور جب فلاں روزہ رکھنا چھوڑ دے گا تو میں بھی چھوڑ دوں گا۔ غور سے سنو! روزہ صرف کھانے پینے کا نام نہیں ہے، بلکہ انہیں تو چھوڑنا ہے ہی لیکن اصل روزہ یہ ہے کہ آدمی جھوٹ، غلط اور بیہودہ باتوں کو بھی چھوڑ دے۔ توجہ سے سنو! رمضان کے مہینہ کو اس کی جگہ سے آگے نہ لے جاؤ، یعنی جب تمہیں رمضان کا چاند نظر آ جائے تو روزے شروع کر دو اور جب عید کا چاند نظر آئے تو روزے رکھنے چھوڑ دو اور اگر رمضان کی 29 کو غروب کے وقت ابر ہو تو پھر مہینہ کی 30 کی گنتی پوری کرو۔ حضرت شعبیؒ کہتے ہیں حضرت علیؓ یہ تمام باتیں فجر اور عصر کے بعد کہا کرتے تھے۔",""],[" (3)","s"]]]],"f":[["(3)","Hasan bin Yahya Qattaan and Bayhaqi, as quoted in Kanzul Ummaal (Vol.4 Pg.322)."]]},{"b":[["n",[["ایک مرتبہ حضرت علیؓ نے بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر موت کا تذکرہ فرمایا، چنانچہ ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" کے بندو! ",""],["ٱللَّٰه","a"],[" کی قسم! موت سے کسی کو چھٹکارا نہیں ہے۔ اگر تم (اس کے لیے تیاری کر کے) اس کے لیے ٹھہر جاؤ گے تو بھی وہ تمہیں پکڑ لے گی اور اگر (اس کے لیے تیاری نہیں کرو گے بلکہ) اس سے بھاگو گے تو بھی وہ تمہیں آ پکڑے گی۔ اس لیے اپنی نجات کی فکر کرو، نجات کی فکر کرو اور جلدی کرو، جلدی کرو، اور ایک چیز تلاش میں تمہارے پیچھے لگی ہوئی ہے جو بہت تیز ہے اور وہ ہے قبر۔ لہٰذا قبر کے بھینچنے سے، اس کی اندھیری سے اور اس کی وحشت سے بچو۔ غور سے سنو! قبر یا تو جہنم کے گڑھوں میں سے ایک گڑھا ہے یا جنت کے باغوں میں سے ایک باغ ہے۔ غور سے سنو! قبر روزانہ تین مرتبہ یہ اعلان کرتی ہے میں تاریکی کا گھر ہوں، میں کیڑوں کا گھر ہوں، میں تنہائی کا گھر ہوں۔ غور سے سنو! قبر کے بعد وہ جگہ ہے جو قبر سے بھی زیادہ سخت ہے، وہ جہنم کی آگ ہے جو بہت گرم اور بہت گہری ہے، جس کے زیور (یعنی سزا دینے کے آلات) لوہے کے ہیں، جس کے نگران فرشتے کا نام مالک ہے، جس میں ",""],["ٱللَّٰه","a"],[" کی طرف سے کسی طرح کی نرمی یا رحم کا ظہور نہیں ہوگا۔ اور توجہ سے سنو! اس کے بعد ایسی جنت ہے جس کی چوڑائی آسمانوں اور زمین کے برابر ہے، جو متقیوں کے لیے تیار کی گئی ہے۔ ",""],["ٱللَّٰه","a"],[" ہمیں اور آپ کو متقیوں میں سے بنائے اور دردناک عذاب سے بچائے۔",""],[" (4)","s"]]]],"f":[["(4)","Saabooni in Al Matayn and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.110)."]]},{"b":[["n",[["حضرت اصبغ بن نباتہؒ","b"],[" بھی اسی بیان کو اسی طرح نقل کرتے ہیں کہ ایک دن حضرت علیؓ منبر پر تشریف فرما ہوئے۔ پہلے انہوں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور موت کا ذکر کیا اور پھر پچھلی حدیث جیسا مضمون ذکر کیا اور قبر جو یہ اعلان کرتی ہے کہ میں تنہائی کا گھر ہوں۔ اس کے بعد اس روایت میں یہ ہے کہ غور سے سنو! قبر کے بعد (قیامت کا) ایک ایسا دن ہے جس میں بچے بوڑھے ہو جائیں گے اور بوڑھے مدہوش، اور تمام حمل والیاں (دن پورے ہونے سے پہلے ہی) اپنا حمل ڈال دیں گی اور (اے مخاطب!) تمہیں لوگ نشہ کی حالت میں نظر آئیں گے حالانکہ وہ نشہ میں نہیں ہوں گے لیکن اس دن ",""],["ٱللَّٰه","a"],[" کا عذاب بہت سخت ہوگا۔ اور ایک روایت میں اس کے بعد یہ ہے کہ پھر حضرت علیؓ رونے لگے اور ان کے ارد گرد کے تمام مسلمان بھی رونے لگے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Katheer has mentioned it in Al Bidaayah wan Nihaayah (Vol.8 Pg.6)."]]},{"b":[["n",[["حضرت صالح عجلیؒ","b"],[" کہتے ہیں ایک دن حضرت علی بن ابی طالبؓ نے بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر نبی کریمؐ پر درود بھیجا، پھر فرمایا ",""],["ٱللَّٰه","a"],[" کے بندو! دنیاوی زندگی تمہیں دھوکہ میں نہ ڈال دے کیونکہ یہ ایسا گھر ہے جو بلاؤں سے گھرا ہوا ہے اور جس کا ایک دن فنا ہو جانا مشہور ہے اور جس کی خاص صفت بد عہدی کرنا ہے، اور اس میں جو کچھ ہے وہ زوال پذیر ہے اور دنیا اپنی جگہ بدلتی رہتی ہے، کبھی کسی کے پاس اور کبھی کسی کے پاس۔ اور اس میں اترانے والے اس کے شر سے ہرگز نہیں بچ سکتے اور دنیا والے خوب فراوانی اور خوشیوں میں ہوتے ہیں اور اچانک آزمائش اور دھوکہ میں آ جاتے ہیں۔ دنیا کے عیش و عشرت میں لگنا قابل مذمت کام ہے اور اس کی فراوانی ہمیشہ نہیں رہتی اور دنیا والے خود دنیا کے لیے نشانہ ہیں، ان پر دنیا اپنے تیر چلاتی رہتی ہے اور موت کے ذریعہ انہیں توڑتی رہتی ہے۔ ",""],["ٱللَّٰه","a"],[" کے بندو! تمہارا دنیا کا راستہ ان لوگوں سے الگ نہیں ہے جو دنیا سے جا چکے ہیں، جن کی عمریں تم سے زیادہ لمبی تھیں اور جن کی پکڑ تم سے زیادہ سخت تھی اور جنہوں نے تم سے زیادہ شہر آباد کیے تھے اور جن کی آبادی کے نشانات بہت زیادہ عرصہ تک رہے تھے اور ان کی آوازوں کا شور بہت زمانے تک رہا تھا لیکن اب ان کی یہ آوازیں بالکل خاموش اور بجھ چکی ہیں اور ان کے جسم بوسیدہ اور ان کے شہر خالی ہو چکے ہیں اور ان کے تمام نشانات مٹ چکے ہیں۔ اور قلعی اور چونے والے محلات، مزین تختوں اور بچھے ہوئے گاؤ تکیوں کے بجائے اب انہیں چٹانیں اور پتھر مل گئے ہیں جو ان کی بغلی قبروں میں رکھے ہوئے ہیں اور گارے سے بنے ہوئے ہیں اور ان کی قبروں کے سامنے کی جگہ ویران اور بے آباد پڑی ہوئی ہے اور مٹی کے گارے سے ان قبروں پر لپائی کی گئی ہے۔ ان قبروں کی جگہ آبادی کے قریب ہے لیکن ان میں رہنے والے بہت دور چلے جانے والے مسافر ہیں۔ ان کی قبریں آبادی کے درمیان ہیں لیکن ان قبروں والے وحشت اور تنہائی محسوس کرتے ہیں۔ ان کی قبریں کسی محلہ میں ہیں لیکن یہ قبروں والے اپنے ہی میں مشغول ہیں اور انہیں آبادی سے کوئی انس نہیں ہے، حالانکہ یہ قبروں والے ایک دوسرے کے پڑوسی ہیں اور ان کی قبریں پاس پاس ہیں لیکن ان میں پڑوسیوں والا کوئی جوڑ نہیں ہے اور ان میں آپس میں جوڑ ہو بھی کیسے سکتا ہے جبکہ بوسیدگی نے انہیں پیس رکھا ہے اور چٹانوں اور گیلی مٹی نے انہیں کھا رکھا ہے۔ پہلے یہ لوگ زندہ تھے اب مر چکے ہیں اور عیش و لذت والی زندگی گزار کر اب ریزہ ریزہ ہو چکے ہیں۔ ان کے مرنے پر ان کے دوستوں کو بہت دکھ ہوا اور مٹی میں انہوں نے بسیرا اختیار کر لیا اور ایسے سفر پر گئے ہیں جہاں سے واپسی نہیں۔ ہائے افسوس! ہائے افسوس! ہرگز ایسا نہیں ہوگا، یہ اس کی صرف ایک بات ہی ہے جس کو وہ کہہ رہا ہے، اور ان کے آگے (یعنی) عالم برزخ ہے اس دن تک کے لیے جس دن لوگ دوبارہ زندہ کیے جائیں گے۔ اور تم بھی ایک دن ان کی طرح قبرستان میں اکیلے رہو گے اور بوسیدہ ہو جاؤ گے اور تمہیں بھی اس لیٹنے کی جگہ کے سپرد کر دیا جائے گا اور یہ قبر کا امانت خانہ تمہیں اپنے میں سمیٹ لے گا۔ تمہارا اس وقت کیا حال ہوگا جب تمام کام ختم ہو جائیں گے اور قبروں کے مردے زندہ کر کے کھڑے کر دیے جائیں گے اور جو کچھ دلوں میں ہے وہ سب کھول کر رکھ دیا جائے گا اور تمہیں جلال و دبدبہ والے بادشاہ کے سامنے اندر کی ساری باتیں ظاہر کرنے کے لیے کھڑا کر دیا جائے گا، پھر گزشتہ گناہوں کے ڈر سے دل اڑنے لگ جائیں گے اور تمہارے اوپر سے تمام رکاوٹیں اور پردے ہٹا دیے جائیں گے اور تمہارے تمام عیب اور راز ظاہر ہو جائیں گے اور ہر انسان کو اپنے کیے کا بدلہ ملے گا۔ برے کام کرنے والوں کو ",""],["ٱللَّٰه","a"],[" تعالیٰ برا بدلہ اور اچھے کام کرنے والوں کو اچھا بدلہ دیں گے اور اعمال نامہ سامنے رکھ دیا جائے گا تو آپ مجرموں کو دیکھیں گے کہ وہ اس اعمال نامہ میں جو کچھ لکھا ہوا ہے اس سے ڈر رہے ہوں گے اور کہہ رہے ہوں گے ہائے ہماری بدقسمتی! اس اعمال نامہ کی عجیب حالت ہے، اس نے لکھے بغیر نہ چھوٹا گناہ چھوڑا اور نہ بڑا۔ اور جو کچھ انہوں نے دنیا میں کیا تھا اسے وہاں سب لکھا ہوا موجود پائیں گے اور آپ کا رب کسی پر ظلم نہیں کرے گا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیں اور آپ کو اپنی کتاب پر عمل کرنے والا اور اپنے دوستوں کے پیچھے چلنے والا بنائے تاکہ ہمیں اور آپ کو اپنے فضل سے ہمیشہ رہنے کے گھر یعنی جنت میں جگہ عطا فرمائے، بیشک وہ تعریف کے قابل بزرگی والا ہے۔ ابن جوزی نے حضرت علیؓ کے اسی بیان کو تفصیل سے ذکر کیا ہے لیکن شروع میں اس مضمون کا اضافہ کیا ہے کہ حضرت علی بن ابی طالبؓ نے بیان فرمایا اور ارشاد فرمایا تمام تعریفیں ",""],["ٱللَّٰه","a"],[" ہی کے لیے ہیں، میں اسی ذات کی تعریف کرتا ہوں اور اسی سے مدد طلب کرتا ہوں اور اسی پر ایمان لاتا ہوں اور اسی پر بھروسہ کرتا ہوں اور اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں اور حضرت محمدؐ اس کے بندے اور رسول ہیں جنہیں ",""],["ٱللَّٰه","a"],[" نے ہدایت اور دین حق دے کر بھیجا تاکہ اس کے ذریعہ سے ",""],["ٱللَّٰه","a"],[" تمہاری تمام بیماریوں کو دور کر دے اور تمہیں غفلت سے بیدار کر دے۔ اور یہ بات جان لو کہ ایک دن تم لوگوں نے مرنا ہے اور مرنے کے بعد قیامت کے دن تم لوگوں کو اٹھایا جائے گا اور اعمال پر لا کر کھڑا کر دیا جائے گا اور پھر ان اعمال کا بدلہ تمہیں دیا جائے گا۔ لہٰذا دنیاوی زندگی تمہیں دھوکہ میں نہ ڈال دے۔ پھر آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Dinawari and Ibn Asaakir from Abdullah bin Saalih Ijli from his father, as quoted in Kanzul Ummaal (Vol.8 Pg.219) and Muntakhab Kanzul Ummaal (Vol.6 Pg.324)."],["(7)","Ibn Jawzi has mentioned it in Safwatus Safwah (Vol.1 Pg.124)."]]},{"b":[["n",[["حضرت جعفر بن محمدؒ","b"],[" کے دادا کہتے ہیں حضرت علیؓ ایک جنازے کے ساتھ تشریف لے گئے۔ جب اس میت کو قبر میں رکھا جانے لگا تو اس کے گھر والے اور رشتہ دار سب اونچی آواز سے رونے لگے۔ حضرت علیؓ نے فرمایا کیوں روتے ہو؟ غور سے سنو! ",""],["ٱللَّٰه","a"],[" کی قسم! ان لوگوں کے مرنے والے نے اب قبر میں جا کر جو منظر دیکھ لیا ہے اگر یہ لوگ بھی وہ منظر دیکھ لیں تو یہ اپنے مردے کو بھول جائیں۔ موت بار بار ان لوگوں کے پاس آتی ہے یہاں تک کہ ان میں سے ایک بھی باقی نہیں رہے گا۔ پھر (بیان کے لیے) کھڑے ہوئے اور فرمایا ",""],["ٱللَّٰه","a"],[" کے بندو! میں تمہیں اس ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں جس نے تمہارے لیے مثالیں بیان کیں، تمہاری موت کا وقت مقرر کیا اور تمہارے ایسے کان بنائے کہ ان میں جو بات پہنچتی ہے اسے سمجھ کر محفوظ کر لیتے ہیں اور ایسی آنکھیں عطا فرمائیں کہ جو کچھ پردے میں ہے اسے وہ ظاہر کر دیتی ہیں اور ایسے دل دیے جو مصائب اور مشکلات کو سمجھتے ہیں، جوان کی صورتوں کی ترکیب میں ان کو پیش آتے ہیں اور اس چیز کو بھی سمجھتے ہیں جس نے ان دلوں کو آباد کیا یعنی ذکر الٰہی کو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہیں بیکار پیدا نہیں کیا اور تم سے نصیحت والی کتاب یعنی قرآن کو ہٹایا بھی نہیں (بلکہ تمہیں نصیحت والی کتاب عطا فرمائی)، بلکہ پوری نعمتوں سے تمہیں نوازا اور مکمل عطیات دیے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہارا پوری طرح احاطہ اور شمار کیا ہوا ہے اور خوشی اور نفع کی حالت میں اور نقصان اور رنج کی حالت میں آپ لوگ جو کچھ کرتے ہیں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس کا بدلہ تیار کیا ہوا ہے۔ ",""],["ٱللَّٰه","a"],[" کے بندو! ",""],["ٱللَّٰه","a"],[" سے ڈرو اور دین کی طلب میں مزید کوشش کرو اور خواہشات کے ٹکڑے کر دینے والی اور لذتوں کو توڑ دینے والی یعنی موت سے پہلے پہلے نیک عمل کر لو کیونکہ دنیا کی نعمتیں ہمیشہ نہیں رہیں گی اور اس کے دردناک حادثات سے امن نہیں ہے۔ دنیا ایک دھوکہ ہے جس کی شکل بدلتی رہتی ہے اور کمزور سا سایہ ہے اور ایسا سہارا ہے جو جھک جاتا ہے یعنی بوقت ضرورت کام نہیں آتا۔ شروع میں یہ دھوکہ نیا نظر آتا ہے لیکن جلدی ہی پرانا ہو کر گزر جاتا ہے اور اپنے پیچھے چلنے والے کو اپنی شہوتوں میں تھکا کر اور دھوکہ کا دودھ پلا کر ہلاک کر دیتا ہے۔ ",""],["ٱللَّٰه","a"],[" کے بندو! عبرت کی چیزوں سے نصیحت پکڑو اور قرآنی آیتوں اور نبوی حدیثوں سے عبرت حاصل کرو اور ڈرانے والی چیزوں سے ڈر جاؤ اور وعظ و نصیحت کی باتوں سے نفع حاصل کرو۔ یوں سمجھو کہ موت نے اپنے پنجے تم میں گاڑ دیے ہیں اور مٹی کے گھرنے نے تمہیں اپنے اندر سمیٹ لیا ہے اور بڑے سخت اور ہولناک مناظر تم پر اچانک آ گئے ہیں (ان مناظر کی تفصیل یہ ہے کہ) صور پھونک دیا گیا ہے اور قبروں میں سے تمام انسانوں کو اٹھایا جا رہا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنی زبردست قدرت سے تمام انسانوں کو ہانک کر محشر میں لا رہے ہیں اور حساب کے لیے کھڑا کر رہے ہیں، اور ہر انسان کے ساتھ ",""],["ٱللَّٰه","a"],[" نے ایک فرشتہ لگا رکھا ہے جو اسے محشر کی طرف ہانک رہا ہے اور ہر انسان کے ساتھ ایک فرشتہ ہے جو اس کے خلاف اس کے برے اعمال کی گواہی دے رہا ہے، اور زمین اپنے رب کے نور سے چمک اٹھی ہے اور اعمال کے حساب کا دفتر لا کر رکھ دیا گیا ہے اور انبیاءؑ اور گواہ سب حاضر کر دیے گئے ہیں اور ان کے درمیان انصاف کے ساتھ فیصلہ کیا جا رہا ہے اور ان پر کسی طرح کا ظلم نہیں کیا جا رہا ہے۔ اس دن کی وجہ سے تمام شہر تھرا رہے ہیں اور ایک اعلان کرنے والا اعلان کر رہا ہے اور یہ اولین اور آخرین کی باہمی معاملات کا دن ہے، اور ",""],["ٱللَّٰه","a"],[" کی طرف سے خاص تجلی ظاہر ہو رہی ہے اور سورج بے نور ہو رہا ہے، جگہ جگہ وحشی جانور گھبرا کر اکٹھے ہو گئے ہیں اور چھپے ہوئے تمام راز کھل گئے ہیں اور شریر لوگ ہلاک ہو رہے ہیں اور انسانوں کے دل کانپ رہے ہیں اور جہنم والوں پر ",""],["ٱللَّٰه","a"],[" کی طرف سے ہلاک کر دینے والا رعب اور رلا دینے والی سزا اتر رہی ہے۔ جہنم کو ظاہر کر دیا گیا ہے، اسے دیکھنے کا اب کوئی آڑ نہیں ہے۔ اس میں آنکڑے اور شور ہے اور کڑک جیسی بھیانک آواز ہے۔ جہنم سخت غصے میں ہے اور دھمکیاں دے رہی ہے اور اس کی آگ بھڑک رہی ہے اور اس کا گرم پانی ابل رہا ہے اور اس کی گرم ہوا میں اور تیزی آ رہی ہے اور اس میں ہمیشہ رہنے والے کا کوئی غم اور پریشانی دور نہیں کی جائے گی اور اس جہنم میں رہنے والوں کی حسرتیں کبھی ختم نہیں ہوں گی اور اس جہنم کی بیڑیاں کبھی توڑی نہیں جائیں گی۔ اور ان جہنمیوں کے ساتھ فرشتے ہیں جو انہیں گرم پانی کی آگ میں داخل ہونے کی خوشخبری دے رہے ہیں اور انہیں ",""],["ٱللَّٰه","a"],[" کے دیدار سے روک دیا گیا ہے اور انہیں دوستوں سے جدا کر دیا گیا ہے اور سب جہنم کی آگ کی طرف چلے جا رہے ہیں۔ ",""],["ٱللَّٰه","a"],[" کے بندو! ",""],["ٱللَّٰه","a"],[" سے اس آدمی کی طرح ڈرو جس نے دب کر عاجزی اختیار کر لی ہو اور (دشمن سے) ڈر کر کوچ کر گیا ہو اور جسے برے کاموں سے ڈرایا گیا ہو اور دیکھ بھال کر ان سے رک گیا ہو اور جلدی جلدی تلاش کرنے لگا ہو اور بھاگ کر نجات حاصل کر لی ہو اور آخرت کے لیے اس نے نیک اعمال آگے بھیج دیے ہوں جہاں لوٹ کر جانا ہے اور نیک اعمال کے توشہ سے اس نے مدد حاصل کی ہو۔ اور بدلہ لینے اور دیکھنے میں ",""],["ٱللَّٰه","a"],[" کافی ہے اور جھگڑنے اور حجت کرنے میں ",""],["ٱللَّٰه","a"],[" کی کتاب کافی ہے اور جنت ثواب کے لیے اور جہنم وبال اور سزا کے لیے کافی ہے اور میں اپنے لیے اور آپ لوگوں کے لیے ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.77) from Ja'far bin Muhammad from his father from his grandfather."]]},{"b":[["n",[["ایک مرتبہ حضرت علیؓ نے بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! دنیا نے پشت پھیر لی ہے اور جدائی کا اعلان کر دیا ہے اور آخرت سامنے آ رہی ہے اور بلندی سے جھانک رہی ہے۔ آج گھوڑے دوڑانے کا یعنی عمل کا میدان ہے، کل تو ایک دوسرے سے آگے نکلنا ہوگا۔ غور سے سنو! تم آج کل دنیاوی امیدوں کے دنوں میں ہو لیکن ان کے پیچھے موت آ رہی ہے اور جس نے امید کے دنوں میں موت کے آنے سے پہلے نیک اعمال میں کوتاہی کی وہ ناکام و نامراد ہو گیا۔ توجہ سے سنو! جیسے تم خوف کے وقت عمل کرتے ہو ایسے ہی دوسرے اوقات میں بھی شوق اور رغبت سے عمل کیا کرو۔ غور سے سنو! میں نے ایسی کوئی چیز نہیں دیکھی جو جنت جیسی ہو اور پھر بھی اس کا طالب سویا ہوا ہو اور نہ ہی ایسی کوئی چیز دیکھی جو جہنم جیسی ہو اور پھر بھی اس سے بھاگنے والا سویا ہوا ہو۔ غور سے سنو! جو حق سے نفع نہیں اٹھاتا اسے باطل ضرور نقصان پہنچاتا ہے۔ جسے ہدایت سیدھے راستے پر نہ چلا سکی اسے گمراہی سیدھے راستے سے ہٹا دے گی۔ غور سے سنو! آپ لوگوں کو یہاں سے کوچ کرنے کا اور سفر آخرت کا حکم مل چکا ہے اور اس سفر کا توشہ بھی آپ لوگوں کو بتا دیا گیا ہے۔ اے لوگو غور سے سنو! یہ دنیا تو ایسا سامان ہے جو سامنے موجود ہے اور اس میں سے اچھا برا ہر ایک کھا رہا ہے اور ",""],["ٱللَّٰه","a"],[" نے آخرت کا جو وعدہ فرما رکھا ہے وہ بالکل سچا ہے اور وہاں وہ بادشاہ فیصلہ کرے گا جو بڑی قدرت والا ہے۔ غور سے سنو! شیطان تمہیں فقیر اور محتاج ہونے سے ڈراتا ہے اور تمہیں بے حیائی کے کاموں کا حکم دیتا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنی طرف سے مغفرت اور فضل کا وعدہ فرماتے ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ بہت وسعت والے اور خوب جاننے والے ہیں۔ اے لوگو! اپنی موجودہ زندگی میں اچھے عمل کر لو اور انجام کار محفوظ رہو گے کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمانبردار سے جنت اور نافرمان سے جہنم کا وعدہ فرما رکھا ہے۔ جہنم کی آگ میں جہنمیوں کا چیخنا کبھی ختم نہ ہوگا۔ اس کے قیدی کو کبھی چھڑایا نہیں جا سکے گا اور اس میں جس کی ہڈی ٹوٹے گی اس کی کبھی جڑ نہ سکے گی۔ اس کی گرمی بہت سخت ہے، وہ بہت گہری ہے اور اس کا پانی خون اور پیپ ہے۔ اور مجھے تم پر سب سے زیادہ خطرہ دو باتوں کا ہے: ایک خواہشات کے پیچھے چلنے کا، دوسرے امیدیں لمبی رکھنے کا۔ اور ایک روایت میں یہ بھی ہے کہ خواہشات کے پیچھے چلنے سے انسان حق سے ہٹ جاتا ہے اور لمبی امیدوں کی وجہ سے آخرت بھول جاتا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Dinawari and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.220) and Muntakhab Kanzul Ummaal (Vol.6 Pg.324). Ibn Katheer in Al Bidaayah wan Nihaayah (Vol.8 Pg.7) has mentioned this sermon in full from Wakee' from Amr bin Munabbih from Awfa bin Wakee."]]},{"b":[["n",[["حضرت زیاد اعرابیؒ","b"],[" کہتے ہیں (خوارج کے) فتنہ کے بعد اور نہروان شہر سے فارغ ہونے کے بعد امیر المومنین حضرت علی بن ابی طالبؓ کوفہ کے منبر پر تشریف فرما ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر آنسوؤں کا ان کے گلے میں پھندا لگ گیا اور اتنا روئے کہ آنسوؤں سے داڑھی تر ہو گئی اور آنسو نیچے گرنے لگے۔ پھر انہوں نے اپنی داڑھی (جھاڑی تو اس کے قطرے کچھ لوگوں پر جا گرے، تو ہم یہ کہا کرتے تھے کہ حضرت علیؓ کے آنسو جس پر گرے ہیں اسے ",""],["ٱللَّٰه","a"],[" تعالیٰ جہنم پر حرام کر دیں گے)۔ پھر حضرت علیؓ نے فرمایا اے لوگو! ان میں سے نہ بنو جو بغیر کچھ کیے آخرت کی امید رکھتے ہیں اور لمبی امیدوں کی وجہ سے توبہ کو ٹالتے رہتے ہیں۔ دنیا کے بارے میں باتیں تو زاہدوں جیسی کرتے ہیں لیکن دنیا کے کام ان لوگوں کی طرح کرتے ہیں جن میں دنیا کی رغبت اور شوق ہو۔ اگر انہیں دنیا ملے تو وہ سیر نہیں ہوتے اور اگر نہ ملے تو ان میں قناعت بالکل نہیں ہے۔ جو نعمتیں انہیں ",""],["ٱللَّٰه","a"],[" دے رہا ہے ان کا شکر نہیں کر سکتے اور پھر چاہتے ہیں کہ نعمتیں اور بڑھ جائیں۔ دوسروں کو نیک کاموں کا حکم کرتے ہیں لیکن خود نہیں کرتے اور برے کاموں سے روکتے ہیں لیکن خود نہیں رکتے۔ محبت تو نیک لوگوں سے کرتے ہیں لیکن ان کے والے عمل نہیں کرتے اور ظالموں سے بغض رکھتے ہیں لیکن خود ظالم ہیں۔ اور (دنیا کے) جن کاموں پر کچھ ملنے کا صرف گمان ہی ہے ان کا نفس ان سے وہ کام تو کروا لیتا ہے اور (آخرت کے) جن کاموں پر ملنا یقینی ہے وہ کام ان سے نہیں کروا سکتا۔ اگر انہیں مال مل جائے تو فتنہ میں پڑ جاتے ہیں، اگر بیمار ہو جائیں تو غمگین ہو جاتے ہیں، اگر فقیر ہو جائیں تو نا امید ہو کر کمزور پڑ جاتے ہیں۔ وہ گناہ بھی کرتے ہیں اور نعمتیں بھی استعمال کرتے ہیں، عافیت ملتی ہے تو شکر نہیں کرتے اور جب کوئی آزمائش آتی ہے تو صبر نہیں کرتے۔ ایسے نظر آتا ہے جیسے دوسروں کو موت سے ڈرایا گیا ہے انہیں نہیں اور آخرت کے سارے وعدے اور وعید دوسروں کے لیے ہیں۔ اے موت کا نشانہ بننے والو! اور موت کے پاس گروی رکھے جانے والو! اے بیماریوں کے برتنو! اے زمانے کے لوٹے ہوئے لوگو! اے زمانہ پر بوجھ نہ بننے والو! اے زمانہ کے پہلو! اے حادثات کی کلیو! اے دلائل کے سامنے گونگے بن جانے والو! اے فتنہ میں ڈوبے ہوئے لوگو! اے وہ لوگو جن کے اور عبرت کی چیزوں کے درمیان رکاوٹیں ہیں! میں حق بات کہہ رہا ہوں، آدمی صرف اپنے آپ کو پہچان کر ہی نجات پا سکتا ہے اور آدمی اپنے ہاتھوں ہی ہلاک ہوتا ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا","a"]]],["p",[["ترجمہ: \"اے ایمان والو! تم اپنے کو اور اپنے گھر والوں کو (دوزخ کی) اس آگ سے بچاؤ\" (سورۂ تحریم، آیت 6)۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیں اور آپ کو ان لوگوں میں سے بنائے جو وعظ و نصیحت سن کر قبول کر لیتے ہیں اور جب ان کو عمل کی دعوت دی جاتی ہے تو وہ اسے قبول کر کے عمل کر لیتے ہیں۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.220) and Muntakhab Kanzul Ummaal (Vol.6 Pg.325)."]]},{"b":[["n",[["حضرت یحییٰ بن یعمرؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت علی بن ابی طالبؓ نے لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! تم سے پہلے لوگ صرف گناہوں کے ارتکاب کی وجہ سے ہی ہلاک ہوئے، ان کے علماء اور فقہاء نے انہیں روکا نہیں تو ",""],["ٱللَّٰه","a"],[" نے ان پر سزائیں نازل کیں۔ غور سے سنو! نیکی کا حکم کرو اور برائی سے روکو اس سے پہلے کہ تم پر بھی وہ عذاب اترے جو ان پر اترا تھا۔ اور یہ سمجھ لو کہ نیکی کا حکم کرنے اور برائی سے روکنے سے نہ رزق کم ہوتا ہے اور نہ موت جلدی آتی ہے۔ آسمان سے تقدیر کے فیصلے بارشوں کے قطروں کی طرح اترتے ہیں، چنانچہ ہر انسان کے اہل و عیال، مال و جان میں کم ہو جانے یا بڑھ جانے کا فیصلہ ",""],["ٱللَّٰه","a"],[" نے مقدر میں لکھا ہوا ہے، وہ آسمان سے اترتا ہے۔ اب جب تمہارے اہل و عیال، مال و جان میں کسی قسم کا نقصان ہو اور تمہیں دوسروں کے اہل و عیال، مال و جان میں نقصان کے بجائے اضافہ نظر آئے تو اس سے تم فتنہ میں نہ پڑ جانا۔ مسلمان آدمی دناءت و کمینگی کا ارتکاب کرنے والا نہ ہو تو اسے جب بھی یہ نقصان یاد آئے گا وہ عاجزی، انکساری، دعا اور التجاء کا مظاہرہ کرے گا (اور یوں اسے باطنی نفع ہوگا) اور کمینے لوگوں کو اس پر بہت غصہ آئے گا۔ جیسے کہ کامیاب ہونے والا جواری، تیروں سے جوا کھیلنے میں پہلی دفعہ ہی ایسی کامیابی کا انتظار کرتا ہے جس سے خوب مال ملے اور تاوان وغیرہ اسے نہ دینا پڑے، ایسے ہی خیانت سے پاک مسلمان آدمی جب ",""],["ٱللَّٰه","a"],[" سے دعا کرتا ہے تو دو بھلائیوں میں سے ایک کی اسے امید ہوتی ہے (کہ یا تو جو مانگا ہے وہ دنیا میں مل جائے گا اور اگر وہ نہ ملا تو پھر اس دعا کی دنیا میں قبول نہ ہونے کے بدلے میں آخرت میں اسے ثواب ملے گا)۔ جو ",""],["ٱللَّٰه","a"],[" کے پاس ہے وہ اس کے لیے بہتر ہے یا پھر ",""],["ٱللَّٰه","a"],[" اسے مال دیں گے اور اس کے اہل و عیال میں خوب کثرت ہوگی اور وہ خوب مالدار ہوگا۔ کھیتی دو طرح کی ہے (ایک دنیا کی دوسری آخرت کی): دنیا کی کھیتی مال اور بیٹے ہیں اور آخرت کی کھیتی نیک اعمال ہیں اور کبھی ",""],["ٱللَّٰه","a"],[" تعالیٰ بعض لوگوں کو دونوں قسم کی کھیتیاں عطا فرماتے ہیں۔ حضرت سفیان بن عیینہؒ کہتے ہیں حضرت علی ابن ابی طالبؓ کے علاوہ اور کون ایسا ہے جو یہ بات اتنے اچھے طریقہ سے کہہ سکے۔ البدایہ کی روایت اسی جیسی ہے اور اس کے آخر میں یہ ہے کہ یا تو ",""],["ٱللَّٰه","a"],[" اس کی دعا دنیا میں پوری کر دیں گے اور وہ بہت زیادہ مال اور اولاد والا ہو جائے گا، خاندانی شرافت اور دین کی نعمت بھی اسے حاصل ہوگی، یا پھر اسے اس دعا کا بدلہ آخرت میں دیں گے، اور آخرت (دنیا سے ہزار درجہ) بہتر اور ہمیشہ رہنے والی ہے۔ کھیتیاں دو ہیں: دنیا کی کھیتی مال اور تقویٰ ہے (بظاہر مال اور اولاد ہے) اور آخرت کی کھیتی باقی رہنے والے اعمال صالحہ ہیں۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Ibn Abi Dunya and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.220) and Muntakhab Kanzul Ummaal (Vol.6 Pg.326)."],["(12)","Ibn Katheer has mentioned it in Al Bidaayah wan Nihaayah (Vol.8 Pg.8) from Ibn Abi Dunya with a chain from Yahya, in which he mentions from his words 'the matter descends from the sky' to the end."]]},{"b":[["n",[["حضرت ابووائلؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت علیؓ نے کوفہ میں لوگوں میں بیان فرمایا، میں نے انہیں اس بیان میں یہ کہتے ہوئے سنا اے لوگو! جو جان بوجھ کر محتاج بنتا ہے وہ محتاج ہو ہی جاتا ہے اور جس کی عمر بہت زیادہ ہو جاتی ہے وہ مختلف بیماریوں اور کمزوریوں میں مبتلا ہو جاتا ہے۔ جو بلا اور آزمائش کے لیے تیاری نہیں کرتا جب اس پر آزمائش آتی ہے تو وہ صبر نہیں کر سکتا۔ جو کسی چیز پر قابو پا لیتا ہے وہ اپنے کو دوسروں پر ترجیح دیتا ہے۔ جو کسی سے مشورہ نہیں کرتا اسے ندامت اٹھانی پڑتی ہے۔ اور اس گفتگو کے بعد یہ فرمایا تھا عنقریب ایسا زمانہ آئے گا کہ اسلام کا صرف نام اور قرآن کا صرف ظاہری نشان باقی رہ جائے گا۔ اور یہ بھی فرمایا تھا غور سے سنو! آدمی کو سیکھنے میں حیا نہیں کرنی چاہیے اور جس آدمی سے ایسی بات پوچھی جائے جسے وہ نہیں جانتا تو اسے یہ کہنے میں حیا نہیں کرنی چاہیے کہ میں نہیں جانتا۔ تمہاری مسجدیں ویسے تو اس دن آباد ہوں گی لیکن تمہارے دل اور جسم اجڑے ہوئے اور ہدایت سے خالی ہوں گے۔ آسمان کے سایہ تلے رہنے والے تمام انسانوں میں سب سے برے تمہارے فقہاء ہوں گے، ان میں سے ہی فتنہ ظاہر ہوگا اور انہی میں لوٹ کر واپس آئے گا۔ اس پر ایک آدمی نے کھڑے ہو کر کہا اے امیر المومنین! ایسا کب ہوگا؟ حضرت علیؓ نے فرمایا جب علم تمہارے گھٹیا لوگوں میں ہوگا اور تمہارے سرداروں میں زنا اور بے حیائی عام ہوگی اور بادشاہت تمہارے چھوٹے لوگوں میں ہوگی (جنہیں نہ تجربہ ہوگا نہ سمجھ ہوگی) اس وقت قیامت قائم ہوگی۔",""],[" (13)","s"]]]],"f":[["(13)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.218)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" ایک دن لوگوں میں بیان کے لیے کھڑے ہوئے اور ارشاد فرمایا تمام تعریفیں ",""],["ٱللَّٰه","a"],[" ہی کے لیے ہیں جو مخلوق کو پیدا کرنے والا، (رات میں سے) پھاڑ کر صبح کو نکالنے والا، مردوں کو زندہ کرنے والا اور قبروں میں جو مدفون ہیں انہیں قیامت کے دن اٹھانے والا ہے۔ اور میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور اس بات کی گواہی دیتا ہوں کہ حضرت محمدؐ اس کے بندے اور رسول ہیں اور میں تمہیں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں۔ بندہ جن اعمال کو ",""],["ٱللَّٰه","a"],[" کے قرب کے لیے وسیلہ بنا سکتا ہے ان میں سب سے افضل ایمان اور جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" ہے اور کلمۂ اخلاص ہے، اس لیے کہ وہ عین انسانی فطرت کے مطابق ہے؛ اور نماز قائم کرنا ہے کیونکہ وہی اصل مذہب ہے؛ اور زکوٰۃ دینا ہے کیونکہ وہ ",""],["ٱللَّٰه","a"],[" کے دینی فرائض میں سے ہے؛ اور رمضان کے روزے رکھنا ہے کیونکہ یہ ",""],["ٱللَّٰه","a"],[" کے عذاب سے ڈھال ہے؛ اور بیت ",""],["ٱللَّٰه","a"],[" کا حج ہے کیونکہ یہ فقر کے دور کرنے اور گناہوں کے ہٹانے کا سبب ہے؛ اور صلہ رحمی کرنا ہے کیونکہ اس سے مال بڑھتا ہے اور عمر لمبی ہوتی ہے اور گھر والوں کی محبت (دوسروں کے دلوں میں) بڑھتی ہے؛ اور چھپ کر صدقہ کرنا ہے کیونکہ اس سے خطائیں مٹ جاتی ہیں اور رب کا غصہ ٹھنڈا پڑ جاتا ہے؛ اور لوگوں کے ساتھ نیکی اور بھلائی کرنا ہے کیونکہ یہ بری موت اور ہولناک جگہوں سے بچاتا ہے۔ اور ",""],["ٱللَّٰه","a"],[" کا ذکر خوب کرو کیونکہ ",""],["ٱللَّٰه","a"],[" کا ذکر سب سے اچھا ذکر ہے۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے متقی لوگوں سے جن چیزوں کا وعدہ فرمایا ہے ان چیزوں کا اپنے اندر شوق پیدا کرو کیونکہ ",""],["ٱللَّٰه","a"],[" کا وعدہ سب سے سچا وعدہ ہے۔ اور اپنے نبی کریمؐ کی سیرت کی اقتداء کرو کیونکہ ان کی سیرت سب سے افضل سیرت ہے اور ان کی سنتوں پر چلو کیونکہ ان کی سنتیں سب سے افضل طریقہ زندگی ہیں۔ اور ",""],["ٱللَّٰه","a"],[" کی کتاب سیکھو کیونکہ وہ سب سے افضل کلام ہے اور دین کی سمجھ حاصل کرو کیونکہ یہی دلوں کی بہار ہے اور ",""],["ٱللَّٰه","a"],[" کے نور سے شفا حاصل کرو کیونکہ یہ دلوں کی تمام بیماریوں کی شفاء ہے۔ اس کی تلاوت اچھی طرح کیا کرو کیونکہ (اس کے اندر) سب سے عمدہ قصے ہیں۔ جب اسے تمہارے سامنے پڑھا جائے تو اسے کان لگا کر سنو اور خاموش رہو تاکہ تم پر ",""],["ٱللَّٰه","a"],[" کی رحمت ہو۔ اور جب تمہیں اس کے علم کے حاصل کرنے کی توفیق مل گئی ہے تو اس پر عمل کرو تاکہ تمہیں ہدایت کامل درجہ کی مل جائے کیونکہ جو عالم اپنے علم کے خلاف عمل کرتا ہے وہ راہ حق سے ہٹے ہوئے اس جاہل جیسا ہے جو اپنی جہالت کی وجہ سے درست نہیں ہو سکا، بلکہ میرا خیال تو یہ ہے کہ جو عالم اپنے علم کو چھوڑ بیٹھا ہے اس کے خلاف حجت زیادہ بڑی ہوگی اور اس پر حسرت زیادہ عرصہ تک رہے گی، اور اس کے مقابلہ میں جہالت میں حیران و پریشان رہنے والے جاہل کے خلاف حجت چھوٹی اور اس پر حسرت کم ہوگی۔ ویسے تو دونوں گمراہ ہیں اور دونوں ہلاک ہوں گے۔ اور تردد میں نہ پڑو ورنہ تم شک میں پڑ جاؤ گے اور اگر تم شک میں پڑ گئے تو ایک دن کافر بن جاؤ گے۔ اور اپنے لیے آسانی اور رخصت والا راستہ اختیار نہ کرو ورنہ تم غفلت میں پڑ جاؤ گے اور اگر تم حق سے غفلت برتنے لگ گئے تو پھر خسارہ والے ہو جاؤ گے۔ غور سے سنو! یہ سمجھداری کی بات ہے کہ تم بھروسہ کرو لیکن اتنا بھروسہ نہ کرو کہ دھوکہ کھا لو۔ اور تم میں سے اپنے آپ کا سب سے زیادہ خیر خواہ وہ ہے جو اپنے رب کی سب سے زیادہ اطاعت کرنے والا ہے اور تم میں سے اپنے آپ کو سب سے زیادہ دھوکہ دینے والا وہ ہے جو اپنے رب کی سب سے زیادہ نافرمانی کرنے والا ہے۔ جو ",""],["ٱللَّٰه","a"],[" کی اطاعت کرے گا وہ امن میں رہے گا اور خوش رہے گا اور جو ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے گا وہ ڈرتا رہے گا اور اسے ندامت اٹھانی پڑے گی۔ پھر تم ",""],["ٱللَّٰه","a"],[" سے یقین مانگو اور اس کے سامنے عافیت کا شوق ظاہر کرو۔ دل کی سب سے بہتر دائمی کیفیت یقین ہے۔ فرائض سب سے افضل عمل ہیں اور جو نئے کام اپنے پاس سے گھڑے جاتے ہیں وہ سب سے برے ہیں۔ ہر نئی بات بدعت ہے اور ہر نئی بات گھڑنے والا بدعتی ہے، جس نے کوئی نئی بات گھڑی اس نے (دین) ضائع کر دیا۔ جب کوئی بدعتی نئی بدعت نکالتا ہے تو وہ اس کی وجہ سے کوئی نہ کوئی سنت ضرور چھوڑتا ہے۔ اصل نقصان والا وہ ہے جس کا دینی نقصان ہوا اور نقصان والا وہ ہے جو اپنے آپ کو خسارے میں ڈال دے۔ ریاکاری شرک میں سے ہے اور اخلاص عمل و ایمان کا حصہ ہے۔ کھیل کود کی مجلسیں قرآن بھلا دیتی ہیں اور ان میں شیطان شریک ہوتا ہے اور یہ مجلسیں ہر گمراہی کی دعوت دیتی ہیں۔ اور عورتوں کے ساتھ زیادہ بیٹھنے سے دل ٹیڑھے ہو جاتے ہیں اور ایسے آدمی کی طرف سب کی نگاہیں اٹھتی ہیں۔ عورتیں شیطان کے جال ہیں۔ ",""],["ٱللَّٰه","a"],[" کے ساتھ سچائی کا معاملہ کرو کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ سچے کے ساتھ ہے اور جھوٹ سے اجتناب کرو کیونکہ جھوٹ ایمان کا مخالف عمل ہے۔ غور سے سنو! سچ نجات اور عزت کی بلند جگہ پر ہے اور جھوٹ ہلاکت اور بربادی کی بلند جگہ پر ہے۔ غور سے سنو! حق بات کہو اس سے تم پہچانے جاؤ گے اور حق پر عمل کرو اس سے تم حق والوں میں سے ہو جاؤ گے۔ جس نے تمہارے پاس امانت رکھوائی ہے اسے اس کی امانت واپس کرو۔ جو رشتہ دار تم سے قطع رحمی کرے تم اس کے ساتھ صلہ رحمی کرو اور جو تمہیں نہ دے بلکہ محروم کرے تم اس کے ساتھ احسان کرو۔ جب تم کسی سے معاہدہ کرو تو اسے پورا کرو۔ جب فیصلہ کرو تو عدل و انصاف والا کرو۔ آباؤ اجداد کے کارناموں پر ایک دوسرے پر فخر نہ کرو اور ایک دوسرے کو برے لقب سے نہ پکارو۔ آپس میں حد سے زیادہ مذاق نہ کرو اور ایک دوسرے کو غصہ نہ دلاؤ۔ اور کمزور، مظلوم، مقروض، مجاہد فی سبیل ",""],["ٱللَّٰه","a"],["، مسافر اور سائل کی مدد کرو اور غلاموں کو آزادی دلوانے میں مدد کرو اور بیوہ اور یتیم پر رحم کرو اور سلام پھیلاؤ اور جو تمہیں سلام کرے تم اسے ویسا ہی جواب دو یا اس سے اچھا جواب دو۔ نیکی اور تقویٰ کے کاموں میں ایک دوسرے کی مدد کرو اور گناہ اور زیادتی کے کاموں میں ایک دوسرے کی مدد نہ کرو اور ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ ",""],["ٱللَّٰه","a"],[" سخت سزا دینے والا ہے۔ اور مہمان کا اکرام کرو اور پڑوسی سے اچھا سلوک کرو۔ بیماروں کی عیادت کرو اور جنازے کے ساتھ جاؤ، ",""],["ٱللَّٰه","a"],[" کے بندو! بھائی بھائی بن کر رہو۔ اما بعد! دنیا منہ پھیر کر جا رہی ہے اور اپنے رخصت ہونے کا اعلان کر رہی ہے اور آخرت سایہ ڈال چکی ہے اور جھانک رہی ہے۔ آج گھوڑے دوڑانے کے لیے تیار کرنے کا دن ہے، کل قیامت کو ایک دوسرے سے آگے بڑھنا ہوگا اور آگے بڑھ کر جنت میں جانا ہوگا، اگر آگے بڑھ کر جنت میں نہ جا سکا تو پھر اس کا انجام جہنم کی آگ ہے۔ توجہ سے سنو! تمہیں ان دنوں عمل کرنے کی مہلت ملی ہوئی ہے۔ اس کے بعد موت ہے جو بہت تیزی سے آ رہی ہے۔ جو مہلت کے دنوں میں موت کے آنے سے پہلے اپنے ہر عمل کو ",""],["ٱللَّٰه","a"],[" کے لیے خالص کرے گا وہ اپنے عمل کو اچھا اور خوبصورت بنا لے گا اور اپنی امید کو پائے گا، اور جس نے اس میں کوتاہی کی اس کے عمل خسارے والے ہو جائیں گے، اس کی امید پوری نہ ہوگی بلکہ امید کی وجہ سے اس کا نقصان ہوگا۔ لہٰذا ",""],["ٱللَّٰه","a"],[" کے ثواب کے شوق میں اور اس کے عذاب سے ڈر کر عمل کرو۔ اگر کبھی نیک اعمال کی رغبت اور شوق کا تم پر غلبہ ہو تو ",""],["ٱللَّٰه","a"],[" کا شکر کرو اور اس شوق کے ساتھ خوف پیدا کرنے کی کوشش کرو، اور اگر کبھی ",""],["ٱللَّٰه","a"],[" کے خوف کا غلبہ ہو تو ",""],["ٱللَّٰه","a"],[" کا ذکر کرو اور اس خوف کے ساتھ کچھ شوق ملانے کی کوشش کرو، کیونکہ ",""],["ٱللَّٰه","a"],[" نے مسلمانوں کو بتایا ہے کہ اچھے عمل پر اچھا بدلہ ملے گا اور جو شکر کرے گا ",""],["ٱللَّٰه","a"],[" اس کی نعمت بڑھائے گا۔ میں نے جنت جیسی کوئی چیز نہیں دیکھی کہ جس کا طالب سو رہا ہو اور میں نے اس سے زیادہ کمانے والا نہیں دیکھا جو اس دن کے لیے نیک اعمال کماتا ہے جس دن کے لیے اعمال کے ذخیرے جمع کیے جاتے ہیں اور جس دن دلوں کے تمام بھید کھل جائیں گے اور تمام بری چیزیں اس دن جمع ہو جائیں گی۔ جسے حق سے کوئی فائدہ نہ ہوا اسے باطل نقصان پہنچائے گا، جسے ہدایت سیدھے راستہ پر نہ چلا سکی اسے گمراہی سیدھے راستہ سے ہٹا دے گی، جسے یقین سے کوئی فائدہ نہ ہوا اسے شک نقصان پہنچائے گا اور جسے اس کی موجودہ چیز نفع نہ پہنچا سکی اسے اس کی دور والی غیر حاضر چیز بالکل نفع نہیں پہنچا سکے گی، یعنی جو براہ راست مجھ سے بیان سن کر فائدہ نہ اٹھا سکے وہ میرے نہ سنے ہوئے بیانات سے تو بالکل فائدہ نہیں اٹھا سکے گا۔ تمہیں کوچ کر کے سفر میں جانے کا حکم دیا جا چکا ہے اور سفر میں کام آنے والا توشہ بھی تمہیں بتایا جا چکا ہے۔ سنو! مجھے آپ لوگوں پر سب سے زیادہ دو چیزوں کا ڈر ہے: ایک لمبی امیدیں، دوسرے خواہشات پر چلنا۔ لمبی امیدوں کی وجہ سے انسان آخرت بھول جاتا ہے اور خواہشات پر چلنے کی وجہ سے حق سے دور ہو جاتا ہے۔ توجہ سے سنو! دنیا پیٹھ پھیر کر جا رہی ہے اور آخرت سامنے سے آ رہی ہے اور دونوں کے طالب اور چاہنے والے ہیں، اگر تم سے ہو سکے تو آخرت والوں میں سے بنو اور دنیا والوں میں سے نہ بنو کیونکہ آج عمل کرنے کا موقع ہے لیکن حساب نہیں ہے۔ کل حساب ہوگا لیکن عمل کا موقع نہیں ہوگا۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Katheer has mentioned it in Al Bidaayah wan Nihaayah (Vol.7 Pg.30) and said: This sermon is eloquent and beneficial, forbidding evil, and it has witnesses and other connected chains. All praise and grace belong to Allah."]]},{"b":[["n",[["حضرت ابوخیرہؒ","b"],[" کہتے ہیں میں حضرت علیؓ کے ساتھ رہا یہاں تک کہ وہ کوفہ پہنچ گئے اور منبر پر تشریف فرما ہوئے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اس وقت کیا کرو گے جب تمہارے نبیؐ کی آل پر تمہارے سامنے فوج حملہ آور ہوگی؟ کوفہ والوں نے کہا ہم ",""],["ٱللَّٰه","a"],[" کو ان کے بارے میں زبردست بہادری دکھائیں گے۔ حضرت علیؓ نے فرمایا اس ذات کی قسم جس کے قبضہ میں میری جان ہے! تمہارے سامنے ان پر فوج حملہ آور ہوگی اور تم مقابلہ پر آ کر ان کو خود قتل کرو گے۔ پھر یہ شعر پڑھنے لگے",""]]],["q",[["هُمْ أَوْرَدُوهُ بِالْغُرُورِ وَغَرَّرُوا","a"]]],["q",[["أَجِيبُوا دَعَاهُ لَا نَجَاةَ وَلَا عُذْرَا","a"]]],["p",[["ترجمہ: \"وہ اسے دھوکے سے لے آئیں گے اور پھر اونچی آواز سے یہ گائیں گے کہ اس (کے مخالف یعنی یزید) کی دعوت (بیعت) قبول کروا لو، اس کے قبول کیے بغیر تمہیں نجات نہیں ملے گی اور اس میں تمہارا کوئی عذر قبول نہیں کیا جائے گا۔\"",""],[" (15)","s"]]]],"f":[["(15)","Tabraani; Haythami (Vol.9 Pg.191) has said that in its chain is Sa'eed bin Wahb who is of a later period and whom I do not know, while the rest of its narrators are reliable."]]},{"b":[["n",[["حضرت ابراہیم تیمیؒ","b"],[" کے والد (حضرت یزید بن شریکؒ) کہتے ہیں ہم میں حضرت علیؓ نے بیان فرمایا جس میں ارشاد فرمایا ہمارے پاس ",""],["ٱللَّٰه","a"],[" کی کتاب اور اس صحیفے کے علاوہ کچھ اور لکھا ہوا ہے جسے ہم پڑھتے رہتے ہیں تو وہ بالکل غلط کہتا ہے۔ اور اس صحیفے میں زکوٰۃ اور دیت اور اونٹوں کی عمر اور زخموں کے مختلف احکام کے بارے میں لکھا ہوا ہے اور اس صحیفے میں یہ بھی ہے کہ حضورؐ نے ارشاد فرمایا مدینہ کا حرم عیر پہاڑ سے ثور پہاڑ تک ہے۔ یہ سارا علاقہ قابل احترام ہے، لہٰذا جو اس علاقہ میں خود کوئی نئی چیز ایجاد کرے یا نئی چیز ایجاد کرنے والے کو ٹھکانہ دے تو اس پر ",""],["ٱللَّٰه","a"],["، فرشتوں اور تمام لوگوں کی لعنت ہوگی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن اس کے کسی فرض اور نفل عمل کو قبول نہیں فرمائیں گے۔ اور جو اپنے باپ کے علاوہ کسی اور کی طرف اپنے نسب کی نسبت کرے گا اور جو غلام اپنے آقا کے علاوہ کسی اور کے غلام ہونے کا دعویٰ کرے گا تو ان دونوں پر ",""],["ٱللَّٰه","a"],["، فرشتوں اور تمام لوگوں کی لعنت ہوگی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن ان کے کسی فرض اور نفل عمل کو قبول نہیں فرمائیں گے۔ تمام مسلمانوں کی ذمہ داری ایک ہے جس کے لیے کم درجے کا مسلمان بھی سعی کرے گا (یعنی ادنیٰ درجہ کا مسلمان بھی کسی کافر یا دشمن کے آدمی کو امان دے دے تو اسے تمام مسلمانوں کی طرف سے امان مل جائے گی)۔",""],[" (16)","s"]]]],"f":[["(16)","Ahmad in his Musnad (Vol.1 Pg.81) from Ibraaheem Taymi from his father."]]},{"b":[["n",[["حضرت ابراہیم نخعیؒ","b"],[" کہتے ہیں حضرت علقمہ بن قیسؒ نے اس منبر پر ہاتھ مار کر کہا حضرت علیؓ نے اس منبر پر ہم میں بیان کیا۔ پہلے انہوں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور کچھ دیر ",""],["ٱللَّٰه","a"],[" کی ذات و صفات کا تذکرہ کیا، پھر فرمایا حضورؐ کے بعد تمام لوگوں میں سب سے بہتر حضرت ابوبکرؓ ہیں، پھر حضرت عمرؓ ہیں، پھر ہم نے ان کے بعد بہت سے نئے کام کیے ہیں جن کا ",""],["ٱللَّٰه","a"],[" ہی فیصلہ کرے گا۔",""],[" (17)","s"]]]],"f":[["(17)","Ahmad (Vol.1 Pg.127)."]]},{"b":[["n",[["حضرت ابوجحیفہؓ","b"],[" فرماتے ہیں حضرت علیؓ منبر پر تشریف فرما ہوئے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر نبی کریمؐ پر درود بھیجا، پھر فرمایا حضورؐ کے بعد اس امت میں سب سے بہترین آدمی حضرت ابوبکرؓ ہیں، پھر دوسرے نمبر پر حضرت عمرؓ ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ جہاں چاہتے ہیں خیر رکھ دیتے ہیں۔ مسند احمد میں حضرت وہب سوائیؓ سے اسی کے ہم معنی روایت مذکور ہے، البتہ اس میں یہ مضمون نہیں ہے کہ پھر ہم نے بہت سے نئے کام کیے اور اس میں حضرت علیؓ کا یہ فرمان ہے کہ ہم اس بات کو بعید نہیں سمجھتے تھے کہ حضرت عمرؓ کی زبان پر فرشتہ بولتا ہے۔",""],[" (18)","s"]]]],"f":[["(18)","Ahmad also (Vol.1 Pg.106)."]]},{"b":[["n",[["حضرت علقمہؒ","b"],[" کہتے ہیں حضرت علیؓ نے ہم لوگوں میں بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا مجھے یہ خبر پہنچی ہے کہ کچھ لوگ مجھے حضرت ابوبکر و حضرت عمرؓ پر فضیلت دیتے ہیں۔ اگر میں اس کام سے لوگوں کو منع کر چکا ہوتا تو آج میں اس پر ضرور سزا دیتا اور روکنے سے پہلے سزا دینا مجھے پسند نہیں۔ بہرحال اب سب سن لیں کہ آئندہ میرے اس بیان کے بعد جو بھی اس بارے میں ذرا سی بھی بات کرے گا وہ میرے نزدیک بہتان باندھنے والا ہوگا اسے وہی سزا ملے گی جو بہتان باندھنے والے کی ہوتی ہے۔ حضورؐ کے بعد لوگوں میں سب سے بہترین حضرت ابوبکرؓ ہیں، پھر حضرت عمرؓ ہیں، پھر ہم نے ان حضرات کے بعد بہت سے نئے کام کیے ہیں، ",""],["ٱللَّٰه","a"],[" تعالیٰ ان کے بارے میں جو چاہیں گے فیصلے فرمائیں گے۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Abi Aasim, Ibn Shaaheen, Laalka'i in As Sunnah, Isbahaani in Al Hujjah and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.116)."]]},{"b":[["n",[["حضرت زید بن وہبؒ","b"],[" کہتے ہیں حضرت سوید بن غفلہؒ حضرت علیؓ کے زمانہ خلافت میں ان کی خدمت میں حاضر ہوئے اور عرض کیا اے امیر المومنین! میں چند لوگوں کے پاس سے گزرا جو حضرت ابوبکرؓ اور حضرت عمرؓ کی شان میں نامناسب کلمات کہہ رہے تھے۔ یہ سن کر حضرت علیؓ اٹھے اور منبر پر تشریف فرما ہوئے اور فرمایا اس ذات کی قسم جس نے دانہ کو (زمین میں جانے کے بعد) پھاڑا اور جان کو پیدا کیا! ان دونوں حضرات سے وہی محبت کرے گا جو مومن اور صاحب فضل و کمال ہوگا اور ان سے بغض صرف بدبخت اور بے دین ہی رکھے گا۔ حضرات شیخینؓ کی محبت ",""],["ٱللَّٰه","a"],[" کا قرب حاصل ہونے کا ذریعہ ہے اور ان حضرات سے بغض و نفرت بے دینی ہے۔ لوگوں کو کیا ہوا کہ وہ حضورؐ کے دو بھائیوں، دو وزیروں، دو خاص ساتھیوں، قریش کے دو سرداروں اور مسلمانوں کے دو روحانی باپوں کا نامناسب کلمات سے ذکر کرتے ہیں۔ جو بھی ان حضرات کا ذکر برائی سے کرے گا میں اس سے بری ہوں اور میں اسے اس وجہ سے سزا دوں گا۔ حضرت علیؓ کا یہ بیان اکابر کی وجہ سے ناراض ہونے کے باب میں پوری تفصیل سے گزر چکا ہے۔",""],[" (20)","s"]]]],"f":[["(20)","Abu Nu'aym in his Hilyah, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.443)."]]},{"b":[["n",[["حضرت علی بن حسینؒ","b"],[" کہتے ہیں جب حضرت علی بن ابی طالبؓ جنگ صفین سے واپس آئے تو ان سے بنو ہاشم کے ایک نوجوان نے کہا اے امیر المومنین! میں نے آپ کو جمعہ کے خطبہ میں یہ کہتے ہوئے سنا اے ",""],["ٱللَّٰه","a"],["! تو نے جس عمل کے ذریعہ سے خلفاء راشدین کی اصلاح فرمائی اسی کے ذریعہ سے ہماری بھی اصلاح فرما، تو یہ خلفاء راشدین کون ہیں؟ اس پر حضرت علیؓ کی دونوں آنکھیں ڈبڈبا آئیں اور فرمایا خلفاء راشدین حضرت ابوبکر اور حضرت عمرؓ ہیں جو کہ ہدایت کے امام اور اسلام کے بڑے زبردست عالم ہیں جن سے حضورؐ کے بعد ہدایت حاصل کی جاتی ہے۔ جو ان دونوں کی اتباع کرے گا اسے صراط مستقیم کی ہدایت ملے گی اور جو ان دونوں کی اقتداء کرے گا وہ رشد والا ہو جائے گا۔ جو ان دونوں کو مضبوطی سے پکڑے گا وہ ",""],["ٱللَّٰه","a"],[" کی جماعت میں شامل ہو جائے گا اور ",""],["ٱللَّٰه","a"],[" کی جماعت والے ہی فلاح پانے والے ہیں۔",""],[" (21)","s"]]]],"f":[["(21)","Laalka'i, Abu Taalib Ushaari and Nasr in Al Hujjah, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.444)."]]},{"b":[["n",[["بنو تمیم کے ایک بڑے میاں کہتے ہیں حضرت علیؓ نے ایک مرتبہ ہم میں بیان فرمایا جس میں ارشاد فرمایا لوگوں پر ایسا زمانہ آئے گا جس میں لوگ ایک دوسرے کو کاٹ کھائیں گے اور مالدار اپنے مال کو روک کر رکھے گا، بالکل خرچ نہیں کرے گا حالانکہ اسے اس کا حکم نہیں دیا گیا تھا (بلکہ اسے تو ضرورت سے زائد سارا مال دوسروں پر خرچ کرنے کا حکم دیا گیا تھا)، ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["وَلَا تَنسَوُا ٱلْفَضْلَ بَيْنَكُمْ","a"]]],["p",[["ترجمہ: \"اور آپس میں احسان کرنے سے غفلت مت کرو\" (سورۂ بقرہ، آیت 237)۔ برے لوگ زور پر ہوں گے، غالب آ جائیں گے۔ نیک لوگ بالکل دب جائیں گے اور مجبور لوگوں سے خرید و فروخت کی جائے گی (یا تو انہیں خرید و فروخت پر کسی طرح مجبور کیا جائے گا یا وہ قرضے وغیرہ کی وجہ سے مجبور ہو کر اپنا سامان وغیرہ سستے داموں بیچیں گے)، حالانکہ حضورؐ نے مجبور انسان سے اس طرح خریدنے سے اور دھوکہ کی خرید و فروخت سے اور پکنے سے پہلے پھل بیچ دینے سے منع فرمایا ہے۔",""],[" (22)","s"]]]],"f":[["(22)","Ahmad (Vol.1 Pg.116)."]]},{"b":[["n",[["حضرت ابوعبیدؒ","b"],[" جو حضرت عبدالرحمٰن بن عوفؓ کے آزاد کردہ غلام ہیں کہتے ہیں میں حضرت علیؓ کے ساتھ عید الاضحی کی نماز میں شریک ہوا، حضرت علیؓ نے خطبہ سے پہلے اذان اور اقامت کے بغیر عید کی نماز پڑھائی، پھر خطبہ دیا اس میں ارشاد فرمایا اے لوگو! حضورؐ نے تمہیں تین دن کے بعد قربانی کا گوشت کھانے سے منع فرمایا ہے، لہٰذا تم لوگ تین دن (تو گوشت کھاؤ اس کے بعد نہ کھاؤ (حضورؐ نے پہلے تو منع فرمایا تھا لیکن بعد میں تین دن کے بعد بھی کھانے کی اجازت دے دی تھی)۔",""],[" (23)","s"]]]],"f":[["(23)","Ahmad (Vol.1 Pg.141)."]]},{"b":[["n",[["حضرت ربعی بن حراشؒ","b"],[" کہتے ہیں میں نے حضرت علیؓ کو بیان میں یہ کہتے ہوئے سنا کہ حضورؐ نے فرمایا میرے بارے میں جھوٹ نہ بولو کیونکہ جو میرے بارے میں جھوٹ بولے گا وہ جہنم کی آگ میں داخل ہوگا۔",""],[" (24)","s"]]]],"f":[["(24)","Ahmad (Vol.1 Pg.150) and Tayaalisi (Pg.17) have reported a similar narration from Rib'i."]]},{"b":[["n",[["حضرت ابوعبدالرحمٰن سلمیؒ","b"],[" کہتے ہیں حضرت علیؓ نے بیان کیا جس میں ارشاد فرمایا اے لوگو! اپنے غلام اور باندیوں پر شرعی حدود قائم کرو چاہے وہ شادی شدہ ہوں یا غیر شادی شدہ، کیونکہ حضورؐ کی ایک باندی سے زنا صادر ہو گیا تھا تو حضورؐ نے مجھے حکم دیا کہ میں اس پر حد شرعی قائم کروں۔ میں اس کے پاس گیا تو دیکھا کہ اس کے ہاں کچھ دیر پہلے بچہ پیدا ہوا ہے تو مجھے ڈر ہوا کہ اگر میں اسے کوڑے ماروں گا تو وہ مر جائے گی۔ میں نے حضورؐ کی خدمت میں آ کر یہ بات عرض کی۔ آپؐ نے فرمایا تم نے اچھا کیا۔",""],[" (25)","s"]]]],"f":[["(25)","Ahmad (Vol.1 Pg.156)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سبعؒ","b"],[" کہتے ہیں حضرت علیؓ نے ہم سے بیان فرمایا جس میں ارشاد فرمایا اس ذات کی قسم جس نے دانے کو پھاڑا اور جان کو پیدا کیا! میری یہ ڈاڑھی سر کے خون سے ضرور رنگین ہوگی یعنی مجھے قتل کیا جائے گا۔ اس پر لوگوں نے کہا آپ ہمیں بتائیں کہ وہ (آپ کو قتل کرنے والا) آدمی کون ہے؟ ",""],["ٱللَّٰه","a"],[" کی قسم! ہم اس کے سارے خاندان کو تباہ کر دیں گے۔ حضرت علیؓ نے فرمایا میں تمہیں ",""],["ٱللَّٰه","a"],[" کا واسطہ دے کر کہتا ہوں کہ میرے قاتل کے علاوہ کوئی اور ہرگز قتل نہ ہو۔ لوگوں نے کہا اگر آپ کو یقین ہے کہ عنقریب آپ کو قتل کر دیا جائے گا تو آپ کسی کو اپنا خلیفہ مقرر فرما دیں۔ فرمایا نہیں بلکہ میں تو تمہیں اسی کے سپرد کرتا ہوں جس کے سپرد حضورؐ کر کے گئے تھے (یعنی حضورؐ نے اپنے بعد کسی کو خلیفہ مقرر نہیں کیا تھا بلکہ ",""],["ٱللَّٰه","a"],[" کے حوالے کیا تھا، میں بھی ایسے ہی کرتا ہوں)۔",""],[" (26)","s"]]]],"f":[["(26)","Ahmad (Vol.1 Pg.156)."]]},{"b":[["n",[["حضرت علاءؒ","b"],[" کہتے ہیں حضرت علیؓ نے بیان فرمایا جس میں ارشاد فرمایا اے لوگو! اس ذات کی قسم جس کے سوا کوئی معبود نہیں! میں نے تمہارے مال میں سے اس شیشی کے علاوہ اور کچھ نہیں لیا، اور اپنے کرتے کی آستین سے خوشبو کی ایک شیشی نکال کر فرمایا یہ ایک گاؤں کے چودھری نے مجھے ہدیہ کی ہے۔",""],[" (27)","s"]]]],"f":[["(27)","Abdur Razzaaq, Abu Ubayd in Al Amwaal and Haakim, and Abu Nu'aym in his Hilyah from Abu Umar bin Ala from his father, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.54)."]]},{"b":[["n",[["حضرت عمیر بن عبدالملکؒ","b"],[" کہتے ہیں حضرت علیؓ نے کوفہ کے منبر پر ہم لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اگر میں خود حضورؐ سے نہ پوچھتا تو آپؐ مجھے خود بتا دیتے اور اگر میں آپؐ سے خیر کے بارے میں پوچھتا تو آپؐ اس کے بارے میں بتاتے۔ آپؐ نے اپنے رب کی طرف سے مجھے یہ حدیث سنائی ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں میرے اپنے عرش کے اوپر بلند ہونے کی قسم! جس بستی والے اور جس گھر والے اور جنگل میں اکیلے رہنے والے سب میری نافرمانی پر ہوں جو کہ مجھے ناپسند ہے، پھر یہ اسے چھوڑ کر میری اطاعت اختیار کر لیں جو مجھے پسند ہے، تو میرا عذاب جو انہیں ناپسند ہے ان سے ہٹا کر اپنی رحمت کو ان کی طرف توجہ کر دوں گا جو انہیں پسند ہے۔ اور جس بستی والے اور جس گھر والے اور جنگل میں اکیلے رہنے والے سب میری اطاعت پر ہوں جو مجھے پسند ہے، وہ اسے چھوڑ کر میری نافرمانی اختیار کر لیں جو مجھے ناپسند ہے، تو میری رحمت جو انہیں پسند ہے وہ ان سے ہٹا کر اپنا غصہ ان کی طرف متوجہ کر دوں گا جو انہیں ناپسند ہے۔",""],[" (28)","s"]]]],"f":[["(28)","Ibn Mardawayh, as quoted in Kanzul Ummaal (Vol.8 Pg.203); Ibn Sa'd (Vol.3 Pg.38)."]]}]},"183":{"lead":[],"stories":[{"b":[["n",[["حضرت ہبیرہؒ","b"],[" کہتے ہیں جب حضرت علی ابن ابی طالبؓ کا انتقال ہو گیا تو حضرت حسن بن علیؓ کھڑے ہو کر منبر پر تشریف فرما ہوئے اور فرمایا اے لوگو! آج رات ایسی ہستی دنیا سے اٹھا لی گئی ہے جن سے پہلے لوگ آگے نہیں جا سکے اور جنہیں پچھلے لوگ پا نہیں سکیں گے۔ حضورؐ انہیں کسی جگہ بھیجتے تو انہیں دائیں طرف سے حضرت جبرائیل علیہ السلام اور بائیں طرف سے حضرت میکائیل علیہ السلام اپنے گھیرے میں لے لیتے اور جب تک ",""],["ٱللَّٰه","a"],[" انہیں فتح نہ دیتے یہ واپس نہ آتے۔ یہ صرف سات سو درہم چھوڑ کر گئے ہیں۔ آپؓ اس سے ایک خادم خریدنا چاہتے تھے۔ آج ستائیس (27) رمضان کی رات میں ان کی روح قبض کی گئی ہے، اسی رات میں حضرت عیسیٰ بن مریم علیہما السلام کو آسمانوں کی طرف اٹھایا گیا۔ ایک روایت میں ہے وہ سونا چاندی کچھ بھی چھوڑ کر نہیں گئے، صرف سات سو درہم چھوڑ گئے ہیں جو ان کے بیت المال میں سے ملنے والے وظیفہ میں سے بچے ہیں۔ اس روایت میں اس سے آگے نہیں ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.65) from Hubayrah with the second wording. Ahmad (Vol.1 Pg.199) has reported it from him in abridged form."]]},{"b":[["n",[["جب حضرت علیؓ شہید ہو گئے تو حضرت حسنؓ نے کھڑے ہو کر بیان فرمایا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! آج رات تم نے ایک آدمی کو قتل کر دیا ہے، اسی رات میں قرآن پاک نازل ہوا۔ اسی میں حضرت عیسیٰ بن مریم علیہما السلام کو اٹھایا گیا اور اسی رات میں حضرت موسیٰ علیہ السلام کے خادم حضرت یوشع بن نونؒ کو شہید کیا گیا اور اسی میں بنی اسرائیل کی توبہ قبول ہوئی۔ طبرانی کی روایت میں اس کے بعد یہ ہے کہ پھر حضرت حسنؓ نے فرمایا جو مجھے جانتا ہے وہ تو جانتا ہے اور جو مجھے نہیں جانتا میں اسے اپنا تعارف کرا دیتا ہوں، میں حضرت محمدؐ کا بیٹا حسن ہوں (میں حضورؐ کو اپنا باپ اس وجہ سے کہہ رہا ہوں کہ حضرت یوسف علیہ السلام نے حضرت ابراہیم اور حضرت اسحاق علیہما السلام کو اپنا باپ کہا ہے حالانکہ یہ دونوں ان کے دادا پردادا تھے)۔ پھر انہوں نے یہ آیت پڑھی جس میں حضرت یوسفؑ کا قول ہے",""]]],["q",[["وَٱتَّبَعْتُ مِلَّةَ ءَابَآءِىٓ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ","a"]]],["p",[["ترجمہ: \"اور میں نے اپنے ان باپ دادوں کا مذہب اختیار کر رکھا ہے، ابراہیمؑ کا، اسحاقؑ کا اور یعقوبؑ کا\" (سورۂ یوسف، آیت 38)۔ پھر ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے کچھ اور پڑھنے لگے، پھر (حضورؐ کے مختلف نام لے کر) فرمایا میں بشارت دینے والے کا بیٹا ہوں، میں ڈرانے والے کا بیٹا ہوں، میں نبی کا بیٹا ہوں، میں ",""],["ٱللَّٰه","a"],[" کے حکم سے ",""],["ٱللَّٰه","a"],[" کی دعوت دینے والے کا بیٹا ہوں، میں روشن چراغ کا بیٹا ہوں۔ میں اس ذات کا بیٹا ہوں جنہیں رحمۃ للعالمین بنا کر بھیجا گیا۔ میں اس گھرانے کا فرد ہوں جن سے ",""],["ٱللَّٰه","a"],[" نے گندگی دور کر دی اور جنہیں خوب اچھی طرح پاک کیا۔ میں اس گھرانے کا فرد ہوں جن کی محبت اور دوستی کو ",""],["ٱللَّٰه","a"],[" نے فرض قرار دیا۔ چنانچہ جو قرآن حضرت محمدؐ پر ",""],["ٱللَّٰه","a"],[" نے نازل کیا اس میں ",""],["ٱللَّٰه","a"],[" نے فرمایا ہے",""]]],["q",[["قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ","a"]]],["p",[["ترجمہ: \"آپ (ان سے) یوں کہیے کہ میں تم سے کچھ مطلب نہیں چاہتا بجز رشتہ داری کی محبت کے\" (سورۂ شوریٰ، آیت 23)۔ طبرانی کی دوسری روایت میں یہ مضمون بھی ہے کہ حضورؐ انہیں جھنڈا دیا کرتے اور جب جنگ میں گھمسان کا رن پڑتا تو جبرائیل علیہ السلام ان کے دائیں جانب آ کر لڑتے۔ راوی کہتے ہیں یہ رمضان کی اکیسویں رات تھی۔ حاکم کی روایت میں یہ بھی ہے کہ میں نبوی گھرانہ میں سے ہوں، حضرت جبرائیل علیہ السلام (آسمان سے) اتر کر ہمارے پاس آیا کرتے تھے اور ہمارے پاس سے (آسمان کو) اوپر جایا کرتے تھے۔ اس روایت میں اسی آیت کا یہ حصہ بھی ہے",""]]],["q",[["وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا","a"]]],["p",[["ترجمہ: \"اور جو شخص کوئی نیکی کرے گا ہم اس میں اور خوبی زیادہ کر دیں گے\" (سورۂ شوریٰ، آیت 23)۔ یہاں نیکی کرنے سے مراد ہمارے سارے گھرانے سے محبت کرنا ہے۔",""],[" (2)","s"],[" (3)","s"],[" (4)","s"],[" (5)","s"]]]],"f":[["(2)","Abu Ya'la, Ibn Jareer and Ibn Asaakir from Hasan, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.61)."],["(3)","Tabraani from Abu Tufayl, mentioning the meaning of the narrations of Ibn Sa'd and Abu Ya'la and others."],["(4)","Haythami (Vol.9 Pg.146) has said that Tabraani has reported it in his Awsat and Kabeer in abridged form, Abu Ya'la in abridged form, Bazzaar likewise, and Ahmad in much abridged form, and that the chain of Ahmad and some chains of Bazzaar and Tabraani in his Kabeer are hasan."],["(5)","Haakim in his Mustadrak (Vol.3 Pg.172) from Ali bin Husayn, in the narration of Abu Tufayl. Dhahabi said that it is not authentic, and Haakim was silent about it."]]},{"b":[["n",[["حضرت ابوجمیلہؒ","b"],[" کہتے ہیں حضرت علیؓ کی شہادت کے بعد حضرت حسن بن علیؓ خلیفہ بنے۔ ایک دفعہ وہ لوگوں کو نماز پڑھا رہے تھے کہ اتنے میں ایک آدمی نے آگے بڑھ کر ان کی سرین پر خنجر مارا جس سے وہ زخمی ہو گئے اور چند ماہ بیمار رہے، پھر کھڑے ہو کر انہوں نے بیان فرمایا تو اس میں فرمایا اے عراق والو! ہمارے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ ہم تمہارے امراء بھی ہیں اور مہمان بھی اور ہم اس گھرانے کے ہیں جس کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ کو یہ منظور ہے کہ اے گھر والو تم سے آلودگی کو دور رکھے اور تم کو (ہر طرح ظاہراً و باطناً) پاک صاف رکھے\" (سورۂ احزاب، آیت 33)۔ حضرت حسنؓ اس موضوع پر کافی دیر گفتگو فرماتے رہے یہاں تک کہ مسجد کا ہر آدمی روتا ہوا نظر آنے لگا۔ ابن ابی حاتم کی روایت میں یہ ہے کہ حضرت حسنؓ ان باتوں کو بار بار کہتے رہے یہاں تک کہ مسجد کا ہر آدمی آواز سے رونے لگا۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Tabraani; Haythami (Vol.9 Pg.172) has said that its narrators are reliable."],["(7)","Ibn Abi Haatim from Abu Jameelah with a similar narration, as quoted in Tafseer Ibn Katheer (Vol.3 Pg.486)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں حضرت معاویہؓ نے حضرت حسن بن علیؓ سے نخیلہ مقام پر صلح کی تو حضرت معاویہؓ نے ان سے کہا جب یہ (صلح کی) بات طے ہو گئی ہے تو آپ کھڑے ہو کر گفتگو کریں اور لوگوں کو بتا دیں کہ آپ نے خلافت چھوڑ دی ہے اور اسے میرے حوالے کر دیا ہے۔ چنانچہ حضرت حسنؓ اٹھے اور منبر پر بیان کیا۔ حضرت شعبیؒ کہتے ہیں میں اس بیان کو سن رہا تھا۔ حضرت حسنؓ نے پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! سب سے زیادہ سمجھداری تقویٰ اختیار کرنا ہے اور سب سے بڑی حماقت گناہوں میں مبتلا ہونا ہے۔ اور میرا اور معاویہؓ کا خلافت کے بارے میں آپس میں اختلاف تھا، یا تو یہ میرا حق تھا جسے میں نے حضرت معاویہؓ کے لیے اس لیے چھوڑ دیا تاکہ اس امت کا آپس میں معاملہ ٹھیک رہے اور ان کے خون محفوظ رہیں، یا کوئی اور اس خلافت کا مجھ سے زیادہ حقدار ہے، تو اب میں نے یہ خلافت ان کے حوالے کر دی ہے۔ اور یہ آیت تلاوت فرمائی",""]]],["q",[["وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ","a"]]],["p",[["ترجمہ: \"اور میں (بالیقین) نہیں جانتا (کہ کیا مصلحت ہے) شاید وہ (تاخیر عذاب) تمہارے لیے (صورتاً) امتحان ہو اور ایک وقت (یعنی موت) تک (زندگی سے) فائدہ پہنچانا ہو\" (سورۂ انبیاء، آیت 111)۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani in his Kabeer; Haythami (Vol.4 Pg.108) has said that in its chain is Mujaalid bin Sa'eed about whom there is criticism and who has also been declared reliable, while the rest of its narrators are those of authentic Ahaadeeth."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں جب حضرت حسن بن علیؓ نے حضرت معاویہؓ سے صلح کی تو انہوں نے نخیلہ مقام میں ہم میں بیان کیا اور کھڑے ہو کر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور پچھلی حدیث جیسا مضمون بیان کیا اور آخر میں مزید یہ بھی ہے کہ میں اسی پر اپنی بات ختم کرتا ہوں اور میں اپنے لیے اور تمہارے لیے ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔",""],[" (9)","s"]]]],"f":[["(9)","Haakim (Vol.3 Pg.175) through Mujaalid, and Bayhaqi (Vol.8 Pg.173) has reported a similar narration through him."]]},{"b":[["n",[["حضرت حسن بن علیؓ","b"],[" نے اپنے اس بیان میں یہ بھی فرمایا اما بعد! اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہمارے پہلوں کے ذریعہ سے (یعنی حضورؐ کے ذریعہ سے) تمہیں ہدایت دی اور ہمارے پچھلوں کے ذریعہ (یعنی میرے ذریعہ) تمہارے خون کی حفاظت کی۔ اس خلافت کی تو ایک خاص مدت ہے اور دنیا تو آنے جانے والی چیز ہے، کبھی کسی کے پاس ہوتی ہے کبھی کسی کے پاس۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبی کریمؐ سے فرمایا ہے",""]]],["q",[["وَإِنْ أَدْرِى لَعَلَّهُۥ فِتْنَةٌ لَّكُمْ وَمَتَٰعٌ إِلَىٰ حِينٍ","a"]]],["p",[["ترجمہ: \"(اس آیت کا) ترجمہ گزر چکا ہے۔\" (سورۂ انبیاء، آیت 111)۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Jareer has mentioned it in his Taareekh (Vol.4 Pg.124)."]]}]},"184":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن کعب قرظیؒ","b"],[" کہتے ہیں حضرت معاویہ بن ابی سفیانؓ ایک دن مدینہ میں بیان فرما رہے تھے، اس میں ارشاد فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ جو چیز دینا چاہے اسے کوئی روک نہیں سکتا اور جسے وہ روک لے اسے کوئی دینے والا نہیں اور کسی مالدار کی مالداری ",""],["ٱللَّٰه","a"],[" کے ہاں کوئی کام نہیں دے سکتی۔ ",""],["ٱللَّٰه","a"],[" جس کے ساتھ خیر کا ارادہ فرماتے ہیں اسے دین کی سمجھ عطا فرماتے ہیں۔ میں نے یہ ساری باتیں (منبر کی) ان لکڑیوں پر حضورؐ سے سنی ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abdul Barr in Jaami'u Bayaanil Ilm (Vol.1 Pg.20)."]]},{"b":[["n",[["حضرت حمید بن عبدالرحمٰنؒ","b"],[" کہتے ہیں حضرت معاویہؓ نے ہم میں بیان فرمایا، میں نے انہیں بیان میں یہ کہتے ہوئے سنا کہ میں نے نبی کریمؐ کو فرماتے ہوئے سنا کہ جس کے ساتھ ",""],["ٱللَّٰه","a"],[" تعالیٰ بھلائی کا ارادہ فرماتے ہیں اسے دین کی سمجھ عطا فرماتے ہیں اور میں تو صرف تقسیم کرنے والا ہی ہوں اور دیتے تو صرف ",""],["ٱللَّٰه","a"],[" ہی ہیں اور یہ امت ہمیشہ حق پر اور ",""],["ٱللَّٰه","a"],[" کے دین پر قائم رہے گی اور جو ان کی مخالفت کرے گا وہ انہیں نقصان نہیں پہنچا سکے گا اور یہ صورت حال ",""],["ٱللَّٰه","a"],[" کے حکم کے آنے تک یعنی قیامت کے قائم ہونے تک ایسے ہی رہے گی۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abdul Barr also."]]},{"b":[["n",[["حضرت عمیر بن ہانیؒ","b"],[" کہتے ہیں حضرت معاویہ بن ابی سفیانؓ نے لوگوں میں بیان فرمایا جس میں ارشاد فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا میری امت میں سے ہمیشہ ایک جماعت ",""],["ٱللَّٰه","a"],[" کے دین کو لے کر کھڑی رہے گی، ان کی مخالفت کرنے والے اور ان کی مدد چھوڑنے والے کوئی بھی ان کا نقصان نہ کر سکیں گے اور ",""],["ٱللَّٰه","a"],[" کے حکم کے آنے تک یعنی قیامت کے قائم ہونے تک وہ ایسے ہی رہیں گے۔ اور ایک روایت میں ہے کہ وہ لوگوں پر غالب رہیں گے۔ حضرت عمیر بن ہانیؒ کہتے ہیں اس پر حضرت مالک بن یخامرؒ نے کھڑے ہو کر کہا میں نے حضرت معاذ بن جبلؓ کو فرماتے ہوئے سنا کہ (میرے خیال میں) یہ جماعت آج کل شام میں ہے۔ حضرت یونس بن حلبس جیلانیؒ سے اسی جیسی حدیث مروی ہے اور اس میں مزید یہ بھی ہے کہ پھر حضرت معاویہؓ نے اس آیت کو بطور دلیل کے ذکر کیا",""]]],["q",[["يَٰعِيسَىٰٓ إِنِّى مُتَوَفِّيكَ وَرَافِعُكَ إِلَىَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِينَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِينَ ٱتَّبَعُوكَ فَوْقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ","a"]]],["p",[["ترجمہ: \"اے عیسیٰ! (کچھ غم نہ کرو) بیشک میں تم کو وفات دینے والا ہوں اور (فی الحال) میں تم کو اپنی طرف اٹھا لیتا ہوں اور تم کو ان لوگوں سے پاک کرنے والا ہوں جو منکر ہیں اور جو لوگ تمہارا کہنا ماننے والے ہیں ان کو غالب رکھنے والا ہوں ان لوگوں پر جو کہ (تمہارے) منکر ہیں روز قیامت تک\" (سورۂ آل عمران، آیت 55)۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Ahmad, Abu Ya'la, Ya'qoob bin Sufyaan and others."],["(4)","Ibn Asaakir."]]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں حضرت معاویہؓ نے منبر پر بیان کرتے ہوئے فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا اے لوگو! علم تو سیکھنے سے آتا ہے اور دین کی سمجھ تو حاصل کرنے سے آتی ہے اور جس کے ساتھ ",""],["ٱللَّٰه","a"],[" خیر کا ارادہ فرماتے ہیں اسے دین کی سمجھ عطا فرماتے ہیں۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کے بندوں میں سے ",""],["ٱللَّٰه","a"],[" سے صرف وہی ڈرتے ہیں (جو اس کی قدرت کا) علم رکھتے ہیں۔ اور میری امت میں سے ایک جماعت ہمیشہ حق پر قائم رہے گی جو لوگوں پر غالب رہے گی اور مخالفین اور دشمنوں کی انہیں کوئی پرواہ نہیں ہوگی اور یہ لوگ قیامت تک یونہی غالب رہیں گے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir also, as quoted in Kanzul Ummaal (Vol.7 Pg.130)."]]}]},"185":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن عبد","b"],["ٱللَّٰه","a"],[" ثقفیؒ","b"],[" کہتے ہیں ایک دفعہ حج کے موقع پر حضرت ابن زبیرؓ کے خطبہ میں شریک ہوا۔ ہمیں ان کے بارے میں اسی وقت پتہ چلا جب وہ یوم الترویہ (آٹھویں ذی الحجہ) سے ایک دن پہلے احرام باندھ کر ہمارے پاس باہر آئے۔ وہ ادھیڑ عمر کے خوبصورت آدمی تھے، وہ سامنے سے آ رہے تھے۔ لوگوں نے کہا یہ امیر المومنین ہیں۔ پھر وہ منبر پر تشریف فرما ہوئے، اس وقت ان پر احرام کی دو سفید چادریں تھیں۔ پھر انہوں نے لوگوں کو سلام کیا، لوگوں نے انہیں سلام کا جواب دیا۔ پھر انہوں نے بڑی اچھی آواز سے لبیک پڑھا، ایسی اچھی آواز میں نے کبھی ہی سنی ہوگی۔ پھر ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی، اس کے بعد فرمایا اما بعد! تم لوگ مختلف علاقوں سے وفد بن کر ",""],["ٱللَّٰه","a"],[" کے پاس آئے ہو، لہٰذا ",""],["ٱللَّٰه","a"],[" پر بھی اس کے فضل سے یہ لازم ہے کہ وہ اپنے پاس وفد بن کر آنے والوں کا اکرام کرے۔ اب جو ان اخروی نعمتوں کا طالب بن کر آیا ہے جو ",""],["ٱللَّٰه","a"],[" کے پاس ہیں تو ",""],["ٱللَّٰه","a"],[" سے طلب کرنے والا محروم نہیں رہتا، لہٰذا اپنے قول کی عمل سے تصدیق کرو کیونکہ قول کا سہارا عمل ہے اور اصل نیت دل کی ہوتی ہے۔ ان دنوں میں ",""],["ٱللَّٰه","a"],[" سے ڈرو کیونکہ ان دنوں میں ",""],["ٱللَّٰه","a"],[" تعالیٰ تمام گناہوں کو معاف کر دیتے ہیں۔ آپ لوگ مختلف علاقوں سے آئے ہیں، آپ لوگوں کا مقصد نہ تجارت ہے اور نہ مال حاصل کرنا اور نہ ہی دنیا لینے کی امید میں آپ لوگ یہاں آئے ہیں۔ پھر حضرت ابن زبیرؓ نے لبیک پڑھا اور لوگوں نے بھی پڑھا۔ پھر انہوں نے بڑی لمبی گفتگو فرمائی، پھر فرمایا اما بعد! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنی کتاب میں فرمایا ہے",""]]],["q",[["ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ","a"]]],["p",[["ترجمہ: \"(زمانہ) حج چند مہینے ہیں جو معلوم ہیں\" (سورۂ بقرہ، آیت 197)۔ فرمایا وہ تین مہینے ہیں: شوال، ذیقعدہ اور ذی الحجہ کے دس دن۔",""]]],["q",[["فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ","a"]]],["p",[["ترجمہ: \"سو جو شخص ان میں حج مقرر کر لے تو پھر (اس کو) نہ کوئی فحش بات (جائز) ہے\" یعنی بیوی سے صحبت کرنا۔",""]]],["q",[["وَلَا فُسُوقَ","a"]]],["p",[["ترجمہ: \"اور نہ کوئی بے حکمی (درست) ہے\" یعنی مسلمانوں کو برا بھلا کہنا۔",""]]],["q",[["وَلَا جِدَالَ","a"]]],["p",[["ترجمہ: \"اور نہ کسی کو نزاع زیبا ہے\" یعنی لڑائی جھگڑا کرنا۔",""]]],["q",[["وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ ۗ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ","a"]]],["p",[["ترجمہ: \"اور جو نیک کام کرو گے خدائے تعالیٰ کو اس کی اطلاع ہوتی ہے اور (جب حج کو جانے لگو) خرچ ضرور لے لیا کرو کیونکہ سب سے بڑی بات خرچ میں (گداگری سے) بچار ہنا ہے۔\" اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ","a"]]],["p",[["ترجمہ: \"تم کو اس میں ذرا بھی گناہ نہیں کہ (حج میں) معاش کی تلاش کرو\" چنانچہ ",""],["ٱللَّٰه","a"],[" نے حاجیوں کو تجارت کی اجازت دے دی۔ پھر ",""],["ٱللَّٰه","a"],[" نے فرمایا",""]]],["q",[["فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ","a"]]],["p",[["ترجمہ: \"پھر جب تم لوگ عرفات سے واپس آنے لگو\" اور عرفات ٹھہرنے کی وہ جگہ ہے جہاں حاجی لوگ سورج کے غروب تک وقوف کرتے ہیں، پھر وہاں سے واپس آتے ہیں۔",""]]],["q",[["فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ","a"]]],["p",[["ترجمہ: \"تو مشعر حرام کے پاس (مزدلفہ میں شب کو قیام کر کے) خدائے تعالیٰ کو یاد کرو\" یہ مزدلفہ کے وہ پہاڑ ہیں جہاں حاجی رات ٹھہرتے ہیں۔",""]]],["q",[["وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ","a"]]],["p",[["ترجمہ: \"اور اس طرح یاد کرو جس طرح تم کو بتلا رکھا ہے\"۔ حضرت ابن زبیرؓ نے فرمایا یہ حکم عام نہیں ہے بلکہ صرف مکہ شہر والوں کے لیے ہے کیونکہ مکہ والے مزدلفہ میں وقوف کرتے ہیں اور عرفات نہیں جاتے تھے، اس لیے وہ مزدلفہ سے واپس آتے تھے۔ جبکہ باقی لوگ عرفات جاتے تھے اور وہاں سے واپس آتے تھے، تو ",""],["ٱللَّٰه","a"],[" نے ان کے فعل پر انکار کرتے ہوئے فرمایا",""]]],["q",[["ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ","a"]]],["p",[["ترجمہ: \"پھر تم سب کو ضروری ہے کہ اسی جگہ ہو کر واپس آؤ جہاں اور لوگ جا کر وہاں سے واپس آتے ہیں\" یعنی وہاں سے واپس آ کر اپنے مناسک پورے کرو۔ زمانہ جاہلیت کے حاجیوں کا دستور یہ تھا کہ وہ حج سے فارغ ہو کر اپنے آباؤ اجداد کے کارناموں کا ذکر کر کے ایک دوسرے پر فخر کرتے تھے، اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیتیں نازل فرمائیں",""]]],["q",[["فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا ۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْءَاخِرَةِ مِنْ خَلَٰقٍ ۞ وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْءَاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ ","a"]]],["p",[["ترجمہ: \"تو حق تعالیٰ کا ذکر کیا کرو جس طرح تم اپنے آباء و اجداد کا ذکر کیا کرتے ہو بلکہ یہ ذکر اس سے (بدرجہا) بڑھ کر ہو۔ سو بعضے آدمی (جو کہ کافر ہیں) ایسے ہیں جو کہتے ہیں کہ اے ہمارے پروردگار ہم کو (جو کچھ دینا ہو) دنیا میں دے دیجیے، اور ایسے شخص کا آخرت میں (بوجہ انکار آخرت کے) کوئی حصہ نہ ملے گا۔ اور بعضے آدمی (جو کہ مومن ہیں) ایسے ہیں جو کہتے ہیں کہ اے ہمارے پروردگار ہم کو دنیا میں بھی بہتری عنایت کیجیے اور آخرت میں بھی بہتری دیجیے اور ہم کو عذاب دوزخ سے بچائیے\" (سورۂ بقرہ، آیات 200–201)۔ یعنی دنیا میں رہ کر دنیا کے لیے بھی محنت کرتے ہیں اور آخرت کے لیے بھی۔ پھر حضرت ابن زبیرؓ نے اس آیت تک تلاوت فرمائی",""]]],["q",[["وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ","a"]]],["p",[["ترجمہ: \"اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کا ذکر کرو چند روز تک\" (سورۂ بقرہ، آیت 203)۔ اور فرمایا اس سے ایام تشریق مراد ہیں اور ان دنوں کے ذکر میں سبحان ",""],["ٱللَّٰه","a"],["، الحمد للہ، ",""],["ٱللَّٰه","a"],[" کہنا، ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہنا، ",""],["ٱللَّٰه","a"],[" اکبر کہنا اور ",""],["ٱللَّٰه","a"],[" کی عظمت والے کلمات کہنا سب شامل ہے۔ پھر حضرت ابن زبیرؓ نے میقات یعنی لوگوں کے احرام باندھنے کی جگہوں کا ذکر کیا، چنانچہ فرمایا مدینہ والوں کے لیے احرام باندھنے کی جگہ ذوالحلیفہ ہے اور عراق والوں کے لیے عقیق ہے اور نجد والوں اور طائف والوں کے لیے قرن ہے اور یمن والوں کے لیے یلملم ہے۔ اس کے بعد اہل کتاب کے کافروں کے لیے یہ بددعا کی اے ",""],["ٱللَّٰه","a"],["! اہل کتاب کے ان کافروں کو عذاب دے جو تیری آیتوں کا انکار کرتے ہیں اور تیرے رسولوں کو جھٹلاتے ہیں اور تیرے راستہ سے روکتے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! انہیں عذاب بھی دے اور ان کے دل بدکار عورتوں جیسے بنا دے۔ اس طرح بہت لمبی دعا کی، پھر فرمایا یہاں کچھ لوگ ایسے ہیں جن کے دلوں کو ",""],["ٱللَّٰه","a"],[" نے ایسے اندھا کر دیا جیسے ان کی آنکھوں کو اندھا کیا، وہ حج تمتع کا یہ فتویٰ دیتے ہیں کہ ایک آدمی مثلاً خراسان سے حج کا احرام باندھ کر آیا تو یہ اس سے کہتے ہیں عمرہ کر کے حج کا احرام کھول دو پھر یہاں سے حج کا احرام باندھ لینا (حالانکہ جب وہ حج کا احرام باندھ کر آیا ہے تو وہ حج کر کے ہی احرام کھول سکتا ہے اس سے پہلے نہیں)۔ ",""],["ٱللَّٰه","a"],[" کی قسم! حج کا احرام باندھ کر آنے والے کو صرف ایک صورت میں تمتع کی یعنی عمرہ کر کے احرام کھول دینے کی اجازت ہے جبکہ اسے حج سے روک دیا جائے۔ پھر حضرت ابن زبیرؓ نے لبیک پڑھا اور تمام لوگوں نے پڑھا۔ راوی کہتے ہیں میں نے لوگوں کو اس دن سے زیادہ روتے ہوئے کسی دن نہیں دیکھا۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Kabeer; Haythami (Vol.3 Pg.250) has said that in its chain is Sa'eed bin Marzubaan who has been declared reliable but about whom there is much criticism. Abu Nu'aym in his Hilyah (Vol.1 Pg.326) has reported a similar narration from Muhammad bin Abdullah Thaqafi, except that it does not mention part of it, and in its chain also is Sa'eed bin Marzubaan."]]},{"b":[["n",[["حضرت ہشام بن عروہؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ نے اپنے بیان میں فرمایا اچھی طرح سمجھ لو کہ بطن عرنہ کے علاوہ سارا عرفات ٹھہرنے کی جگہ ہے اور خوب جان لو کہ بطن محسر کے علاوہ سارا مزدلفہ ٹھہرنے کی جگہ ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer in his Tafseer (Vol.2 Pg.168)."]]},{"b":[["n",[["حضرت عباس بن سہل بن سعد ساعدی انصاریؒ","b"],[" کہتے ہیں میں نے مکہ کے منبر پر حضرت ابن زبیرؓ کو بیان میں یہ فرماتے ہوئے سنا اے لوگو! حضورؐ فرمایا کرتے تھے اگر ابن آدم کو سونے کی ایک وادی دے دی جائے تو وہ دوسری وادی کی تمنا کرنے لگے گا اور اگر اسے دوسری وادی دے دی جائے تو تیسری کی تمنا کرنے لگے گا اور ابن آدم کے پیٹ کو (قبر کی) مٹی کے سوا اور کوئی چیز نہیں بھر سکتی، اور جو ",""],["ٱللَّٰه","a"],[" کے سامنے توبہ کرتا ہے ",""],["ٱللَّٰه","a"],[" اس کی توبہ قبول فرما لیتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.337)."]]},{"b":[["n",[["حضرت عطاء بن ابی رباحؒ","b"],[" کہتے ہیں حضرت ابن زبیرؓ نے ہم لوگوں میں بیان کرتے ہوئے فرمایا حضورؐ نے فرمایا میری اس مسجد میں ایک نماز مسجد حرام کے علاوہ دوسری مساجد کی ہزار نماز سے افضل ہے اور مسجد حرام کی ایک نماز (میری مسجد کی نماز پر) سو گنا فضیلت رکھتی ہے۔ حضرت عطاءؒ کہتے ہیں اس طرح مسجد حرام کی نماز دوسری مسجد کی نماز پر لاکھ گنا فضیلت حاصل کر جائے گی۔ حضرت عطاءؒ کہتے ہیں میں نے حضرت ابن زبیرؓ سے پوچھا اے ابو محمد! یہ لاکھ گنا فضیلت صرف مسجد حرام میں ہے یا سارے حرم میں ہے؟ انہوں نے فرمایا نہیں، سارے حرم میں ہے کیونکہ سارا حرم مسجد (کے حکم میں) ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Dawood Tayaalisi (Pg.195)."]]},{"b":[["n",[["حضرت وہب بن کیسانؒ","b"],[" جو حضرت ابن زبیرؓ کے آزاد کردہ غلام ہیں کہتے ہیں حضرت ابن زبیرؓ نے عید کے دن عید کی نماز پڑھائی، پھر کھڑے ہو کر خطبہ پڑھا۔ میں نے انہیں خطبہ میں یہ کہتے ہوئے سنا اے لوگو! عید کی نماز سے پہلے خطبہ پڑھنا ہرگز درست نہیں۔ عید کے بعد خطبہ پڑھنا ",""],["ٱللَّٰه","a"],[" اور رسول کی طرف سے مقرر کردہ طریقہ ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad in his Musnad (Vol.4 Pg.4)."]]},{"b":[["n",[["حضرت ثابتؒ","b"],[" کہتے ہیں میں نے حضرت ابن زبیرؓ کو بیان میں یہ کہتے ہوئے سنا کہ حضرت محمدؐ نے فرمایا ہے جو مرد دنیا میں ریشم پہنے گا وہ آخرت میں نہیں پہن سکے گا۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad (Vol.4 Pg.5)."]]},{"b":[["n",[["حضرت ابوالزبیرؒ","b"],[" کہتے ہیں میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ کو اس منبر پر یہ فرماتے ہوئے سنا حضورؐ جب نماز کے بعد سلام پھیرتے تو یہ کلمات پڑھتے",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ، لَا إِلَٰهَ إِلَّا ٱللَّهُ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ ٱلنِّعْمَةُ وَلَهُ ٱلْفَضْلُ وَلَهُ ٱلثَّنَاءُ ٱلْحَسَنُ، لَا إِلَٰهَ إِلَّا ٱللَّهُ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَافِرُونَ ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، وہ یکتا ہے، اس کا کوئی شریک نہیں، ساری بادشاہت اسی کے لیے ہے، تمام تعریفیں اسی کے لیے ہیں، وہ ہر چیز پر قدرت رکھنے والا ہے۔ برائی سے بچنے اور نیکی کے کرنے کی طاقت صرف اسی سے ملتی ہے۔ ہم صرف اسی کی عبادت کرتے ہیں، وہ نعمت، فضل اور اچھی تعریف والا ہے۔ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں۔ ہم پورے اخلاص کے ساتھ دین پر چل رہے ہیں چاہے یہ کافروں کو برا لگے۔\"",""],[" (7)","s"]]]],"f":[["(7)","Ahmad (Vol.4 Pg.5)."]]},{"b":[["n",[["حضرت ثورؒ","b"],[" کہتے ہیں میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ کو منبر پر یہ فرماتے ہوئے سنا کہ یہ عاشورا (دس محرم) کا دن ہے، اس میں روزہ رکھو کیونکہ حضورؐ نے اس دن کے روزے کا حکم دیا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad (Vol.4 Pg.6)."]]},{"b":[["n",[["حضرت کلثوم بن جبرؒ","b"],[" کہتے ہیں حضرت ابن زبیرؓ دینی امور میں بڑی مشکل سے رعایت کرتے تھے۔ انہوں نے ایک مرتبہ ہم میں بیان فرمایا اس میں ارشاد فرمایا اے مکہ والو! مجھے قریش کے کچھ لوگوں کے بارے میں یہ خبر پہنچی ہے کہ وہ نردشیر کھیل کھیلتے ہیں (یہ شطرنج جیسا کھیل ہے)، حالانکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تو فرمایا",""]]],["q",[["إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ","a"]]],["p",[["ترجمہ: \"بات یہی ہے کہ شراب اور جوا اور بت وغیرہ اور قرعہ کے تیر یہ سب گندی باتیں شیطانی کام ہیں، سو ان سے بالکل الگ رہنا کہ تم کو فلاح ہو\" (سورۂ مائدہ، آیت 90)۔ اور میں ",""],["ٱللَّٰه","a"],[" کی قسم کھا کر کہتا ہوں کہ میرے پاس جو آدمی ایسا لایا گیا جو یہ کھیل کھیلتا ہوگا تو میں اس کے بال اور کھال ادھیڑ دوں گا اور سخت سزا دوں گا اور اس کا سامان اسے دے دوں گا جو اسے میرے پاس لائے گا۔",""],[" (9)","s"]]]],"f":[["(9)","Bukhaari in Adabul Mufrad (Pg.186)."]]}]},"186":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے مختصر بیان فرمایا، بیان سے فارغ ہو کر آپؐ نے فرمایا اے ابوبکر! تم کھڑے ہو کر بیان کرو۔ چنانچہ انہوں نے حضورؐ سے کم بیان کیا، جب وہ بیان سے فارغ ہو گئے تو حضورؐ نے فرمایا اے عمر! اب تم اٹھو اور بیان کرو۔ چنانچہ وہ کھڑے ہوئے اور انہوں نے حضورؐ سے بھی اور حضرت ابوبکرؓ سے بھی کم بیان کیا۔ جب وہ بیان سے فارغ ہو گئے تو آپؐ نے فرمایا اے فلانے! اب تم کھڑے ہو کر بیان کرو۔ اس نے کھڑے ہو کر خوب منہ بھر کر باتیں کیں، حضورؐ نے اسے فرمایا خاموش ہو جاؤ اور بیٹھ جاؤ کیونکہ خوب منہ بھر کر باتیں کرنا شیطان کی طرف سے ہے اور بعض بیان جادو کی طرح اثر انداز ہوتے ہیں۔ پھر آپؐ نے (حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ سے) فرمایا اے ابن ام عبد! اب تم کھڑے ہو کر بیان کرو۔ انہوں نے کھڑے ہو کر پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر کہا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمارے رب ہیں اور اسلام ہمارا دین ہے اور قرآن ہمارا امام ہے اور بیت ",""],["ٱللَّٰه","a"],[" ہمارا قبلہ ہے، اور ہاتھ سے حضورؐ کی طرف اشارہ کر کے کہا اور یہ ہمارے نبی ہیں، اور ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے جو کچھ ہمارے لیے پسند کیا ہم نے بھی اسے اپنے لیے پسند کیا اور جو کچھ ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے ہمارے لیے ناپسند کیا ہم نے بھی اسے اپنے لیے ناپسند کیا۔ اس پر حضورؐ نے فرمایا ابن ام عبد نے ٹھیک کہا، ابن ام عبد نے ٹھیک اور سچ کہا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو کچھ میرے لیے اور میری امت کے لیے پسند کیا وہ مجھے بھی پسند ہے اور جو کچھ ابن ام عبد نے پسند کیا وہ بھی مجھے پسند ہے۔ ابن عساکر کی روایت میں اس کے بعد یہ بھی ہے کہ جو کچھ ",""],["ٱللَّٰه","a"],[" نے میرے لیے اور میری امت کے لیے ناپسند کیا وہ مجھے بھی ناپسند ہے اور جو کچھ ابن ام عبد نے ناپسند کیا وہ مجھے بھی ناپسند ہے۔ ابن عساکر کی دوسری روایت میں ہے کہ حضورؐ نے حضرت ابن مسعودؓ سے فرمایا اب تم بات کرو، چنانچہ شروع میں انہوں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور حضورؐ پر درود و سلام بھیجا پھر کلمہ شہادت پڑھا، پھر یہ کہا ہم ",""],["ٱللَّٰه","a"],[" کے رب ہونے اور اسلام کے دین ہونے پر راضی ہیں اور میں نے بھی آپ لوگوں کے لیے وہی پسند کیا جو ",""],["ٱللَّٰه","a"],[" اور اس کے رسول نے پسند کیا۔ اس پر حضورؐ نے فرمایا میں بھی تمہارے لیے وہی پسند کرتا ہوں جو تمہارے لیے ابن ام عبد یعنی حضرت ابن مسعودؓ نے پسند کیا۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.9 Pg.290) has said that its narrators are those of authentic Ahaadeeth except Ubaydullah bin Uthmaan bin Khuthaym, who is reliable, but Sa'eed bin Jubayr did not hear from Abu Darda, and Allah knows best."],["(2)","Ibn Asaakir from Sa'eed bin Jubayr from Abu Darda similarly. Ibn Asaakir said that Sa'eed bin Jubayr did not meet Abu Darda."],["(3)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.237)."]]},{"b":[["n",[["حضرت ابوالاحوص جشمیؒ","b"],[" کہتے ہیں ایک دن حضرت ابن مسعودؓ بیان فرما رہے تھے کہ اتنے میں انہیں دیوار پر سانپ چلتا ہوا نظر آیا، انہوں نے بیان چھوڑ کر چھڑی سے اسے اتنا مارا کہ وہ مر گیا، پھر فرمایا میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جس نے کسی سانپ کو مارا تو گویا اس نے ایسے مشرک آدمی کو مارا جس کا خون بہانا حلال ہو گیا ہو۔",""],[" (4)","s"]]]],"f":[["(4)","Ahmad (Vol.1 Pg.421)."]]},{"b":[["n",[["حضرت ابو وائلؒ","b"],[" کہتے ہیں جب حضرت عثمان بن عفانؓ خلیفہ بنے تو حضرت ابن مسعودؓ مدینہ سے کوفہ روانہ ہوئے، آٹھ دن سفر کرنے کے بعد انہوں نے ایک جگہ بیان کیا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! امیر المومنین حضرت عمر بن خطابؓ کا انتقال ہوا تو ہم نے لوگوں کو اس دن سے زیادہ روتے ہوئے کسی دن نہیں دیکھا۔ پھر ہم حضرت محمدؐ کے صحابہ جمع ہوئے اور ایسے آدمی کے تلاش کرنے میں کوئی کمی نہیں کی جو ہم میں سب سے بہتر ہو اور ہر لحاظ سے ہم پر فوقیت رکھنے والا ہو، چنانچہ ہم نے امیر المومنین حضرت عثمانؓ سے بیعت کر لی ہے۔ آپ لوگ بھی ان سے بیعت ہو جائیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.3 Pg.63)."]]}]},"187":{"lead":[],"stories":[{"b":[["n",[["حضرت خالد بن عمیر عدویؒ","b"],[" کہتے ہیں حضرت عتبہ بن غزوانؓ بصرہ کے گورنر تھے۔ ایک مرتبہ انہوں نے ہم لوگوں میں بیان کیا تو پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! دنیا نے اپنے ختم ہو جانے کا اعلان کر دیا ہے اور پیٹھ پھیر کر تیزی سے جا رہی ہے اور دنیا میں سے بس تھوڑا سا حصہ باقی رہ گیا ہے جیسے برتن میں اخیر میں تھوڑا سا رہ جاتا ہے اور آدمی اسے چوس لیتا ہے۔ اور تم یہاں سے منتقل ہو کر ایسے جہاں میں چلے جاؤ گے جو کبھی ختم نہیں ہوگا، لہٰذا جو اچھے اعمال تمہارے پاس موجود ہیں ان کو لے کر اگلے جہان میں جاؤ۔ ہمیں بتایا گیا ہے کہ جہنم کے کنارے سے ایک پتھر پھینکا جائے گا جو ستر سال تک جہنم میں گرتا رہے گا لیکن پھر بھی اس کی تہہ تک نہیں پہنچ سکے گا۔ ",""],["ٱللَّٰه","a"],[" کی قسم! یہ جہنم بھی ایک دن انسانوں سے بھر جائے گی، کیا تمہیں اس پر تعجب ہو رہا ہے؟ اور ہمیں یہ بھی بتایا گیا ہے کہ جنت کے دروازے کے دو پٹوں کے درمیان چالیس سال کا فاصلہ ہے لیکن ایک دن ایسا آئے گا کہ جنتیوں کے ہجوم کی وجہ سے اتنا چوڑا دروازہ بھی بھرا ہوا ہوگا۔ اور میں نے وہ زمانہ بھی دیکھا ہے کہ ہم حضورؐ کے ساتھ صرف سات آدمی تھے اور میں ان میں بھی شامل تھا اور ہمیں کھانے کو صرف درختوں کے پتے ملتے تھے جنہیں مسلسل کھانے کی وجہ سے ہمارے جبڑے بھی زخمی ہو گئے تھے اور مجھے ایک گری پڑی چادر ملی تھی، میں نے اس کے دو ٹکڑے کیے، ایک ٹکڑے کو میں نے لنگی بنا لیا اور ایک کو حضرت سعد بن مالکؓ نے۔ ایک زمانہ میں تو ہمارے فقر و فاقہ کا یہ حال تھا اور آج ہم میں سے ہر ایک کسی نہ کسی شہر کا گورنر بنا ہوا ہے، اور میں اس بات سے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی پناہ چاہتا ہوں کہ میں اپنی نگاہ میں تو بڑا ہوں اور ",""],["ٱللَّٰه","a"],[" کے ہاں چھوٹا ہوں۔ حاکم کی روایت کے آخر میں یہ مضمون بھی ہے کہ ہر نبوت کی لائن دن بدن کم ہوتی چلی گئی ہے اور بالآخر اس کی جگہ بادشاہت نے لے لی ہے اور میرے بعد تم اور گورنروں کا تجربہ کر لو گے۔ ابن سعد میں اس روایت کے شروع میں یہ مضمون ہے کہ حضرت عتبہؓ نے بصرہ میں سب سے پہلا یہ بیان کیا کہ تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں، میں اس کی تعریف بیان کرتا ہوں اور اس سے مدد مانگتا ہوں اور اس پر ایمان لاتا ہوں اور اسی پر بھروسہ کرتا ہوں اور اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور حضرت محمدؐ اس کے بندے اور رسول ہیں۔ اما بعد! اے لوگو! آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Muslim, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.179)."],["(2)","Haakim (Vol.3 Pg.261), whose narrators are reliable. Ibn Jowzi has reported a similar narration in his Safwatus Safwah (Vol.1 Pg.152), as has Naabulsi in his Dhakhaa'irul Mawaareeth (Vol.2 Pg.229) from Muslim, Ibn Majah and Tirmidhi. Ahmad (Vol.4 Pg.174) has reported a similar narration, as has Abu Nu'aym in his Hilyah (Vol.1 Pg.171)."],["(3)","Ibn Sa'd (Vol.7 Pg.6)."]]}]},"188":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوعبدالرحمٰن سلمیؒ","b"],[" کہتے ہیں حضرت حذیفہ بن یمانؓ مدائن شہر کے گورنر تھے۔ ہمارے اور مدائن کے درمیان ایک فرسخ یعنی تین میل کا فاصلہ تھا۔ میں اپنے والد کے ساتھ مدائن جمعہ پڑھنے گیا، چنانچہ وہ منبر پر تشریف فرما ہوئے۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا قیامت قریب آ گئی اور چاند کے ٹکڑے ہو گئے۔ غور سے سنو! چاند کے تو ٹکڑے ہو چکے ہیں۔ توجہ سے سنو! دنیا نے جدائی کا اعلان کر دیا ہے۔ غور سے سنو! آج تو تیاری کا دن ہے، کل کو ایک دوسرے سے آگے نکلنے کا مقابلہ ہوگا۔ میں نے اپنے والد سے کہا ان کے نزدیک آگے نکلنے کا کیا مطلب ہے؟ انہوں نے کہا اس کا مطلب یہ ہے کہ کون جنت کی طرف آگے بڑھتا ہے۔ ابن جریر کی روایت کے شروع میں یہ مضمون ہے غور سے سنو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ","a"]]],["p",[["ترجمہ: \"قیامت نزدیک آ پہنچی اور چاند شق ہو گیا\" (سورۂ قمر، آیت 1)۔ غور سے سنو! بیشک قیامت قریب آ چکی ہے۔ اس روایت کے آخر میں یہ ہے کہ میں نے اپنے والد سے پوچھا کیا سچ مچ کل لوگوں کا آگے نکلنے میں مقابلہ ہوگا؟ میرے والد نے کہا اے میرے بیٹے! تم تو بالکل نادان ہو، اس سے تو اعمال میں ایک دوسرے سے آگے بڑھنا مراد ہے۔ پھر اگلا جمعہ آیا، ہم جمعہ میں آئے، حضرت حذیفہؓ نے پھر بیان فرمایا، غور سے سنو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ توجہ سے سنو! دنیا نے جدائی کا اعلان کر دیا ہے۔ غور سے سنو! آج تیاری کا دن ہے، کل ایک دوسرے سے آگے نکلنے کا مقابلہ ہوگا اور (تیاری نہ کرنے والے کا) انجام جہنم کی آگ ہے اور آگے نکل جانے والا وہ ہے جو جنت کی طرف سبقت لے جائے گا۔","a"],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.281)."],["(2)","Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.261). Haakim (Vol.4 Pg.609) has also reported it."]]},{"b":[["n",[["حضرت کردوسؒ","b"],[" کہتے ہیں ایک دفعہ حضرت حذیفہؓ نے مدائن شہر میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! تم نے اپنے غلاموں کے ذمہ لگایا ہے کہ وہ مال کما کر تمہیں دیں، وہ اپنی کمائی لا کر تمہیں دیتے ہیں، ان کی کمائیوں کا خیال رکھو، اگر وہ حلال کی ہوں تو کھا لو ورنہ چھوڑ دو کیونکہ میں نے حضورؐ کو فرماتے ہوئے سنا ہے کہ جو گوشت حرام سے پرورش پائے گا وہ جنت میں نہیں جا سکے گا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.281)."]]},{"b":[["n",[["حضرت ابوداؤد احمریؒ","b"],[" کہتے ہیں حضرت حذیفہؓ نے مدائن شہر میں ہم لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! اپنے غلاموں کی کمائی کی تحقیق کرتے رہو اور یہ معلوم کرو کہ وہ کہاں سے کما کر تمہارے پاس لاتے ہیں، کیونکہ حرام سے پرورش پانے والا گوشت بھی جنت میں داخل نہیں ہو سکے گا۔ اور یہ بات جان لو کہ شراب کا بیچنے والا، خریدنے والا اور اپنے لیے بنانے والا یہ سب شراب پینے والے کی طرح ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.218)."]]}]},"189":{"lead":[],"stories":[{"b":[["n",[["حضرت قسامہ بن زہیرؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابوموسیٰؓ نے بصرہ میں لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! رویا کرو اور اگر رونا نہ آئے تو رونے جیسی شکل ہی بنا لیا کرو کیونکہ جہنم والے اتنا روئیں گے کہ ان کے آنسو ختم ہو جائیں گے، پھر وہ خون کے اتنے آنسو روئیں گے کہ اگر ان آنسوؤں میں کشتیاں چلائی جائیں تو وہ بھی چل جائیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.4 Pg.110). Abu Nu'aym has reported a similar narration in his Hilyah (Vol.1 Pg.261)."]]}]},"190":{"lead":[],"stories":[{"b":[["n",[["حضرت شقیقؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ ایک مرتبہ موسم حج کے امیر تھے، انہوں نے ہم میں بیان فرمایا، انہوں نے سورۂ بقرہ شروع کر دی، آیتیں پڑھتے جاتے تھے اور ان کی تفسیر کرتے جاتے تھے۔ میں اپنے دل میں کہنے لگا نہ تو میں نے ان جیسا آدمی دیکھا اور نہ ان جیسا کلام کبھی سنا، اگر فارس اور روم والے ان کا کلام سن لیں تو سب مسلمان ہو جائیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.324)."]]}]},"191":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو یزید مدنیؒ","b"],[" کہتے ہیں حضرت ابوہریرہؓ نے مدینہ میں حضورؐ کے منبر پر کھڑے ہو کر بیان فرمایا اور حضورؐ کے کھڑے ہونے کی جگہ سے ایک سیڑھی نیچے کھڑے ہوئے اور ارشاد فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے ابوہریرہؓ کو اسلام کی ہدایت دی اور تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے ابوہریرہؓ کو قرآن سکھایا اور تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے حضرت محمدؐ کی صحبت میں رہنے کا موقع عنایت فرما کر ابوہریرہؓ پر بڑا احسان فرمایا اور تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے مجھے خمیری روٹی کھلائی اور اچھا کپڑا پہنایا اور تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے بنت غزوان سے میری شادی کرا دی، حالانکہ پہلے میں پیٹ بھر کھانے کے بدلے اس کے پاس مزدوری پر کام کرتا تھا اور وہ مجھے سواری دیا کرتی تھی، اب میں اسے سواری دیتا ہوں جیسے وہ مجھے دیا کرتی تھی۔ پھر فرمایا عربوں کے لیے ہلاکت ہو کہ ایک بہت بڑا شر قریب آ گیا ہے، اور ان کے لیے ہلاکت ہو کہ عنقریب بچے حاکم بن جائیں گے اور لوگوں میں اپنی مرضی اور خواہش کے فیصلے کریں گے اور غصہ میں آ کر لوگوں کو ناحق قتل کریں گے۔ اے (حضرت ابراہیمؑ کے بیٹے) فروخ کے بیٹو! یعنی عجم کے رہنے والو! (حضرت ابراہیمؑ کے اس بیٹے کی اولاد عجم کہلاتی ہے) تمہیں خوشخبری ہو، اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اگر دین ثریا ستارے کے پاس لٹکا ہوا ہوتا تو بھی تمہارے کچھ آدمی اسے ضرور حاصل کر لیتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.383)."]]},{"b":[["n",[["حضرت ابوجیبیہؒ","b"],[" کہتے ہیں جن دنوں حضرت عثمانؓ اپنے گھر میں محصور تھے میں ان کی خدمت میں ان کے گھر گیا۔ وہاں میں نے دیکھا حضرت ابوہریرہؓ حضرت عثمانؓ سے لوگوں سے بات کرنے کی اجازت مانگ رہے ہیں۔ حضرت عثمانؓ نے انہیں اجازت دے دی، چنانچہ وہ بیان کے لیے کھڑے ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا کہ میرے بعد تم پر ایک بڑا فتنہ اور بڑا اختلاف ظاہر ہوگا۔ ایک صحابیؓ نے حضورؐ سے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ان حالات میں آپ ہمیں کیا کرنے کا حکم کرتے ہیں؟ حضورؐ نے فرمایا امیر اور اس کے ساتھیوں کو مضبوطی سے پکڑے رہنا۔ یہ فرماتے ہوئے حضرت ابوہریرہؓ حضرت عثمانؓ کی طرف اشارہ فرما رہے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.4 Pg.433), who said that it is authentic although Bukhaari and Muslim did not report it, and Dhahabi agreed."]]}]},"192":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن یوسفؒ","b"],[" جو حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ کے پوتے ہیں کہتے ہیں میں نے حجاج بن یوسف سے اندر آنے کی اجازت مانگی، اس نے مجھے اجازت دے دی۔ میں نے اندر جا کر سلام کیا۔ حجاج کے تخت کے قریب دو آدمی بیٹھے ہوئے تھے، حجاج نے ان سے کہا انہیں جگہ دے دو۔ انہوں نے مجھے جگہ دے دی۔ میں وہاں بیٹھ گیا۔ حجاج نے مجھ سے کہا ",""],["ٱللَّٰه","a"],[" نے آپ کے والد کو بہت خوبیاں عطا فرمائی تھیں، کیا آپ وہ حدیث جانتے ہیں جو آپ کے والد نے عبدالملک بن مروان کو آپ کے دادا حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ کی طرف سے سنائی تھی؟ میں نے کہا آپ پر ",""],["ٱللَّٰه","a"],[" رحم فرمائے، کون سی حدیث؟ حدیثیں تو بہت ہیں۔ حجاج نے کہا مصریوں نے حضرت عثمانؓ کا محاصرہ کیا تھا، ان کے بارے میں حدیث۔ میں نے کہا ہاں وہ حدیث مجھے معلوم ہے اور وہ یہ ہے کہ حضرت عثمانؓ محصور تھے، حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ تشریف لائے اور حضرت عثمانؓ کے گھر میں داخل ہونا چاہا تو اندر موجود لوگوں نے ان کے لیے راستہ بنا دیا جس سے وہ اندر داخل ہو گئے اور انہوں نے حضرت عثمانؓ سے کہا السلام علیک یا امیر المومنین! حضرت عثمانؓ نے فرمایا و علیک السلام یا عبد",""],["ٱللَّٰه","a"],[" بن سلام! کیسے آنا ہوا؟ حضرت ابن سلامؓ نے کہا میں تو یہ پختہ عزم لے کر آیا ہوں کہ یہاں سے ایسے ہی نہیں جاؤں گا (بلکہ آپ کی طرف سے ان مصریوں سے لڑوں گا)، پھر یا تو شہید ہو جاؤں گا یا ",""],["ٱللَّٰه","a"],[" آپ کو فتح نصیب فرما دیں گے۔ مجھے تو یہی نظر آ رہا ہے یہ لوگ آپ کو قتل کر دیں گے۔ اگر ان لوگوں نے آپ کو قتل کر دیا تو یہ آپ کے لیے تو بہتر ہوگا لیکن ان کے لیے بہت برا ہوگا۔ حضرت عثمانؓ نے فرمایا آپ کے اوپر میرا جو حق ہے اس کا واسطہ دے کر کہتا ہوں کہ آپ ان کے پاس ضرور جائیں اور انہیں سمجھائیں۔ ہو سکتا ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ آپ کے ذریعہ سے خیر کو لے آئیں اور شر کو ختم کر دیں۔ حضرت ابن سلامؓ نے اپنا ارادہ چھوڑ دیا اور حضرت عثمانؓ کی بات مان لی اور ان مصریوں کے پاس باہر آئے۔ جب مصریوں نے ان کو دیکھا تو وہ سب ان کے پاس اکٹھے ہو گئے، وہ یہ سمجھے کہ حضرت ابن سلامؓ کوئی خوشی کی بات لائے ہیں۔ چنانچہ حضرت ابن سلامؓ بیان کے لیے کھڑے ہوئے، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اما بعد! ",""],["ٱللَّٰه","a"],[" نے حضرت محمدؐ کو خوشخبری سنانے والا اور ڈرانے والا بنا کر بھیجا تھا، جو ان کی اطاعت کرتا تھا اسے جنت کی بشارت دیتے تھے اور جو نافرمانی کرتا تھا اسے جہنم سے ڈراتے تھے۔ آخر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضورؐ کا اتباع کرنے والوں کو تمام دین والوں پر غالب کر دیا اگرچہ یہ بات مشرکوں کو بہت ناگوار گزری۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضورؐ کے لیے بہت سی رہنے کی جگہیں پسند فرمائیں اور ان میں سے مدینہ منورہ کو منتخب فرمایا اور اسے ہجرت کا گھر اور ایمان کا گھر قرار دیا (ہر جگہ سے مسلمان ہجرت کر کے وہاں آتے رہے اور ایمان سیکھتے رہے)۔ ",""],["ٱللَّٰه","a"],[" کی قسم! جب سے حضورؐ مدینہ تشریف لائے ہیں اس وقت سے لے کر آج تک ہر وقت فرشتے اسے ہر طرف سے گھیرے رہتے ہیں اور جب سے حضورؐ مدینہ تشریف لائے ہیں اس وقت سے لے کر آج تک ",""],["ٱللَّٰه","a"],[" کی تلوار آپ لوگوں سے نیام میں ہے (یعنی مسلمان قتل نہیں ہو رہے ہیں)۔ پھر فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت محمدؐ کو حق دے کر بھیجا، لہٰذا جسے ہدایت ملی اسے ",""],["ٱللَّٰه","a"],[" کے دین سے ملی اور جو گمراہ ہوا وہ واضح اور کھلی دلیل کے آنے کے بعد گمراہ ہوا۔ پہلے زمانے میں جو بھی نبی شہید کیا گیا اس کے بدلے میں ستر ہزار جنگجو جوان قتل کیے گئے، ان میں سے ہر ایک اس نبی کے بدلے میں قتل کیا گیا، اور جو بھی خلیفہ شہید کیا گیا اس کے بدلے میں 35 ہزار جنگجو جوان قتل کیے گئے، ان میں سے ہر ایک اس خلیفہ کے بدلے میں قتل ہوا۔ لہٰذا تم جلد بازی نہ کرو (کہیں) ان بڑے میاں کو قتل نہ کر دو۔ ",""],["ٱللَّٰه","a"],[" کی قسم! تم میں سے جو آدمی بھی انہیں قتل کرے گا وہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" کے ہاں اس حال میں پیش ہوگا کہ اس کا ہاتھ کٹا ہوا اور شل ہوگا۔ اور یہ بات اچھی طرح جان لو کہ ایک باپ کا اپنے بیٹے پر جتنا حق ہوتا ہے اتنا ہی ان بڑے میاں کا تمہارے اوپر (حق) ہے۔ راوی کہتے ہیں یہ سن کر وہ سارے باغی ہو گئے اور کہنے لگے یہودی جھوٹے ہیں، یہودی جھوٹے ہیں (چونکہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ پہلے یہودی تھے اور بعد میں مسلمان ہوئے، اس لیے بطور طعنہ کے انہوں نے ایسا کہا)۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا غلط کہتے ہو، ",""],["ٱللَّٰه","a"],[" کی قسم! یہ بات کہہ کر تم گنہگار ہو گئے ہو، میں یہودی نہیں ہوں، میں تو مسلمان ہوں۔ یہ بات ",""],["ٱللَّٰه","a"],[" اور اس کے رسول اور سارے مومن جانتے ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے میرے بارے میں قرآن کی یہ آیت نازل فرمائی ہے",""]]],["q",[["قُلْ كَفَىٰ بِٱللَّهِ شَهِيدًۢا بَيْنِى وَبَيْنَكُمْ وَمَنْ عِندَهُۥ عِلْمُ ٱلْكِتَٰبِ","a"]]],["p",[["ترجمہ: \"آپ فرما دیجیے کہ میرے اور تمہارے درمیان (میری نبوت پر) ",""],["ٱللَّٰه","a"],[" تعالیٰ اور وہ شخص جس کے پاس کتاب (آسمانی) کا علم ہے کافی گواہ ہیں\" (سورۂ رعد، آیت 43)۔ (جس کے پاس گزشتہ آسمانی کتاب کا علم ہے اس سے مراد حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ اور ان جیسے دوسرے یہودی علماء ہیں جو تورات کی بتائی ہوئی نشانیاں دیکھ کر مسلمان ہو گئے تھے۔) اور میرے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت بھی نازل فرمائی ہے",""]]],["q",[["قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ وَكَفَرْتُم بِهِۦ وَشَهِدَ شَاهِدٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ مِثْلِهِۦ فَـَٔامَنَ وَٱسْتَكْبَرْتُمْ","a"]]],["p",[["ترجمہ: \"آپ کہہ دیجیے کہ تم مجھ کو بتاؤ کہ اگر یہ قرآن منجانب ",""],["ٱللَّٰه","a"],[" ہو اور تم اس کے منکر ہو اور بنی اسرائیل میں سے کوئی گواہ اس جیسی کتاب پر گواہی دے کر ایمان لے آوے اور تم تکبر ہی میں رہو\" (سورۂ احقاف، آیت 10)۔ پھر راوی نے حضرت عثمانؓ کی شہادت کے بارے میں حدیث ذکر کی۔",""]]]],"f":[]}]},"193":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن حسنؒ","b"],[" کہتے ہیں جب عمر بن سعد نے (لشکر لے کر) حضرت حسینؓ کے پاس پڑاؤ کیا اور حضرت حسینؓ کو یقین ہو گیا کہ یہ لوگ انہیں قتل کر دیں گے تو انہوں نے اپنے ساتھیوں میں کھڑے ہو کر بیان کیا۔ پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا جو معاملہ تم دیکھ رہے ہو وہ ہم پر آن پڑا ہے (ہمیں قتل کرنے کے لیے لشکر آ گیا ہے)۔ دنیا بدل گئی ہے اور اوپری ہو گئی ہے۔ اس کی نیکی پیٹھ پھیر کر چلی گئی ہے اور دنیا کی نیکی میں صرف اتنا رہ گیا ہے جتنا برتن کے نچلے حصہ میں رہ جایا کرتا ہے، بس گھٹیا زندگی رہ گئی ہے جیسے مضر صحت چراگاہ ہوا کرتی ہے جس کا گھاس کھانے سے ہر جانور بیمار ہو جاتا ہے۔ کیا آپ لوگ دیکھتے نہیں ہیں کہ حق پر عمل نہیں کیا جا رہا اور باطل سے روکا نہیں جا رہا (ان حالات میں) مومن کو ",""],["ٱللَّٰه","a"],[" سے ملاقات کا شوق ہونا چاہیے۔ میں تو اس وقت موت کو بڑی سعادت کی چیز اور ظالموں کے ساتھ زندگی کو پریشانی اور بے چینی کی چیز سمجھتا ہوں۔ حضرت عقبہ بن ابی العیزارؒ کی روایت تاریخ ابن جریر میں اس طرح ہے کہ حضرت حسینؓ نے ذی حسم مقام میں کھڑے ہو کر بیان کیا اور ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی اور پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani; Haythami (Vol.9 Pg.193) has commented that this Muhammad bin Hasan is Ibn Zabaalah who is matrook and did not witness the incident."]]},{"b":[["n",[["حضرت عقبہ بن ابی العیزارؒ","b"],[" کہتے ہیں حضرت حسینؓ نے بیضہ مقام میں اپنے ساتھیوں میں اور حر بن یزید کے ساتھیوں میں بیان کیا، پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا اے لوگو! حضورؐ نے فرمایا ہے کہ جو آدمی ایسے ظالم سلطان کو دیکھے جو ",""],["ٱللَّٰه","a"],[" کی حرام کردہ چیزوں کو حلال سمجھے اور ",""],["ٱللَّٰه","a"],[" سے کیے ہوئے معاہدے کو توڑے اور حضورؐ کی سنت کا مخالف ہو اور ",""],["ٱللَّٰه","a"],[" کے بندوں کے بارے میں گناہ اور زیادتی کے کام کرتا ہو اور پھر وہ آدمی اس بادشاہ کو اپنے قول اور فعل سے نہ بدلے تو ",""],["ٱللَّٰه","a"],[" پر حق ہوگا کہ وہ اسے اس جرم کے لائق جگہ یعنی جہنم میں داخل کرے۔ غور سے سنو! ان لوگوں نے شیطان کی اطاعت کو لازم پکڑ لیا ہے اور رحمٰن کی اطاعت چھوڑ دی ہے اور فساد کو غالب کر دیا ہے اور ",""],["ٱللَّٰه","a"],[" کی مقرر کردہ حدود کو چھوڑ دیا ہے اور مال غنیمت پر خود قبضہ کر لیا ہے اور ",""],["ٱللَّٰه","a"],[" کی حرام کردہ چیزوں کو حلال اور ",""],["ٱللَّٰه","a"],[" کی حلال کردہ چیزوں کو حرام قرار دے دیا ہے۔ ان لوگوں کو بدلنے کا سب سے زیادہ حق مجھ پر ہے۔ تمہارے خط میرے پاس آئے تھے اور تمہارے قاصد بھی مسلسل آتے رہے کہ تم مجھ سے بیعت ہونا چاہتے ہو اور مجھے بے یار و مددگار نہیں چھوڑو گے۔ اب اگر تم اپنی بیعت پر پورے اترتے ہو تو تمہیں پوری ہدایت ملے گی اور پھر میں بھی علی کا بیٹا حسین ہوں اور محمدؐ کی صاحبزادی فاطمہؓ کا بیٹا ہوں۔ میری جان تمہاری جان کے ساتھ ہے اور میرے گھر والے تمہارے گھر والوں کے ساتھ ہیں۔ تم لوگوں کے لیے میں بہترین نمونہ ہوں۔ اور اگر تم نے ایسا نہ کیا اور عہد توڑ دیا اور میری بیعت کو اپنی گردن سے اتار پھینکا تو میری جان کی قسم! ایسا کرنا تم لوگوں کے لیے کوئی اجنبی اور اوپری چیز نہیں ہے بلکہ تم لوگ تو ایسا میرے والد، میرے بھائی اور میرے چچازاد بھائی (مسلم بن عقیل) کے ساتھ بھی کر چکے ہو۔ جو تم لوگوں سے دھوکہ کھائے وہ اصل دھوکہ میں پڑا ہوا ہے اور تم نے (خوش قسمتی میں سے) اپنا حصہ ضائع کر دیا، اور جو عہد توڑے گا تو اس کا نقصان خود اسی کو ہوگا اور عنقریب ",""],["ٱللَّٰه","a"],[" تعالیٰ تم لوگوں سے مستغنی کر دے گا، تم لوگوں کی مجھے ضرورت نہ رہے گی۔ والسلام علیکم و رحمۃ ",""],["ٱللَّٰه","a"],[" و برکاتہ۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.9 Pg.193) has commented on the chain of narrators. A narration of Ibn Jareer (Vol.4 Pg.305) states that this lecture was delivered at a place called Dhu Husum."]]}]},"194":{"lead":[],"stories":[{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں حضرت یزید بن شجرہؓ ان لوگوں میں سے تھے جن کا عمل ان کے قول کی تصدیق کرتا تھا۔ انہوں نے ایک مرتبہ ہم میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" نے جو نعمتیں تمہیں دی ہیں انہیں یاد رکھو اور ",""],["ٱللَّٰه","a"],[" کی یہ نعمتیں کتنی اچھی ہیں! ہم سرخ، سبز اور زرد رنگ برنگے کپڑے دیکھ رہے ہیں اور گھروں میں جو سامان ہے وہ اس کے علاوہ ہے۔ حضرت یزیدؓ یہ بھی فرماتے تھے کہ جب لوگ نماز کے لیے صفیں بنا لیتے ہیں اور لڑائی کے لیے صفیں بنا لیتے ہیں تو آسمان کے، جنت کے اور دوزخ کے دروازے کھول دیے جاتے ہیں اور موٹی آنکھوں والی حوریں سجائی جاتی ہیں اور وہ جھانک کر دیکھنے لگ جاتی ہیں۔ جب آدمی آگے بڑھتا ہے تو وہ کہتی ہیں اے ",""],["ٱللَّٰه","a"],["! اس کی مدد فرما اور جب پیٹھ پھیرتا ہے اور پیچھے ہٹتا ہے تو اس سے پردہ کر لیتی ہیں اور کہتی ہیں اے ",""],["ٱللَّٰه","a"],["! اس کی مغفرت فرما۔ لہٰذا تم پورے زور سے جنگ کرو، میرے ماں باپ تم پر قربان ہوں، اور موٹی آنکھوں والی حوروں کو روانہ کرو۔ کیونکہ جب خون کا پہلا قطرہ زمین پر گرتا ہے تو اس نے جتنے گناہ کیے ہوتے ہیں وہ سب معاف ہو جاتے ہیں اور دو حوریں آسمان سے اترتی ہیں اور اس کے چہرے کو صاف کرتی ہیں اور کہتی ہیں ہم سے ملاقات کا وقت آ گیا ہے۔ پھر اسے سو جوڑے پہنائے جاتے ہیں جو بنی آدم کی بنائی ہوئی نہیں ہوتے بلکہ جنت کی پیداوار کے ہوتے ہیں اور وہ اتنے باریک اور لطیف ہوتے ہیں کہ وہ سو جوڑے دو انگلیوں کے درمیان رکھ دیے جائیں تو سارے دونوں کے درمیان آ جائیں۔ اور حضرت یزیدؓ فرمایا کرتے تھے کہ مجھے بتایا گیا ہے کہ تلواریں جنت کی چابیاں ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, whose narrators are reliable as confirmed by Haythami (Vol.5 Pg.294)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں حضرت یزید بن شجرہ رہاویؓ شام کے گورنروں میں سے ایک گورنر تھے۔ حضرت معاویہؓ انہیں لشکروں کا امیر بنایا کرتے تھے۔ ایک دن انہوں نے ہم لوگوں میں بیان فرمایا جس میں ارشاد فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو نعمتیں تمہیں عطا فرمائی ہیں انہیں یاد رکھو۔ اگر تم غور سے دیکھو تو تمہیں بھی وہ سیاہ، سرخ، سبز اور سفید رنگ برنگی نعمتیں نظر آ جائیں گی جو مجھے نظر آ رہی ہیں اور گھروں میں بھی کتنی نعمتیں ہیں۔ اور جب نماز کھڑی ہوتی ہے تو آسمان کے، جنت کے اور جہنم کے دروازے کھول دیے جاتے ہیں اور حوروں کو سجایا جاتا ہے اور وہ زمین کی طرف جھانکتی ہیں (اور جب میدان جنگ میں مسلمان صفیں بناتے ہیں تو اس وقت بھی یہ سب کچھ ہوتا ہے)۔ اور جب مسلمان جنگ کی طرف متوجہ ہو کر آگے بڑھتا ہے تو وہ حوریں کہتی ہیں (اے ",""],["ٱللَّٰه","a"],["! اس کو جما دے۔ اے ",""],["ٱللَّٰه","a"],["! اس کی مدد فرما)، اور جب کوئی پشت پھیر کر میدان سے بھاگ گیا ہے تو وہ حوریں اس سے پردہ کر لیتی ہیں اور کہتی ہیں اے ",""],["ٱللَّٰه","a"],["! اس کی مغفرت فرما۔ لہٰذا تم دشمن کے چہروں پر پورے زور سے حملہ کرو، میرے ماں باپ تم پر قربان ہوں۔ جب کوئی آگے بڑھتے ہوئے زخمی ہو کر گرتا ہے تو خون کے پہلے قطرے کے گرتے ہی اس کے گناہ ایسے گر جاتے ہیں جیسے خزاں میں درختوں کے پتے گرتے ہیں اور موٹی آنکھوں والی دو حوریں اتر کر اس کے پاس آتی ہیں اور اس کے چہرے سے گرد و غبار صاف کرتی ہیں۔ وہ ان دونوں سے کہتا ہے میں تم دونوں کے لیے ہوں۔ وہ کہتی ہیں نہیں، ہم دونوں آپ کے لیے ہیں۔ اور اسے ایسے سو جوڑے پہنائے جاتے ہیں کہ اگر انہیں اکٹھا کر کے میری ان دو انگلیوں (درمیانی اور شہادت کی انگلیوں) کے درمیان رکھا جائے تو وہ باریکی اور لطافت کی وجہ سے سارے ان کے درمیان آ جائیں، اور وہ بنی آدم کے بنے ہوئے نہیں ہیں بلکہ جنت کے کپڑوں میں سے ہیں۔ تم لوگوں کے نام، نشانیاں، حلیے، تنہائی کی باتیں اور مجلسیں سب چیزیں ",""],["ٱللَّٰه","a"],[" کے پاس لکھی ہوئی ہیں۔ جب قیامت کا دن آئے گا تو کسی سے کہا جائے گا اے فلانے! یہ تیرا نور ہے اور کسی سے کہا جائے گا اے فلانے! تیرے لیے کوئی نور نہیں ہے۔ اور جیسے سمندر کا ساحل ہوتا ہے ایسے ہی جہنم کا بھی ساحل ہے، وہاں کیڑے مکوڑے، حشرات الارض اور کھجور کے درخت جتنے لمبے سانپ اور خچر کے برابر بچھو ہیں۔ جب جہنم والے ",""],["ٱللَّٰه","a"],[" سے فریاد کریں گے کہ ہمارا جہنم کا عذاب ہلکا کر دیا جائے تو ان سے کہا جائے گا کہ جہنم سے نکل کر ساحل پر چلے جاؤ، وہ نکل کر وہاں آئیں گے تو کیڑے مکوڑے حشرات الارض ان کے ہونٹوں، چہروں اور دوسرے اعضاء کو پکڑ لیں گے اور انہیں نوچ کھائیں گے، تو تب یہ فریاد کرنے لگیں گے کہ ہمیں ان سے چھڑایا جائے اور جہنم میں واپس جانے دیا جائے۔ اور جہنم والوں پر خارش کا عذاب بھی مسلط کیا جائے گا اور جہنمی اتنا کھجائے گا کہ اس کی ہڈی ننگی ہو جائے گی۔ فرشتہ کہے گا اے فلانے! کیا تجھے اس خارش سے تکلیف ہو رہی ہے؟ وہ کہے گا ہاں! فرشتہ کہے گا تو جو مسلمانوں کو تکلیف دیا کرتا تھا یہ اس کے بدلے میں ہے۔",""]]]],"f":[]}]},"195":{"lead":[],"stories":[{"b":[["n",[["حضرت سعد بن سویدؒ","b"],[" کہتے ہیں حضرت عمیر بن سعدؓ نبی کریمؐ کے صحابہؓ میں سے تھے اور حمص کے گورنر تھے، وہ منبر پر فرمایا کرتے تھے غور سے سنو! اسلام کی ایک مضبوط دیوار ہے اور اس کا ایک مضبوط دروازہ ہے۔ اسلام کی دیوار عدل و انصاف ہے اور اس کا دروازہ حق ہے لہٰذا جب دیوار توڑ دی جائے گی اور دروازے کے ٹکڑے ٹکڑے کر دیے جائیں گے تو اسلام مفتوح ہو جائے گا۔ اور جب تک سلطان قوی ہوگا اسلام مضبوط رہے گا اور سلطان کی قوت تلوار سے قتل کرنے یا کوڑے مارنے سے نہیں ہے بلکہ حق کے فیصلے کرنے اور عدل و انصاف کرنے سے ہے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.294). Ibn Mubaarak in his Zuhd, Ibn Mandah and Bayhaqi have all reported a similar narration in detail, as quoted in Isaabah (Vol.3 Pg.658)."],["(2)","Ibn Sa'd (Vol.4 Pg.375)."]]}]},"196":{"lead":[],"stories":[{"b":[["n",[["حضرت سعد بن عبیدؓ","b"],[" نے لوگوں میں بیان فرمایا تو ارشاد فرمایا کل دشمن سے ہماری مڈبھیڑ ہوگی اور کل ہم شہید ہو جائیں گے، لہٰذا ہمارے جسم پر جو خون لگا ہوا ہے اسے مت دھونا اور ہمارے جسم پر جو کپڑے ہوں گے وہی ہمارا کفن ہوں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.4 Pg.458)."]]}]},"197":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمہ بن سبرہؒ","b"],[" کہتے ہیں ملک شام میں حضرت معاذ بن جبلؓ نے ہم لوگوں میں بیان فرمایا تو ارشاد فرمایا تم لوگ ایمان والے ہو، تم لوگ جنتی ہو۔ ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے امید ہے کہ تم لوگوں نے روم و فارس کے جن لوگوں کو قیدی بنا لیا ہے ",""],["ٱللَّٰه","a"],[" انہیں بھی جنت میں داخل کرے گا، اور اس کی وجہ یہ ہے کہ ان میں سے کوئی جب تمہارا کوئی کام کر دیتا ہے تو تم شکریہ میں اسے یہ تعریفی اور دعائیہ کلمات کہتے ہو تم نے اچھا کیا، تم پر ",""],["ٱللَّٰه","a"],[" رحم فرمائے، تم نے اچھا کیا تم کو ",""],["ٱللَّٰه","a"],[" برکت عطا فرمائے (تمہاری ان دعاؤں کی برکت سے ",""],["ٱللَّٰه","a"],[" انہیں ایمان دے کر جنت میں داخل کر دے گا)۔ پھر حضرت معاذؓ نے یہ آیت پڑھی",""]]],["q",[["وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ","a"]]],["p",[["ترجمہ: \"اور (",""],["ٱللَّٰه","a"],[" تعالیٰ) ان لوگوں کی عبادت قبول کرتا ہے جو ایمان لائے اور انہوں نے نیک عمل کیے اور اپنے فضل سے اور زیادہ (ثواب) دیتا ہے\" (سورۂ شوریٰ، آیت 26)۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer and Ibn Abi Haatim, as quoted in Tafseer Ibn Katheer (Vol.4 Pg.115)."]]}]},"198":{"lead":[],"stories":[{"b":[["n",[["حضرت حوشب فرازیؒ","b"],[" کہتے ہیں میں نے حضرت ابوالدرداءؓ کو منبر پر بیان میں یہ فرماتے ہوئے سنا میں اس دن سے بہت ڈرتا ہوں جس دن میرا رب مجھے پکار کر کہے گا اے عویمر! میں کہوں گا لبیک، پھر میرا رب کہے گا تو نے اپنے علم پر کیا عمل کیا؟ ",""],["ٱللَّٰه","a"],[" کی کتاب کی وہ آیت بھی آئے گی جو کسی برے عمل سے روکنے والی ہے اور وہ آیت بھی آئے گی جو کسی نیک عمل کا حکم دینے والی ہے اور ہر آیت مجھ سے اپنے حق کا مطالبہ کرے گی۔ اب اگر میں نے اس نیک عمل کو نہیں کیا ہوگا تو وہ حکم دینے والی آیت میرے خلاف گواہی دے گی اور اگر میں نے اس برے کام کو نہیں چھوڑا ہوگا تو وہ روکنے والی آیت میرے خلاف گواہی دے گی۔ اب بتاؤ میں کیسے چھوٹ سکتا ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.78)."]]}]}}});
